const e=[{id:1,name:"Foundations & Core Middleware",icon:"Cpu",range:[1,6],lesson_count:6,lessons:[{id:"lesson_01",num_str:"01",title:"Linux Fundamentals for Robotics Engineers"},{id:"lesson_02",num_str:"02",title:"ROS 2 Overview & Environment Setup"},{id:"lesson_03",num_str:"03",title:"ROS 2 Workspace & HelloWorld in Python"},{id:"lesson_04",num_str:"04",title:"ROS 2 Package Architecture & Configuration Deep Dive"},{id:"lesson_05",num_str:"05",title:"Communication Mechanism I: Publishers, Subscribers & QoS"},{id:"lesson_06",num_str:"06",title:"VS Code IDE Tooling & ROS 2 Logging Framework"}]},{id:2,name:"Advanced Communication Patterns",icon:"Network",range:[7,13],lesson_count:7,lessons:[{id:"lesson_07",num_str:"07",title:"ROS 2 Interfaces & Custom Messages/Services"},{id:"lesson_08",num_str:"08",title:"Communication Mechanism II: Service Servers & Clients in Python"},{id:"lesson_09",num_str:"09",title:"Communication Mechanism III: Dynamic Parameters & YAML Configuration"},{id:"lesson_10",num_str:"10",title:"Runtime Management & Python Launch Files"},{id:"lesson_11",num_str:"11",title:"Communication Mechanism IV: Action Servers & Clients in Python"},{id:"lesson_12",num_str:"12",title:"Data Recording & Playback with ROS 2 Bags"},{id:"lesson_13",num_str:"13",title:"Complete ROS 2 Command-Line Interface (CLI) Mastery"}]},{id:3,name:"Kinematics, TF2 & Computer Vision",icon:"Eye",range:[14,16],lesson_count:3,lessons:[{id:"lesson_14",num_str:"14",title:"TF2 Spatial Coordinate Transformations in Python"},{id:"lesson_15",num_str:"15",title:"Distributed ROS 2, Multi-Robot Fleets & DDS Networking"},{id:"lesson_16",num_str:"16",title:"Project 3.2: Computer Vision & OpenCV Integration with ROS 2"}]},{id:4,name:"3D Simulation & World Modeling",icon:"Box",range:[17,20],lesson_count:4,lessons:[{id:"lesson_17",num_str:"17",title:"3D Robot Modeling with URDF & Xacro"},{id:"lesson_18",num_str:"18",title:"RViz2 Visualization & Kinematic TF Inspection"},{id:"lesson_19",num_str:"19",title:"Gazebo Physics Simulation & Sensor Plugins"},{id:"lesson_20",num_str:"20",title:"Building Custom Simulation Worlds in Gazebo"}]},{id:5,name:"Autonomous Navigation with Nav2",icon:"Compass",range:[21,26],lesson_count:6,lessons:[{id:"lesson_21",num_str:"21",title:"2D LiDAR SLAM Mapping with SLAM Toolbox"},{id:"lesson_22",num_str:"22",title:"Nav2 Stack Architecture & Costmap 2D Configuration"},{id:"lesson_23",num_str:"23",title:"Nav2 Path Planners & Local Controller Tuning"},{id:"lesson_24",num_str:"24",title:"Behavior Trees, Recovery Behaviors & Lifecycle Management"},{id:"lesson_25",num_str:"25",title:"Autonomous Navigation Scripting with Nav2 Simple Commander"},{id:"lesson_26",num_str:"26",title:"Physical Robot Hardware Deployment (Sim-to-Real)"}]}],n=JSON.parse(`[{"id":"lesson_01","num":1,"num_str":"01","title":"Linux Fundamentals for Robotics Engineers","slug":"linux_fundamentals_for_robotics","filename":"01_linux_fundamentals_for_robotics.md","module":"Foundations & Core Middleware","module_id":1,"duration":"45-60 min","focus":"Essential Linux Terminal Commands, Filesystem Hierarchy, File Permissions & Process Management","snapshot":[["Filesystem","Navigate directories with pwd, cd, and create nested trees with mkdir -p."],["Executable Permission","Scripts must have the execute bit set with chmod +x script.sh before execution."],["Process Management","Monitor resource utilization with top and terminate jobs cleanly with kill <PID> or killall."],["Shell Aliases","Automate repetitive command paths by adding aliases to ~/.bashrc."]],"html_content":"<h1 id=\\"lesson-01-linux-fundamentals-for-robotics-engineers\\">Lesson 01: Linux Fundamentals for Robotics Engineers</h1>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Focus:</strong> Essential Linux Terminal Commands, Filesystem Hierarchy, File Permissions &amp; Process Management<br><strong>Course Track:</strong> NavPro Learning Hub - Level 1 &amp;bull; Zero-to-Autonomous AMR Engineer<br><strong>Target Environment:</strong> Ubuntu 24.04 LTS (Noble Numbat) / Containerized Docker / Raspberry Pi &amp; Jetson</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"1-overview--learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>Robotics software runs on Linux (Ubuntu LTS). Before diving into robotics middleware in Lesson 02, you must master the fundamental command-line workflows: navigating directories, inspecting files, granting executable permissions to scripts, and managing background processes.</p>\\n<div class=\\"lesson-image-wrapper\\"><img src=\\"assets/images/robotics_software_stack.svg\\" alt=\\"Robotics Software Stack\\" class=\\"lesson-image\\" loading=\\"lazy\\"><span class=\\"image-caption\\">Robotics Software Stack</span></div>\\n<p>By the end of this lesson, you will:</p>\\n<ul class=\\"lesson-bullet-list\\">\\n<li><strong>Navigate the Linux filesystem</strong> and understand where user files, system packages, and logs reside.</li>\\n<li><strong>Master daily command-line utilities</strong> (<code class=\\"inline-code\\">cd</code>, <code class=\\"inline-code\\">ls</code>, <code class=\\"inline-code\\">mkdir -p</code>, <code class=\\"inline-code\\">cp</code>, <code class=\\"inline-code\\">rm</code>, <code class=\\"inline-code\\">grep</code>) in an unbroken hands-on workflow.</li>\\n<li><strong>Understand file permission strings</strong> and use <code class=\\"inline-code\\">chmod +x</code> to make shell scripts directly executable.</li>\\n<li><strong>Inspect and cleanly terminate background processes</strong> (<code class=\\"inline-code\\">top</code>, <code class=\\"inline-code\\">kill</code>, <code class=\\"inline-code\\">killall</code>).</li>\\n<li><strong>Configure <code class=\\"inline-code\\">~/.bashrc</code></strong> with productivity shell shortcuts (<code class=\\"inline-code\\">alias</code>) and automated environment variables.</li>\\n<li><strong>Use Terminator</strong> to split and orchestrate multi-terminal workflows on a single screen.</li>\\n</ul>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-the-linux-filesystem-what-you-need-to-know\\">2. The Linux Filesystem: What You Need to Know</h2>\\n<p>In Linux, all files, hardware devices, and network sockets are organized into a single unified tree originating at root (<code class=\\"inline-code\\">/</code>):</p>\\n<div class=\\"lesson-image-wrapper\\"><img src=\\"assets/images/linux_filesystem_tree.svg\\" alt=\\"Linux Filesystem Hierarchy\\" class=\\"lesson-image\\" loading=\\"lazy\\"><span class=\\"image-caption\\">Linux Filesystem Hierarchy</span></div>\\n<h3 id=\\"key-directory-guide-for-roboticists\\">Key Directory Guide for Roboticists</h3>\\n<div class=\\"info-grid\\">\\n  <div class=\\"info-card\\">\\n    <h4>📁 <code>~/</code> (/home/student/)</h4>\\n    <p>Your personal user workspace. You have full read, write, and execute permissions here without requiring <code>sudo</code>.</p>\\n  </div>\\n  <div class=\\"info-card\\">\\n    <h4>⚙️ <code>/opt/</code></h4>\\n    <p>Where system-level robotics packages and pre-compiled software stacks reside (e.g. <code>/opt/ros/jazzy/</code>).</p>\\n  </div>\\n  <div class=\\"info-card\\">\\n    <h4>🌐 <code>/etc/</code></h4>\\n    <p>System-wide configuration files (networking, hosts, user groups, and APT package repositories).</p>\\n  </div>\\n  <div class=\\"info-card\\">\\n    <h4>📊 <code>/var/log/</code></h4>\\n    <p>System service logs, boot diagnostics, and runtime error traces.</p>\\n  </div>\\n  <div class=\\"info-card\\">\\n    <h4>🔌 <code>/dev/</code></h4>\\n    <p>Device nodes representing hardware peripherals (USB LiDARs <code>/dev/ttyUSB0</code> and microcontrollers).</p>\\n  </div>\\n</div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-hands-on-practical-building-a-robotics-workspace\\">3. Hands-On Practical: Building a Robotics Workspace</h2>\\n<p>Follow this continuous hands-on workflow in your terminal. Every single command builds directly upon the folders and files created in the preceding step, ensuring zero <em>&quot;file not found&quot;</em> errors.</p>\\n<h3 id=\\"30-step-0-how-to-open-the-terminal--switch-to-home-directory\\">3.0 Step 0: How to Open the Terminal &amp; Switch to Home Directory</h3>\\n<p>Before executing any commands, you need an open terminal window:</p>\\n<ul class=\\"lesson-bullet-list\\">\\n<li><strong>In the Browser Desktop (noVNC / TigerVNC):</strong> Click the <strong>Terminal</strong> (or <strong>Terminator</strong>) icon on the desktop dock/panel, or press <kbd>Ctrl</kbd> + <kbd>Alt</kbd> + <kbd>T</kbd>.</li>\\n<li><strong>In the Cloud VS Code IDE (Code Server):</strong> Press <kbd>Ctrl</kbd> + <kbd>\`</kbd> (Backtick) or select <strong>Terminal &rarr; New Terminal</strong> from the top menu bar.</li>\\n</ul>\\n<div class=\\"alert-callout alert-warning\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Crucial First Step: Switch to Your Home Directory (<code>cd ~</code>)</strong><br>In containerized robotics environments, new terminals often launch inside the pre-configured ROS 2 workspace folder (<code>/home/student/ros2_ws</code>).<br><strong>Before running the Linux commands below, return to your user home directory root (<code>/home/student</code>) by entering:</strong><br><div class=\\"code-container\\" data-language=\\"bash\\"><pre><code class=\\"language-bash\\">cd ~</code></pre></div><br>Run <code>pwd</code> to confirm your terminal prompt displays <code>/home/student</code>, then proceed with the exercises below!</div></div>\\n<hr class=\\"divider\\">\\n<h3 id=\\"31-step-1-navigating--inspecting-your-workspace\\">3.1 Step 1: Navigating &amp; Inspecting Your Workspace</h3>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">pwd</span>\\n      <span class=\\"cmd-title\\">Print Current Working Directory</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>pwd</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Prints the absolute filesystem path of the directory you are currently working in. Useful to orient yourself before creating or modifying files.</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"pwd\\n# Output: /home/student\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">pwd\\n# Output: /home/student</code></pre></div>\\n</div>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">ls -lah</span>\\n      <span class=\\"cmd-title\\">List Files with Detailed Permissions &amp; Sizes</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>ls [options] [path]</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Lists directory contents. Flag <code>-l</code> uses long format with permissions and owners, <code>-a</code> reveals hidden files (<code>.bashrc</code>), and <code>-h</code> formats file sizes in human-readable units (KB, MB).</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"ls -lah\\n# Displays: permissions, owner, size, and filenames including .bashrc\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">ls -lah\\n# Displays: permissions, owner, size, and filenames including .bashrc</code></pre></div>\\n</div>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">cd</span>\\n      <span class=\\"cmd-title\\">Change Working Directory</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>cd &lt;target_directory&gt;</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Changes your active shell location. Use <code>cd ~</code> to return to your home directory, <code>cd ..</code> to step up one level, and <code>cd -</code> to toggle back to the previous directory.</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# Ensure you are at your user home directory root\\ncd ~\\npwd\\n# Output: /home/student\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># Ensure you are at your user home directory root\\ncd ~\\npwd\\n# Output: /home/student</code></pre></div>\\n</div>\\n<hr class=\\"divider\\">\\n<h3 id=\\"32-step-2-creating-a-structured-robotics-workspace-amp-files\\">3.2 Step 2: Creating a Structured Robotics Workspace &amp;amp; Files</h3>\\n<p>Let&#x27;s build a clean robotics project folder <code class=\\"inline-code\\">~/robotics_lab</code> with dedicated subdirectories for configurations (<code class=\\"inline-code\\">config</code>), scripts (<code class=\\"inline-code\\">scripts</code>), and runtime logs (<code class=\\"inline-code\\">logs</code>).</p>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">mkdir / mkdir -p</span>\\n      <span class=\\"cmd-title\\">Create Directories (Single, Multiple &amp; Nested Trees)</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>mkdir &lt;dir&gt;</code> | <code>mkdir &lt;d1&gt; &lt;d2&gt;</code> | <code>mkdir -p &lt;parent/child&gt;</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Creates new directories. You can create a single directory, multiple directories in one command by separating names with spaces, or entire nested directory hierarchies using the <code>-p</code> (parents) flag.</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# 1. Create a single directory:\\nmkdir my_robot_test\\n\\n# 2. Create multiple separate directories at once (separated by spaces):\\nmkdir sensors actuators telemetry\\n\\n# 3. Create nested directory hierarchies automatically using -p (parents flag):\\nmkdir -p ~/robotics_lab/config ~/robotics_lab/scripts ~/robotics_lab/logs\\n\\n# Clean up temporary practice folders:\\nrm -rf my_robot_test sensors actuators telemetry\\n\\n# Verify the structured robotics lab directories exist:\\nls -la ~/robotics_lab\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># 1. Create a single directory:\\nmkdir my_robot_test\\n\\n# 2. Create multiple separate directories at once (separated by spaces):\\nmkdir sensors actuators telemetry\\n\\n# 3. Create nested directory hierarchies automatically using -p (parents flag):\\n# Without -p, Linux throws &quot;No such file or directory&quot; if parent folders do not exist.\\n# With -p, missing parents are generated automatically without errors:\\nmkdir -p ~/robotics_lab/config ~/robotics_lab/scripts ~/robotics_lab/logs\\n\\n# Clean up temporary practice folders:\\nrm -rf my_robot_test sensors actuators telemetry\\n\\n# Verify the structured robotics lab directories exist:\\nls -la ~/robotics_lab</code></pre></div>\\n</div>\\n</div>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">echo &gt; &gt;&gt;</span>\\n      <span class=\\"cmd-title\\">Create &amp; Append Configuration Files</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>echo \\"text\\" &gt; file</code> (create/overwrite) | <code>echo \\"text\\" &gt;&gt; file</code> (append)</span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Emits text strings. The <code>&gt;</code> redirection operator writes output to a file (creating it or overwriting existing content), while <code>&gt;&gt;</code> appends new lines to the end of an existing file.</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"echo &quot;robot_model: navpro_mini&quot; &gt; ~/robotics_lab/config/robot_params.yaml\\necho &quot;max_linear_velocity: 0.5&quot; &gt;&gt; ~/robotics_lab/config/robot_params.yaml\\necho &quot;lidar_topic: /scan&quot; &gt;&gt; ~/robotics_lab/config/robot_params.yaml\\n\\n# Inspect the written configuration:\\ncat ~/robotics_lab/config/robot_params.yaml\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">echo &quot;robot_model: navpro_mini&quot; &gt; ~/robotics_lab/config/robot_params.yaml\\necho &quot;max_linear_velocity: 0.5&quot; &gt;&gt; ~/robotics_lab/config/robot_params.yaml\\necho &quot;lidar_topic: /scan&quot; &gt;&gt; ~/robotics_lab/config/robot_params.yaml\\n\\n# Inspect the written configuration:\\ncat ~/robotics_lab/config/robot_params.yaml</code></pre></div>\\n</div>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">touch</span>\\n      <span class=\\"cmd-title\\">Create Empty Placeholder Files</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>touch &lt;file_path&gt;</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Creates an empty 0-byte file if it does not already exist, or updates the file's last-modified timestamp without altering its contents.</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"touch ~/robotics_lab/scripts/diagnostics.sh\\necho &quot;Pre-flight test initialization completed at $(date)&quot; &gt; ~/robotics_lab/logs/boot_temp.log\\n\\n# Verify both files now exist on disk:\\nls -l ~/robotics_lab/scripts/ ~/robotics_lab/logs/\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">touch ~/robotics_lab/scripts/diagnostics.sh\\necho &quot;Pre-flight test initialization completed at $(date)&quot; &gt; ~/robotics_lab/logs/boot_temp.log\\n\\n# Verify both files now exist on disk:\\nls -l ~/robotics_lab/scripts/ ~/robotics_lab/logs/</code></pre></div>\\n</div>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">cp / cp -r</span>\\n      <span class=\\"cmd-title\\">Copy Files &amp; Recursive Directories</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>cp [options] &lt;source&gt; &lt;destination&gt;</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Copies files or folders to a target location. Use flag <code>-r</code> (recursive) to copy an entire directory and all nested files within it.</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# 1. Create a safety backup copy of the robot config file\\ncp ~/robotics_lab/config/robot_params.yaml ~/robotics_lab/config/robot_params_backup.yaml\\n\\n# 2. Copy the entire scripts directory recursively (-r)\\ncp -r ~/robotics_lab/scripts ~/robotics_lab/scripts_backup\\n\\n# Verify both backup copies exist:\\nls -l ~/robotics_lab/config/\\nls -la ~/robotics_lab/scripts_backup/\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># 1. Create a safety backup copy of the robot config file\\ncp ~/robotics_lab/config/robot_params.yaml ~/robotics_lab/config/robot_params_backup.yaml\\n\\n# 2. Copy the entire scripts directory recursively (-r)\\ncp -r ~/robotics_lab/scripts ~/robotics_lab/scripts_backup\\n\\n# Verify both backup copies exist:\\nls -l ~/robotics_lab/config/\\nls -la ~/robotics_lab/scripts_backup/</code></pre></div>\\n</div>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">mv</span>\\n      <span class=\\"cmd-title\\">Move or Rename Files &amp; Directories</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>mv &lt;source&gt; &lt;destination&gt;</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Moves files or folders to a new directory path, or renames them in place when the source and destination reside within the same parent folder.</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# 1. Rename diagnostics.sh to sensor_diagnostics.sh in place\\nmv ~/robotics_lab/scripts/diagnostics.sh ~/robotics_lab/scripts/sensor_diagnostics.sh\\n\\n# 2. Move the backup config into the logs directory for archiving\\nmv ~/robotics_lab/config/robot_params_backup.yaml ~/robotics_lab/logs/archived_params.yaml\\n\\n# Verify updates:\\nls -l ~/robotics_lab/scripts/\\nls -l ~/robotics_lab/logs/\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># 1. Rename diagnostics.sh to sensor_diagnostics.sh in place\\nmv ~/robotics_lab/scripts/diagnostics.sh ~/robotics_lab/scripts/sensor_diagnostics.sh\\n\\n# 2. Move the backup config into the logs directory for archiving\\nmv ~/robotics_lab/config/robot_params_backup.yaml ~/robotics_lab/logs/archived_params.yaml\\n\\n# Verify updates:\\nls -l ~/robotics_lab/scripts/\\nls -l ~/robotics_lab/logs/</code></pre></div>\\n</div>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">rm / rm -rf</span>\\n      <span class=\\"cmd-title\\">Safe File &amp; Directory Cleanup</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>rm [options] &lt;target_path&gt;</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Deletes files or directories permanently. Flag <code>-r</code> enables recursive directory deletion, and <code>-f</code> (force) suppresses confirmation prompts and ignores non-existent files.</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# 1. Remove the temporary test log file\\nrm ~/robotics_lab/logs/boot_temp.log\\n\\n# 2. Recursively force delete the scripts_backup directory\\nrm -rf ~/robotics_lab/scripts_backup\\n\\n# Confirm clean workspace structure:\\nls -la ~/robotics_lab/\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># 1. Remove the temporary test log file\\nrm ~/robotics_lab/logs/boot_temp.log\\n\\n# 2. Recursively force delete the scripts_backup directory\\nrm -rf ~/robotics_lab/scripts_backup\\n\\n# Confirm clean workspace structure:\\nls -la ~/robotics_lab/</code></pre></div>\\n</div>\\n<hr class=\\"divider\\">\\n<h3 id=\\"33-step-3-inspecting-reading-amp-searching-files\\">3.3 Step 3: Inspecting, Reading &amp;amp; Searching Files</h3>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">cat</span>\\n      <span class=\\"cmd-title\\">Display Full File Contents</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>cat &lt;file_path&gt;</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Concatenates and streams the entire contents of a file directly to standard output. Best suited for short configuration files and scripts.</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"cat ~/robotics_lab/config/robot_params.yaml\\n\\n# Output:\\n# robot_model: navpro_mini\\n# max_linear_velocity: 0.5\\n# lidar_topic: /scan\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">cat ~/robotics_lab/config/robot_params.yaml\\n\\n# Output:\\n# robot_model: navpro_mini\\n# max_linear_velocity: 0.5\\n# lidar_topic: /scan</code></pre></div>\\n</div>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">head / tail</span>\\n      <span class=\\"cmd-title\\">Inspect Top or Bottom Lines of Files</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>head -n &lt;N&gt; &lt;file&gt;</code> | <code>tail -f &lt;file&gt;</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\"><code>head</code> prints the first $N$ lines of a file; <code>tail</code> prints the last $N$ lines. Flag <code>-f</code> with <code>tail</code> follows live logs in real-time as background daemons write new data.</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# View the first 5 lines of network hosts\\nhead -n 5 /etc/hosts\\n\\n# Output displays: 127.0.0.1 localhost, ::1 ip6-localhost...\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># View the first 5 lines of network hosts\\nhead -n 5 /etc/hosts\\n\\n# Output displays: 127.0.0.1 localhost, ::1 ip6-localhost...</code></pre></div>\\n</div>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">grep -rn</span>\\n      <span class=\\"cmd-title\\">Search Text Patterns Across Files &amp; Folders</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>grep [options] \\"&lt;pattern&gt;\\" &lt;path&gt;</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Searches text lines matching a query. Flag <code>-r</code> searches recursively through directories, and <code>-n</code> displays the exact line number of each match.</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# Search recursively for &quot;navpro&quot; inside our robotics lab workspace\\ngrep -rn &quot;navpro&quot; ~/robotics_lab/\\n\\n# Output:\\n# /home/student/robotics_lab/config/robot_params.yaml:1:robot_model: navpro_mini\\n# /home/student/robotics_lab/logs/archived_params.yaml:1:robot_model: navpro_mini\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># Search recursively for &quot;navpro&quot; inside our robotics lab workspace\\ngrep -rn &quot;navpro&quot; ~/robotics_lab/\\n\\n# Output:\\n# /home/student/robotics_lab/config/robot_params.yaml:1:robot_model: navpro_mini\\n# /home/student/robotics_lab/logs/archived_params.yaml:1:robot_model: navpro_mini</code></pre></div>\\n</div>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">| (Pipe)</span>\\n      <span class=\\"cmd-title\\">Piping Output: Filter &amp; Chain Commands (cat | grep)</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>command_1 | command_2</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">The <strong>Pipe (<code>|</code>)</strong> operator takes the Standard Output (<code>stdout</code>) of the command on the left and redirects it directly into the Standard Input (<code>stdin</code>) of the command on the right. In robotics, combining <code>cat</code> with <code>grep</code> is an indispensable technique for instantly filtering configuration files, system parameters, and diagnostic logs without scrolling through hundreds of lines.</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# 1. Pipe file contents from 'cat' into 'grep' to filter specific robot parameters:\\ncat ~/robotics_lab/config/robot_params.yaml | grep &quot;velocity&quot;\\n\\n# 2. Inspect operating system release information by piping cat into grep:\\ncat /etc/os-release | grep &quot;PRETTY_NAME&quot;\\n\\n# 3. Practical Robotics Real-World Examples:\\n# - Filter live ROS 2 topic streams:  ros2 topic list | grep cmd_vel\\n# - Filter system error logs:         cat /var/log/syslog | grep -i error\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># 1. Pipe file contents from &#x27;cat&#x27; into &#x27;grep&#x27; to filter specific robot parameters:\\ncat ~/robotics_lab/config/robot_params.yaml | grep &quot;velocity&quot;\\n# Output: max_linear_velocity: 0.5\\n\\n# 2. Inspect operating system release information by piping cat into grep:\\ncat /etc/os-release | grep &quot;PRETTY_NAME&quot;\\n# Output: PRETTY_NAME=&quot;Ubuntu 24.04 LTS&quot;\\n\\n# 3. Practical Robotics Real-World Examples:\\n# - Filter live ROS 2 topic streams:  ros2 topic list | grep cmd_vel\\n# - Filter system error logs:         cat /var/log/syslog | grep -i error</code></pre></div>\\n</div>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">&amp;&amp; / ; / ||</span>\\n      <span class=\\"cmd-title\\">Executing Multiple Commands in a Single Line</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>cmd1 &amp;&amp; cmd2</code> | <code>cmd1 ; cmd2</code> | <code>cmd1 || cmd2</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">In Linux, you can chain multiple commands onto a single command line using three operators depending on whether you want subsequent commands to depend on previous success, run unconditionally, or act as an error fallback.</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# 1. The '&&' Operator (Logical AND - Run next ONLY IF previous command succeeded):\\ncd ~/robotics_lab && ls -la\\n\\n# The Gold Standard ROS 2 Build & Source workflow:\\n# cd ~/ros2_ws && colcon build --symlink-install && source install/setup.bash\\n\\n# 2. The ';' Semicolon (Sequential Execution - Run regardless of success or failure):\\necho &quot;Starting pre-flight check...&quot; ; ls -l ~/robotics_lab ; echo &quot;Pre-flight check complete.&quot;\\n\\n# 3. The '||' Operator (Logical OR - Run next ONLY IF previous command failed):\\ngrep &quot;camera_topic&quot; ~/robotics_lab/config/robot_params.yaml || echo &quot;⚠️ Warning: Camera parameter not found in config!&quot;\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># 1. The &#x27;&amp;&amp;&#x27; Operator (Logical AND - Run next ONLY IF previous command succeeded):\\n# If the first command fails, execution halts immediately. Crucial for robotics builds!\\ncd ~/robotics_lab &amp;&amp; ls -la\\n\\n# The Gold Standard ROS 2 Build &amp; Source workflow:\\n# (If compilation fails, it will NOT attempt to source broken binaries):\\n# cd ~/ros2_ws &amp;&amp; colcon build --symlink-install &amp;&amp; source install/setup.bash\\n\\n# 2. The &#x27;;&#x27; Semicolon (Sequential Execution - Run regardless of success or failure):\\n# Commands run one after another in order, even if an earlier command threw an error:\\necho &quot;Starting pre-flight check...&quot; ; ls -l ~/robotics_lab ; echo &quot;Pre-flight check complete.&quot;\\n\\n# 3. The &#x27;||&#x27; Operator (Logical OR - Run next ONLY IF previous command failed):\\n# Perfect for error alerts and fallback defaults:\\ngrep &quot;camera_topic&quot; ~/robotics_lab/config/robot_params.yaml || echo &quot;⚠️ Warning: Camera parameter not found in config!&quot;</code></pre></div>\\n</div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-file-permissions-making-shell-scripts-executable\\">4. File Permissions: Making Shell Scripts Executable</h2>\\n<p>When you create a script in Linux, it is created without execution permissions by default. Attempting to run it directly triggers:</p>\\n<div class=\\"code-container\\" data-language=\\"text\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">TEXT</span><button class=\\"copy-code-btn\\" data-code=\\"bash: ./diagnostics.sh: Permission denied\\">📋 Copy</button></div><pre><code class=\\"language-text\\">bash: ./diagnostics.sh: Permission denied</code></pre></div>\\n<h3 id=\\"41-understanding-the-permission-string\\">4.1 Understanding the Permission String</h3>\\n<p>Running <code class=\\"inline-code\\">ls -l</code> outputs a 10-character permission string:</p>\\n<div class=\\"code-container\\" data-language=\\"text\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">TEXT</span><button class=\\"copy-code-btn\\" data-code=\\"-rwxr-xr-x 1 student student 1420 Oct 13 10:00 diagnostics.sh\\n │├──┘├──┘└── Others permissions (Read, Execute)\\n ││   └── Group permissions (Read, Execute)\\n │└── User (Owner) permissions: Read (r), Write (w), Execute (x)\\n └── File type: &#x27;-&#x27; = regular file, &#x27;d&#x27; = directory\\">📋 Copy</button></div><pre><code class=\\"language-text\\">-rwxr-xr-x 1 student student 1420 Oct 13 10:00 diagnostics.sh\\n │├──┘├──┘└── Others permissions (Read, Execute)\\n ││   └── Group permissions (Read, Execute)\\n │└── User (Owner) permissions: Read (r), Write (w), Execute (x)\\n └── File type: &#x27;-&#x27; = regular file, &#x27;d&#x27; = directory</code></pre></div>\\n<p>Each triplet represents:</p>\\n<ul class=\\"lesson-bullet-list\\">\\n<li><strong><code class=\\"inline-code\\">r</code> (Read = 4):</strong> View file contents.</li>\\n<li><strong><code class=\\"inline-code\\">w</code> (Write = 2):</strong> Modify or delete file.</li>\\n<li><strong><code class=\\"inline-code\\">x</code> (Execute = 1):</strong> Execute the file as a program.</li>\\n</ul>\\n<h3 id=\\"42-hands-on-exercise-creating-amp-running-an-executable-script\\">4.2 Hands-On Exercise: Creating &amp;amp; Running an Executable Script</h3>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">chmod +x</span>\\n      <span class=\\"cmd-title\\">Grant Executable Permission to Shell Script</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>chmod +x &lt;script_file&gt;</code> | <code>chmod 755 &lt;script_file&gt;</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Modifies file access permissions. Flag <code>+x</code> grants execution rights so the operating system can run the script directly as an independent program.</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# Step 1: Create a real diagnostic script inside ~/robotics_lab/scripts/\\ncat &lt;&lt; &#x27;EOF&#x27; &gt; ~/robotics_lab/scripts/system_check.sh\\n#!/bin/bash\\necho &quot;==========================================&quot;\\necho &quot;      ROBOT SUBSYSTEM PRE-FLIGHT CHECK    &quot;\\necho &quot;==========================================&quot;\\necho &quot;Timestamp:    $(date)&quot;\\necho &quot;Kernel:       $(uname -r)&quot;\\necho &quot;Architecture: $(uname -m)&quot;\\necho &quot;Free Memory:  $(free -h | awk &#x27;/^Mem:/ {print $4}&#x27;)&quot;\\necho &quot;All host subsystems operating normally!&quot;\\necho &quot;==========================================&quot;\\nEOF\\n\\n# Step 2: Try running the script directly (triggers Permission denied)\\n~/robotics_lab/scripts/system_check.sh\\n\\n# Step 3: Grant executable permission (+x)\\nchmod +x ~/robotics_lab/scripts/system_check.sh\\n\\n# Step 4: Run the script successfully!\\n~/robotics_lab/scripts/system_check.sh\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># Step 1: Create a real diagnostic script inside ~/robotics_lab/scripts/\\ncat &lt;&lt; &#x27;EOF&#x27; &gt; ~/robotics_lab/scripts/system_check.sh\\n#!/bin/bash\\necho &quot;==========================================&quot;\\necho &quot;      ROBOT SUBSYSTEM PRE-FLIGHT CHECK    &quot;\\necho &quot;==========================================&quot;\\necho &quot;Timestamp:    $(date)&quot;\\necho &quot;Kernel:       $(uname -r)&quot;\\necho &quot;Architecture: $(uname -m)&quot;\\necho &quot;Free Memory:  $(free -h | awk &#x27;/^Mem:/ {print $4}&#x27;)&quot;\\necho &quot;All host subsystems operating normally!&quot;\\necho &quot;==========================================&quot;\\nEOF\\n\\n# Step 2: Try running the script directly (triggers Permission denied)\\n~/robotics_lab/scripts/system_check.sh\\n\\n# Step 3: Grant executable permission (+x)\\nchmod +x ~/robotics_lab/scripts/system_check.sh\\n\\n# Step 4: Run the script successfully!\\n~/robotics_lab/scripts/system_check.sh</code></pre></div>\\n</div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-process-management-amp-background-jobs\\">5. Process Management &amp;amp; Background Jobs</h2>\\n<p>Robotics systems run multiple programs simultaneously (LiDAR driver, SLAM, motor controllers). You must know how to inspect resource usage, start background jobs, and terminate stalled processes.</p>\\n<h3 id=\\"51-monitoring-running-processes\\">5.1 Monitoring Running Processes</h3>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">sleep &amp; / ps aux</span>\\n      <span class=\\"cmd-title\\">Launch Background Jobs &amp; Inspect Processes</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>&lt;cmd&gt; &amp;</code> | <code>ps aux | grep &lt;name&gt;</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Appending <code>&amp;</code> to any command runs it as a background job, freeing your terminal immediately. <code>ps aux</code> lists all running processes with user, PID, CPU, memory, and command path.</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# 1. Start a harmless sleep process in the background using the &#x27;&amp;&#x27; operator\\nsleep 300 &amp;\\n# Output: [1] 42109\\n\\n# 2. Filter active processes to find our background sleep job:\\nps aux | grep sleep\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># 1. Start a harmless sleep process in the background using the &#x27;&amp;&#x27; operator\\nsleep 300 &amp;\\n# Output: [1] 42109\\n\\n# 2. Filter active processes to find our background sleep job:\\nps aux | grep sleep</code></pre></div>\\n</div>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">top</span>\\n      <span class=\\"cmd-title\\">Interactive System Resource Task Manager</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>top</code> (press 'q' to exit)</span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Interactive real-time process viewer displaying total CPU usage, memory utilization, and active process states sorted by resource consumption.</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"top\\n# Displays live PID table, memory load, and CPU %. Press &#x27;q&#x27; to exit.\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">top\\n# Displays live PID table, memory load, and CPU %. Press &#x27;q&#x27; to exit.</code></pre></div>\\n</div>\\n<h3 id=\\"52-terminating-processes-cleanly\\">5.2 Terminating Processes Cleanly</h3>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">kill / killall</span>\\n      <span class=\\"cmd-title\\">Terminate Background Processes Cleanly</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>kill &lt;PID&gt;</code> | <code>kill -9 &lt;PID&gt;</code> | <code>killall &lt;name&gt;</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Sends POSIX termination signals. Standard <code>kill</code> sends SIGTERM (graceful shutdown); <code>kill -9</code> sends SIGKILL (forced instant halt); <code>killall</code> terminates all processes matching a binary name.</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# 1. Terminate all running sleep test processes cleanly\\nkillall sleep\\n\\n# 2. Verify the process has terminated (returns only grep itself):\\nps aux | grep sleep\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># 1. Terminate all running sleep test processes cleanly\\nkillall sleep\\n\\n# 2. Verify the process has terminated (returns only grep itself):\\nps aux | grep sleep</code></pre></div>\\n</div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-shell-automation-with-bashrc\\">6. Shell Automation with <code class=\\"inline-code\\">~/.bashrc</code></h2>\\n<p>Every time you launch a new terminal, Linux reads and executes <code class=\\"inline-code\\">~/.bashrc</code>. You can define custom shortcut aliases to streamline daily terminal operations:</p>\\n<div class=\\"cmd-card\\">\\n  <div class=\\"cmd-header\\">\\n    <div class=\\"cmd-header-left\\">\\n      <span class=\\"cmd-badge\\">alias / source</span>\\n      <span class=\\"cmd-title\\">Shell Shortcuts &amp; Automated Sourcing</span>\\n    </div>\\n    <span class=\\"cmd-syntax\\">Syntax: <code>alias &lt;key&gt;='&lt;command&gt;'</code> | <code>source &lt;file&gt;</code></span>\\n  </div>\\n  <p class=\\"cmd-desc\\">Defines persistent shortcuts in <code>~/.bashrc</code>. The <code>source</code> command reloads the configuration in the active terminal immediately without restarting the shell.</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# 1. Append productivity shortcuts to ~/.bashrc:\\necho &#x27;alias ll=&quot;ls -lah&quot;&#x27; &gt;&gt; ~/.bashrc\\necho &#x27;alias c=&quot;clear&quot;&#x27; &gt;&gt; ~/.bashrc\\necho &#x27;alias lab=&quot;cd ~/robotics_lab&quot;&#x27; &gt;&gt; ~/.bashrc\\necho &#x27;alias myip=&quot;hostname -I | awk &#x27;\\\\&#x27;&#x27;{print \\\\$1}&#x27;\\\\&#x27;&#x27;&quot;&#x27; &gt;&gt; ~/.bashrc\\n\\n# 2. Reload bash configuration in current active terminal:\\nsource ~/.bashrc\\n\\n# 3. Test your custom shortcut:\\nlab\\npwd\\n# Output: /home/student/robotics_lab\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># 1. Append productivity shortcuts to ~/.bashrc:\\necho &#x27;alias ll=&quot;ls -lah&quot;&#x27; &gt;&gt; ~/.bashrc\\necho &#x27;alias c=&quot;clear&quot;&#x27; &gt;&gt; ~/.bashrc\\necho &#x27;alias lab=&quot;cd ~/robotics_lab&quot;&#x27; &gt;&gt; ~/.bashrc\\necho &#x27;alias myip=&quot;hostname -I | awk &#x27;\\\\&#x27;&#x27;{print \\\\$1}&#x27;\\\\&#x27;&#x27;&quot;&#x27; &gt;&gt; ~/.bashrc\\n\\n# 2. Reload bash configuration in current active terminal:\\nsource ~/.bashrc\\n\\n# 3. Test your custom shortcut:\\nlab\\npwd\\n# Output: /home/student/robotics_lab</code></pre></div>\\n</div>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\">In <strong>Lesson 02</strong>, we will add your ROS 2 underlay paths (<code class=\\"inline-code\\">/opt/ros/jazzy/setup.bash</code>) to this file so every terminal is automatically primed for robotics programming!</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"7-multi-pane-terminal-workflows-terminator\\">7. Multi-Pane Terminal Workflows (Terminator)</h2>\\n<p>Robotics workflows often require 3–4 terminal windows running concurrently (simulation, sensors, visualization, commands). <strong>Terminator</strong> allows splitting your screen into a clean multi-terminal grid:</p>\\n<div class=\\"lesson-image-wrapper\\"><img src=\\"assets/images/terminator_layout.svg\\" alt=\\"Terminator Multi-Pane Layout\\" class=\\"lesson-image\\" loading=\\"lazy\\"><span class=\\"image-caption\\">Terminator Multi-Pane Layout</span></div>\\n<div class=\\"table-wrapper\\"><table>\\n<thead><tr>\\n<th>Shortcut</th>\\n<th>Function</th>\\n<th>Purpose in Robotics</th>\\n</tr></thead><tbody>\\n<tr>\\n<td><code class=\\"inline-code\\">Ctrl + Shift + O</code></td>\\n<td><strong>Split Horizontally</strong></td>\\n<td>Creates top and bottom terminal panes</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">Ctrl + Shift + E</code></td>\\n<td><strong>Split Vertically</strong></td>\\n<td>Creates left and right terminal panes</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">Alt + Arrow Keys</code></td>\\n<td><strong>Navigate Active Panes</strong></td>\\n<td>Switch focus quickly without touching mouse</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">Ctrl + Shift + X</code></td>\\n<td><strong>Maximize / Restore Active Pane</strong></td>\\n<td>Zoom in on a busy node log</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">Ctrl + Shift + W</code></td>\\n<td><strong>Close Current Pane</strong></td>\\n<td>Safely exit an active terminal session</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">Alt + A</code></td>\\n<td><strong>Broadcast Keystrokes to All Panes</strong></td>\\n<td>Send identical commands across multiple panes</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">Alt + O</code></td>\\n<td><strong>Disable Broadcast Mode</strong></td>\\n<td>Return to independent pane control</td>\\n</tr>\\n</tbody></table></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"8--pro-tips-amp-hardware-reference\\">8. 💡 Pro-Tips &amp;amp; Hardware Reference</h2>\\n<div class=\\"alert-callout alert-tip\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\">Connecting Physical USB Sensors (Microcontrollers &amp; LiDARs)<br>If plugging in an external USB microcontroller (ESP32, Arduino) or LiDAR produces <code class=\\"inline-code\\">Permission denied: /dev/ttyUSB0</code>, grant your user serial permissions once:<br><div class=\\"code-container\\"><pre><code>sudo usermod -a -G dialout $USER</code></pre></div><br>Then log out and log back in (or run <code class=\\"inline-code\\">newgrp dialout</code>).</div></div>\\n<div class=\\"alert-callout alert-tip\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\">Searching Bash Command History<br>Press <code class=\\"inline-code\\">Ctrl + R</code> in any terminal and start typing a previous command (e.g. <code class=\\"inline-code\\">system_check</code>) to search and auto-complete your command history without retyping.</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"9-summary-amp-next-steps\\">9. Summary &amp;amp; Next Steps</h2>\\n<p>You now have a solid command of Linux engineering fundamentals:</p>\\n<ul class=\\"lesson-bullet-list\\">\\n<li><strong>Navigated the filesystem hierarchy</strong> and inspected essential system paths.</li>\\n<li><strong>Created and managed files</strong> in an organized robotics project workspace.</li>\\n<li><strong>Created shell scripts and granted execution rights</strong> using <code class=\\"inline-code\\">chmod +x</code>.</li>\\n<li><strong>Managed background processes</strong> and monitored resource consumption with <code class=\\"inline-code\\">top</code> and <code class=\\"inline-code\\">killall</code>.</li>\\n<li><strong>Configured productivity aliases</strong> in <code class=\\"inline-code\\">~/.bashrc</code>.</li>\\n</ul>\\n<p>In <strong><a href=\\"#/lesson/02\\" class=\\"internal-lesson-link\\" data-lesson=\\"02\\">Lesson 02</a></strong>, we build on these Linux foundations to install our robotics stack: exploring ROS 2 Jazzy architecture, the peer-to-peer DDS middleware, and containerized Docker setup!</p>","quizzes":[{"id":"q_l1_01_1","prompt":"Which Linux command is required to make a newly created Python node script executable by the ROS 2 runtime?","options":["chmod -R 777 script.py","chmod +x script.py","chown student:student script.py","source script.py"],"correct":1,"explanation":"chmod +x grants execution permissions to the script. While 777 also grants execution, it is an insecure antipattern in production robotics. chmod +x is the targeted industry standard."},{"id":"q_l1_01_2","prompt":"What does running 'source ~/.bashrc' achieve in an active terminal session?","options":["It restarts the Linux kernel and graphics drivers","It reloads environment variables, ROS 2 underlay paths, and aliases without closing the shell","It permanently writes current bash history to NVMe disk","It kills all running ROS 2 nodes"],"correct":1,"explanation":"source ~/.bashrc re-executes the user profile in the active shell context, updating paths like $ROS_DISTRO and custom aliases without requiring the engineer to spawn a new terminal window."}],"has_quiz":true,"next_id":"lesson_02","prev_id":null},{"id":"lesson_02","num":2,"num_str":"02","title":"ROS 2 Overview & Environment Setup","slug":"ros2_overview_and_environment_setup","filename":"02_ros2_overview_and_environment_setup.md","module":"Foundations & Core Middleware","module_id":1,"duration":"45-60 min","focus":"Python-Only Robotics Engineering Workflow","snapshot":[["Peer-to-Peer DDS","Zero master bottleneck (roscore eliminated); nodes discover each other dynamically."],["ROS 2 Jazzy LTS","Standardized on Ubuntu 24.04 Noble Numbat and Python 3.12 with enhanced DDS performance."],["Terminator","Manage bringup, teleoperation, RViz, and telemetry in a single split-window layout."]],"html_content":"<h1 id=\\"lesson-02-ros-2-overview--environment-setup\\">Lesson 02: ROS 2 Overview &amp; Environment Setup</h1>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Focus:</strong> Python-Only Robotics Engineering Workflow<br><strong>Course Track:</strong> NavPro Learning Hub - Level 1<br><strong>Target Environment:</strong> Ubuntu 24.04 LTS / Docker Container with ROS 2 Jazzy Jalisco</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"1-overview--learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>Welcome to the foundation of modern robotics software engineering. This tutorial introduces <strong>Robot Operating System 2 (ROS 2)</strong>, the global standard for building commercial autonomous robots.</p>\\n<p>By the end of this lesson, you will:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Understand the core architectural differences between ROS 1 and ROS 2 (DDS middleware vs. Master node).</li>\\n<li>Learn the release lifecycle and why <strong>ROS 2 Jazzy Jalisco</strong> on Ubuntu 24.04 is the industry benchmark.</li>\\n<li>Install and configure a complete ROS 2 development workstation (Native Ubuntu or Containerized Docker).</li>\\n<li>Configure multi-terminal development tooling with <strong>Terminator</strong> and <strong>VS Code</strong>.</li>\\n<li>Set up automatic shell environment sourcing and productivity aliases.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-hardware-and-software-prerequisites\\">2. Hardware and Software Prerequisites</h2>\\n<div class=\\"table-wrapper\\"><table>\\n<thead><tr>\\n<th>Component</th>\\n<th>Specification</th>\\n<th>Purpose</th>\\n</tr></thead><tbody>\\n<tr>\\n<td><strong>Operating System</strong></td>\\n<td>Ubuntu 24.04 LTS (Noble Numbat) or Docker</td>\\n<td>Base OS supporting ROS 2 Jazzy</td>\\n</tr>\\n<tr>\\n<td><strong>Processor</strong></td>\\n<td>x86_64 or ARM64 (e.g. Jetson Orin, Raspberry Pi 5)</td>\\n<td>Host compute</td>\\n</tr>\\n<tr>\\n<td><strong>RAM</strong></td>\\n<td>Minimum 8 GB (16 GB recommended for Gazebo sim)</td>\\n<td>Colcon builds and simulation</td>\\n</tr>\\n<tr>\\n<td><strong>ROS 2 Distro</strong></td>\\n<td><strong>ROS 2 Jazzy Jalisco</strong> (LTS until May 2027)</td>\\n<td>Robotics middleware</td>\\n</tr>\\n<tr>\\n<td><strong>Python</strong></td>\\n<td>Python 3.12+</td>\\n<td>Primary programming language</td>\\n</tr>\\n<tr>\\n<td><strong>Editor</strong></td>\\n<td>Visual Studio Code (or Web code-server)</td>\\n<td>Code development &amp; debugging</td>\\n</tr>\\n<tr>\\n<td><strong>Terminal</strong></td>\\n<td>Terminator or tmux</td>\\n<td>Multi-pane ROS 2 CLI monitoring</td>\\n</tr>\\n</tbody></table></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-what-is-ros-2\\">3. What is ROS 2?</h2>\\n<p><strong>ROS 2</strong> is not a traditional operating system like Linux or Windows. It is a <strong>meta-operating system</strong>—a modular software framework and middleware suite providing:</p>\\n<ul class=\\"lesson-bullet-list\\">\\n<li><strong>Hardware Abstraction:</strong> Drivers for LiDARs, depth cameras, IMUs, motor controllers.</li>\\n<li><strong>Inter-Process Communication (IPC):</strong> Standardized message passing between isolated processes (Nodes).</li>\\n<li><strong>Package Management:</strong> Modular build, dependency, and release tooling via <code class=\\"inline-code\\">colcon</code> and <code class=\\"inline-code\\">rosdep</code>.</li>\\n<li><strong>Ecosystem Libraries:</strong> Advanced algorithms for 2D/3D SLAM (<code class=\\"inline-code\\">slam_toolbox</code>), path planning (<code class=\\"inline-code\\">Nav2</code>), perception (<code class=\\"inline-code\\">OpenCV</code>), and kinematics (<code class=\\"inline-code\\">TF2</code>).</li>\\n</ul>\\n<h3 id=\\"31-ros-1-vs-ros-2-the-architectural-paradigm-shift\\">3.1 ROS 1 vs. ROS 2: The Architectural Paradigm Shift</h3>\\n<div class=\\"lesson-image-wrapper\\"><img src=\\"assets/images/ros1_vs_ros2_dds.svg\\" alt=\\"ROS 1 vs ROS 2 DDS Architectural Comparison\\" class=\\"lesson-image\\" loading=\\"lazy\\"><span class=\\"image-caption\\">ROS 1 vs ROS 2 DDS Architectural Comparison</span></div>\\n<p>Key evolutions in ROS 2:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li><strong>No Master Node (<code class=\\"inline-code\\">roscore</code> eliminated):</strong> In ROS 1, if <code class=\\"inline-code\\">roscore</code> crashed, the entire robot halted. In ROS 2, nodes automatically discover each other over the local network via peer-to-peer <strong>DDS (Data Distribution Service)</strong> discovery.</li>\\n<li><strong>Industrial Quality of Service (QoS):</strong> Customize delivery guarantees per topic (e.g., Best Effort for high-rate sensor streams vs. Reliable for safety commands).</li>\\n<li><strong>Native Multi-Robot Networking:</strong> Robots on the same network communicate seamlessly using isolated <code class=\\"inline-code\\">ROS_DOMAIN_ID</code> channels.</li>\\n<li><strong>Modern Python 3 Standard:</strong> Pure Python 3 architecture with asynchronous execution (<code class=\\"inline-code\\">asyncio</code> and <code class=\\"inline-code\\">rclpy.executors</code>).</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-ros-2-release-timeline\\">4. ROS 2 Release Timeline</h2>\\n<p>ROS 2 releases are named alphabetically after adjectives and marine/amphibian species:</p>\\n<div class=\\"table-wrapper\\"><table>\\n<thead><tr>\\n<th>Release Name</th>\\n<th>Target Ubuntu</th>\\n<th>Release Date</th>\\n<th>End of Life (EOL)</th>\\n<th>Industry Status</th>\\n</tr></thead><tbody>\\n<tr>\\n<td>Foxy Fitzroy</td>\\n<td>Ubuntu 20.04 LTS</td>\\n<td>June 2020</td>\\n<td>May 2023</td>\\n<td>End of Life</td>\\n</tr>\\n<tr>\\n<td>Galactic Geochelone</td>\\n<td>Ubuntu 20.04 LTS</td>\\n<td>May 2021</td>\\n<td>Nov 2022</td>\\n<td>End of Life</td>\\n</tr>\\n<tr>\\n<td>Humble Hawksbill</td>\\n<td>Ubuntu 22.04 LTS</td>\\n<td>May 2022</td>\\n<td>May 2027</td>\\n<td>Mature LTS</td>\\n</tr>\\n<tr>\\n<td>Iron Irwini</td>\\n<td>Ubuntu 22.04 LTS</td>\\n<td>May 2023</td>\\n<td>Nov 2024</td>\\n<td>End of Life</td>\\n</tr>\\n<tr>\\n<td><strong>Jazzy Jalisco</strong></td>\\n<td><strong>Ubuntu 24.04 LTS</strong></td>\\n<td><strong>May 2024</strong></td>\\n<td><strong>May 2029</strong></td>\\n<td><strong>Primary Recommended LTS (Workshop Standard)</strong></td>\\n</tr>\\n</tbody></table></div>\\n<div class=\\"alert-callout alert-important\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>ROS 2 Jazzy Jalisco</strong> on <strong>Ubuntu 24.04 LTS (Noble Numbat)</strong> represents the state-of-the-art long-term support release, featuring Python 3.12, native MCAP bag storage, enhanced FastDDS / CycloneDDS middleware, and the latest Nav2 autonomous navigation framework.</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-step-by-step-installation-on-ubuntu-2404-lts\\">5. Step-by-Step Installation on Ubuntu 24.04 LTS</h2>\\n<p>If installing natively on Ubuntu 24.04, follow these exact verified steps:</p>\\n<h3 id=\\"step-51-configure-locale-utf-8-verification\\">Step 5.1: Configure Locale (UTF-8 Verification)</h3>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\">[!SYNTAX]<br><strong>Command Syntax:</strong> <code class=\\"inline-code\\">locale</code> &amp;nbsp;|&amp;nbsp; <code class=\\"inline-code\\">sudo locale-gen &lt;locale&gt;</code> &amp;nbsp;|&amp;nbsp; <code class=\\"inline-code\\">sudo update-locale &lt;vars&gt;</code><br><strong>Description:</strong> ROS 2 requires an explicit UTF-8 locale environment to process character encoding in ROS message strings, logs, and telemetry packets.</div></div>\\n<p><strong>Hands-On Practical Command:</strong></p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"locale  # Verify output contains UTF-8\\n\\nsudo apt update &amp;&amp; sudo apt install -y locales\\nsudo locale-gen en_US en_US.UTF-8\\nsudo update-locale LC_ALL=en_US.UTF-8 LANG=en_US.UTF-8\\nexport LANG=en_US.UTF-8\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">locale  # Verify output contains UTF-8\\n\\nsudo apt update &amp;&amp; sudo apt install -y locales\\nsudo locale-gen en_US en_US.UTF-8\\nsudo update-locale LC_ALL=en_US.UTF-8 LANG=en_US.UTF-8\\nexport LANG=en_US.UTF-8</code></pre></div>\\n<hr class=\\"divider\\">\\n<h3 id=\\"step-52-enable-ubuntu-universe-repository\\">Step 5.2: Enable Ubuntu Universe Repository</h3>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\">[!SYNTAX]<br><strong>Command Syntax:</strong> <code class=\\"inline-code\\">sudo add-apt-repository &lt;repo_name&gt;</code><br><strong>Description:</strong> Enables the official Ubuntu Universe repository, which provides community-maintained open-source packages and build tools.</div></div>\\n<p><strong>Hands-On Practical Command:</strong></p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"sudo apt install -y software-properties-common\\nsudo add-apt-repository universe\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">sudo apt install -y software-properties-common\\nsudo add-apt-repository universe</code></pre></div>\\n<hr class=\\"divider\\">\\n<h3 id=\\"step-53-add-official-ros-2-gpg-key--apt-source\\">Step 5.3: Add Official ROS 2 GPG Key &amp; APT Source</h3>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\">[!SYNTAX]<br><strong>Command Syntax:</strong> <code class=\\"inline-code\\">curl -sSL &lt;key_url&gt; -o &lt;keyring_path&gt;</code> &amp;nbsp;|&amp;nbsp; <code class=\\"inline-code\\">tee /etc/apt/sources.list.d/&lt;list&gt;</code><br><strong>Description:</strong> Downloads OpenPGP archive keys into <code class=\\"inline-code\\">/usr/share/keyrings</code> and adds the official Open Robotics package repository to your APT sources list for cryptographically verified package installations.</div></div>\\n<p><strong>Hands-On Practical Command:</strong></p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"sudo apt update &amp;&amp; sudo apt install -y curl gnupg lsb-release\\n\\n# Download official ROS archive key\\nsudo curl -sSL https://raw.githubusercontent.com/ros/rosdistro/master/ros.key -o /usr/share/keyrings/ros-archive-keyring.gpg\\n\\n# Add ROS 2 repository to sources list\\necho &quot;deb [arch=$(dpkg --print-architecture) signed-by=/usr/share/keyrings/ros-archive-keyring.gpg] http://packages.ros.org/ros2/ubuntu $(. /etc/os-release &amp;&amp; echo $UBUNTU_CODENAME) main&quot; | sudo tee /etc/apt/sources.list.d/ros2.list &gt; /dev/null\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">sudo apt update &amp;&amp; sudo apt install -y curl gnupg lsb-release\\n\\n# Download official ROS archive key\\nsudo curl -sSL https://raw.githubusercontent.com/ros/rosdistro/master/ros.key -o /usr/share/keyrings/ros-archive-keyring.gpg\\n\\n# Add ROS 2 repository to sources list\\necho &quot;deb [arch=$(dpkg --print-architecture) signed-by=/usr/share/keyrings/ros-archive-keyring.gpg] http://packages.ros.org/ros2/ubuntu $(. /etc/os-release &amp;&amp; echo $UBUNTU_CODENAME) main&quot; | sudo tee /etc/apt/sources.list.d/ros2.list &gt; /dev/null</code></pre></div>\\n<hr class=\\"divider\\">\\n<h3 id=\\"step-54-install-ros-2-jazzy-desktop--build-tools\\">Step 5.4: Install ROS 2 Jazzy Desktop &amp; Build Tools</h3>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\">[!SYNTAX]<br><strong>Command Syntax:</strong> <code class=\\"inline-code\\">sudo apt install -y ros-jazzy-desktop python3-colcon-common-extensions</code><br><strong>Description:</strong> Installs the core ROS 2 libraries, RViz2 visualization, Gazebo integration packages, Python 3 bindings, and the Colcon build tool.</div></div>\\n<p><strong>Hands-On Practical Command:</strong></p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"sudo apt update\\nsudo apt install -y ros-jazzy-desktop\\n\\n# Install Colcon build system, rosdep, and python dependencies\\nsudo apt install -y python3-colcon-common-extensions python3-rosdep python3-pip python3-argcomplete\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">sudo apt update\\nsudo apt install -y ros-jazzy-desktop\\n\\n# Install Colcon build system, rosdep, and python dependencies\\nsudo apt install -y python3-colcon-common-extensions python3-rosdep python3-pip python3-argcomplete</code></pre></div>\\n<hr class=\\"divider\\">\\n<h3 id=\\"step-55-initialize-rosdep\\">Step 5.5: Initialize Rosdep</h3>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\">[!SYNTAX]<br><strong>Command Syntax:</strong> <code class=\\"inline-code\\">sudo rosdep init</code> &amp;nbsp;|&amp;nbsp; <code class=\\"inline-code\\">rosdep update</code><br><strong>Description:</strong> Initializes the package dependency index. <code class=\\"inline-code\\">rosdep</code> queries the global ROS package index to resolve and install OS system dependencies (apt libraries, C++ headers, Python packages) required by ROS 2 nodes.</div></div>\\n<p><strong>Hands-On Practical Command:</strong></p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"sudo rosdep init\\nrosdep update\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">sudo rosdep init\\nrosdep update</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-docker-containerized-setup-zero-friction-option\\">6. Docker Containerized Setup (Zero-Friction Option)</h2>\\n<p>For students on Windows, macOS, or clean Linux installations, the <strong>NavPro Learning Hub</strong> provides a fully pre-configured Docker image containing ROS 2 Jazzy, Gazebo Sim (Harmonic), Nav2, an in-browser Ubuntu 24.04 desktop GUI (<strong>noVNC</strong>), and an in-browser VS Code editor (<strong>code-server</strong>).</p>\\n<h3 id=\\"step-60-prerequisites--installing-docker\\">Step 6.0: Prerequisites — Installing Docker</h3>\\n<p>Before building the container, ensure Docker Engine and Docker Compose are installed on your host system.</p>\\n<h4 id=\\"a-installing-docker-on-windows-wsl-2-backend\\">A. Installing Docker on Windows (WSL 2 Backend)</h4>\\n<ol class=\\"lesson-ordered-list\\">\\n<li><strong>Enable Hardware Virtualization:</strong> Ensure Virtualization (VT-x / AMD-V) is enabled in your PC&#x27;s BIOS/UEFI settings.</li>\\n<li><strong>Install WSL 2 (Windows Subsystem for Linux):</strong> Open PowerShell as Administrator and execute:</li>\\n</ol>\\n<div class=\\"code-container\\" data-language=\\"powershell\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">POWERSHELL</span><button class=\\"copy-code-btn\\" data-code=\\"   wsl --install\\">📋 Copy</button></div><pre><code class=\\"language-powershell\\">   wsl --install</code></pre></div>\\n<p>Restart your computer if prompted by Windows.</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li><strong>Download &amp; Install Docker Desktop:</strong></li>\\n</ol>\\n<ul class=\\"lesson-bullet-list\\">\\n<li>Download the official installer from <a href=\\"https://docs.docker.com/desktop/setup/install/windows-install/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Docker Desktop for Windows</a>.</li>\\n<li>During setup, verify the option <strong>&quot;Use WSL 2 instead of Hyper-V&quot;</strong> is checked.</li>\\n<li>Launch Docker Desktop, navigate to <strong>Settings &amp;rarr; Resources &amp;rarr; WSL Integration</strong>, and ensure your Ubuntu/WSL distro is toggled on.</li>\\n<li>Test in PowerShell or Command Prompt:</li>\\n</ul>\\n<div class=\\"code-container\\" data-language=\\"powershell\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">POWERSHELL</span><button class=\\"copy-code-btn\\" data-code=\\"     docker --version\\n     docker compose version\\">📋 Copy</button></div><pre><code class=\\"language-powershell\\">     docker --version\\n     docker compose version</code></pre></div>\\n<h4 id=\\"b-installing-docker-on-linux-ubuntu-2204--2404-lts\\">B. Installing Docker on Linux (Ubuntu 22.04 / 24.04 LTS)</h4>\\n<ol class=\\"lesson-ordered-list\\">\\n<li><strong>Remove conflicting legacy packages:</strong></li>\\n</ol>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"   for pkg in docker.io docker-doc docker-compose podman-docker containerd runc; do sudo apt-get remove -y $pkg; done\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">   for pkg in docker.io docker-doc docker-compose podman-docker containerd runc; do sudo apt-get remove -y $pkg; done</code></pre></div>\\n<ol class=\\"lesson-ordered-list\\">\\n<li><strong>Set up Docker&#x27;s official APT repository:</strong></li>\\n</ol>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"   sudo apt update\\n   sudo apt install -y ca-certificates curl gnupg\\n   sudo install -m 0755 -d /etc/apt/keyrings\\n   sudo curl -fsSL https://download.docker.com/linux/ubuntu/gpg -o /etc/apt/keyrings/docker.asc\\n   sudo chmod a+r /etc/apt/keyrings/docker.asc\\n\\n   echo &quot;deb [arch=$(dpkg --print-architecture) signed-by=/etc/apt/keyrings/docker.asc] https://download.docker.com/linux/ubuntu $(. /etc/os-release &amp;&amp; echo &quot;$UBUNTU_CODENAME&quot;) stable&quot; | sudo tee /etc/apt/sources.list.d/docker.list &gt; /dev/null\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">   sudo apt update\\n   sudo apt install -y ca-certificates curl gnupg\\n   sudo install -m 0755 -d /etc/apt/keyrings\\n   sudo curl -fsSL https://download.docker.com/linux/ubuntu/gpg -o /etc/apt/keyrings/docker.asc\\n   sudo chmod a+r /etc/apt/keyrings/docker.asc\\n\\n   echo &quot;deb [arch=$(dpkg --print-architecture) signed-by=/etc/apt/keyrings/docker.asc] https://download.docker.com/linux/ubuntu $(. /etc/os-release &amp;&amp; echo &quot;$UBUNTU_CODENAME&quot;) stable&quot; | sudo tee /etc/apt/sources.list.d/docker.list &gt; /dev/null</code></pre></div>\\n<ol class=\\"lesson-ordered-list\\">\\n<li><strong>Install Docker Engine &amp; Compose plugin:</strong></li>\\n</ol>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"   sudo apt update\\n   sudo apt install -y docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">   sudo apt update\\n   sudo apt install -y docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin</code></pre></div>\\n<ol class=\\"lesson-ordered-list\\">\\n<li><strong>Configure Non-Root User Permissions (Post-Install):</strong></li>\\n</ol>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"   sudo usermod -aG docker $USER\\n   newgrp docker\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">   sudo usermod -aG docker $USER\\n   newgrp docker</code></pre></div>\\n<ol class=\\"lesson-ordered-list\\">\\n<li><strong>Verify installation:</strong></li>\\n</ol>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"   docker run --rm hello-world\\n   docker compose version\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">   docker run --rm hello-world\\n   docker compose version</code></pre></div>\\n<h4 id=\\"official-reference-documentation-links\\">Official Reference Documentation Links</h4>\\n<div class=\\"table-wrapper\\"><table>\\n<thead><tr>\\n<th>Resource</th>\\n<th>URL &amp; Official Guide</th>\\n<th>Description</th>\\n</tr></thead><tbody>\\n<tr>\\n<td><strong>Docker Desktop for Windows</strong></td>\\n<td><a href=\\"https://docs.docker.com/desktop/setup/install/windows-install/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Install Docker Desktop on Windows</a></td>\\n<td>Official installation walkthrough for Windows 10/11 with WSL 2 backend</td>\\n</tr>\\n<tr>\\n<td><strong>Microsoft WSL 2 Setup</strong></td>\\n<td><a href=\\"https://learn.microsoft.com/en-us/windows/wsl/install\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">How to install Linux on Windows with WSL</a></td>\\n<td>Microsoft documentation for setting up the WSL 2 Linux kernel</td>\\n</tr>\\n<tr>\\n<td><strong>Docker Engine for Ubuntu</strong></td>\\n<td><a href=\\"https://docs.docker.com/engine/install/ubuntu/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Install Docker Engine on Ubuntu</a></td>\\n<td>Official APT repository setup guide for Ubuntu 22.04 &amp; 24.04 LTS</td>\\n</tr>\\n<tr>\\n<td><strong>Docker Linux Post-Install</strong></td>\\n<td><a href=\\"https://docs.docker.com/engine/install/linux-postinstall/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Linux Post-installation Steps</a></td>\\n<td>Managing Docker as a non-root user and systemd auto-start</td>\\n</tr>\\n<tr>\\n<td><strong>Docker Compose Docs</strong></td>\\n<td><a href=\\"https://docs.docker.com/compose/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Overview of Docker Compose</a></td>\\n<td>Reference guide for compose syntax and CLI commands</td>\\n</tr>\\n</tbody></table></div>\\n<hr class=\\"divider\\">\\n<h3 id=\\"step-61-build--launch-the-complete-stack-with-one-command\\">Step 6.1: Build &amp; Launch the Complete Stack with One Command</h3>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\">[!SYNTAX]<br><strong>Command Syntax:</strong> <code class=\\"inline-code\\">docker compose up [options]</code><br><strong>Description:</strong> Builds and starts containerized services defined in <code class=\\"inline-code\\">docker-compose.yml</code>. Flag <code class=\\"inline-code\\">--build</code> compiles images from the local Dockerfile; <code class=\\"inline-code\\">-d</code> runs containers detached in the background.</div></div>\\n<p><strong>One-Command Stack Launch (Level 1 Repository):</strong></p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# Navigate to the Level 1 repository directory\\ncd /home/chaitu/Projects/navpro_learning_hub/level1\\n\\n# Launch the entire ecosystem (Web Portal, Desktop GUI, and VS Code) in one command:\\ndocker compose up --build -d\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># Navigate to the Level 1 repository directory\\ncd /home/chaitu/Projects/navpro_learning_hub/level1\\n\\n# Launch the entire ecosystem (Web Portal, Desktop GUI, and VS Code) in one command:\\ndocker compose up --build -d</code></pre></div>\\n<p>Verify that the Level 1 container is active and running:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"docker ps --filter &quot;name=navpro_level1_container&quot;\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">docker ps --filter &quot;name=navpro_level1_container&quot;</code></pre></div>\\n<p><em>Expected Terminal Output:</em></p>\\n<div class=\\"code-container\\" data-language=\\"text\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">TEXT</span><button class=\\"copy-code-btn\\" data-code=\\"CONTAINER ID   IMAGE                          STATUS         PORTS\\na1b2c3d4e5f6   navpro-level1-ros2-sim:latest  Up 2 minutes   0.0.0.0:8000-&gt;8000/tcp, 0.0.0.0:6080-&gt;6080/tcp, 0.0.0.0:8443-&gt;8443/tcp\\">📋 Copy</button></div><pre><code class=\\"language-text\\">CONTAINER ID   IMAGE                          STATUS         PORTS\\na1b2c3d4e5f6   navpro-level1-ros2-sim:latest  Up 2 minutes   0.0.0.0:8000-&gt;8000/tcp, 0.0.0.0:6080-&gt;6080/tcp, 0.0.0.0:8443-&gt;8443/tcp</code></pre></div>\\n<hr class=\\"divider\\">\\n<h3 id=\\"step-62-one-click-launch-via-top-navigation-status-bar\\">Step 6.2: One-Click Launch via Top Navigation Status Bar</h3>\\n<p>You do not need to memorize URLs. Notice the <strong>quick-launch buttons on the top status bar / header</strong> of this web portal:</p>\\n<div class=\\"table-wrapper\\"><table>\\n<thead><tr>\\n<th>Status Bar Button</th>\\n<th>Destination URL</th>\\n<th>Purpose &amp; Environment</th>\\n</tr></thead><tbody>\\n<tr>\\n<td><strong><code class=\\"inline-code\\">🖥️ Desktop GUI</code></strong></td>\\n<td><code class=\\"inline-code\\">http://localhost:6080/vnc.html?autoconnect=true&amp;resize=remote</code></td>\\n<td>Opens full Ubuntu 24.04 XFCE desktop with Gazebo, RViz2, and Terminator.</td>\\n</tr>\\n<tr>\\n<td><strong><code class=\\"inline-code\\">💻 VS Code</code></strong></td>\\n<td><code class=\\"inline-code\\">http://localhost:8443/?folder=/home/student/ros2_ws</code></td>\\n<td>Opens in-browser VS Code editor directly rooted in your ROS 2 workspace.</td>\\n</tr>\\n</tbody></table></div>\\n<div class=\\"alert-callout alert-important\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Authentication &amp; Passwords:</strong><br>* <strong>noVNC Desktop GUI:</strong> <strong>No password required (Passwordless Instant Connect)</strong>. When the browser tab opens, it connects automatically to your Ubuntu desktop, ready to launch Gazebo and RViz2.<br>* <strong>In-Browser VS Code IDE:</strong> <strong>No password required</strong> (pre-authenticated). It opens directly into <code class=\\"inline-code\\">/home/student/ros2_ws</code>.</div></div>\\n<hr class=\\"divider\\">\\n<h3 id=\\"step-63-command-line-terminal-access-inside-container\\">Step 6.3: Command-Line Terminal Access inside Container</h3>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\">[!SYNTAX]<br><strong>Command Syntax:</strong> <code class=\\"inline-code\\">docker exec -it &lt;container_name&gt; &lt;shell_binary&gt;</code><br><strong>Description:</strong> Opens an interactive terminal session inside a running container. Flag <code class=\\"inline-code\\">-i</code> keeps stdin open, and <code class=\\"inline-code\\">-t</code> allocates a terminal TTY buffer.</div></div>\\n<p><strong>Hands-On Practical Command:</strong></p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"docker exec -it navpro_level1_container bash\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">docker exec -it navpro_level1_container bash</code></pre></div>\\n<p>Inside the container shell, all ROS 2 Jazzy paths and workspace tools are auto-sourced:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# Verify environment inside container:\\nros2 pkg list | grep turtlebot3\\ngz sim --version\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># Verify environment inside container:\\nros2 pkg list | grep turtlebot3\\ngz sim --version</code></pre></div>\\n<p><em>Expected Terminal Output:</em></p>\\n<div class=\\"code-container\\" data-language=\\"text\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">TEXT</span><button class=\\"copy-code-btn\\" data-code=\\"turtlebot3_description\\nturtlebot3_navigation2\\nGazebo Sim, version 8.6.0\\">📋 Copy</button></div><pre><code class=\\"language-text\\">turtlebot3_description\\nturtlebot3_navigation2\\nGazebo Sim, version 8.6.0</code></pre></div>\\n<hr class=\\"divider\\">\\n<h3 id=\\"step-64-stopping-the-container\\">Step 6.4: Stopping the Container</h3>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"cd /home/chaitu/Projects/navpro_learning_hub/level1/docker\\ndocker compose down\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">cd /home/chaitu/Projects/navpro_learning_hub/level1/docker\\ndocker compose down</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"7-productivity-development-tooling\\">7. Productivity Development Tooling</h2>\\n<p>Robotics programming requires running multiple nodes, echoing topics, and monitoring logs simultaneously.</p>\\n<h3 id=\\"71-multi-terminal-manager-terminator\\">7.1 Multi-Terminal Manager: Terminator</h3>\\n<p>Install Terminator for easy terminal window splitting:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"sudo apt install -y terminator\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">sudo apt install -y terminator</code></pre></div>\\n<p><strong>Essential Terminator Shortcuts:</strong></p>\\n<ul class=\\"lesson-bullet-list\\">\\n<li><code class=\\"inline-code\\">Ctrl + Shift + O</code>: Split pane <strong>horizontally</strong> (top and bottom).</li>\\n<li><code class=\\"inline-code\\">Ctrl + Shift + E</code>: Split pane <strong>vertically</strong> (left and right).</li>\\n<li><code class=\\"inline-code\\">Alt + Arrow Keys</code>: Navigate between active split panes.</li>\\n<li><code class=\\"inline-code\\">Ctrl + Shift + W</code>: Close active pane.</li>\\n<li><code class=\\"inline-code\\">F11</code>: Toggle fullscreen.</li>\\n</ul>\\n<div class=\\"lesson-image-wrapper\\"><img src=\\"assets/images/terminator_layout.svg\\" alt=\\"Terminator Multi-Pane Terminal Layout\\" class=\\"lesson-image\\" loading=\\"lazy\\"><span class=\\"image-caption\\">Terminator Multi-Pane Terminal Layout</span></div>\\n<h3 id=\\"72-visual-studio-code-configuration\\">7.2 Visual Studio Code Configuration</h3>\\n<p>Launch VS Code in your workspace:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"code .\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">code .</code></pre></div>\\n<p>Recommended Extensions for ROS 2 Python:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li><strong>Python</strong> (<code class=\\"inline-code\\">ms-python.python</code>): IntelliSense, linting, syntax highlighting.</li>\\n<li><strong>ROS</strong> (<code class=\\"inline-code\\">ms-iot.vscode-ros</code>): ROS 2 environment discovery, build task runners.</li>\\n<li><strong>XML</strong> (<code class=\\"inline-code\\">redhat.vscode-xml</code>): Autocompletion and syntax validation for <code class=\\"inline-code\\">package.xml</code> and URDF/Xacro files.</li>\\n<li><strong>Even Better TOML</strong> / <strong>YAML</strong>: Syntax highlighting for parameter and configuration files.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"8-shell-environment-sourcing--productive-aliases\\">8. Shell Environment Sourcing &amp; Productive Aliases</h2>\\n<p>By default, every new bash terminal needs to know where ROS 2 is installed. Adding the setup script to <code class=\\"inline-code\\">~/.bashrc</code> automates this.</p>\\n<p>Edit your <code class=\\"inline-code\\">~/.bashrc</code> file:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"nano ~/.bashrc\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">nano ~/.bashrc</code></pre></div>\\n<p>Append the following lines to the bottom of the file:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# -------------------------------------------------------------\\n# NavPro ROS 2 Environment Setup &amp; Aliases\\n# -------------------------------------------------------------\\nsource /opt/ros/jazzy/setup.bash\\n\\n# Ensure local workspace overlay is sourced if present\\nif [ -f &quot;$HOME/ros2_ws/install/setup.bash&quot; ]; then\\n    source &quot;$HOME/ros2_ws/install/setup.bash&quot;\\nfi\\n\\n# Set isolated DDS domain ID (Change per student to avoid network crosstalk)\\nexport ROS_DOMAIN_ID=1\\n\\n# Productivity Shortcuts\\nalias sb=&#x27;source ~/.bashrc &amp;&amp; echo &quot;Environment sourced!&quot;&#x27;\\nalias cb=&#x27;colcon build --symlink-install&#x27;\\nalias cbp=&#x27;colcon build --symlink-install --packages-select&#x27;\\nalias killros=&#x27;killall -9 gzserver gzclient robot_state_publisher 2&gt;/dev/null&#x27;\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># -------------------------------------------------------------\\n# NavPro ROS 2 Environment Setup &amp; Aliases\\n# -------------------------------------------------------------\\nsource /opt/ros/jazzy/setup.bash\\n\\n# Ensure local workspace overlay is sourced if present\\nif [ -f &quot;$HOME/ros2_ws/install/setup.bash&quot; ]; then\\n    source &quot;$HOME/ros2_ws/install/setup.bash&quot;\\nfi\\n\\n# Set isolated DDS domain ID (Change per student to avoid network crosstalk)\\nexport ROS_DOMAIN_ID=1\\n\\n# Productivity Shortcuts\\nalias sb=&#x27;source ~/.bashrc &amp;&amp; echo &quot;Environment sourced!&quot;&#x27;\\nalias cb=&#x27;colcon build --symlink-install&#x27;\\nalias cbp=&#x27;colcon build --symlink-install --packages-select&#x27;\\nalias killros=&#x27;killall -9 gzserver gzclient robot_state_publisher 2&gt;/dev/null&#x27;</code></pre></div>\\n<p>Save and reload the environment:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"source ~/.bashrc\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">source ~/.bashrc</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"9-verification--hello-world-smoke-test\\">9. Verification &amp; &quot;Hello World&quot; Smoke Test</h2>\\n<p>Run the built-in ROS 2 talker and listener demo nodes to verify that DDS peer discovery is operational.</p>\\n<h3 id=\\"step-91-launch-talker-node\\">Step 9.1: Launch Talker Node</h3>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\">[!SYNTAX]<br><strong>Command Syntax:</strong> <code class=\\"inline-code\\">ros2 run &lt;package_name&gt; &lt;executable_name&gt;</code><br><strong>Description:</strong> Executes a compiled ROS 2 executable from an installed package. Starts the node process and begins publishing on DDS topics.</div></div>\\n<p><strong>Hands-On Practical Command (Terminal 1):</strong></p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"ros2 run demo_nodes_py talker\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">ros2 run demo_nodes_py talker</code></pre></div>\\n<p><em>Expected Terminal Output:</em></p>\\n<div class=\\"code-container\\" data-language=\\"text\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">TEXT</span><button class=\\"copy-code-btn\\" data-code=\\"[INFO] [talker]: Publishing: &quot;Hello World: 1&quot;\\n[INFO] [talker]: Publishing: &quot;Hello World: 2&quot;\\n[INFO] [talker]: Publishing: &quot;Hello World: 3&quot;\\">📋 Copy</button></div><pre><code class=\\"language-text\\">[INFO] [talker]: Publishing: &quot;Hello World: 1&quot;\\n[INFO] [talker]: Publishing: &quot;Hello World: 2&quot;\\n[INFO] [talker]: Publishing: &quot;Hello World: 3&quot;</code></pre></div>\\n<hr class=\\"divider\\">\\n<h3 id=\\"step-92-launch-listener-node\\">Step 9.2: Launch Listener Node</h3>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\">[!SYNTAX]<br><strong>Command Syntax:</strong> <code class=\\"inline-code\\">ros2 run &lt;package_name&gt; &lt;executable_name&gt;</code><br><strong>Description:</strong> Runs the subscriber node which dynamically discovers <code class=\\"inline-code\\">/talker</code> over local DDS multicast and prints received messages.</div></div>\\n<p><strong>Hands-On Practical Command (Terminal 2):</strong></p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"ros2 run demo_nodes_py listener\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">ros2 run demo_nodes_py listener</code></pre></div>\\n<p><em>Expected Terminal Output:</em></p>\\n<div class=\\"code-container\\" data-language=\\"text\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">TEXT</span><button class=\\"copy-code-btn\\" data-code=\\"[INFO] [listener]: I heard: [Hello World: 1]\\n[INFO] [listener]: I heard: [Hello World: 2]\\n[INFO] [listener]: I heard: [Hello World: 3]\\">📋 Copy</button></div><pre><code class=\\"language-text\\">[INFO] [listener]: I heard: [Hello World: 1]\\n[INFO] [listener]: I heard: [Hello World: 2]\\n[INFO] [listener]: I heard: [Hello World: 3]</code></pre></div>\\n<hr class=\\"divider\\">\\n<h3 id=\\"step-93-inspect-active-nodes--echo-topics\\">Step 9.3: Inspect Active Nodes &amp; Echo Topics</h3>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\">[!SYNTAX]<br><strong>Command Syntax:</strong> <code class=\\"inline-code\\">ros2 node list</code> &amp;nbsp;|&amp;nbsp; <code class=\\"inline-code\\">ros2 topic list</code> &amp;nbsp;|&amp;nbsp; <code class=\\"inline-code\\">ros2 topic echo &lt;topic_name&gt;</code><br><strong>Description:</strong> Queries the DDS peer discovery bus to inspect live running nodes, active message topics, and echo real-time data packets in the terminal.</div></div>\\n<p><strong>Hands-On Practical Command:</strong></p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"ros2 node list\\n# Displays: /talker, /listener\\n\\nros2 topic list\\n# Displays: /chatter, /parameter_events, /rosout\\n\\nros2 topic echo /chatter\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">ros2 node list\\n# Displays: /talker, /listener\\n\\nros2 topic list\\n# Displays: /chatter, /parameter_events, /rosout\\n\\nros2 topic echo /chatter</code></pre></div>\\n<p><em>Expected Terminal Output:</em></p>\\n<div class=\\"code-container\\" data-language=\\"text\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">TEXT</span><button class=\\"copy-code-btn\\" data-code=\\"data: &#x27;Hello World: 4&#x27;\\n---\\ndata: &#x27;Hello World: 5&#x27;\\n---\\">📋 Copy</button></div><pre><code class=\\"language-text\\">data: &#x27;Hello World: 4&#x27;\\n---\\ndata: &#x27;Hello World: 5&#x27;\\n---</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"10-summary--next-steps\\">10. Summary &amp; Next Steps</h2>\\n<p>You now have a fully operational, industry-grade ROS 2 Jazzy workstation. In <strong>Lesson 03</strong>, we will build our first custom ROS 2 workspace from scratch and write an object-oriented Python node with timers and logging!</p>","quizzes":[{"id":"q_l1_02_1","prompt":"What primary architectural component replaces the centralized 'roscore' master from ROS 1 in ROS 2 Jazzy?","options":["A central Redis server running in Docker","The decentralized Data Distribution Service (DDS) discovery protocol","systemd service manager","The Linux D-Bus messaging broker"],"correct":1,"explanation":"ROS 2 is built on top of the OMG DDS standard. Discovery is fully decentralized using peer-to-peer multicast participant announcements, eliminating the single point of failure (roscore) present in ROS 1."},{"id":"q_l1_02_2","prompt":"In an environment where multiple robots share the same Wi-Fi network, how do you isolate their ROS 2 DDS communications?","options":["By setting unique IP subnets on each robot's router","By setting a unique ROS_DOMAIN_ID environment variable (0-101 or 0-232) on each robot","By encrypting the disk with LUKS","By changing the ROS_DISTRO environment variable"],"correct":1,"explanation":"ROS_DOMAIN_ID maps directly to DDS domain partition ports. Robots on different ROS_DOMAIN_IDs cannot discover or interfere with each other's topics, even on identical subnets."}],"has_quiz":true,"next_id":"lesson_03","prev_id":"lesson_01"},{"id":"lesson_03","num":3,"num_str":"03","title":"ROS 2 Workspace & HelloWorld in Python","slug":"workspace_and_first_python_node","filename":"03_workspace_and_first_python_node.md","module":"Foundations & Core Middleware","module_id":1,"duration":"45-60 min","focus":"Python-Only Robotics Engineering Workflow","snapshot":[["Underlay vs Overlay","System ROS 2 binaries live in /opt/ros/jazzy; your custom packages live in ~/ros2_ws."],["Python Node Lifecycle","Initialize with rclpy.init(), instantiate Node class, hand off to rclpy.spin(), and clean up with node.destroy_node()."],["Colcon Symlink","Always compile python nodes using colcon build --symlink-install for instant live-editing without rebuilding."]],"html_content":"<h1 id=\\"lesson-03-ros-2-workspace--helloworld-in-python\\">Lesson 03: ROS 2 Workspace &amp; HelloWorld in Python</h1>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Focus:</strong> Python-Only Robotics Engineering Workflow<br><strong>Course Track:</strong> NavPro Learning Hub - Level 1<br><strong>Target Environment:</strong> ROS 2 Jazzy Jalisco</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"1-overview--learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>In this lesson, you will master the foundational workflow of all ROS 2 Python development:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Understand the core terminologies: Nodes, Computational Graphs, and DDS Client Libraries (<code class=\\"inline-code\\">rclpy</code>).</li>\\n<li>Demystify the ROS 2 workspace architecture: <strong>Underlay</strong> vs. <strong>Overlay</strong>, and the four workspace folders (<code class=\\"inline-code\\">src/</code>, <code class=\\"inline-code\\">build/</code>, <code class=\\"inline-code\\">install/</code>, <code class=\\"inline-code\\">log/</code>).</li>\\n<li>Master <code class=\\"inline-code\\">colcon build</code> and learn why the <code class=\\"inline-code\\">--symlink-install</code> flag is a game-changer for Python developers.</li>\\n<li>Write, explain line-by-line, build, and execute a production-grade Object-Oriented ROS 2 Python node.</li>\\n<li>Complete an interactive student challenge to modify node logging and timer frequency.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-core-terminologies-how-ros-2-thinks\\">2. Core Terminologies: How ROS 2 Thinks</h2>\\n<p>Before writing code, let&#x27;s establish the mental model of ROS 2:</p>\\n<div class=\\"lesson-image-wrapper\\"><img src=\\"assets/images/ros2_graph_dds_bus.svg\\" alt=\\"ROS 2 Computational Graph &amp; DDS Bus\\" class=\\"lesson-image\\" loading=\\"lazy\\"><span class=\\"image-caption\\">ROS 2 Computational Graph &amp; DDS Bus</span></div>\\n<ul class=\\"lesson-bullet-list\\">\\n<li><strong>Node:</strong> An independent software process dedicated to a single robotic task (e.g., read LiDAR data, compute kinematics, plan paths, stream video). A robotic system consists of tens or hundreds of interconnected nodes.</li>\\n<li><strong>Graph:</strong> The network of active nodes and the communication pathways connecting them.</li>\\n<li><strong>Client Library (<code class=\\"inline-code\\">rclpy</code>):</strong> The Python API wrapper around the native ROS 2 C implementation (<code class=\\"inline-code\\">rcl</code>). It provides classes for nodes, publishers, subscribers, services, and executors.</li>\\n<li><strong>DDS (Data Distribution Service):</strong> The underlying peer-to-peer messaging protocol handling data serialization, transport, and discovery without requiring a central coordinator.</li>\\n</ul>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-the-ros-2-workspace-architecture\\">3. The ROS 2 Workspace Architecture</h2>\\n<p>A <strong>Workspace</strong> is a dedicated directory on your filesystem where you develop, build, and install custom ROS 2 packages.</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"ros2_ws/\\n├── src/        &lt;-- SOURCE CODE: Your custom packages, git repos, and python scripts\\n├── build/      &lt;-- BUILD CACHE: Intermediate compilation artifacts (managed by colcon)\\n├── install/    &lt;-- RUNTIME OVERLAY: Where binaries, libraries, and launch scripts live\\n└── log/        &lt;-- BUILD LOGS: stdout/stderr reports from colcon build operations\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">ros2_ws/\\n├── src/        &lt;-- SOURCE CODE: Your custom packages, git repos, and python scripts\\n├── build/      &lt;-- BUILD CACHE: Intermediate compilation artifacts (managed by colcon)\\n├── install/    &lt;-- RUNTIME OVERLAY: Where binaries, libraries, and launch scripts live\\n└── log/        &lt;-- BUILD LOGS: stdout/stderr reports from colcon build operations</code></pre></div>\\n<h3 id=\\"31-underlays-vs-overlays\\">3.1 Underlays vs. Overlays</h3>\\n<p>ROS 2 uses an <strong>overlay</strong> mechanism to isolate system software from project software:</p>\\n<ul class=\\"lesson-bullet-list\\">\\n<li><strong>The Underlay:</strong> The core operating system installation (<code class=\\"inline-code\\">/opt/ros/jazzy</code>). It contains system-level ROS 2 tools, standard message definitions, and Nav2 binaries.</li>\\n<li><strong>The Overlay:</strong> Your custom development workspace (<code class=\\"inline-code\\">~/ros2_ws</code>). When you source <code class=\\"inline-code\\">~/ros2_ws/install/setup.bash</code>, your workspace <em>overlays</em> the underlay, allowing you to use your custom packages or override system packages without breaking the operating system.</li>\\n</ul>\\n<div class=\\"lesson-image-wrapper\\"><img src=\\"assets/images/ros2_overlay_underlay.svg\\" alt=\\"ROS 2 Overlay vs Underlay Architecture\\" class=\\"lesson-image\\" loading=\\"lazy\\"><span class=\\"image-caption\\">ROS 2 Overlay vs Underlay Architecture</span></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-step-by-step-creating-a-workspace--first-python-node\\">4. Step-by-Step: Creating a Workspace &amp; First Python Node</h2>\\n<p>Follow these steps directly in your terminal.</p>\\n<h3 id=\\"step-41-initialize-the-workspace-directory\\">Step 4.1: Initialize the Workspace Directory</h3>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"mkdir -p ~/ros2_ws/src\\ncd ~/ros2_ws\\ncolcon build\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">mkdir -p ~/ros2_ws/src\\ncd ~/ros2_ws\\ncolcon build</code></pre></div>\\n<p>Verify that the workspace directories were created:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"ls ~/ros2_ws\\n# Output: build  install  log  src\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">ls ~/ros2_ws\\n# Output: build  install  log  src</code></pre></div>\\n<h3 id=\\"step-42-create-a-pure-python-package\\">Step 4.2: Create a Pure Python Package</h3>\\n<p>Use <code class=\\"inline-code\\">ros2 pkg create</code> to scaffold a package. Specify <code class=\\"inline-code\\">--build-type ament_python</code>:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"cd ~/ros2_ws/src\\nros2 pkg create --build-type ament_python --node-name hello_node navpro_hello_py\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">cd ~/ros2_ws/src\\nros2 pkg create --build-type ament_python --node-name hello_node navpro_hello_py</code></pre></div>\\n<p>Let&#x27;s inspect the generated directory layout:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"tree navpro_hello_py/\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">tree navpro_hello_py/</code></pre></div>\\n<p><em>Output:</em></p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"navpro_hello_py/\\n├── navpro_hello_py/\\n│   ├── __init__.py\\n│   └── hello_node.py\\n├── package.xml\\n├── resource/\\n│   └── navpro_hello_py\\n├── setup.cfg\\n└── setup.py\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">navpro_hello_py/\\n├── navpro_hello_py/\\n│   ├── __init__.py\\n│   └── hello_node.py\\n├── package.xml\\n├── resource/\\n│   └── navpro_hello_py\\n├── setup.cfg\\n└── setup.py</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-writing-the-python-node-code--line-by-line-breakdown\\">5. Writing the Python Node: Code &amp; Line-by-Line Breakdown</h2>\\n<p>Open <code class=\\"inline-code\\">~/ros2_ws/src/navpro_hello_py/navpro_hello_py/hello_node.py</code> in your code editor and update it to the production Object-Oriented structure below:</p>\\n<div class=\\"code-container\\" data-language=\\"python\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">PYTHON</span><button class=\\"copy-code-btn\\" data-code=\\"#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nNavPro Learning Hub - Lesson 03: First ROS 2 Python Node\\nDemonstrates the Object-Oriented rclpy Node architecture with periodic timers and logging.\\n&quot;&quot;&quot;\\n\\nimport rclpy\\nfrom rclpy.node import Node\\n\\n\\nclass HelloWorldNode(Node):\\n    &quot;&quot;&quot;\\n    Inherits from rclpy.node.Node.\\n    Every ROS 2 Python component should be written as a class.\\n    &quot;&quot;&quot;\\n\\n    def __init__(self):\\n        # Initialize parent Node with node name &#x27;navpro_hello_node&#x27;\\n        super().__init__(&#x27;navpro_hello_node&#x27;)\\n\\n        # Internal state variable\\n        self.counter_ = 0\\n\\n        # Log initial startup message\\n        self.get_logger().info(&#x27;Hello World! NavPro ROS 2 Python Node has booted.&#x27;)\\n\\n        # Create a periodic timer running at 1.0 Hz (every 1.0 second)\\n        # Parameters: (period_in_seconds, callback_function)\\n        self.timer_ = self.create_timer(1.0, self.timer_callback)\\n\\n    def timer_callback(self):\\n        &quot;&quot;&quot;Executed automatically every 1.0 second by the ROS 2 executor.&quot;&quot;&quot;\\n        self.counter_ += 1\\n        self.get_logger().info(f&#x27;[Heartbeat #{self.counter_}] NavPro AMR is alive and operational.&#x27;)\\n\\n\\ndef main(args=None):\\n    # 1. Initialize ROS 2 DDS communications\\n    rclpy.init(args=args)\\n\\n    # 2. Instantiate our custom node class\\n    node = HelloWorldNode()\\n\\n    # 3. Spin the node: keeps the process alive and processes timer callbacks\\n    try:\\n        rclpy.spin(node)\\n    except KeyboardInterrupt:\\n        node.get_logger().warn(&#x27;Keyboard interrupt detected! Shutting down gracefully...&#x27;)\\n    finally:\\n        # 4. Clean up resources and destroy the node\\n        node.destroy_node()\\n        # 5. Shutdown the ROS 2 middleware\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\">📋 Copy</button></div><pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nNavPro Learning Hub - Lesson 03: First ROS 2 Python Node\\nDemonstrates the Object-Oriented rclpy Node architecture with periodic timers and logging.\\n&quot;&quot;&quot;\\n\\nimport rclpy\\nfrom rclpy.node import Node\\n\\n\\nclass HelloWorldNode(Node):\\n    &quot;&quot;&quot;\\n    Inherits from rclpy.node.Node.\\n    Every ROS 2 Python component should be written as a class.\\n    &quot;&quot;&quot;\\n\\n    def __init__(self):\\n        # Initialize parent Node with node name &#x27;navpro_hello_node&#x27;\\n        super().__init__(&#x27;navpro_hello_node&#x27;)\\n\\n        # Internal state variable\\n        self.counter_ = 0\\n\\n        # Log initial startup message\\n        self.get_logger().info(&#x27;Hello World! NavPro ROS 2 Python Node has booted.&#x27;)\\n\\n        # Create a periodic timer running at 1.0 Hz (every 1.0 second)\\n        # Parameters: (period_in_seconds, callback_function)\\n        self.timer_ = self.create_timer(1.0, self.timer_callback)\\n\\n    def timer_callback(self):\\n        &quot;&quot;&quot;Executed automatically every 1.0 second by the ROS 2 executor.&quot;&quot;&quot;\\n        self.counter_ += 1\\n        self.get_logger().info(f&#x27;[Heartbeat #{self.counter_}] NavPro AMR is alive and operational.&#x27;)\\n\\n\\ndef main(args=None):\\n    # 1. Initialize ROS 2 DDS communications\\n    rclpy.init(args=args)\\n\\n    # 2. Instantiate our custom node class\\n    node = HelloWorldNode()\\n\\n    # 3. Spin the node: keeps the process alive and processes timer callbacks\\n    try:\\n        rclpy.spin(node)\\n    except KeyboardInterrupt:\\n        node.get_logger().warn(&#x27;Keyboard interrupt detected! Shutting down gracefully...&#x27;)\\n    finally:\\n        # 4. Clean up resources and destroy the node\\n        node.destroy_node()\\n        # 5. Shutdown the ROS 2 middleware\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()</code></pre></div>\\n<hr class=\\"divider\\">\\n<h3 id=\\"51-comprehensive-line-by-line-code-breakdown\\">5.1 Comprehensive Line-by-Line Code Breakdown</h3>\\n<div class=\\"table-wrapper\\"><table>\\n<thead><tr>\\n<th>Code Line</th>\\n<th>Purpose &amp; Explanation</th>\\n</tr></thead><tbody>\\n<tr>\\n<td><code class=\\"inline-code\\">#!/usr/bin/env python3</code></td>\\n<td><strong>Shebang:</strong> Tells the Linux OS to execute this script using the active Python 3 interpreter.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">import rclpy</code></td>\\n<td>Imports the core ROS 2 Python client library, providing initialization, spinning, and shutdown methods.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">from rclpy.node import Node</code></td>\\n<td>Imports the base <code class=\\"inline-code\\">Node</code> class. In ROS 2, nodes encapsulate all communication capabilities.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">class HelloWorldNode(Node):</code></td>\\n<td>Defines our custom class inheriting from <code class=\\"inline-code\\">Node</code>. This Object-Oriented design is the industry standard for encapsulation and state management.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">super().__init__(&#x27;navpro_hello_node&#x27;)</code></td>\\n<td>Calls the parent constructor to register the node in the ROS graph under the unique name <code class=\\"inline-code\\">&#x27;navpro_hello_node&#x27;</code>.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">self.get_logger().info(...)</code></td>\\n<td>Uses the node&#x27;s managed logger. Unlike plain <code class=\\"inline-code\\">print()</code>, <code class=\\"inline-code\\">get_logger()</code> prefixes timestamps, node names, and supports severity levels and redirection to <code class=\\"inline-code\\">/rosout</code>.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">self.create_timer(1.0, callback)</code></td>\\n<td>Registers a periodic hardware timer. The ROS 2 executor triggers <code class=\\"inline-code\\">callback</code> every 1.0 second without blocking the thread.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">rclpy.init(args=args)</code></td>\\n<td>Initializes the ROS 2 communications context and parses any ROS command-line arguments (e.g. remappings). Must be called once before instantiating nodes.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">rclpy.spin(node)</code></td>\\n<td>Enters the event loop. Blocks the main thread and yields CPU execution to handle incoming timer ticks, subscriber messages, and service requests.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">node.destroy_node()</code></td>\\n<td>Explicitly frees internal DDS handles, publishers, and timers.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">rclpy.shutdown()</code></td>\\n<td>Shuts down the DDS middleware context cleanly before the Python process exits.</td>\\n</tr>\\n</tbody></table></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-building-and-symlink-installation\\">6. Building and Symlink Installation</h2>\\n<p>To make the node executable by ROS 2, we build the workspace using <code class=\\"inline-code\\">colcon</code>.</p>\\n<h3 id=\\"61-the-power-of---symlink-install\\">6.1 The Power of <code class=\\"inline-code\\">--symlink-install</code></h3>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"cd ~/ros2_ws\\ncolcon build --symlink-install\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">cd ~/ros2_ws\\ncolcon build --symlink-install</code></pre></div>\\n<div class=\\"alert-callout alert-tip\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Why <code class=\\"inline-code\\">--symlink-install</code> is Essential for Python Developers:</strong><br>By default, <code class=\\"inline-code\\">colcon build</code> copies your <code class=\\"inline-code\\">.py</code> source files from <code class=\\"inline-code\\">src/</code> into <code class=\\"inline-code\\">install/</code>. If you modify a Python script, you would have to run <code class=\\"inline-code\\">colcon build</code> again before changes take effect.<br>With <code class=\\"inline-code\\">--symlink-install</code>, <code class=\\"inline-code\\">colcon</code> creates a symbolic link (symlink) from <code class=\\"inline-code\\">install/</code> directly pointing back to your source file in <code class=\\"inline-code\\">src/</code>. <strong>You can edit Python code and run it immediately without rebuilding!</strong></div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"7-execution--verification\\">7. Execution &amp; Verification</h2>\\n<p>Open a new terminal (or Terminator split pane) and run:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# 1. Source the workspace overlay\\nsource ~/ros2_ws/install/setup.bash\\n\\n# 2. Run your new node\\nros2 run navpro_hello_py hello_node\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># 1. Source the workspace overlay\\nsource ~/ros2_ws/install/setup.bash\\n\\n# 2. Run your new node\\nros2 run navpro_hello_py hello_node</code></pre></div>\\n<h3 id=\\"expected-output\\">Expected Output:</h3>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"[INFO] [1718204921.120485] [navpro_hello_node]: Hello World! NavPro ROS 2 Python Node has booted.\\n[INFO] [1718204922.121304] [navpro_hello_node]: [Heartbeat #1] NavPro AMR is alive and operational.\\n[INFO] [1718204923.121541] [navpro_hello_node]: [Heartbeat #2] NavPro AMR is alive and operational.\\n[INFO] [1718204924.121702] [navpro_hello_node]: [Heartbeat #3] NavPro AMR is alive and operational.\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">[INFO] [1718204921.120485] [navpro_hello_node]: Hello World! NavPro ROS 2 Python Node has booted.\\n[INFO] [1718204922.121304] [navpro_hello_node]: [Heartbeat #1] NavPro AMR is alive and operational.\\n[INFO] [1718204923.121541] [navpro_hello_node]: [Heartbeat #2] NavPro AMR is alive and operational.\\n[INFO] [1718204924.121702] [navpro_hello_node]: [Heartbeat #3] NavPro AMR is alive and operational.</code></pre></div>\\n<p>In a second terminal, inspect the active node:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"ros2 node list\\n# /navpro_hello_node\\n\\nros2 node info /navpro_hello_node\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">ros2 node list\\n# /navpro_hello_node\\n\\nros2 node info /navpro_hello_node</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"8-hands-on-student-challenge\\">8. Hands-on Student Challenge</h2>\\n<p><strong>Task:</strong></p>\\n<p>Modify <code class=\\"inline-code\\">hello_node.py</code> to:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Increase the timer frequency from <code class=\\"inline-code\\">1.0 Hz</code> to <code class=\\"inline-code\\">5.0 Hz</code> (period = <code class=\\"inline-code\\">0.2</code> seconds).</li>\\n<li>Add a simulated battery percentage that starts at <code class=\\"inline-code\\">100.0%</code> and decreases by <code class=\\"inline-code\\">0.5%</code> on every timer tick.</li>\\n<li>Log a warning with <code class=\\"inline-code\\">self.get_logger().warn(...)</code> when the simulated battery drops below <code class=\\"inline-code\\">20.0%</code>.</li>\\n</ol>\\n<div class=\\"code-container\\" data-language=\\"python\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">PYTHON</span><button class=\\"copy-code-btn\\" data-code=\\"# TODO: FILL IN CODE HERE inside hello_node.py\\n# 1. Change create_timer period to 0.2\\n# 2. self.battery = 100.0\\n# 3. Inside callback: self.battery -= 0.5\\n# 4. Check if self.battery &lt; 20.0, use self.get_logger().warn(...)\\">📋 Copy</button></div><pre><code class=\\"language-python\\"># TODO: FILL IN CODE HERE inside hello_node.py\\n# 1. Change create_timer period to 0.2\\n# 2. self.battery = 100.0\\n# 3. Inside callback: self.battery -= 0.5\\n# 4. Check if self.battery &lt; 20.0, use self.get_logger().warn(...)</code></pre></div>\\n<p>Save your changes and re-run with <code class=\\"inline-code\\">ros2 run navpro_hello_py hello_node</code>—notice how <code class=\\"inline-code\\">--symlink-install</code> reflected your changes instantly!</p>","quizzes":[{"id":"q_l1_03_1","prompt":"What is the key benefit of passing the '--symlink-install' flag when building a Python package with colcon?","options":["It reduces compiled binary size by 50%","It links Python source files directly to the install folder so code changes take effect immediately without rebuilding","It creates symbolic links for C++ header libraries","It automatically signs the code with GPG keys"],"correct":1,"explanation":"--symlink-install creates symbolic links pointing from install/ to your source code in src/. For pure Python nodes, edits take effect immediately upon rerunning the node without invoking colcon build again."},{"id":"q_l1_03_2","prompt":"In an object-oriented ROS 2 Python node, which base class should your custom node inherit from?","options":["rclpy.node.Node","rclpy.executor.Executor","ros2.core.LifecycleNode","threading.Thread"],"correct":0,"explanation":"All standard ROS 2 Python nodes inherit from rclpy.node.Node, which encapsulates node lifecycle, parameter declarations, logging, publisher/subscriber factories, and callback timers."}],"has_quiz":true,"next_id":"lesson_04","prev_id":"lesson_02"},{"id":"lesson_04","num":4,"num_str":"04","title":"ROS 2 Package Architecture & Configuration Deep Dive","slug":"package_architecture_and_configuration","filename":"04_package_architecture_and_configuration.md","module":"Foundations & Core Middleware","module_id":1,"duration":"45-60 min","focus":"Python Package Internals (\`ament_python\`), \`package.xml\`, and \`setup.py\`","snapshot":[],"html_content":"<h1 id=\\"lesson-04-ros-2-package-architecture--configuration-deep-dive\\">Lesson 04: ROS 2 Package Architecture &amp; Configuration Deep Dive</h1>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Focus:</strong> Python Package Internals (<code class=\\"inline-code\\">ament_python</code>), <code class=\\"inline-code\\">package.xml</code>, and <code class=\\"inline-code\\">setup.py</code><br><strong>Course Track:</strong> NavPro Learning Hub - Level 1<br><strong>Target Environment:</strong> ROS 2 Jazzy Jalisco</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"1-overview--learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>In ROS 2, code cannot exist in isolation. All executable nodes, launch configurations, URDF models, and YAML parameters must reside inside a <strong>Package</strong>.</p>\\n<p>By the end of this lesson, you will:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Understand the anatomy and filesystem structure of an <code class=\\"inline-code\\">ament_python</code> package.</li>\\n<li>Master <code class=\\"inline-code\\">package.xml</code> (Format 3 schema), understanding dependency resolution tags (<code class=\\"inline-code\\">&lt;depend&gt;</code>, <code class=\\"inline-code\\">&lt;exec_depend&gt;</code>).</li>\\n<li>Master <code class=\\"inline-code\\">setup.py</code>, including <code class=\\"inline-code\\">data_files</code> installation to <code class=\\"inline-code\\">share/</code> and <code class=\\"inline-code\\">entry_points</code> console script mappings.</li>\\n<li>Understand how the <strong>Ament Index</strong> (<code class=\\"inline-code\\">resource/</code> marker file) enables <code class=\\"inline-code\\">ros2 run</code> and <code class=\\"inline-code\\">ros2 pkg</code> discovery.</li>\\n<li>Manually configure a production robotics package from scratch without relying on boilerplate generators.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-package-anatomy-what-makes-a-folder-a-ros-2-package\\">2. Package Anatomy: What Makes a Folder a ROS 2 Package?</h2>\\n<p>A pure Python package in ROS 2 follows the standard Python <code class=\\"inline-code\\">setuptools</code> packaging structure augmented with ROS 2 metadata:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"navpro_controller/\\n├── package.xml                 # 1. Package metadata &amp; dependency declarations (XML)\\n├── setup.py                    # 2. Python build script &amp; executable entry points\\n├── setup.cfg                   # 3. Target script installation directory configuration\\n├── resource/                   # 4. Ament Index marker folder\\n│   └── navpro_controller       #    Empty file matching package name (Discovery token)\\n├── navpro_controller/          # 5. Actual Python module directory\\n│   ├── __init__.py             #    Makes directory an importable Python module\\n│   ├── motor_driver.py         #    Custom node implementation\\n│   └── safety_supervisor.py    #    Custom node implementation\\n├── launch/                     # 6. Runtime launch files\\n│   └── controller.launch.py\\n└── config/                     # 7. YAML parameters and tuning files\\n    └── controller_params.yaml\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">navpro_controller/\\n├── package.xml                 # 1. Package metadata &amp; dependency declarations (XML)\\n├── setup.py                    # 2. Python build script &amp; executable entry points\\n├── setup.cfg                   # 3. Target script installation directory configuration\\n├── resource/                   # 4. Ament Index marker folder\\n│   └── navpro_controller       #    Empty file matching package name (Discovery token)\\n├── navpro_controller/          # 5. Actual Python module directory\\n│   ├── __init__.py             #    Makes directory an importable Python module\\n│   ├── motor_driver.py         #    Custom node implementation\\n│   └── safety_supervisor.py    #    Custom node implementation\\n├── launch/                     # 6. Runtime launch files\\n│   └── controller.launch.py\\n└── config/                     # 7. YAML parameters and tuning files\\n    └── controller_params.yaml</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-deep-dive-packagexml-schema-format-3\\">3. Deep Dive: <code class=\\"inline-code\\">package.xml</code> (Schema Format 3)</h2>\\n<p>The <code class=\\"inline-code\\">package.xml</code> file is parsed by <code class=\\"inline-code\\">colcon</code>, <code class=\\"inline-code\\">rosdep</code>, and the Debian packaging tools to determine dependencies and build order.</p>\\n<p>Here is a complete, production-grade <code class=\\"inline-code\\">package.xml</code> for a Python package:</p>\\n<div class=\\"code-container\\" data-language=\\"xml\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">XML</span><button class=\\"copy-code-btn\\" data-code=\\"&lt;?xml version=&quot;1.0&quot;?&gt;\\n&lt;?xml-model href=&quot;http://download.ros.org/schema/package_format3.xsd&quot; schematypens=&quot;http://www.w3.org/2001/XMLSchema&quot;?&gt;\\n&lt;package format=&quot;3&quot;&gt;\\n  &lt;name&gt;navpro_controller&lt;/name&gt;\\n  &lt;version&gt;1.0.0&lt;/version&gt;\\n  &lt;description&gt;Differential drive motor controller and safety supervisor for NavPro AMR&lt;/description&gt;\\n  \\n  &lt;maintainer email=&quot;engineer@navpro.io&quot;&gt;NavPro Robotics Team&lt;/maintainer&gt;\\n  &lt;license&gt;Apache-2.0&lt;/license&gt;\\n  \\n  &lt;author email=&quot;dev@navpro.io&quot;&gt;Lead Robotics Architect&lt;/author&gt;\\n\\n  &lt;!-- Build Tool Dependencies --&gt;\\n  &lt;!-- Python packages require setuptools to build and install --&gt;\\n  &lt;buildtool_depend&gt;ament_python&lt;/buildtool_depend&gt;\\n  &lt;buildtool_depend&gt;python3-setuptools&lt;/buildtool_depend&gt;\\n\\n  &lt;!-- Runtime / Execution Dependencies --&gt;\\n  &lt;!-- Packages your Python code imports at runtime --&gt;\\n  &lt;depend&gt;rclpy&lt;/depend&gt;\\n  &lt;depend&gt;geometry_msgs&lt;/depend&gt;\\n  &lt;depend&gt;sensor_msgs&lt;/depend&gt;\\n  &lt;depend&gt;std_msgs&lt;/depend&gt;\\n  &lt;depend&gt;nav_msgs&lt;/depend&gt;\\n\\n  &lt;!-- Testing Dependencies --&gt;\\n  &lt;test_depend&gt;ament_copyright&lt;/test_depend&gt;\\n  &lt;test_depend&gt;ament_flake8&lt;/test_depend&gt;\\n  &lt;test_depend&gt;ament_pep257&lt;/test_depend&gt;\\n  &lt;test_depend&gt;python3-pytest&lt;/test_depend&gt;\\n\\n  &lt;!-- Export Declaration --&gt;\\n  &lt;!-- Informs colcon this package is built with ament_python --&gt;\\n  &lt;export&gt;\\n    &lt;build_type&gt;ament_python&lt;/build_type&gt;\\n  &lt;/export&gt;\\n&lt;/package&gt;\\">📋 Copy</button></div><pre><code class=\\"language-xml\\">&lt;?xml version=&quot;1.0&quot;?&gt;\\n&lt;?xml-model href=&quot;http://download.ros.org/schema/package_format3.xsd&quot; schematypens=&quot;http://www.w3.org/2001/XMLSchema&quot;?&gt;\\n&lt;package format=&quot;3&quot;&gt;\\n  &lt;name&gt;navpro_controller&lt;/name&gt;\\n  &lt;version&gt;1.0.0&lt;/version&gt;\\n  &lt;description&gt;Differential drive motor controller and safety supervisor for NavPro AMR&lt;/description&gt;\\n  \\n  &lt;maintainer email=&quot;engineer@navpro.io&quot;&gt;NavPro Robotics Team&lt;/maintainer&gt;\\n  &lt;license&gt;Apache-2.0&lt;/license&gt;\\n  \\n  &lt;author email=&quot;dev@navpro.io&quot;&gt;Lead Robotics Architect&lt;/author&gt;\\n\\n  &lt;!-- Build Tool Dependencies --&gt;\\n  &lt;!-- Python packages require setuptools to build and install --&gt;\\n  &lt;buildtool_depend&gt;ament_python&lt;/buildtool_depend&gt;\\n  &lt;buildtool_depend&gt;python3-setuptools&lt;/buildtool_depend&gt;\\n\\n  &lt;!-- Runtime / Execution Dependencies --&gt;\\n  &lt;!-- Packages your Python code imports at runtime --&gt;\\n  &lt;depend&gt;rclpy&lt;/depend&gt;\\n  &lt;depend&gt;geometry_msgs&lt;/depend&gt;\\n  &lt;depend&gt;sensor_msgs&lt;/depend&gt;\\n  &lt;depend&gt;std_msgs&lt;/depend&gt;\\n  &lt;depend&gt;nav_msgs&lt;/depend&gt;\\n\\n  &lt;!-- Testing Dependencies --&gt;\\n  &lt;test_depend&gt;ament_copyright&lt;/test_depend&gt;\\n  &lt;test_depend&gt;ament_flake8&lt;/test_depend&gt;\\n  &lt;test_depend&gt;ament_pep257&lt;/test_depend&gt;\\n  &lt;test_depend&gt;python3-pytest&lt;/test_depend&gt;\\n\\n  &lt;!-- Export Declaration --&gt;\\n  &lt;!-- Informs colcon this package is built with ament_python --&gt;\\n  &lt;export&gt;\\n    &lt;build_type&gt;ament_python&lt;/build_type&gt;\\n  &lt;/export&gt;\\n&lt;/package&gt;</code></pre></div>\\n<h3 id=\\"dependency-tags-explained\\">Dependency Tags Explained:</h3>\\n<ul class=\\"lesson-bullet-list\\">\\n<li><code class=\\"inline-code\\">&lt;buildtool_depend&gt;</code>: Tools required to <em>build</em> the package (e.g. <code class=\\"inline-code\\">ament_python</code>).</li>\\n<li><code class=\\"inline-code\\">&lt;depend&gt;</code>: Declares that the package needs this dependency at <strong>both build-time and runtime</strong> (equivalent to specifying both <code class=\\"inline-code\\">&lt;build_depend&gt;</code> and <code class=\\"inline-code\\">&lt;exec_depend&gt;</code>).</li>\\n<li><code class=\\"inline-code\\">&lt;exec_depend&gt;</code>: Required <em>only</em> at runtime when the node executes.</li>\\n<li><code class=\\"inline-code\\">&lt;test_depend&gt;</code>: Required only when running unit tests via <code class=\\"inline-code\\">colcon test</code>.</li>\\n</ul>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-deep-dive-setuppy--console-scripts\\">4. Deep Dive: <code class=\\"inline-code\\">setup.py</code> &amp; Console Scripts</h2>\\n<p>The <code class=\\"inline-code\\">setup.py</code> script directs Python&#x27;s <code class=\\"inline-code\\">setuptools</code> on how to install code, configuration files, and create CLI binaries.</p>\\n<div class=\\"code-container\\" data-language=\\"python\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">PYTHON</span><button class=\\"copy-code-btn\\" data-code=\\"from setuptools import find_packages, setup\\nimport os\\nfrom glob import glob\\n\\npackage_name = &#x27;navpro_controller&#x27;\\n\\nsetup(\\n    name=package_name,\\n    version=&#x27;1.0.0&#x27;,\\n    # Automatically locate python subpackages inside navpro_controller/\\n    packages=find_packages(exclude=[&#x27;test&#x27;]),\\n    \\n    # data_files installs non-Python assets into the install/share/&lt;pkg&gt; directory\\n    data_files=[\\n        # 1. Ament Index Marker: Registers package with ROS 2 discovery\\n        (&#x27;share/ament_index/resource_index/packages&#x27;, [&#x27;resource/&#x27; + package_name]),\\n        \\n        # 2. package.xml: Installs package manifest into share/\\n        (&#x27;share/&#x27; + package_name, [&#x27;package.xml&#x27;]),\\n        \\n        # 3. Launch files: Installs all *.launch.py into share/&lt;pkg&gt;/launch\\n        (os.path.join(&#x27;share&#x27;, package_name, &#x27;launch&#x27;), glob(&#x27;launch/*.launch.py&#x27;)),\\n        \\n        # 4. Config files: Installs all *.yaml into share/&lt;pkg&gt;/config\\n        (os.path.join(&#x27;share&#x27;, package_name, &#x27;config&#x27;), glob(&#x27;config/*.yaml&#x27;)),\\n    ],\\n    \\n    install_requires=[&#x27;setuptools&#x27;],\\n    zip_safe=True,\\n    maintainer=&#x27;NavPro Robotics Team&#x27;,\\n    maintainer_email=&#x27;engineer@navpro.io&#x27;,\\n    description=&#x27;Differential drive motor controller package&#x27;,\\n    license=&#x27;Apache-2.0&#x27;,\\n    \\n    # entry_points generates executable binaries inside install/&lt;pkg&gt;/lib/&lt;pkg&gt;/\\n    entry_points={\\n        &#x27;console_scripts&#x27;: [\\n            # Syntax: &#x27;executable_name = package_dir.python_file:entry_function&#x27;\\n            &#x27;motor_driver = navpro_controller.motor_driver:main&#x27;,\\n            &#x27;safety_supervisor = navpro_controller.safety_supervisor:main&#x27;,\\n        ],\\n    },\\n)\\">📋 Copy</button></div><pre><code class=\\"language-python\\">from setuptools import find_packages, setup\\nimport os\\nfrom glob import glob\\n\\npackage_name = &#x27;navpro_controller&#x27;\\n\\nsetup(\\n    name=package_name,\\n    version=&#x27;1.0.0&#x27;,\\n    # Automatically locate python subpackages inside navpro_controller/\\n    packages=find_packages(exclude=[&#x27;test&#x27;]),\\n    \\n    # data_files installs non-Python assets into the install/share/&lt;pkg&gt; directory\\n    data_files=[\\n        # 1. Ament Index Marker: Registers package with ROS 2 discovery\\n        (&#x27;share/ament_index/resource_index/packages&#x27;, [&#x27;resource/&#x27; + package_name]),\\n        \\n        # 2. package.xml: Installs package manifest into share/\\n        (&#x27;share/&#x27; + package_name, [&#x27;package.xml&#x27;]),\\n        \\n        # 3. Launch files: Installs all *.launch.py into share/&lt;pkg&gt;/launch\\n        (os.path.join(&#x27;share&#x27;, package_name, &#x27;launch&#x27;), glob(&#x27;launch/*.launch.py&#x27;)),\\n        \\n        # 4. Config files: Installs all *.yaml into share/&lt;pkg&gt;/config\\n        (os.path.join(&#x27;share&#x27;, package_name, &#x27;config&#x27;), glob(&#x27;config/*.yaml&#x27;)),\\n    ],\\n    \\n    install_requires=[&#x27;setuptools&#x27;],\\n    zip_safe=True,\\n    maintainer=&#x27;NavPro Robotics Team&#x27;,\\n    maintainer_email=&#x27;engineer@navpro.io&#x27;,\\n    description=&#x27;Differential drive motor controller package&#x27;,\\n    license=&#x27;Apache-2.0&#x27;,\\n    \\n    # entry_points generates executable binaries inside install/&lt;pkg&gt;/lib/&lt;pkg&gt;/\\n    entry_points={\\n        &#x27;console_scripts&#x27;: [\\n            # Syntax: &#x27;executable_name = package_dir.python_file:entry_function&#x27;\\n            &#x27;motor_driver = navpro_controller.motor_driver:main&#x27;,\\n            &#x27;safety_supervisor = navpro_controller.safety_supervisor:main&#x27;,\\n        ],\\n    },\\n)</code></pre></div>\\n<h3 id=\\"how-entry_points-works\\">How <code class=\\"inline-code\\">entry_points</code> Works:</h3>\\n<p>When you execute <code class=\\"inline-code\\">ros2 run navpro_controller motor_driver</code>:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>ROS 2 queries the Ament Index for <code class=\\"inline-code\\">navpro_controller</code>.</li>\\n<li>It looks inside <code class=\\"inline-code\\">install/navpro_controller/lib/navpro_controller/motor_driver</code>.</li>\\n<li>Setuptools generates a wrapper script that automatically imports <code class=\\"inline-code\\">navpro_controller.motor_driver</code> and invokes <code class=\\"inline-code\\">main()</code>.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-supporting-files-setupcfg-and-resource\\">5. Supporting Files: <code class=\\"inline-code\\">setup.cfg</code> and <code class=\\"inline-code\\">resource/</code></h2>\\n<h3 id=\\"51-setupcfg\\">5.1 <code class=\\"inline-code\\">setup.cfg</code></h3>\\n<p>Tells setuptools where to place the generated executable binaries:</p>\\n<div class=\\"code-container\\" data-language=\\"ini\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">INI</span><button class=\\"copy-code-btn\\" data-code=\\"[develop]\\nscript_dir=$base/lib/navpro_controller\\n[install]\\ninstall_scripts=$base/lib/navpro_controller\\">📋 Copy</button></div><pre><code class=\\"language-ini\\">[develop]\\nscript_dir=$base/lib/navpro_controller\\n[install]\\ninstall_scripts=$base/lib/navpro_controller</code></pre></div>\\n<p>Without this file, executables would be placed directly in <code class=\\"inline-code\\">/bin</code> or <code class=\\"inline-code\\">/lib</code>, breaking ROS 2&#x27;s package namespacing.</p>\\n<h3 id=\\"52-resourcepackage_name\\">5.2 <code class=\\"inline-code\\">resource/&lt;package_name&gt;</code></h3>\\n<p>An empty file whose filename <strong>must exactly match</strong> <code class=\\"inline-code\\">package_name</code>. When installed into <code class=\\"inline-code\\">share/ament_index/resource_index/packages</code>, it acts as a marker. Commands like <code class=\\"inline-code\\">ros2 pkg list</code> simply read the directory listings of this resource folder.</p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-step-by-step-creating-a-modular-package-manually\\">6. Step-by-Step: Creating a Modular Package Manually</h2>\\n<p>Let&#x27;s create a real package called <code class=\\"inline-code\\">navpro_teleop_hub</code> step-by-step.</p>\\n<h3 id=\\"step-61-create-directory-tree\\">Step 6.1: Create Directory Tree</h3>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"cd ~/ros2_ws/src\\nmkdir -p navpro_teleop_hub/navpro_teleop_hub\\nmkdir -p navpro_teleop_hub/resource\\nmkdir -p navpro_teleop_hub/launch\\nmkdir -p navpro_teleop_hub/config\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">cd ~/ros2_ws/src\\nmkdir -p navpro_teleop_hub/navpro_teleop_hub\\nmkdir -p navpro_teleop_hub/resource\\nmkdir -p navpro_teleop_hub/launch\\nmkdir -p navpro_teleop_hub/config</code></pre></div>\\n<h3 id=\\"step-62-create-module-and-resource-markers\\">Step 6.2: Create Module and Resource Markers</h3>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"touch navpro_teleop_hub/navpro_teleop_hub/__init__.py\\ntouch navpro_teleop_hub/resource/navpro_teleop_hub\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">touch navpro_teleop_hub/navpro_teleop_hub/__init__.py\\ntouch navpro_teleop_hub/resource/navpro_teleop_hub</code></pre></div>\\n<h3 id=\\"step-63-create-setupcfg\\">Step 6.3: Create <code class=\\"inline-code\\">setup.cfg</code></h3>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"cat &lt;&lt; &#x27;EOF&#x27; &gt; navpro_teleop_hub/setup.cfg\\n[develop]\\nscript_dir=$base/lib/navpro_teleop_hub\\n[install]\\ninstall_scripts=$base/lib/navpro_teleop_hub\\nEOF\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">cat &lt;&lt; &#x27;EOF&#x27; &gt; navpro_teleop_hub/setup.cfg\\n[develop]\\nscript_dir=$base/lib/navpro_teleop_hub\\n[install]\\ninstall_scripts=$base/lib/navpro_teleop_hub\\nEOF</code></pre></div>\\n<h3 id=\\"step-64-write-the-node-file-teleop_hubpy\\">Step 6.4: Write the Node File (<code class=\\"inline-code\\">teleop_hub.py</code>)</h3>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"cat &lt;&lt; &#x27;EOF&#x27; &gt; navpro_teleop_hub/navpro_teleop_hub/teleop_hub.py\\n#!/usr/bin/env python3\\nimport rclpy\\nfrom rclpy.node import Node\\n\\nclass TeleopHub(Node):\\n    def __init__(self):\\n        super().__init__(&#x27;teleop_hub&#x27;)\\n        self.get_logger().info(&#x27;Teleop Hub Node initialized successfully!&#x27;)\\n\\ndef main():\\n    rclpy.init()\\n    node = TeleopHub()\\n    try:\\n        rclpy.spin(node)\\n    except KeyboardInterrupt:\\n        pass\\n    finally:\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\nEOF\\nchmod +x navpro_teleop_hub/navpro_teleop_hub/teleop_hub.py\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">cat &lt;&lt; &#x27;EOF&#x27; &gt; navpro_teleop_hub/navpro_teleop_hub/teleop_hub.py\\n#!/usr/bin/env python3\\nimport rclpy\\nfrom rclpy.node import Node\\n\\nclass TeleopHub(Node):\\n    def __init__(self):\\n        super().__init__(&#x27;teleop_hub&#x27;)\\n        self.get_logger().info(&#x27;Teleop Hub Node initialized successfully!&#x27;)\\n\\ndef main():\\n    rclpy.init()\\n    node = TeleopHub()\\n    try:\\n        rclpy.spin(node)\\n    except KeyboardInterrupt:\\n        pass\\n    finally:\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\nEOF\\nchmod +x navpro_teleop_hub/navpro_teleop_hub/teleop_hub.py</code></pre></div>\\n<h3 id=\\"step-65-configure-packagexml-and-setuppy\\">Step 6.5: Configure <code class=\\"inline-code\\">package.xml</code> and <code class=\\"inline-code\\">setup.py</code></h3>\\n<p>Add the standard <code class=\\"inline-code\\">package.xml</code> and <code class=\\"inline-code\\">setup.py</code> templates detailed in Sections 3 and 4 with entry point:</p>\\n<p><code class=\\"inline-code\\">&#x27;teleop_hub = navpro_teleop_hub.teleop_hub:main&#x27;</code></p>\\n<h3 id=\\"step-66-build-and-test\\">Step 6.6: Build and Test</h3>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"cd ~/ros2_ws\\ncolcon build --symlink-install --packages-select navpro_teleop_hub\\nsource install/setup.bash\\nros2 run navpro_teleop_hub teleop_hub\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">cd ~/ros2_ws\\ncolcon build --symlink-install --packages-select navpro_teleop_hub\\nsource install/setup.bash\\nros2 run navpro_teleop_hub teleop_hub</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"7-common-package-debugging--error-resolution\\">7. Common Package Debugging &amp; Error Resolution</h2>\\n<div class=\\"table-wrapper\\"><table>\\n<thead><tr>\\n<th>Symptom / Error</th>\\n<th>Root Cause</th>\\n<th>Solution</th>\\n</tr></thead><tbody>\\n<tr>\\n<td><code class=\\"inline-code\\">Package &#x27;xyz&#x27; not found</code></td>\\n<td>Workspace not sourced, or missing resource marker file</td>\\n<td>Run <code class=\\"inline-code\\">source install/setup.bash</code>. Check if <code class=\\"inline-code\\">resource/xyz</code> exists and is installed in <code class=\\"inline-code\\">setup.py</code>.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">No executable found</code></td>\\n<td>Missing entry point in <code class=\\"inline-code\\">setup.py</code>, or <code class=\\"inline-code\\">setup.cfg</code> missing</td>\\n<td>Check <code class=\\"inline-code\\">entry_points[&#x27;console_scripts&#x27;]</code> for typos. Rebuild with <code class=\\"inline-code\\">colcon build</code>.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">ModuleNotFoundError: No module named &#x27;xyz&#x27;</code></td>\\n<td>Package name mismatch or missing <code class=\\"inline-code\\">__init__.py</code> in python subfolder</td>\\n<td>Ensure directory name matches package name and contains <code class=\\"inline-code\\">__init__.py</code>.</td>\\n</tr>\\n<tr>\\n<td>Changes in <code class=\\"inline-code\\">.py</code> file not updating</td>\\n<td>Built without <code class=\\"inline-code\\">--symlink-install</code></td>\\n<td>Rebuild using <code class=\\"inline-code\\">colcon build --symlink-install</code>.</td>\\n</tr>\\n</tbody></table></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"8-hands-on-student-challenge\\">8. Hands-on Student Challenge</h2>\\n<p><strong>Task:</strong></p>\\n<p>In your newly created package <code class=\\"inline-code\\">navpro_teleop_hub</code>:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Create a second node file: <code class=\\"inline-code\\">navpro_teleop_hub/battery_monitor.py</code>.</li>\\n<li>Register it as a second executable in <code class=\\"inline-code\\">setup.py</code> entry points under the binary name <code class=\\"inline-code\\">battery_monitor</code>.</li>\\n<li>Re-run <code class=\\"inline-code\\">colcon build --symlink-install --packages-select navpro_teleop_hub</code>.</li>\\n<li>Verify you can run both nodes independently via <code class=\\"inline-code\\">ros2 run navpro_teleop_hub teleop_hub</code> and <code class=\\"inline-code\\">ros2 run navpro_teleop_hub battery_monitor</code>.</li>\\n</ol>","quizzes":[{"id":"q_l1_04_1","prompt":"In a Python ROS 2 package, where must executable CLI scripts be declared so 'ros2 run <pkg> <executable>' can discover them?","options":["Inside package.xml under <export><executable>","Inside setup.py under entry_points={'console_scripts': [...] }","In a bash script located in /usr/local/bin","In the resource/ marker file"],"correct":1,"explanation":"setuptools uses the entry_points dict with 'console_scripts' to generate standard Python executable wrappers in the package's install/lib/<pkg> directory during colcon build."},{"id":"q_l1_04_2","prompt":"What is the purpose of the empty marker file inside the 'resource/' directory of a ROS 2 Python package?","options":["It stores cached colcon build timestamps","It allows the ament indexer (ament_index_python) to register and find the package at runtime","It is a required license verification stamp","It holds URDF mesh textures"],"correct":1,"explanation":"The file resource/<pkg_name> is indexed by ament_index. It allows tools like 'ros2 pkg list' and 'get_package_share_directory()' to locate the package share directory on the system."}],"has_quiz":true,"next_id":"lesson_05","prev_id":"lesson_03"},{"id":"lesson_05","num":5,"num_str":"05","title":"Communication Mechanism I: Publishers, Subscribers & QoS","slug":"publishers_subscribers_and_qos","filename":"05_publishers_subscribers_and_qos.md","module":"Foundations & Core Middleware","module_id":1,"duration":"45-60 min","focus":"Asynchronous Topic Communication, Quality of Service (QoS) & Python Implementation","snapshot":[["Publish/Subscribe","Asynchronous, non-blocking one-to-many communication over the DDS bus."],["Quality of Service (QoS)","Sensor data (LiDAR, Camera) utilizes BEST_EFFORT (lossy UDP); mission commands use RELIABLE (guaranteed TCP-like)."],["Volatile vs Transient Local","Late-joining subscribers miss past data under Volatile, but receive cached historical states under Transient Local."]],"html_content":"<h1 id=\\"lesson-05-communication-mechanism-i-publishers-subscribers--qos\\">Lesson 05: Communication Mechanism I: Publishers, Subscribers &amp; QoS</h1>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Focus:</strong> Asynchronous Topic Communication, Quality of Service (QoS) &amp; Python Implementation<br><strong>Course Track:</strong> NavPro Learning Hub - Level 1 (Chapters 5.2, 8.2 &amp; Project 1.2)<br><strong>Target Environment:</strong> ROS 2 Jazzy Jalisco</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"1-overview--learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>The <strong>Publish-Subscribe (Pub/Sub)</strong> pattern is the primary asynchronous communication backbone of ROS 2. Nodes communicate via named buses called <strong>Topics</strong> without needing to know which specific nodes are producing or consuming the data.</p>\\n<p>By the end of this lesson, you will:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Understand the anonymous, asynchronous nature of ROS 2 Topics.</li>\\n<li>Build an object-oriented Python <strong>Publisher</strong> sending velocity setpoints (<code class=\\"inline-code\\">geometry_msgs/msg/Twist</code>).</li>\\n<li>Build an object-oriented Python <strong>Subscriber</strong> processing incoming sensor data with custom callbacks.</li>\\n<li>Master <strong>Quality of Service (QoS)</strong> policies: Reliability, Durability, and History.</li>\\n<li>Prevent the #1 common ROS 2 networking bug: <strong>QoS Incompatibility</strong>.</li>\\n<li>Build <strong>Project 1.2</strong>: An autonomous differential drive velocity supervisor and obstacle filter.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-topic-communication-architecture\\">2. Topic Communication Architecture</h2>\\n<p>In ROS 2, topics are unidirectional, many-to-many data streams:</p>\\n<div class=\\"lesson-image-wrapper\\"><img src=\\"assets/images/ros2_pubsub_pipeline.svg\\" alt=\\"ROS 2 Publish-Subscribe Computational Graph\\" class=\\"lesson-image\\" loading=\\"lazy\\"><span class=\\"image-caption\\">ROS 2 Publish-Subscribe Computational Graph</span></div>\\n<ul class=\\"lesson-bullet-list\\">\\n<li><strong>Publishers:</strong> Produce structured messages and push them onto a topic.</li>\\n<li><strong>Subscribers:</strong> Register interest in a topic and invoke a designated callback function whenever a new message arrives.</li>\\n<li><strong>Anonymous &amp; Decoupled:</strong> A publisher does not know or care how many subscribers exist, or even if any exist at all.</li>\\n</ul>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-deep-dive-quality-of-service-qos-policies\\">3. Deep Dive: Quality of Service (QoS) Policies</h2>\\n<p>Unlike ROS 1 (which used TCP/UDP sockets with hardcoded parameters), ROS 2 allows developers to fine-tune network transport behavior per topic using DDS <strong>QoS Profiles</strong>.</p>\\n<div class=\\"table-wrapper\\"><table>\\n<thead><tr>\\n<th>QoS Policy</th>\\n<th>Setting</th>\\n<th>Behavior &amp; Characteristics</th>\\n</tr></thead><tbody>\\n<tr>\\n<td><strong>Reliability</strong></td>\\n<td><code class=\\"inline-code\\">RELIABLE</code></td>\\n<td>Guarantees message delivery via packet ACKs and retransmissions. Ideal for commands and state flags.</td>\\n</tr>\\n<tr>\\n<td><strong>Reliability</strong></td>\\n<td><code class=\\"inline-code\\">BEST_EFFORT</code></td>\\n<td>Fire-and-forget. Drops lost packets immediately without retransmission. Lowest latency for high-rate sensors (LiDAR, Cameras).</td>\\n</tr>\\n<tr>\\n<td><strong>Durability</strong></td>\\n<td><code class=\\"inline-code\\">VOLATILE</code></td>\\n<td>Default. Late-joining subscribers only receive messages published after connection.</td>\\n</tr>\\n<tr>\\n<td><strong>Durability</strong></td>\\n<td><code class=\\"inline-code\\">TRANSIENT_LOCAL</code></td>\\n<td>Publisher retains the last $N$ messages in memory. Late subscribers receive recent history upon connection.</td>\\n</tr>\\n<tr>\\n<td><strong>History</strong></td>\\n<td><code class=\\"inline-code\\">KEEP_LAST</code></td>\\n<td>Retains up to $N$ messages in the queue (depth configurable). Oldest messages dropped when full.</td>\\n</tr>\\n<tr>\\n<td><strong>History</strong></td>\\n<td><code class=\\"inline-code\\">KEEP_ALL</code></td>\\n<td>Buffers all incoming messages until consumed. Risk of out-of-memory if subscribers process slowly.</td>\\n</tr>\\n</tbody></table></div>\\n<h3 id=\\"31-the-qos-compatibility-rule\\">3.1 The QoS Compatibility Rule</h3>\\n<div class=\\"alert-callout alert-warning\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>A subscriber&#x27;s QoS requirements must be LESS restrictive than or equal to the publisher&#x27;s QoS offering.</strong><br>If a publisher offers <code class=\\"inline-code\\">BEST_EFFORT</code>, but a subscriber requests <code class=\\"inline-code\\">RELIABLE</code>, <strong>DDS will reject the connection and NO DATA will be received!</strong></div></div>\\n<div class=\\"table-wrapper\\"><table>\\n<thead><tr>\\n<th>Publisher Offers</th>\\n<th>Subscriber Requests</th>\\n<th>Compatible?</th>\\n<th>Result</th>\\n</tr></thead><tbody>\\n<tr>\\n<td><code class=\\"inline-code\\">RELIABLE</code></td>\\n<td><code class=\\"inline-code\\">RELIABLE</code></td>\\n<td>✅ YES</td>\\n<td>Reliable delivery with ACKs</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">RELIABLE</code></td>\\n<td><code class=\\"inline-code\\">BEST_EFFORT</code></td>\\n<td>✅ YES</td>\\n<td>Subscriber tolerates drops, Publisher guarantees delivery</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">BEST_EFFORT</code></td>\\n<td><code class=\\"inline-code\\">BEST_EFFORT</code></td>\\n<td>✅ YES</td>\\n<td>Fast best-effort streaming (ideal for LiDAR / Cameras)</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">BEST_EFFORT</code></td>\\n<td><code class=\\"inline-code\\">RELIABLE</code></td>\\n<td>❌ <strong>NO</strong></td>\\n<td><strong>SILENT FAILURE: No messages delivered!</strong></td>\\n</tr>\\n</tbody></table></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-step-by-step-writing-a-velocity-publisher-in-python\\">4. Step-by-Step: Writing a Velocity Publisher in Python</h2>\\n<p>Let&#x27;s write a node that periodically publishes <code class=\\"inline-code\\">geometry_msgs/msg/Twist</code> commands to drive the robot.</p>\\n<p>Create file <code class=\\"inline-code\\">publisher_node.py</code>:</p>\\n<div class=\\"code-container\\" data-language=\\"python\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">PYTHON</span><button class=\\"copy-code-btn\\" data-code=\\"#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nNavPro Learning Hub - Lesson 05\\nTopic Publisher: Generates smooth velocity setpoints for differential drive robots.\\n&quot;&quot;&quot;\\n\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom geometry_msgs.msg import Twist\\nfrom rclpy.qos import QoSProfile, ReliabilityPolicy, HistoryPolicy\\n\\n\\nclass VelocityPublisher(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;velocity_publisher_node&#x27;)\\n\\n        # 1. Define custom QoS profile for motion control (Reliable, keep last 10)\\n        qos_profile = QoSProfile(\\n            reliability=ReliabilityPolicy.RELIABLE,\\n            history=HistoryPolicy.KEEP_LAST,\\n            depth=10\\n        )\\n\\n        # 2. Create Publisher: topic=&#x27;/cmd_vel&#x27;, type=Twist\\n        self.publisher_ = self.create_publisher(Twist, &#x27;/cmd_vel&#x27;, qos_profile)\\n\\n        # 3. Create timer loop running at 10 Hz (period = 0.1s)\\n        self.timer_ = self.create_timer(0.1, self.publish_velocity)\\n        self.tick_count_ = 0\\n\\n        self.get_logger().info(&#x27;Velocity Publisher initialized. Broadcasting on /cmd_vel at 10Hz.&#x27;)\\n\\n    def publish_velocity(self):\\n        msg = Twist()\\n        # Linear velocity (forward/backward) along X axis (m/s)\\n        msg.linear.x = 0.35\\n        msg.linear.y = 0.0\\n        msg.linear.z = 0.0\\n\\n        # Angular velocity (rotation/yaw) around Z axis (rad/s)\\n        msg.angular.x = 0.0\\n        msg.angular.y = 0.0\\n        msg.angular.z = 0.15\\n\\n        self.publisher_.publish(msg)\\n        self.tick_count_ += 1\\n\\n        # Log every 20 ticks (every 2 seconds) to avoid spamming terminal\\n        if self.tick_count_ % 20 == 0:\\n            self.get_logger().info(\\n                f&#x27;Published /cmd_vel -&gt; Linear: {msg.linear.x:.2f} m/s, Angular: {msg.angular.z:.2f} rad/s&#x27;\\n            )\\n\\n\\ndef main(args=None):\\n    rclpy.init(args=args)\\n    node = VelocityPublisher()\\n    try:\\n        rclpy.spin(node)\\n    except KeyboardInterrupt:\\n        node.get_logger().warn(&#x27;Stopping velocity publisher...&#x27;)\\n    finally:\\n        # Publish zero velocity before exiting to stop physical motors!\\n        stop_msg = Twist()\\n        node.publisher_.publish(stop_msg)\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\">📋 Copy</button></div><pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nNavPro Learning Hub - Lesson 05\\nTopic Publisher: Generates smooth velocity setpoints for differential drive robots.\\n&quot;&quot;&quot;\\n\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom geometry_msgs.msg import Twist\\nfrom rclpy.qos import QoSProfile, ReliabilityPolicy, HistoryPolicy\\n\\n\\nclass VelocityPublisher(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;velocity_publisher_node&#x27;)\\n\\n        # 1. Define custom QoS profile for motion control (Reliable, keep last 10)\\n        qos_profile = QoSProfile(\\n            reliability=ReliabilityPolicy.RELIABLE,\\n            history=HistoryPolicy.KEEP_LAST,\\n            depth=10\\n        )\\n\\n        # 2. Create Publisher: topic=&#x27;/cmd_vel&#x27;, type=Twist\\n        self.publisher_ = self.create_publisher(Twist, &#x27;/cmd_vel&#x27;, qos_profile)\\n\\n        # 3. Create timer loop running at 10 Hz (period = 0.1s)\\n        self.timer_ = self.create_timer(0.1, self.publish_velocity)\\n        self.tick_count_ = 0\\n\\n        self.get_logger().info(&#x27;Velocity Publisher initialized. Broadcasting on /cmd_vel at 10Hz.&#x27;)\\n\\n    def publish_velocity(self):\\n        msg = Twist()\\n        # Linear velocity (forward/backward) along X axis (m/s)\\n        msg.linear.x = 0.35\\n        msg.linear.y = 0.0\\n        msg.linear.z = 0.0\\n\\n        # Angular velocity (rotation/yaw) around Z axis (rad/s)\\n        msg.angular.x = 0.0\\n        msg.angular.y = 0.0\\n        msg.angular.z = 0.15\\n\\n        self.publisher_.publish(msg)\\n        self.tick_count_ += 1\\n\\n        # Log every 20 ticks (every 2 seconds) to avoid spamming terminal\\n        if self.tick_count_ % 20 == 0:\\n            self.get_logger().info(\\n                f&#x27;Published /cmd_vel -&gt; Linear: {msg.linear.x:.2f} m/s, Angular: {msg.angular.z:.2f} rad/s&#x27;\\n            )\\n\\n\\ndef main(args=None):\\n    rclpy.init(args=args)\\n    node = VelocityPublisher()\\n    try:\\n        rclpy.spin(node)\\n    except KeyboardInterrupt:\\n        node.get_logger().warn(&#x27;Stopping velocity publisher...&#x27;)\\n    finally:\\n        # Publish zero velocity before exiting to stop physical motors!\\n        stop_msg = Twist()\\n        node.publisher_.publish(stop_msg)\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-step-by-step-writing-a-velocity-subscriber-in-python\\">5. Step-by-Step: Writing a Velocity Subscriber in Python</h2>\\n<p>Now let&#x27;s build the consumer node that receives <code class=\\"inline-code\\">/cmd_vel</code> messages and simulates motor actuation.</p>\\n<p>Create file <code class=\\"inline-code\\">subscriber_node.py</code>:</p>\\n<div class=\\"code-container\\" data-language=\\"python\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">PYTHON</span><button class=\\"copy-code-btn\\" data-code=\\"#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nNavPro Learning Hub - Lesson 05\\nTopic Subscriber: Consumes velocity commands and computes wheel drive velocities.\\n&quot;&quot;&quot;\\n\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom geometry_msgs.msg import Twist\\nfrom rclpy.qos import QoSProfile, ReliabilityPolicy, HistoryPolicy\\n\\n\\nclass MotorControllerSubscriber(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;motor_controller_subscriber&#x27;)\\n\\n        # Differential drive robot geometry constants\\n        self.WHEEL_RADIUS = 0.06       # meters\\n        self.WHEEL_SEPARATION = 0.32   # meters\\n\\n        # Subscriber QoS profile (must match or be less strict than publisher)\\n        qos_profile = QoSProfile(\\n            reliability=ReliabilityPolicy.RELIABLE,\\n            history=HistoryPolicy.KEEP_LAST,\\n            depth=10\\n        )\\n\\n        # Create Subscription: topic=&#x27;/cmd_vel&#x27;, type=Twist, callback=self.cmd_vel_callback\\n        self.subscription_ = self.create_subscription(\\n            Twist,\\n            &#x27;/cmd_vel&#x27;,\\n            self.cmd_vel_callback,\\n            qos_profile\\n        )\\n\\n        self.get_logger().info(&#x27;Motor Controller Subscriber active. Listening on /cmd_vel.&#x27;)\\n\\n    def cmd_vel_callback(self, msg: Twist):\\n        &quot;&quot;&quot;Executed automatically whenever a new Twist message arrives on /cmd_vel.&quot;&quot;&quot;\\n        v = msg.linear.x      # Forward linear velocity (m/s)\\n        w = msg.angular.z     # Rotational angular velocity (rad/s)\\n\\n        # Compute individual left and right wheel velocities using inverse kinematics\\n        # v_left  = v - (w * L / 2)\\n        # v_right = v + (w * L / 2)\\n        v_left = v - (w * self.WHEEL_SEPARATION / 2.0)\\n        v_right = v + (w * self.WHEEL_SEPARATION / 2.0)\\n\\n        # Convert linear wheel speed to rotational wheel angular speed: omega = v / R\\n        omega_left = v_left / self.WHEEL_RADIUS\\n        omega_right = v_right / self.WHEEL_RADIUS\\n\\n        self.get_logger().info(\\n            f&#x27;Received (v={v:.2f}, w={w:.2f}) -&gt; Wheel RPM: Left={omega_left:.1f} rad/s, Right={omega_right:.1f} rad/s&#x27;\\n        )\\n\\n\\ndef main(args=None):\\n    rclpy.init(args=args)\\n    node = MotorControllerSubscriber()\\n    try:\\n        rclpy.spin(node)\\n    except KeyboardInterrupt:\\n        pass\\n    finally:\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\">📋 Copy</button></div><pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nNavPro Learning Hub - Lesson 05\\nTopic Subscriber: Consumes velocity commands and computes wheel drive velocities.\\n&quot;&quot;&quot;\\n\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom geometry_msgs.msg import Twist\\nfrom rclpy.qos import QoSProfile, ReliabilityPolicy, HistoryPolicy\\n\\n\\nclass MotorControllerSubscriber(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;motor_controller_subscriber&#x27;)\\n\\n        # Differential drive robot geometry constants\\n        self.WHEEL_RADIUS = 0.06       # meters\\n        self.WHEEL_SEPARATION = 0.32   # meters\\n\\n        # Subscriber QoS profile (must match or be less strict than publisher)\\n        qos_profile = QoSProfile(\\n            reliability=ReliabilityPolicy.RELIABLE,\\n            history=HistoryPolicy.KEEP_LAST,\\n            depth=10\\n        )\\n\\n        # Create Subscription: topic=&#x27;/cmd_vel&#x27;, type=Twist, callback=self.cmd_vel_callback\\n        self.subscription_ = self.create_subscription(\\n            Twist,\\n            &#x27;/cmd_vel&#x27;,\\n            self.cmd_vel_callback,\\n            qos_profile\\n        )\\n\\n        self.get_logger().info(&#x27;Motor Controller Subscriber active. Listening on /cmd_vel.&#x27;)\\n\\n    def cmd_vel_callback(self, msg: Twist):\\n        &quot;&quot;&quot;Executed automatically whenever a new Twist message arrives on /cmd_vel.&quot;&quot;&quot;\\n        v = msg.linear.x      # Forward linear velocity (m/s)\\n        w = msg.angular.z     # Rotational angular velocity (rad/s)\\n\\n        # Compute individual left and right wheel velocities using inverse kinematics\\n        # v_left  = v - (w * L / 2)\\n        # v_right = v + (w * L / 2)\\n        v_left = v - (w * self.WHEEL_SEPARATION / 2.0)\\n        v_right = v + (w * self.WHEEL_SEPARATION / 2.0)\\n\\n        # Convert linear wheel speed to rotational wheel angular speed: omega = v / R\\n        omega_left = v_left / self.WHEEL_RADIUS\\n        omega_right = v_right / self.WHEEL_RADIUS\\n\\n        self.get_logger().info(\\n            f&#x27;Received (v={v:.2f}, w={w:.2f}) -&gt; Wheel RPM: Left={omega_left:.1f} rad/s, Right={omega_right:.1f} rad/s&#x27;\\n        )\\n\\n\\ndef main(args=None):\\n    rclpy.init(args=args)\\n    node = MotorControllerSubscriber()\\n    try:\\n        rclpy.spin(node)\\n    except KeyboardInterrupt:\\n        pass\\n    finally:\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-verification-with-the-ros-2-command-line-interface-cli\\">6. Verification with the ROS 2 Command Line Interface (CLI)</h2>\\n<p>Open two Terminator panes and run the nodes:</p>\\n<p><strong>Pane 1:</strong></p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"ros2 run navpro_basics publisher_explained\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">ros2 run navpro_basics publisher_explained</code></pre></div>\\n<p><strong>Pane 2:</strong></p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"ros2 run navpro_basics subscriber_explained\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">ros2 run navpro_basics subscriber_explained</code></pre></div>\\n<p>In a third pane, inspect the live DDS topic communication:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# 1. List all active topics\\nros2 topic list\\n\\n# 2. Inspect topic type and publisher/subscriber count\\nros2 topic info /cmd_vel\\n\\n# 3. Echo live messages passing through the DDS bus\\nros2 topic echo /cmd_vel\\n\\n# 4. Measure message publishing frequency (Hz)\\nros2 topic hz /cmd_vel\\n\\n# 5. Measure network bandwidth consumed by topic\\nros2 topic bw /cmd_vel\\n\\n# 6. Manually publish a one-shot velocity command from terminal\\nros2 topic pub --once /cmd_vel geometry_msgs/msg/Twist &quot;{linear: {x: 0.5}, angular: {z: 0.0}}&quot;\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># 1. List all active topics\\nros2 topic list\\n\\n# 2. Inspect topic type and publisher/subscriber count\\nros2 topic info /cmd_vel\\n\\n# 3. Echo live messages passing through the DDS bus\\nros2 topic echo /cmd_vel\\n\\n# 4. Measure message publishing frequency (Hz)\\nros2 topic hz /cmd_vel\\n\\n# 5. Measure network bandwidth consumed by topic\\nros2 topic bw /cmd_vel\\n\\n# 6. Manually publish a one-shot velocity command from terminal\\nros2 topic pub --once /cmd_vel geometry_msgs/msg/Twist &quot;{linear: {x: 0.5}, angular: {z: 0.0}}&quot;</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"7-project-12-dual-publisher--subscriber-safety-supervisor\\">7. Project 1.2: Dual Publisher &amp; Subscriber Safety Supervisor</h2>\\n<h3 id=\\"project-objective\\">Project Objective:</h3>\\n<p>Write a node named <code class=\\"inline-code\\">safety_supervisor</code> that bridges raw teleoperation input and physical motor execution.</p>\\n<p><strong>Requirements:</strong></p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Subscribe to <code class=\\"inline-code\\">/teleop/cmd_vel</code> (<code class=\\"inline-code\\">geometry_msgs/msg/Twist</code>).</li>\\n<li>Subscribe to <code class=\\"inline-code\\">/obstacle_distance</code> (<code class=\\"inline-code\\">std_msgs/msg/Float32</code>).</li>\\n<li>If <code class=\\"inline-code\\">/obstacle_distance</code> is <code class=\\"inline-code\\">&lt; 0.4</code> meters:</li>\\n</ol>\\n<ul class=\\"lesson-bullet-list\\">\\n<li>Immediately override <code class=\\"inline-code\\">linear.x</code> to <code class=\\"inline-code\\">0.0</code> (emergency stop).</li>\\n<li>Log a warning: <code class=\\"inline-code\\">EMERGENCY BRAKE ENGAGED! Obstacle too close.</code></li>\\n</ul>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Otherwise:</li>\\n</ol>\\n<ul class=\\"lesson-bullet-list\\">\\n<li>Scale <code class=\\"inline-code\\">linear.x</code> and <code class=\\"inline-code\\">angular.z</code> by safety scale factor <code class=\\"inline-code\\">0.85</code>.</li>\\n</ul>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Publish the safe velocity command to <code class=\\"inline-code\\">/cmd_vel</code>.</li>\\n</ol>\\n<div class=\\"code-container\\" data-language=\\"python\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">PYTHON</span><button class=\\"copy-code-btn\\" data-code=\\"# Project 1.2 Boilerplate Starter Code\\nclass SafetySupervisor(Node):\\n    def __init__(self):\\n        super().__init__(&#x27;safety_supervisor&#x27;)\\n        \\n        # TODO 1: Create publisher on &#x27;/cmd_vel&#x27; (Twist)\\n        # TODO: FILL IN CODE HERE\\n        \\n        # TODO 2: Create subscriber on &#x27;/teleop/cmd_vel&#x27; (Twist)\\n        # TODO: FILL IN CODE HERE\\n        \\n        # TODO 3: Create subscriber on &#x27;/obstacle_distance&#x27; (Float32)\\n        # TODO: FILL IN CODE HERE\\n        \\n        self.obstacle_distance = 10.0  # meters\\n        \\n    def on_obstacle_scan(self, msg):\\n        # TODO 4: Update self.obstacle_distance\\n        # TODO: FILL IN CODE HERE\\n        pass\\n        \\n    def on_teleop_cmd(self, msg):\\n        # TODO 5: If obstacle_distance &lt; 0.4: zero out linear.x\\n        # TODO 6: Else: scale velocities by 0.85 and publish\\n        # TODO: FILL IN CODE HERE\\n        pass\\">📋 Copy</button></div><pre><code class=\\"language-python\\"># Project 1.2 Boilerplate Starter Code\\nclass SafetySupervisor(Node):\\n    def __init__(self):\\n        super().__init__(&#x27;safety_supervisor&#x27;)\\n        \\n        # TODO 1: Create publisher on &#x27;/cmd_vel&#x27; (Twist)\\n        # TODO: FILL IN CODE HERE\\n        \\n        # TODO 2: Create subscriber on &#x27;/teleop/cmd_vel&#x27; (Twist)\\n        # TODO: FILL IN CODE HERE\\n        \\n        # TODO 3: Create subscriber on &#x27;/obstacle_distance&#x27; (Float32)\\n        # TODO: FILL IN CODE HERE\\n        \\n        self.obstacle_distance = 10.0  # meters\\n        \\n    def on_obstacle_scan(self, msg):\\n        # TODO 4: Update self.obstacle_distance\\n        # TODO: FILL IN CODE HERE\\n        pass\\n        \\n    def on_teleop_cmd(self, msg):\\n        # TODO 5: If obstacle_distance &lt; 0.4: zero out linear.x\\n        # TODO 6: Else: scale velocities by 0.85 and publish\\n        # TODO: FILL IN CODE HERE\\n        pass</code></pre></div>","quizzes":[{"id":"q_l1_05_1","prompt":"Which ROS 2 QoS Reliability policy is best suited for 50Hz LiDAR sensor streams where low latency is critical and dropping an occasional packet is acceptable?","options":["ReliabilityPolicy.RELIABLE","ReliabilityPolicy.BEST_EFFORT","DurabilityPolicy.TRANSIENT_LOCAL","HistoryPolicy.KEEP_ALL"],"correct":1,"explanation":"BEST_EFFORT transmits UDP packets without waiting for retransmission ACKs. For high-frequency sensor streams, late packets are obsolete anyway because fresh sensor frames are already incoming."},{"id":"q_l1_05_2","prompt":"If a subscriber sets DurabilityPolicy.VOLATILE, what happens to messages published before that subscriber joined the network?","options":["The subscriber retrieves the last 10 messages from the DDS ring buffer","The subscriber misses all past messages and only receives future publications","The publisher throws a DDS_QOS_INCOMPATIBLE exception","The DDS broker crashes"],"correct":1,"explanation":"VOLATILE durability ignores past messages. To receive historical messages published prior to subscription (such as map data or robot configurations), TRANSIENT_LOCAL must be chosen."}],"has_quiz":true,"next_id":"lesson_06","prev_id":"lesson_04"},{"id":"lesson_06","num":6,"num_str":"06","title":"VS Code IDE Tooling & ROS 2 Logging Framework","slug":"vscode_debugging_and_ros2_logging","filename":"06_vscode_debugging_and_ros2_logging.md","module":"Foundations & Core Middleware","module_id":1,"duration":"45-60 min","focus":"Productivity Configuration (\`tasks.json\`, \`settings.json\`) & Industrial Logging","snapshot":[],"html_content":"<h1 id=\\"lesson-06-vs-code-ide-tooling--ros-2-logging-framework\\">Lesson 06: VS Code IDE Tooling &amp; ROS 2 Logging Framework</h1>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Focus:</strong> Productivity Configuration (<code class=\\"inline-code\\">tasks.json</code>, <code class=\\"inline-code\\">settings.json</code>) &amp; Industrial Logging<br><strong>Course Track:</strong> NavPro Learning Hub - Level 1 (Chapters 7, 8.4 &amp; 9)<br><strong>Target Environment:</strong> ROS 2 Jazzy Jalisco</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"1-overview--learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>Writing robust robotics software requires fast feedback loops: one-key compilation, IntelliSense autocompletion for ROS message types, and contextual logging that doesn&#x27;t spam your terminal.</p>\\n<p>By the end of this lesson, you will:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Configure VS Code with <code class=\\"inline-code\\">.vscode/tasks.json</code> to trigger <code class=\\"inline-code\\">colcon build</code> with <code class=\\"inline-code\\">Ctrl + Shift + B</code>.</li>\\n<li>Configure <code class=\\"inline-code\\">.vscode/settings.json</code> so Python language servers resolve ROS 2 packages (<code class=\\"inline-code\\">rclpy</code>, <code class=\\"inline-code\\">geometry_msgs</code>).</li>\\n<li>Master the ROS 2 Logging Framework: understand why standard <code class=\\"inline-code\\">print()</code> is forbidden in production robotics.</li>\\n<li>Use all five logging severity levels: <code class=\\"inline-code\\">DEBUG</code>, <code class=\\"inline-code\\">INFO</code>, <code class=\\"inline-code\\">WARN</code>, <code class=\\"inline-code\\">ERROR</code>, and <code class=\\"inline-code\\">FATAL</code>.</li>\\n<li>Implement throttled logging (<code class=\\"inline-code\\">throttle_duration_sec</code>) and one-shot logging to avoid CPU and terminal bloat.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-vs-code-ide-configuration-for-ros-2-python\\">2. VS Code IDE Configuration for ROS 2 Python</h2>\\n<p>To enable code autocompletion and one-click build tasks in VS Code, create a <code class=\\"inline-code\\">.vscode</code> folder in your workspace root (<code class=\\"inline-code\\">~/ros2_ws/.vscode/</code>).</p>\\n<h3 id=\\"21-workspace-settings-vscodesettingsjson\\">2.1 Workspace Settings (<code class=\\"inline-code\\">.vscode/settings.json</code>)</h3>\\n<p>This file points the Python analyzer to both the core ROS 2 underlay and your workspace install overlay:</p>\\n<div class=\\"code-container\\" data-language=\\"json\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">JSON</span><button class=\\"copy-code-btn\\" data-code=\\"{\\n  &quot;python.autoComplete.extraPaths&quot;: [\\n    &quot;/opt/ros/jazzy/lib/python3.12/site-packages&quot;,\\n    &quot;\${workspaceFolder}/install/navpro_basics/lib/python3.12/site-packages&quot;,\\n    &quot;\${workspaceFolder}/install/navpro_description/lib/python3.12/site-packages&quot;,\\n    &quot;\${workspaceFolder}/install/navpro_navigation/lib/python3.12/site-packages&quot;\\n  ],\\n  &quot;python.analysis.extraPaths&quot;: [\\n    &quot;/opt/ros/jazzy/lib/python3.12/site-packages&quot;,\\n    &quot;\${workspaceFolder}/install/navpro_basics/lib/python3.12/site-packages&quot;,\\n    &quot;\${workspaceFolder}/install/navpro_description/lib/python3.12/site-packages&quot;,\\n    &quot;\${workspaceFolder}/install/navpro_navigation/lib/python3.12/site-packages&quot;\\n  ],\\n  &quot;python.linting.enabled&quot;: true,\\n  &quot;python.linting.pylintEnabled&quot;: false,\\n  &quot;python.linting.flake8Enabled&quot;: true,\\n  &quot;files.associations&quot;: {\\n    &quot;*.xacro&quot;: &quot;xml&quot;,\\n    &quot;*.urdf&quot;: &quot;xml&quot;\\n  }\\n}\\">📋 Copy</button></div><pre><code class=\\"language-json\\">{\\n  &quot;python.autoComplete.extraPaths&quot;: [\\n    &quot;/opt/ros/jazzy/lib/python3.12/site-packages&quot;,\\n    &quot;\${workspaceFolder}/install/navpro_basics/lib/python3.12/site-packages&quot;,\\n    &quot;\${workspaceFolder}/install/navpro_description/lib/python3.12/site-packages&quot;,\\n    &quot;\${workspaceFolder}/install/navpro_navigation/lib/python3.12/site-packages&quot;\\n  ],\\n  &quot;python.analysis.extraPaths&quot;: [\\n    &quot;/opt/ros/jazzy/lib/python3.12/site-packages&quot;,\\n    &quot;\${workspaceFolder}/install/navpro_basics/lib/python3.12/site-packages&quot;,\\n    &quot;\${workspaceFolder}/install/navpro_description/lib/python3.12/site-packages&quot;,\\n    &quot;\${workspaceFolder}/install/navpro_navigation/lib/python3.12/site-packages&quot;\\n  ],\\n  &quot;python.linting.enabled&quot;: true,\\n  &quot;python.linting.pylintEnabled&quot;: false,\\n  &quot;python.linting.flake8Enabled&quot;: true,\\n  &quot;files.associations&quot;: {\\n    &quot;*.xacro&quot;: &quot;xml&quot;,\\n    &quot;*.urdf&quot;: &quot;xml&quot;\\n  }\\n}</code></pre></div>\\n<h3 id=\\"22-colcon-build-tasks-vscodetasksjson\\">2.2 Colcon Build Tasks (<code class=\\"inline-code\\">.vscode/tasks.json</code>)</h3>\\n<p>Allows you to press <code class=\\"inline-code\\">Ctrl + Shift + B</code> inside VS Code to instantly build your workspace:</p>\\n<div class=\\"code-container\\" data-language=\\"json\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">JSON</span><button class=\\"copy-code-btn\\" data-code=\\"{\\n  &quot;version&quot;: &quot;2.0.0&quot;,\\n  &quot;tasks&quot;: [\\n    {\\n      &quot;label&quot;: &quot;colcon: build (symlink-install)&quot;,\\n      &quot;type&quot;: &quot;shell&quot;,\\n      &quot;command&quot;: &quot;colcon build --symlink-install&quot;,\\n      &quot;group&quot;: {\\n        &quot;kind&quot;: &quot;build&quot;,\\n        &quot;isDefault&quot;: true\\n      },\\n      &quot;problemMatcher&quot;: [],\\n      &quot;presentation&quot;: {\\n        &quot;echo&quot;: true,\\n        &quot;reveal&quot;: &quot;always&quot;,\\n        &quot;focus&quot;: false,\\n        &quot;panel&quot;: &quot;shared&quot;\\n      }\\n    },\\n    {\\n      &quot;label&quot;: &quot;colcon: clean build artifacts&quot;,\\n      &quot;type&quot;: &quot;shell&quot;,\\n      &quot;command&quot;: &quot;rm -rf build install log&quot;,\\n      &quot;problemMatcher&quot;: []\\n    }\\n  ]\\n}\\">📋 Copy</button></div><pre><code class=\\"language-json\\">{\\n  &quot;version&quot;: &quot;2.0.0&quot;,\\n  &quot;tasks&quot;: [\\n    {\\n      &quot;label&quot;: &quot;colcon: build (symlink-install)&quot;,\\n      &quot;type&quot;: &quot;shell&quot;,\\n      &quot;command&quot;: &quot;colcon build --symlink-install&quot;,\\n      &quot;group&quot;: {\\n        &quot;kind&quot;: &quot;build&quot;,\\n        &quot;isDefault&quot;: true\\n      },\\n      &quot;problemMatcher&quot;: [],\\n      &quot;presentation&quot;: {\\n        &quot;echo&quot;: true,\\n        &quot;reveal&quot;: &quot;always&quot;,\\n        &quot;focus&quot;: false,\\n        &quot;panel&quot;: &quot;shared&quot;\\n      }\\n    },\\n    {\\n      &quot;label&quot;: &quot;colcon: clean build artifacts&quot;,\\n      &quot;type&quot;: &quot;shell&quot;,\\n      &quot;command&quot;: &quot;rm -rf build install log&quot;,\\n      &quot;problemMatcher&quot;: []\\n    }\\n  ]\\n}</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-the-ros-2-logging-framework\\">3. The ROS 2 Logging Framework</h2>\\n<h3 id=\\"31-why-print-is-forbidden-in-production\\">3.1 Why <code class=\\"inline-code\\">print()</code> is Forbidden in Production</h3>\\n<p>In Python scripts, developers often use <code class=\\"inline-code\\">print(&quot;Robot moving&quot;)</code>. In production robotics, this creates critical problems:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li><strong>No Timestamp:</strong> You cannot tell when an event occurred during a post-mortem crash analysis.</li>\\n<li><strong>No Node Source:</strong> In a multi-node system with 50 nodes running, <code class=\\"inline-code\\">print()</code> outputs are mixed together with no way to identify which node printed what.</li>\\n<li><strong>No Centralized Aggregation:</strong> <code class=\\"inline-code\\">print()</code> writes to stdout. ROS 2 logger writes to the <code class=\\"inline-code\\">/rosout</code> topic, enabling remote telemetry dashboards and fleet servers to monitor errors across a factory floor.</li>\\n<li><strong>No Severity Filtering:</strong> You cannot disable high-frequency debug prints in production without modifying source code.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-the-five-logging-severity-levels\\">4. The Five Logging Severity Levels</h2>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"                     LOGGING SEVERITY HIERARCHY\\n                     \\n   [DEBUG]  --&gt; Granular diagnostic data (raw sensor values, loop ticks)\\n      |\\n   [INFO]   --&gt; Normal operational state changes (arrived at waypoint)\\n      |\\n   [WARN]   --&gt; Recoverable anomalies (battery &lt; 20%, low WiFi signal)\\n      |\\n   [ERROR]  --&gt; Component failures (laser sensor timeout, planner abort)\\n      |\\n   [FATAL]  --&gt; Critical emergency (hardware estop triggered, motor burned)\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">                     LOGGING SEVERITY HIERARCHY\\n                     \\n   [DEBUG]  --&gt; Granular diagnostic data (raw sensor values, loop ticks)\\n      |\\n   [INFO]   --&gt; Normal operational state changes (arrived at waypoint)\\n      |\\n   [WARN]   --&gt; Recoverable anomalies (battery &lt; 20%, low WiFi signal)\\n      |\\n   [ERROR]  --&gt; Component failures (laser sensor timeout, planner abort)\\n      |\\n   [FATAL]  --&gt; Critical emergency (hardware estop triggered, motor burned)</code></pre></div>\\n<h3 id=\\"41-python-implementation-example\\">4.1 Python Implementation Example</h3>\\n<div class=\\"code-container\\" data-language=\\"python\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">PYTHON</span><button class=\\"copy-code-btn\\" data-code=\\"#!/usr/bin/env python3\\nimport rclpy\\nfrom rclpy.node import Node\\n\\n\\nclass LoggingMasteryNode(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;logging_mastery_node&#x27;)\\n\\n        # 1. Standard Info Log\\n        self.get_logger().info(&#x27;NavPro AMR Diagnostic System Initialized.&#x27;)\\n\\n        # 2. Debug Log (Visible only if log level is set to DEBUG)\\n        raw_encoder_ticks = 4096\\n        self.get_logger().debug(f&#x27;Encoder calibration register: 0x{raw_encoder_ticks:04X}&#x27;)\\n\\n        # 3. Warning Log (Colorized Yellow in terminal)\\n        battery_pct = 18.5\\n        if battery_pct &lt; 20.0:\\n            self.get_logger().warn(f&#x27;Battery level low: {battery_pct:.1f}% remaining!&#x27;)\\n\\n        # 4. Error Log (Colorized Red in terminal)\\n        sensor_connected = False\\n        if not sensor_connected:\\n            self.get_logger().error(&#x27;LiDAR communication timeout on /dev/ttyUSB0!&#x27;)\\n\\n        # 5. Fatal Log (Colorized Bold Red / Highlighted)\\n        emergency_circuit_broken = True\\n        if emergency_circuit_broken:\\n            self.get_logger().fatal(&#x27;HARDWARE SAFETY INTERLOCK BROKEN: SYSTEM HALTED!&#x27;)\\n\\n\\ndef main():\\n    rclpy.init()\\n    node = LoggingMasteryNode()\\n    rclpy.spin_once(node)\\n    node.destroy_node()\\n    rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\">📋 Copy</button></div><pre><code class=\\"language-python\\">#!/usr/bin/env python3\\nimport rclpy\\nfrom rclpy.node import Node\\n\\n\\nclass LoggingMasteryNode(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;logging_mastery_node&#x27;)\\n\\n        # 1. Standard Info Log\\n        self.get_logger().info(&#x27;NavPro AMR Diagnostic System Initialized.&#x27;)\\n\\n        # 2. Debug Log (Visible only if log level is set to DEBUG)\\n        raw_encoder_ticks = 4096\\n        self.get_logger().debug(f&#x27;Encoder calibration register: 0x{raw_encoder_ticks:04X}&#x27;)\\n\\n        # 3. Warning Log (Colorized Yellow in terminal)\\n        battery_pct = 18.5\\n        if battery_pct &lt; 20.0:\\n            self.get_logger().warn(f&#x27;Battery level low: {battery_pct:.1f}% remaining!&#x27;)\\n\\n        # 4. Error Log (Colorized Red in terminal)\\n        sensor_connected = False\\n        if not sensor_connected:\\n            self.get_logger().error(&#x27;LiDAR communication timeout on /dev/ttyUSB0!&#x27;)\\n\\n        # 5. Fatal Log (Colorized Bold Red / Highlighted)\\n        emergency_circuit_broken = True\\n        if emergency_circuit_broken:\\n            self.get_logger().fatal(&#x27;HARDWARE SAFETY INTERLOCK BROKEN: SYSTEM HALTED!&#x27;)\\n\\n\\ndef main():\\n    rclpy.init()\\n    node = LoggingMasteryNode()\\n    rclpy.spin_once(node)\\n    node.destroy_node()\\n    rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-throttled--one-shot-logging\\">5. Throttled &amp; One-Shot Logging</h2>\\n<p>High-frequency control loops (e.g. 50 Hz motor loops) should not print every iteration, as doing so floods terminal buffers and consumes significant CPU.</p>\\n<h3 id=\\"51-throttling-by-duration\\">5.1 Throttling by Duration:</h3>\\n<div class=\\"code-container\\" data-language=\\"python\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">PYTHON</span><button class=\\"copy-code-btn\\" data-code=\\"def control_loop(self):\\n    # Logs at most once every 2.0 seconds, regardless of how often this loop runs!\\n    self.get_logger().info(\\n        f&#x27;Robot pose: x={self.x:.2f}, y={self.y:.2f}&#x27;,\\n        throttle_duration_sec=2.0\\n    )\\">📋 Copy</button></div><pre><code class=\\"language-python\\">def control_loop(self):\\n    # Logs at most once every 2.0 seconds, regardless of how often this loop runs!\\n    self.get_logger().info(\\n        f&#x27;Robot pose: x={self.x:.2f}, y={self.y:.2f}&#x27;,\\n        throttle_duration_sec=2.0\\n    )</code></pre></div>\\n<h3 id=\\"52-one-shot-logging\\">5.2 One-Shot Logging:</h3>\\n<div class=\\"code-container\\" data-language=\\"python\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">PYTHON</span><button class=\\"copy-code-btn\\" data-code=\\"def on_network_connect(self):\\n    # Prints exactly once during the entire lifetime of the node\\n    self.get_logger().info(&#x27;DDS discovery handshake completed with Fleet Server.&#x27;, once=True)\\">📋 Copy</button></div><pre><code class=\\"language-python\\">def on_network_connect(self):\\n    # Prints exactly once during the entire lifetime of the node\\n    self.get_logger().info(&#x27;DDS discovery handshake completed with Fleet Server.&#x27;, once=True)</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-runtime-log-level-configuration\\">6. Runtime Log Level Configuration</h2>\\n<p>You can change the logging verbosity level of any node from the command line without recompiling code:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# Launch node with DEBUG messages enabled:\\nros2 run navpro_basics logging_node --ros-args --log-level debug\\n\\n# Launch node displaying only WARNINGS and higher (suppressing INFO):\\nros2 run navpro_basics logging_node --ros-args --log-level warn\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># Launch node with DEBUG messages enabled:\\nros2 run navpro_basics logging_node --ros-args --log-level debug\\n\\n# Launch node displaying only WARNINGS and higher (suppressing INFO):\\nros2 run navpro_basics logging_node --ros-args --log-level warn</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"7-hands-on-student-challenge\\">7. Hands-on Student Challenge</h2>\\n<p><strong>Task:</strong></p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Open <code class=\\"inline-code\\">.vscode/tasks.json</code> in your workspace and test building using the shortcut <code class=\\"inline-code\\">Ctrl + Shift + B</code>.</li>\\n<li>Write a Python script <code class=\\"inline-code\\">log_demo.py</code> that runs a 20 Hz timer (period = 0.05s).</li>\\n<li>Use <code class=\\"inline-code\\">throttle_duration_sec=1.5</code> to log a heartbeat message every 1.5 seconds.</li>\\n<li>Verify that running with <code class=\\"inline-code\\">--ros-args --log-level warn</code> suppresses the heartbeat log.</li>\\n</ol>","quizzes":[{"id":"q_l1_06_1","prompt":"Which of the following represents the correct ascending order of ROS 2 logger severity levels?","options":["DEBUG < INFO < WARN < ERROR < FATAL","INFO < DEBUG < WARN < ERROR < FATAL","WARN < INFO < DEBUG < ERROR < CRITICAL","TRACE < NOTICE < ALERT < EMERGENCY"],"correct":0,"explanation":"ROS 2 logging follows standard POSIX severity: DEBUG (10), INFO (20), WARN (30), ERROR (40), and FATAL (50). Setting logger level to WARN filters out INFO and DEBUG."}],"has_quiz":true,"next_id":"lesson_07","prev_id":"lesson_05"},{"id":"lesson_07","num":7,"num_str":"07","title":"ROS 2 Interfaces & Custom Messages/Services","slug":"interfaces_and_custom_messages","filename":"07_interfaces_and_custom_messages.md","module":"Advanced Communication Patterns","module_id":2,"duration":"45-60 min","focus":"Interface Architecture, Standard Message Libraries & Building Custom \`.msg\`, \`.srv\`, \`.action\` Packages","snapshot":[],"html_content":"<h1 id=\\"lesson-07-ros-2-interfaces--custom-messagesservices\\">Lesson 07: ROS 2 Interfaces &amp; Custom Messages/Services</h1>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Focus:</strong> Interface Architecture, Standard Message Libraries &amp; Building Custom <code class=\\"inline-code\\">.msg</code>, <code class=\\"inline-code\\">.srv</code>, <code class=\\"inline-code\\">.action</code> Packages<br><strong>Course Track:</strong> NavPro Learning Hub - Level 1 (Chapters 10 &amp; 13)<br><strong>Target Environment:</strong> ROS 2 Jazzy Jalisco</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"1-overview--learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>In ROS 2, nodes achieve language-agnostic interoperability because they communicate using strictly typed <strong>Interfaces</strong>. An interface defined once in an IDL (Interface Definition Language) file is automatically compiled into native Python classes and C++ structs.</p>\\n<p>By the end of this lesson, you will:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Understand the hierarchy of standard ROS 2 message libraries (<code class=\\"inline-code\\">std_msgs</code>, <code class=\\"inline-code\\">geometry_msgs</code>, <code class=\\"inline-code\\">sensor_msgs</code>, <code class=\\"inline-code\\">nav_msgs</code>).</li>\\n<li>Learn the golden architectural rule: <strong>Why interface packages must use <code class=\\"inline-code\\">ament_cmake</code> even when consuming them in pure Python</strong>.</li>\\n<li>Create custom message (<code class=\\"inline-code\\">.msg</code>), service (<code class=\\"inline-code\\">.srv</code>), and action (<code class=\\"inline-code\\">.action</code>) definitions.</li>\\n<li>Configure <code class=\\"inline-code\\">CMakeLists.txt</code> with <code class=\\"inline-code\\">rosidl_generate_interfaces</code> and <code class=\\"inline-code\\">package.xml</code>.</li>\\n<li>Import and instantiate custom interfaces in a production Python node.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-standard-ros-2-interface-libraries\\">2. Standard ROS 2 Interface Libraries</h2>\\n<p>Before creating custom messages, always verify if a standardized ROS message already exists:</p>\\n<div class=\\"table-wrapper\\"><table>\\n<thead><tr>\\n<th>Library</th>\\n<th>Key Interface Types</th>\\n<th>Primary Use Case</th>\\n</tr></thead><tbody>\\n<tr>\\n<td><strong><code class=\\"inline-code\\">std_msgs</code></strong></td>\\n<td><code class=\\"inline-code\\">Bool</code>, <code class=\\"inline-code\\">Float32</code>, <code class=\\"inline-code\\">Int32</code>, <code class=\\"inline-code\\">String</code>, <code class=\\"inline-code\\">Header</code></td>\\n<td>Primitive data types and timestamps.</td>\\n</tr>\\n<tr>\\n<td><strong><code class=\\"inline-code\\">geometry_msgs</code></strong></td>\\n<td><code class=\\"inline-code\\">Point</code>, <code class=\\"inline-code\\">Quaternion</code>, <code class=\\"inline-code\\">Pose</code>, <code class=\\"inline-code\\">PoseStamped</code>, <code class=\\"inline-code\\">Twist</code></td>\\n<td>2D/3D spatial coordinates, orientations, velocities.</td>\\n</tr>\\n<tr>\\n<td><strong><code class=\\"inline-code\\">sensor_msgs</code></strong></td>\\n<td><code class=\\"inline-code\\">LaserScan</code>, <code class=\\"inline-code\\">Image</code>, <code class=\\"inline-code\\">Imu</code>, <code class=\\"inline-code\\">BatteryState</code>, <code class=\\"inline-code\\">JointState</code></td>\\n<td>Raw sensor telemetry from cameras, LiDARs, IMUs.</td>\\n</tr>\\n<tr>\\n<td><strong><code class=\\"inline-code\\">nav_msgs</code></strong></td>\\n<td><code class=\\"inline-code\\">Odometry</code>, <code class=\\"inline-code\\">OccupancyGrid</code>, <code class=\\"inline-code\\">Path</code></td>\\n<td>SLAM 2D occupancy grid maps, robot odometry, paths.</td>\\n</tr>\\n</tbody></table></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-the-custom-interface-architecture-rule\\">3. The Custom Interface Architecture Rule</h2>\\n<div class=\\"alert-callout alert-important\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>ROS 2 Custom Interfaces Must Be Built Using <code class=\\"inline-code\\">ament_cmake</code>:</strong><br>The ROS 2 IDL generator (<code class=\\"inline-code\\">rosidl</code>) compiles <code class=\\"inline-code\\">.msg</code> and <code class=\\"inline-code\\">.srv</code> files into C, C++, and Python bindings. The IDL generator plugins require CMake.<br>Therefore, industry best practice is to create a dedicated interface package (e.g., <code class=\\"inline-code\\">navpro_interfaces</code>) built with <code class=\\"inline-code\\">ament_cmake</code>. Your Python packages (<code class=\\"inline-code\\">navpro_basics</code>, <code class=\\"inline-code\\">navpro_navigation</code>) simply add <code class=\\"inline-code\\">&lt;depend&gt;navpro_interfaces&lt;/depend&gt;</code> to their <code class=\\"inline-code\\">package.xml</code> and import the generated classes cleanly.</div></div>\\n<div class=\\"lesson-image-wrapper\\"><img src=\\"assets/images/interface_idl_pipeline.svg\\" alt=\\"Interface IDL Pipeline\\" class=\\"lesson-image\\" loading=\\"lazy\\"><span class=\\"image-caption\\">Interface IDL Pipeline</span></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-step-by-step-creating-the-navpro_interfaces-package\\">4. Step-by-Step: Creating the <code class=\\"inline-code\\">navpro_interfaces</code> Package</h2>\\n<h3 id=\\"step-41-create-the-cmake-package\\">Step 4.1: Create the CMake Package</h3>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"cd ~/ros2_ws/src\\nros2 pkg create --build-type ament_cmake navpro_interfaces\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">cd ~/ros2_ws/src\\nros2 pkg create --build-type ament_cmake navpro_interfaces</code></pre></div>\\n<p>Create interface subdirectories:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"mkdir -p navpro_interfaces/msg\\nmkdir -p navpro_interfaces/srv\\nmkdir -p navpro_interfaces/action\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">mkdir -p navpro_interfaces/msg\\nmkdir -p navpro_interfaces/srv\\nmkdir -p navpro_interfaces/action</code></pre></div>\\n<h3 id=\\"step-42-define-custom-message-msgrobotstatusmsg\\">Step 4.2: Define Custom Message (<code class=\\"inline-code\\">msg/RobotStatus.msg</code>)</h3>\\n<p>Create <code class=\\"inline-code\\">navpro_interfaces/msg/RobotStatus.msg</code>:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# Header contains timestamp and coordinate frame ID\\nstd_msgs/Header header\\n\\n# Identity and operational metrics\\nstring robot_id\\nfloat32 battery_percentage\\nfloat32 internal_temperature_celsius\\nbool is_docked\\nbool emergency_stop_latched\\n\\n# Operating mode constants\\nuint8 MODE_MANUAL_TELEOP = 0\\nuint8 MODE_AUTONOMOUS_NAV = 1\\nuint8 MODE_CHARGING = 2\\nuint8 active_mode\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># Header contains timestamp and coordinate frame ID\\nstd_msgs/Header header\\n\\n# Identity and operational metrics\\nstring robot_id\\nfloat32 battery_percentage\\nfloat32 internal_temperature_celsius\\nbool is_docked\\nbool emergency_stop_latched\\n\\n# Operating mode constants\\nuint8 MODE_MANUAL_TELEOP = 0\\nuint8 MODE_AUTONOMOUS_NAV = 1\\nuint8 MODE_CHARGING = 2\\nuint8 active_mode</code></pre></div>\\n<h3 id=\\"step-43-define-custom-service-srvsetspeedmodesrv\\">Step 4.3: Define Custom Service (<code class=\\"inline-code\\">srv/SetSpeedMode.srv</code>)</h3>\\n<p>In <code class=\\"inline-code\\">.srv</code> files, three dashes <code class=\\"inline-code\\">---</code> separate the <strong>Request</strong> from the <strong>Response</strong>.</p>\\n<p>Create <code class=\\"inline-code\\">navpro_interfaces/srv/SetSpeedMode.srv</code>:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# Request\\nstring speed_mode       # e.g., &quot;ECO&quot;, &quot;STANDARD&quot;, &quot;TURBO&quot;\\nfloat32 custom_multiplier\\n---\\n# Response\\nbool success\\nstring message\\nfloat32 effective_max_linear_speed\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># Request\\nstring speed_mode       # e.g., &quot;ECO&quot;, &quot;STANDARD&quot;, &quot;TURBO&quot;\\nfloat32 custom_multiplier\\n---\\n# Response\\nbool success\\nstring message\\nfloat32 effective_max_linear_speed</code></pre></div>\\n<h3 id=\\"step-44-define-custom-action-actionpatrolaction\\">Step 4.4: Define Custom Action (<code class=\\"inline-code\\">action/Patrol.action</code>)</h3>\\n<p>In <code class=\\"inline-code\\">.action</code> files, three dashes <code class=\\"inline-code\\">---</code> separate <strong>Goal</strong>, <strong>Result</strong>, and <strong>Feedback</strong>.</p>\\n<p>Create <code class=\\"inline-code\\">navpro_interfaces/action/Patrol.action</code>:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# Goal\\ngeometry_msgs/PoseStamped[] waypoints\\nuint32 loop_count\\n---\\n# Result\\nbool success\\nuint32 completed_waypoints\\nfloat32 total_distance_traveled\\n---\\n# Feedback\\nuint32 current_waypoint_index\\nfloat32 distance_to_next_waypoint\\nfloat32 battery_remaining_pct\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># Goal\\ngeometry_msgs/PoseStamped[] waypoints\\nuint32 loop_count\\n---\\n# Result\\nbool success\\nuint32 completed_waypoints\\nfloat32 total_distance_traveled\\n---\\n# Feedback\\nuint32 current_waypoint_index\\nfloat32 distance_to_next_waypoint\\nfloat32 battery_remaining_pct</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-configuring-packagexml--cmakeliststxt\\">5. Configuring <code class=\\"inline-code\\">package.xml</code> &amp; <code class=\\"inline-code\\">CMakeLists.txt</code></h2>\\n<h3 id=\\"51-packagexml-configuration\\">5.1 <code class=\\"inline-code\\">package.xml</code> Configuration</h3>\\n<p>Add the IDL generator and runtime dependencies:</p>\\n<div class=\\"code-container\\" data-language=\\"xml\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">XML</span><button class=\\"copy-code-btn\\" data-code=\\"&lt;?xml version=&quot;1.0&quot;?&gt;\\n&lt;package format=&quot;3&quot;&gt;\\n  &lt;name&gt;navpro_interfaces&lt;/name&gt;\\n  &lt;version&gt;1.0.0&lt;/version&gt;\\n  &lt;description&gt;Custom ROS 2 message, service, and action interfaces for NavPro AMR&lt;/description&gt;\\n  &lt;maintainer email=&quot;engineer@navpro.io&quot;&gt;NavPro Robotics&lt;/maintainer&gt;\\n  &lt;license&gt;Apache-2.0&lt;/license&gt;\\n\\n  &lt;buildtool_depend&gt;ament_cmake&lt;/buildtool_depend&gt;\\n\\n  &lt;!-- Required for IDL code generation --&gt;\\n  &lt;buildtool_depend&gt;rosidl_default_generators&lt;/buildtool_depend&gt;\\n  &lt;exec_depend&gt;rosidl_default_runtime&lt;/exec_depend&gt;\\n  &lt;member_of_group&gt;rosidl_interface_packages&lt;/member_of_group&gt;\\n\\n  &lt;!-- Dependencies for field types used in custom messages --&gt;\\n  &lt;depend&gt;std_msgs&lt;/depend&gt;\\n  &lt;depend&gt;geometry_msgs&lt;/depend&gt;\\n\\n  &lt;export&gt;\\n    &lt;build_type&gt;ament_cmake&lt;/build_type&gt;\\n  &lt;/export&gt;\\n&lt;/package&gt;\\">📋 Copy</button></div><pre><code class=\\"language-xml\\">&lt;?xml version=&quot;1.0&quot;?&gt;\\n&lt;package format=&quot;3&quot;&gt;\\n  &lt;name&gt;navpro_interfaces&lt;/name&gt;\\n  &lt;version&gt;1.0.0&lt;/version&gt;\\n  &lt;description&gt;Custom ROS 2 message, service, and action interfaces for NavPro AMR&lt;/description&gt;\\n  &lt;maintainer email=&quot;engineer@navpro.io&quot;&gt;NavPro Robotics&lt;/maintainer&gt;\\n  &lt;license&gt;Apache-2.0&lt;/license&gt;\\n\\n  &lt;buildtool_depend&gt;ament_cmake&lt;/buildtool_depend&gt;\\n\\n  &lt;!-- Required for IDL code generation --&gt;\\n  &lt;buildtool_depend&gt;rosidl_default_generators&lt;/buildtool_depend&gt;\\n  &lt;exec_depend&gt;rosidl_default_runtime&lt;/exec_depend&gt;\\n  &lt;member_of_group&gt;rosidl_interface_packages&lt;/member_of_group&gt;\\n\\n  &lt;!-- Dependencies for field types used in custom messages --&gt;\\n  &lt;depend&gt;std_msgs&lt;/depend&gt;\\n  &lt;depend&gt;geometry_msgs&lt;/depend&gt;\\n\\n  &lt;export&gt;\\n    &lt;build_type&gt;ament_cmake&lt;/build_type&gt;\\n  &lt;/export&gt;\\n&lt;/package&gt;</code></pre></div>\\n<h3 id=\\"52-cmakeliststxt-configuration\\">5.2 <code class=\\"inline-code\\">CMakeLists.txt</code> Configuration</h3>\\n<div class=\\"code-container\\" data-language=\\"cmake\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">CMAKE</span><button class=\\"copy-code-btn\\" data-code=\\"cmake_minimum_required(VERSION 3.8)\\nproject(navpro_interfaces)\\n\\nif(CMAKE_COMPILER_IS_GNUCXX OR CMAKE_CXX_COMPILER_ID MATCHES &quot;Clang&quot;)\\n  add_compile_options(-Wall -Wextra -Wpedantic)\\nendif()\\n\\nfind_package(ament_cmake REQUIRED)\\nfind_package(rosidl_default_generators REQUIRED)\\nfind_package(std_msgs REQUIRED)\\nfind_package(geometry_msgs REQUIRED)\\n\\n# Generate language bindings for all custom IDL definitions\\nrosidl_generate_interfaces(\${PROJECT_NAME}\\n  &quot;msg/RobotStatus.msg&quot;\\n  &quot;srv/SetSpeedMode.srv&quot;\\n  &quot;action/Patrol.action&quot;\\n  DEPENDENCIES std_msgs geometry_msgs\\n)\\n\\nament_package()\\">📋 Copy</button></div><pre><code class=\\"language-cmake\\">cmake_minimum_required(VERSION 3.8)\\nproject(navpro_interfaces)\\n\\nif(CMAKE_COMPILER_IS_GNUCXX OR CMAKE_CXX_COMPILER_ID MATCHES &quot;Clang&quot;)\\n  add_compile_options(-Wall -Wextra -Wpedantic)\\nendif()\\n\\nfind_package(ament_cmake REQUIRED)\\nfind_package(rosidl_default_generators REQUIRED)\\nfind_package(std_msgs REQUIRED)\\nfind_package(geometry_msgs REQUIRED)\\n\\n# Generate language bindings for all custom IDL definitions\\nrosidl_generate_interfaces(\${PROJECT_NAME}\\n  &quot;msg/RobotStatus.msg&quot;\\n  &quot;srv/SetSpeedMode.srv&quot;\\n  &quot;action/Patrol.action&quot;\\n  DEPENDENCIES std_msgs geometry_msgs\\n)\\n\\nament_package()</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-building--verifying-interfaces-with-cli\\">6. Building &amp; Verifying Interfaces with CLI</h2>\\n<p>Build the interface package:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"cd ~/ros2_ws\\ncolcon build --packages-select navpro_interfaces\\nsource install/setup.bash\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">cd ~/ros2_ws\\ncolcon build --packages-select navpro_interfaces\\nsource install/setup.bash</code></pre></div>\\n<p>Use <code class=\\"inline-code\\">ros2 interface</code> CLI commands to inspect generated types:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# 1. View structure of our custom message\\nros2 interface show navpro_interfaces/msg/RobotStatus\\n\\n# 2. View structure of our custom service\\nros2 interface show navpro_interfaces/srv/SetSpeedMode\\n\\n# 3. View structure of our custom action\\nros2 interface show navpro_interfaces/action/Patrol\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># 1. View structure of our custom message\\nros2 interface show navpro_interfaces/msg/RobotStatus\\n\\n# 2. View structure of our custom service\\nros2 interface show navpro_interfaces/srv/SetSpeedMode\\n\\n# 3. View structure of our custom action\\nros2 interface show navpro_interfaces/action/Patrol</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"7-using-custom-interfaces-in-a-python-node\\">7. Using Custom Interfaces in a Python Node</h2>\\n<p>Now, any Python node in your workspace can import and publish this message type:</p>\\n<div class=\\"code-container\\" data-language=\\"python\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">PYTHON</span><button class=\\"copy-code-btn\\" data-code=\\"#!/usr/bin/env python3\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom navpro_interfaces.msg import RobotStatus\\n\\n\\nclass StatusBroadcasterNode(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;status_broadcaster_node&#x27;)\\n        self.pub_ = self.create_publisher(RobotStatus, &#x27;/navpro/status&#x27;, 10)\\n        self.timer_ = self.create_timer(1.0, self.publish_status)\\n\\n    def publish_status(self):\\n        msg = RobotStatus()\\n        msg.header.stamp = self.get_clock().now().to_msg()\\n        msg.header.frame_id = &#x27;base_footprint&#x27;\\n        msg.robot_id = &#x27;NAVPRO-AMR-402&#x27;\\n        msg.battery_percentage = 94.2\\n        msg.internal_temperature_celsius = 38.5\\n        msg.is_docked = False\\n        msg.emergency_stop_latched = False\\n        msg.active_mode = RobotStatus.MODE_AUTONOMOUS_NAV\\n\\n        self.pub_.publish(msg)\\n        self.get_logger().info(f&#x27;Published Status: {msg.robot_id} | Batt: {msg.battery_percentage}%&#x27;)\\n\\n\\ndef main():\\n    rclpy.init()\\n    node = StatusBroadcasterNode()\\n    try:\\n        rclpy.spin(node)\\n    finally:\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\">📋 Copy</button></div><pre><code class=\\"language-python\\">#!/usr/bin/env python3\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom navpro_interfaces.msg import RobotStatus\\n\\n\\nclass StatusBroadcasterNode(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;status_broadcaster_node&#x27;)\\n        self.pub_ = self.create_publisher(RobotStatus, &#x27;/navpro/status&#x27;, 10)\\n        self.timer_ = self.create_timer(1.0, self.publish_status)\\n\\n    def publish_status(self):\\n        msg = RobotStatus()\\n        msg.header.stamp = self.get_clock().now().to_msg()\\n        msg.header.frame_id = &#x27;base_footprint&#x27;\\n        msg.robot_id = &#x27;NAVPRO-AMR-402&#x27;\\n        msg.battery_percentage = 94.2\\n        msg.internal_temperature_celsius = 38.5\\n        msg.is_docked = False\\n        msg.emergency_stop_latched = False\\n        msg.active_mode = RobotStatus.MODE_AUTONOMOUS_NAV\\n\\n        self.pub_.publish(msg)\\n        self.get_logger().info(f&#x27;Published Status: {msg.robot_id} | Batt: {msg.battery_percentage}%&#x27;)\\n\\n\\ndef main():\\n    rclpy.init()\\n    node = StatusBroadcasterNode()\\n    try:\\n        rclpy.spin(node)\\n    finally:\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()</code></pre></div>","quizzes":[{"id":"q_l1_07_1","prompt":"Why must custom ROS 2 messages, services, and actions be compiled inside a CMake package rather than a pure Python (ament_python) package?","options":["Python does not support compiling binary structs","rosidl_default_generators is a CMake build pipeline that compiles .msg files into C, C++, and Python type bindings simultaneously","Python setup.py cannot create directories","DDS middleware only accepts C++ code"],"correct":1,"explanation":"Custom ROS 2 interfaces require the rosidl_default_generators CMake package to generate language-specific C, C++, Python, and DDS type support serialization libraries."}],"has_quiz":true,"next_id":"lesson_08","prev_id":"lesson_06"},{"id":"lesson_08","num":8,"num_str":"08","title":"Communication Mechanism II: Service Servers & Clients in Python","slug":"services_server_client_python","filename":"08_services_server_client_python.md","module":"Advanced Communication Patterns","module_id":2,"duration":"45-60 min","focus":"Request-Response Communication, Deadlock Prevention & Asynchronous Client Design","snapshot":[["Service RPC Pattern","Synchronous, paired Request -> Response communication between two specific nodes."],["When to Use","Use services for discrete actions (reset odometry, trigger sensor calibration), not high-rate continuous streaming."]],"html_content":"<h1 id=\\"lesson-08-communication-mechanism-ii-service-servers--clients-in-python\\">Lesson 08: Communication Mechanism II: Service Servers &amp; Clients in Python</h1>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Focus:</strong> Request-Response Communication, Deadlock Prevention &amp; Asynchronous Client Design<br><strong>Course Track:</strong> NavPro Learning Hub - Level 1 (Chapters 14, 15 &amp; 16)<br><strong>Target Environment:</strong> ROS 2 Jazzy Jalisco</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"1-overview--learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>While Topics handle continuous high-frequency data streams (e.g. sensor feeds), <strong>Services</strong> implement the synchronous or asynchronous <strong>Request-Response</strong> pattern. A client node sends a request to a service server and waits for a response.</p>\\n<p>By the end of this lesson, you will:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Understand the Request-Response communication model and when to use Services vs Topics vs Actions.</li>\\n<li>Build an object-oriented Python <strong>Service Server</strong> that processes requests and returns structured responses.</li>\\n<li>Build an asynchronous Python <strong>Service Client</strong> using <code class=\\"inline-code\\">call_async()</code> and <code class=\\"inline-code\\">Future</code> objects.</li>\\n<li>Understand the critical <strong>SingleThreadedExecutor Deadlock Bug</strong> and how to avoid it.</li>\\n<li>Trigger and test service endpoints directly from the command line using <code class=\\"inline-code\\">ros2 service call</code>.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-decision-matrix-topics-vs-services-vs-actions\\">2. Decision Matrix: Topics vs Services vs Actions</h2>\\n<div class=\\"table-wrapper\\"><table>\\n<thead><tr>\\n<th>Communication Pattern</th>\\n<th>Data Flow</th>\\n<th>Blocking?</th>\\n<th>Feedback During Execution?</th>\\n<th>Example Robotics Use Case</th>\\n</tr></thead><tbody>\\n<tr>\\n<td><strong>Topic</strong></td>\\n<td>Publisher -&gt; Subscriber (Unidirectional, Continuous)</td>\\n<td>No (Asynchronous)</td>\\n<td>No</td>\\n<td>Continuous LiDAR scans (<code class=\\"inline-code\\">/scan</code>), Wheel velocities (<code class=\\"inline-code\\">/cmd_vel</code>)</td>\\n</tr>\\n<tr>\\n<td><strong>Service</strong></td>\\n<td>Client &lt;-&gt; Server (Bidirectional, Request/Response)</td>\\n<td>Optional (Sync or Async)</td>\\n<td>No (Returns only once at completion)</td>\\n<td>Motor calibration, Camera trigger, Mode toggle (<code class=\\"inline-code\\">/set_speed_mode</code>)</td>\\n</tr>\\n<tr>\\n<td><strong>Action</strong></td>\\n<td>Action Client &lt;-&gt; Action Server (Goal -&gt; Feedback -&gt; Result)</td>\\n<td>No (Asynchronous)</td>\\n<td><strong>Yes</strong> (Continuous progress updates)</td>\\n<td>Navigate 10 meters to waypoint, Execute 30-second docking trajectory</td>\\n</tr>\\n</tbody></table></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-step-by-step-writing-a-service-server-in-python\\">3. Step-by-Step: Writing a Service Server in Python</h2>\\n<p>Let&#x27;s write a service server that dynamically sets the robot speed mode (ECO vs TURBO) using <code class=\\"inline-code\\">std_srvs/srv/SetBool</code>.</p>\\n<p>Create file <code class=\\"inline-code\\">speed_mode_server.py</code>:</p>\\n<div class=\\"code-container\\" data-language=\\"python\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">PYTHON</span><button class=\\"copy-code-btn\\" data-code=\\"#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nNavPro Learning Hub - Lesson 08\\nService Server: Manages robot drive mode transitions.\\n&quot;&quot;&quot;\\n\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom std_srvs.srv import SetBool\\n\\n\\nclass SpeedModeServer(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;speed_mode_server&#x27;)\\n\\n        # Internal state\\n        self.turbo_enabled_ = False\\n        self.max_speed_ = 0.5  # m/s\\n\\n        # Create Service Server: type=SetBool, name=&#x27;/robot/set_turbo_mode&#x27;, callback=self.handle_set_turbo\\n        self.srv_ = self.create_service(\\n            SetBool,\\n            &#x27;/robot/set_turbo_mode&#x27;,\\n            self.handle_set_turbo\\n        )\\n\\n        self.get_logger().info(&#x27;Speed Mode Service Server ready on /robot/set_turbo_mode&#x27;)\\n\\n    def handle_set_turbo(self, request: SetBool.Request, response: SetBool.Response) -&gt; SetBool.Response:\\n        &quot;&quot;&quot;\\n        Callback triggered whenever a client calls /robot/set_turbo_mode.\\n        Receives request: request.data (bool)\\n        Must return response: response.success (bool), response.message (str)\\n        &quot;&quot;&quot;\\n        self.turbo_enabled_ = request.data\\n\\n        if self.turbo_enabled_:\\n            self.max_speed_ = 1.2\\n            response.success = True\\n            response.message = f&#x27;TURBO MODE ENGAGED: Max speed increased to {self.max_speed_} m/s.&#x27;\\n            self.get_logger().warn(response.message)\\n        else:\\n            self.max_speed_ = 0.5\\n            response.success = True\\n            response.message = f&#x27;ECO MODE ENGAGED: Max speed restricted to {self.max_speed_} m/s.&#x27;\\n            self.get_logger().info(response.message)\\n\\n        return response\\n\\n\\ndef main():\\n    rclpy.init()\\n    node = SpeedModeServer()\\n    try:\\n        rclpy.spin(node)\\n    except KeyboardInterrupt:\\n        pass\\n    finally:\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\">📋 Copy</button></div><pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nNavPro Learning Hub - Lesson 08\\nService Server: Manages robot drive mode transitions.\\n&quot;&quot;&quot;\\n\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom std_srvs.srv import SetBool\\n\\n\\nclass SpeedModeServer(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;speed_mode_server&#x27;)\\n\\n        # Internal state\\n        self.turbo_enabled_ = False\\n        self.max_speed_ = 0.5  # m/s\\n\\n        # Create Service Server: type=SetBool, name=&#x27;/robot/set_turbo_mode&#x27;, callback=self.handle_set_turbo\\n        self.srv_ = self.create_service(\\n            SetBool,\\n            &#x27;/robot/set_turbo_mode&#x27;,\\n            self.handle_set_turbo\\n        )\\n\\n        self.get_logger().info(&#x27;Speed Mode Service Server ready on /robot/set_turbo_mode&#x27;)\\n\\n    def handle_set_turbo(self, request: SetBool.Request, response: SetBool.Response) -&gt; SetBool.Response:\\n        &quot;&quot;&quot;\\n        Callback triggered whenever a client calls /robot/set_turbo_mode.\\n        Receives request: request.data (bool)\\n        Must return response: response.success (bool), response.message (str)\\n        &quot;&quot;&quot;\\n        self.turbo_enabled_ = request.data\\n\\n        if self.turbo_enabled_:\\n            self.max_speed_ = 1.2\\n            response.success = True\\n            response.message = f&#x27;TURBO MODE ENGAGED: Max speed increased to {self.max_speed_} m/s.&#x27;\\n            self.get_logger().warn(response.message)\\n        else:\\n            self.max_speed_ = 0.5\\n            response.success = True\\n            response.message = f&#x27;ECO MODE ENGAGED: Max speed restricted to {self.max_speed_} m/s.&#x27;\\n            self.get_logger().info(response.message)\\n\\n        return response\\n\\n\\ndef main():\\n    rclpy.init()\\n    node = SpeedModeServer()\\n    try:\\n        rclpy.spin(node)\\n    except KeyboardInterrupt:\\n        pass\\n    finally:\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-the-critical-singlethreadedexecutor-deadlock-bug\\">4. The Critical SingleThreadedExecutor Deadlock Bug</h2>\\n<div class=\\"alert-callout alert-warning\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Never use blocking <code class=\\"inline-code\\">client.call(request)</code> inside a callback!</strong><br>If you call a service synchronously using <code class=\\"inline-code\\">client.call()</code> from within a timer callback or subscriber callback, the single-threaded executor blocks waiting for the response. But because the thread is blocked, the same executor cannot process the incoming response from the server!<br><strong>Result:</strong> The node freezes forever in an unrecoverable deadlock.<br><strong>Solution:</strong> Always use asynchronous client calls: <code class=\\"inline-code\\">client.call_async(request)</code>.</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-step-by-step-writing-an-asynchronous-service-client-in-python\\">5. Step-by-Step: Writing an Asynchronous Service Client in Python</h2>\\n<p>Here is the correct, non-blocking asynchronous Python Service Client using <code class=\\"inline-code\\">call_async()</code> and a future callback:</p>\\n<p>Create file <code class=\\"inline-code\\">speed_mode_client.py</code>:</p>\\n<div class=\\"code-container\\" data-language=\\"python\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">PYTHON</span><button class=\\"copy-code-btn\\" data-code=\\"#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nNavPro Learning Hub - Lesson 08\\nService Client: Calls /robot/set_turbo_mode asynchronously without deadlocks.\\n&quot;&quot;&quot;\\n\\nimport sys\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom std_srvs.srv import SetBool\\n\\n\\nclass SpeedModeClient(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;speed_mode_client&#x27;)\\n\\n        # 1. Create client: type=SetBool, name=&#x27;/robot/set_turbo_mode&#x27;\\n        self.client_ = self.create_client(SetBool, &#x27;/robot/set_turbo_mode&#x27;)\\n\\n        # 2. Wait until the server node is online\\n        while not self.client_.wait_for_service(timeout_sec=1.0):\\n            self.get_logger().warn(&#x27;Service /robot/set_turbo_mode not available, waiting...&#x27;)\\n\\n        self.get_logger().info(&#x27;Connected to Service Server successfully.&#x27;)\\n\\n    def send_request(self, enable_turbo: bool):\\n        &quot;&quot;&quot;Asynchronously dispatches the service request.&quot;&quot;&quot;\\n        request = SetBool.Request()\\n        request.data = enable_turbo\\n\\n        self.get_logger().info(f&#x27;Sending request: enable_turbo = {enable_turbo}&#x27;)\\n        \\n        # call_async returns a Future object immediately without blocking!\\n        future = self.client_.call_async(request)\\n        \\n        # Attach callback triggered when the server responds\\n        future.add_done_callback(self.response_callback)\\n\\n    def response_callback(self, future):\\n        &quot;&quot;&quot;Executed automatically when the server finishes and returns a response.&quot;&quot;&quot;\\n        try:\\n            response = future.result()\\n            self.get_logger().info(f&#x27;Response Received -&gt; Success: {response.success} | Message: &quot;{response.message}&quot;&#x27;)\\n        except Exception as e:\\n            self.get_logger().error(f&#x27;Service call failed: {e}&#x27;)\\n\\n\\ndef main():\\n    rclpy.init()\\n    client_node = SpeedModeClient()\\n\\n    # Send request to activate Turbo Mode\\n    client_node.send_request(enable_turbo=True)\\n\\n    try:\\n        # Spin keeps the client node alive until the response arrives\\n        rclpy.spin(client_node)\\n    except KeyboardInterrupt:\\n        pass\\n    finally:\\n        client_node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\">📋 Copy</button></div><pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nNavPro Learning Hub - Lesson 08\\nService Client: Calls /robot/set_turbo_mode asynchronously without deadlocks.\\n&quot;&quot;&quot;\\n\\nimport sys\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom std_srvs.srv import SetBool\\n\\n\\nclass SpeedModeClient(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;speed_mode_client&#x27;)\\n\\n        # 1. Create client: type=SetBool, name=&#x27;/robot/set_turbo_mode&#x27;\\n        self.client_ = self.create_client(SetBool, &#x27;/robot/set_turbo_mode&#x27;)\\n\\n        # 2. Wait until the server node is online\\n        while not self.client_.wait_for_service(timeout_sec=1.0):\\n            self.get_logger().warn(&#x27;Service /robot/set_turbo_mode not available, waiting...&#x27;)\\n\\n        self.get_logger().info(&#x27;Connected to Service Server successfully.&#x27;)\\n\\n    def send_request(self, enable_turbo: bool):\\n        &quot;&quot;&quot;Asynchronously dispatches the service request.&quot;&quot;&quot;\\n        request = SetBool.Request()\\n        request.data = enable_turbo\\n\\n        self.get_logger().info(f&#x27;Sending request: enable_turbo = {enable_turbo}&#x27;)\\n        \\n        # call_async returns a Future object immediately without blocking!\\n        future = self.client_.call_async(request)\\n        \\n        # Attach callback triggered when the server responds\\n        future.add_done_callback(self.response_callback)\\n\\n    def response_callback(self, future):\\n        &quot;&quot;&quot;Executed automatically when the server finishes and returns a response.&quot;&quot;&quot;\\n        try:\\n            response = future.result()\\n            self.get_logger().info(f&#x27;Response Received -&gt; Success: {response.success} | Message: &quot;{response.message}&quot;&#x27;)\\n        except Exception as e:\\n            self.get_logger().error(f&#x27;Service call failed: {e}&#x27;)\\n\\n\\ndef main():\\n    rclpy.init()\\n    client_node = SpeedModeClient()\\n\\n    # Send request to activate Turbo Mode\\n    client_node.send_request(enable_turbo=True)\\n\\n    try:\\n        # Spin keeps the client node alive until the response arrives\\n        rclpy.spin(client_node)\\n    except KeyboardInterrupt:\\n        pass\\n    finally:\\n        client_node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-verification-with-the-ros-2-cli\\">6. Verification with the ROS 2 CLI</h2>\\n<p>Start the server node in Terminal 1:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"ros2 run navpro_basics service_server_explained\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">ros2 run navpro_basics service_server_explained</code></pre></div>\\n<p>In Terminal 2, inspect and call the service using the command line:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# 1. List all active service endpoints\\nros2 service list\\n\\n# 2. Find the message type of the service\\nros2 service type /robot/set_autonomous_mode\\n\\n# 3. Call the service directly from terminal with JSON-style payload\\nros2 service call /robot/set_autonomous_mode std_srvs/srv/SetBool &quot;{data: true}&quot;\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># 1. List all active service endpoints\\nros2 service list\\n\\n# 2. Find the message type of the service\\nros2 service type /robot/set_autonomous_mode\\n\\n# 3. Call the service directly from terminal with JSON-style payload\\nros2 service call /robot/set_autonomous_mode std_srvs/srv/SetBool &quot;{data: true}&quot;</code></pre></div>\\n<p><em>Expected Output in Terminal 2:</em></p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"requester: making request: std_srvs.srv.SetBool_Request(data=True)\\n\\nresponse:\\nstd_srvs.srv.SetBool_Response(success=True, message=&#x27;Autonomous mode ENABLED&#x27;)\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">requester: making request: std_srvs.srv.SetBool_Request(data=True)\\n\\nresponse:\\nstd_srvs.srv.SetBool_Response(success=True, message=&#x27;Autonomous mode ENABLED&#x27;)</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"7-hands-on-student-challenge\\">7. Hands-on Student Challenge</h2>\\n<p><strong>Task:</strong></p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Create a service server named <code class=\\"inline-code\\">battery_health_server</code>.</li>\\n<li>Use <code class=\\"inline-code\\">std_srvs/srv/Trigger</code> (<code class=\\"inline-code\\">---</code> <code class=\\"inline-code\\">bool success</code>, <code class=\\"inline-code\\">string message</code>).</li>\\n<li>When called, the service checks simulated battery voltage. If voltage &gt; 24.0V, it returns <code class=\\"inline-code\\">success=True</code> with message <code class=\\"inline-code\\">&quot;Battery healthy: 24.8V&quot;</code>. Otherwise, it returns <code class=\\"inline-code\\">success=False</code> with <code class=\\"inline-code\\">&quot;Warning: Battery under-voltage: 21.2V&quot;</code>.</li>\\n<li>Test calling the service using <code class=\\"inline-code\\">ros2 service call /check_battery std_srvs/srv/Trigger</code>.</li>\\n</ol>","quizzes":[{"id":"q_l1_08_1","prompt":"Why should you NEVER call 'client.call(request)' synchronously inside a ROS 2 Python timer callback?","options":["Because synchronous calls cause memory leaks","Because synchronous calls block the single-threaded executor, preventing the response callback from ever executing and causing a permanent deadlock","Because ROS 2 Jazzy does not support synchronous calls","Because the service server rejects synchronous clients"],"correct":1,"explanation":"In a SingleThreadedExecutor, calling client.call() blocks the only worker thread waiting for a response, but that same thread is needed to process the incoming response callback—deadlocking the node!"}],"has_quiz":true,"next_id":"lesson_09","prev_id":"lesson_07"},{"id":"lesson_09","num":9,"num_str":"09","title":"Communication Mechanism III: Dynamic Parameters & YAML Configuration","slug":"dynamic_parameters_and_yaml","filename":"09_dynamic_parameters_and_yaml.md","module":"Advanced Communication Patterns","module_id":2,"duration":"45-60 min","focus":"Node Parameters, Validation Callbacks (\`SetParametersResult\`) & YAML Files","snapshot":[],"html_content":"<h1 id=\\"lesson-09-communication-mechanism-iii-dynamic-parameters--yaml-configuration\\">Lesson 09: Communication Mechanism III: Dynamic Parameters &amp; YAML Configuration</h1>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Focus:</strong> Node Parameters, Validation Callbacks (<code class=\\"inline-code\\">SetParametersResult</code>) &amp; YAML Files<br><strong>Course Track:</strong> NavPro Learning Hub - Level 1 (Chapter 11.2)<br><strong>Target Environment:</strong> ROS 2 Jazzy Jalisco</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"1-overview--learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>Hardcoding numeric thresholds, robot dimensions, or PID gains in Python scripts is an anti-pattern. In ROS 2, <strong>Parameters</strong> allow configuration values to be injected into nodes at startup (via YAML files or launch arguments) and dynamically modified at runtime without stopping the process.</p>\\n<p>By the end of this lesson, you will:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Understand how ROS 2 parameters are scoped per-node (eliminating the centralized ROS 1 parameter server).</li>\\n<li>Declare typed parameters with <code class=\\"inline-code\\">ParameterDescriptor</code> metadata and range constraints.</li>\\n<li>Implement dynamic runtime parameter validation using <code class=\\"inline-code\\">add_on_set_parameters_callback</code> and <code class=\\"inline-code\\">SetParametersResult</code>.</li>\\n<li>Structure industry-standard <code class=\\"inline-code\\">.yaml</code> configuration files and load them at launch.</li>\\n<li>Use CLI tools (<code class=\\"inline-code\\">ros2 param list</code>, <code class=\\"inline-code\\">get</code>, <code class=\\"inline-code\\">set</code>, <code class=\\"inline-code\\">dump</code>) to tune live running robots.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-ros-1-vs-ros-2-parameter-architecture\\">2. ROS 1 vs. ROS 2 Parameter Architecture</h2>\\n<div class=\\"lesson-image-wrapper\\"><img src=\\"assets/images/ros1_vs_ros2_params.svg\\" alt=\\"ROS 1 vs. ROS 2 Parameter Architecture\\" class=\\"lesson-image\\" loading=\\"lazy\\"><span class=\\"image-caption\\">ROS 1 vs. ROS 2 Parameter Architecture</span></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-step-by-step-declaring-parameters-in-python\\">3. Step-by-Step: Declaring Parameters in Python</h2>\\n<p>Let&#x27;s build a parameter-driven node with validation.</p>\\n<p>Create file <code class=\\"inline-code\\">parameter_controller.py</code>:</p>\\n<div class=\\"code-container\\" data-language=\\"python\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">PYTHON</span><button class=\\"copy-code-btn\\" data-code=\\"#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nNavPro Learning Hub - Lesson 09\\nDynamic Parameters: Declares, validates, and responds to runtime configuration changes.\\n&quot;&quot;&quot;\\n\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom rcl_interfaces.msg import ParameterDescriptor, ParameterType, SetParametersResult\\n\\n\\nclass ParameterizedController(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;parameterized_controller&#x27;)\\n\\n        # -------------------------------------------------------------\\n        # 1. Parameter Declaration with Descriptors\\n        # -------------------------------------------------------------\\n        # String parameter\\n        robot_id_desc = ParameterDescriptor(\\n            description=&#x27;Unique factory serial identifier of the AMR&#x27;,\\n            type=ParameterType.PARAMETER_STRING\\n        )\\n        self.declare_parameter(&#x27;robot_id&#x27;, &#x27;navpro-mini-42&#x27;, robot_id_desc)\\n\\n        # Float parameter with logical limits\\n        max_speed_desc = ParameterDescriptor(\\n            description=&#x27;Maximum allowable linear speed in meters/second&#x27;,\\n            type=ParameterType.PARAMETER_DOUBLE\\n        )\\n        self.declare_parameter(&#x27;max_linear_speed&#x27;, 0.5, max_speed_desc)\\n\\n        # Boolean parameter\\n        safety_brake_desc = ParameterDescriptor(\\n            description=&#x27;Enforce ultrasonic proximity safety brake&#x27;,\\n            type=ParameterType.PARAMETER_BOOL\\n        )\\n        self.declare_parameter(&#x27;enable_proximity_brake&#x27;, True, safety_brake_desc)\\n\\n        # -------------------------------------------------------------\\n        # 2. Retrieve Initial Values\\n        # -------------------------------------------------------------\\n        self.robot_id = self.get_parameter(&#x27;robot_id&#x27;).value\\n        self.max_speed = self.get_parameter(&#x27;max_linear_speed&#x27;).value\\n        self.brake_enabled = self.get_parameter(&#x27;enable_proximity_brake&#x27;).value\\n\\n        self.get_logger().info(\\n            f&#x27;Loaded Params | ID: {self.robot_id} | MaxSpeed: {self.max_speed} m/s | Brake: {self.brake_enabled}&#x27;\\n        )\\n\\n        # -------------------------------------------------------------\\n        # 3. Register Dynamic Parameter Change Callback\\n        # -------------------------------------------------------------\\n        self.add_on_set_parameters_callback(self.parameter_validation_callback)\\n\\n    def parameter_validation_callback(self, params):\\n        &quot;&quot;&quot;\\n        Executed automatically whenever a user runs \`ros2 param set\`.\\n        Allows the node to validate constraints and REJECT invalid values!\\n        &quot;&quot;&quot;\\n        for param in params:\\n            if param.name == &#x27;max_linear_speed&#x27;:\\n                # Enforce physical safety constraint: speed must be between 0.05 and 1.5 m/s\\n                if param.value &lt;= 0.0 or param.value &gt; 1.5:\\n                    self.get_logger().error(f&#x27;Rejected invalid speed: {param.value}. Must be in range (0.0, 1.5]!&#x27;)\\n                    return SetParametersResult(\\n                        successful=False,\\n                        reason=&quot;max_linear_speed must be between 0.01 and 1.5 m/s&quot;\\n                    )\\n                self.max_speed = param.value\\n                self.get_logger().info(f&#x27;UPDATED max_linear_speed to: {self.max_speed} m/s&#x27;)\\n\\n            elif param.name == &#x27;enable_proximity_brake&#x27;:\\n                self.brake_enabled = param.value\\n                self.get_logger().warn(f&#x27;UPDATED enable_proximity_brake to: {self.brake_enabled}&#x27;)\\n\\n        return SetParametersResult(successful=True, reason=&quot;Parameters applied successfully&quot;)\\n\\n\\ndef main():\\n    rclpy.init()\\n    node = ParameterizedController()\\n    try:\\n        rclpy.spin(node)\\n    except KeyboardInterrupt:\\n        pass\\n    finally:\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\">📋 Copy</button></div><pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nNavPro Learning Hub - Lesson 09\\nDynamic Parameters: Declares, validates, and responds to runtime configuration changes.\\n&quot;&quot;&quot;\\n\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom rcl_interfaces.msg import ParameterDescriptor, ParameterType, SetParametersResult\\n\\n\\nclass ParameterizedController(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;parameterized_controller&#x27;)\\n\\n        # -------------------------------------------------------------\\n        # 1. Parameter Declaration with Descriptors\\n        # -------------------------------------------------------------\\n        # String parameter\\n        robot_id_desc = ParameterDescriptor(\\n            description=&#x27;Unique factory serial identifier of the AMR&#x27;,\\n            type=ParameterType.PARAMETER_STRING\\n        )\\n        self.declare_parameter(&#x27;robot_id&#x27;, &#x27;navpro-mini-42&#x27;, robot_id_desc)\\n\\n        # Float parameter with logical limits\\n        max_speed_desc = ParameterDescriptor(\\n            description=&#x27;Maximum allowable linear speed in meters/second&#x27;,\\n            type=ParameterType.PARAMETER_DOUBLE\\n        )\\n        self.declare_parameter(&#x27;max_linear_speed&#x27;, 0.5, max_speed_desc)\\n\\n        # Boolean parameter\\n        safety_brake_desc = ParameterDescriptor(\\n            description=&#x27;Enforce ultrasonic proximity safety brake&#x27;,\\n            type=ParameterType.PARAMETER_BOOL\\n        )\\n        self.declare_parameter(&#x27;enable_proximity_brake&#x27;, True, safety_brake_desc)\\n\\n        # -------------------------------------------------------------\\n        # 2. Retrieve Initial Values\\n        # -------------------------------------------------------------\\n        self.robot_id = self.get_parameter(&#x27;robot_id&#x27;).value\\n        self.max_speed = self.get_parameter(&#x27;max_linear_speed&#x27;).value\\n        self.brake_enabled = self.get_parameter(&#x27;enable_proximity_brake&#x27;).value\\n\\n        self.get_logger().info(\\n            f&#x27;Loaded Params | ID: {self.robot_id} | MaxSpeed: {self.max_speed} m/s | Brake: {self.brake_enabled}&#x27;\\n        )\\n\\n        # -------------------------------------------------------------\\n        # 3. Register Dynamic Parameter Change Callback\\n        # -------------------------------------------------------------\\n        self.add_on_set_parameters_callback(self.parameter_validation_callback)\\n\\n    def parameter_validation_callback(self, params):\\n        &quot;&quot;&quot;\\n        Executed automatically whenever a user runs \`ros2 param set\`.\\n        Allows the node to validate constraints and REJECT invalid values!\\n        &quot;&quot;&quot;\\n        for param in params:\\n            if param.name == &#x27;max_linear_speed&#x27;:\\n                # Enforce physical safety constraint: speed must be between 0.05 and 1.5 m/s\\n                if param.value &lt;= 0.0 or param.value &gt; 1.5:\\n                    self.get_logger().error(f&#x27;Rejected invalid speed: {param.value}. Must be in range (0.0, 1.5]!&#x27;)\\n                    return SetParametersResult(\\n                        successful=False,\\n                        reason=&quot;max_linear_speed must be between 0.01 and 1.5 m/s&quot;\\n                    )\\n                self.max_speed = param.value\\n                self.get_logger().info(f&#x27;UPDATED max_linear_speed to: {self.max_speed} m/s&#x27;)\\n\\n            elif param.name == &#x27;enable_proximity_brake&#x27;:\\n                self.brake_enabled = param.value\\n                self.get_logger().warn(f&#x27;UPDATED enable_proximity_brake to: {self.brake_enabled}&#x27;)\\n\\n        return SetParametersResult(successful=True, reason=&quot;Parameters applied successfully&quot;)\\n\\n\\ndef main():\\n    rclpy.init()\\n    node = ParameterizedController()\\n    try:\\n        rclpy.spin(node)\\n    except KeyboardInterrupt:\\n        pass\\n    finally:\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-organizing-configuration-with-yaml-files\\">4. Organizing Configuration with YAML Files</h2>\\n<p>In production, robots load parameter hierarchies from YAML files rather than setting them one-by-one.</p>\\n<h3 id=\\"structure-of-ros-2-yaml-files\\">Structure of ROS 2 YAML Files:</h3>\\n<div class=\\"code-container\\" data-language=\\"yaml\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">YAML</span><button class=\\"copy-code-btn\\" data-code=\\"# Package: navpro_basics\\n# File: config/teleop_params.yaml\\n\\nparameterized_controller:        # MUST match the node name registered in super().__init__()\\n  ros__parameters:               # Note the double underscore!\\n    robot_id: &quot;navpro-wh-01&quot;\\n    max_linear_speed: 0.75\\n    enable_proximity_brake: true\\">📋 Copy</button></div><pre><code class=\\"language-yaml\\"># Package: navpro_basics\\n# File: config/teleop_params.yaml\\n\\nparameterized_controller:        # MUST match the node name registered in super().__init__()\\n  ros__parameters:               # Note the double underscore!\\n    robot_id: &quot;navpro-wh-01&quot;\\n    max_linear_speed: 0.75\\n    enable_proximity_brake: true</code></pre></div>\\n<h3 id=\\"loading-yaml-via-the-cli\\">Loading YAML via the CLI:</h3>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"ros2 run navpro_basics param_node_explained --ros-args --params-file src/navpro_basics/config/teleop_params.yaml\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">ros2 run navpro_basics param_node_explained --ros-args --params-file src/navpro_basics/config/teleop_params.yaml</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-parameter-inspection-with-the-cli\\">5. Parameter Inspection with the CLI</h2>\\n<p>With the node running in Terminal 1, open Terminal 2:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# 1. List all parameters exposed by all running nodes\\nros2 param list\\n\\n# 2. Get current value of a parameter\\nros2 param get /parameterized_controller max_linear_speed\\n# Integer: 0.5\\n\\n# 3. Dynamically modify a parameter at runtime\\nros2 param set /parameterized_controller max_linear_speed 1.2\\n# Set parameter successful\\n\\n# 4. Verify parameter validation rejects out-of-bounds values!\\nros2 param set /parameterized_controller max_linear_speed 99.0\\n# Setting parameter failed: max_linear_speed must be between 0.01 and 1.5 m/s\\n\\n# 5. Dump all live parameters of a node to a YAML file\\nros2 param dump /parameterized_controller\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># 1. List all parameters exposed by all running nodes\\nros2 param list\\n\\n# 2. Get current value of a parameter\\nros2 param get /parameterized_controller max_linear_speed\\n# Integer: 0.5\\n\\n# 3. Dynamically modify a parameter at runtime\\nros2 param set /parameterized_controller max_linear_speed 1.2\\n# Set parameter successful\\n\\n# 4. Verify parameter validation rejects out-of-bounds values!\\nros2 param set /parameterized_controller max_linear_speed 99.0\\n# Setting parameter failed: max_linear_speed must be between 0.01 and 1.5 m/s\\n\\n# 5. Dump all live parameters of a node to a YAML file\\nros2 param dump /parameterized_controller</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-hands-on-student-challenge\\">6. Hands-on Student Challenge</h2>\\n<p><strong>Task:</strong></p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>In your controller node, add an integer parameter <code class=\\"inline-code\\">&#x27;control_frequency_hz&#x27;</code> (default = <code class=\\"inline-code\\">20</code>).</li>\\n<li>In the validation callback, verify that <code class=\\"inline-code\\">&#x27;control_frequency_hz&#x27;</code> is between <code class=\\"inline-code\\">1</code> and <code class=\\"inline-code\\">100</code> Hz.</li>\\n<li>Write a timer that uses <code class=\\"inline-code\\">1.0 / self.control_frequency_hz</code> as its period.</li>\\n<li>Test changing the frequency from the CLI using <code class=\\"inline-code\\">ros2 param set</code>.</li>\\n</ol>","quizzes":[{"id":"q_l1_09_1","prompt":"Which method on rclpy.node.Node is used to register a parameter and define its default value?","options":["self.set_parameter('speed', 1.0)","self.declare_parameter('speed', 1.0)","self.register_param('speed', 1.0)","self.add_parameter('speed', 1.0)"],"correct":1,"explanation":"declare_parameter registers the parameter name, type descriptor, and default value with the parameter server, enabling external overrides via CLI or YAML."}],"has_quiz":true,"next_id":"lesson_10","prev_id":"lesson_08"},{"id":"lesson_10","num":10,"num_str":"10","title":"Runtime Management & Python Launch Files","slug":"launch_files_and_runtime_management","filename":"10_launch_files_and_runtime_management.md","module":"Advanced Communication Patterns","module_id":2,"duration":"45-60 min","focus":"Python Launch System, Multi-Node Orchestration, Namespaces & Remappings","snapshot":[],"html_content":"<h1 id=\\"lesson-10-runtime-management--python-launch-files\\">Lesson 10: Runtime Management &amp; Python Launch Files</h1>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Focus:</strong> Python Launch System, Multi-Node Orchestration, Namespaces &amp; Remappings<br><strong>Course Track:</strong> NavPro Learning Hub - Level 1 (Chapter 12.2 &amp; Project 2.2)<br><strong>Target Environment:</strong> ROS 2 Jazzy Jalisco</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"1-overview--learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>An autonomous robot rarely runs a single node. A standard AMR simultaneously executes hardware drivers, odometry estimators, SLAM filters, costmap generators, and safety watchdogs. Starting each node manually across 15 separate terminals is error-prone.</p>\\n<p>ROS 2 provides a programmatic <strong>Python Launch System</strong> to orchestrate multi-node lifecycles, inject YAML parameters, pass CLI arguments, and resolve topic name collisions.</p>\\n<p>By the end of this lesson, you will:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Understand the Python launch API: <code class=\\"inline-code\\">LaunchDescription</code>, <code class=\\"inline-code\\">Node</code>, <code class=\\"inline-code\\">DeclareLaunchArgument</code>, and <code class=\\"inline-code\\">LaunchConfiguration</code>.</li>\\n<li>Master <strong>Topic Remappings</strong> to rewire node inputs and outputs without modifying source code.</li>\\n<li>Use <strong>Namespaces</strong> to prevent topic collisions when deploying multiple robots.</li>\\n<li>Compose nested launch systems using <code class=\\"inline-code\\">IncludeLaunchDescription</code>.</li>\\n<li>Complete <strong>Project 2.2</strong>: Build a unified multi-node robotics supervisor launch script.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-the-python-launch-architecture\\">2. The Python Launch Architecture</h2>\\n<p>In ROS 1, launch files were written in XML (<code class=\\"inline-code\\">.launch</code>). ROS 2 introduces pure <strong>Python Launch Files</strong> (<code class=\\"inline-code\\">.launch.py</code>), allowing dynamic conditionals, loop constructs, and Python logic.</p>\\n<div class=\\"lesson-image-wrapper\\"><img src=\\"assets/images/ros2_launch_architecture.svg\\" alt=\\"ROS 2 Python Launch System Architecture\\" class=\\"lesson-image\\" loading=\\"lazy\\"><span class=\\"image-caption\\">ROS 2 Python Launch System Architecture</span></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-step-by-step-writing-a-python-launch-file\\">3. Step-by-Step: Writing a Python Launch File</h2>\\n<p>Let&#x27;s build a modular launch file that brings up our teleop safety controller with configurable arguments and YAML loading.</p>\\n<p>Create file <code class=\\"inline-code\\">src/navpro_basics/launch/teleop_supervisor.launch.py</code>:</p>\\n<div class=\\"code-container\\" data-language=\\"python\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">PYTHON</span><button class=\\"copy-code-btn\\" data-code=\\"#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nNavPro Learning Hub - Lesson 10\\nLaunch Script: teleop_supervisor.launch.py\\nDemonstrates arguments, YAML loading, namespaces, and topic remappings.\\n&quot;&quot;&quot;\\n\\nimport os\\nfrom ament_index_python.packages import get_package_share_directory\\nfrom launch import LaunchDescription\\nfrom launch.actions import DeclareLaunchArgument, LogInfo\\nfrom launch.substitutions import LaunchConfiguration\\nfrom launch_ros.actions import Node\\n\\n\\ndef generate_launch_description():\\n    &quot;&quot;&quot;Entry point function required by all ROS 2 launch files.&quot;&quot;&quot;\\n\\n    # 1. Locate the package share directory where installed files reside\\n    pkg_share = get_package_share_directory(&#x27;navpro_basics&#x27;)\\n    default_config_path = os.path.join(pkg_share, &#x27;config&#x27;, &#x27;teleop_params.yaml&#x27;)\\n\\n    # 2. Declare Launch Arguments (Configurable from the command line)\\n    config_file_arg = DeclareLaunchArgument(\\n        &#x27;config_file&#x27;,\\n        default_value=default_config_path,\\n        description=&#x27;Full path to YAML configuration file&#x27;\\n    )\\n\\n    use_sim_time_arg = DeclareLaunchArgument(\\n        &#x27;use_sim_time&#x27;,\\n        default_value=&#x27;false&#x27;,\\n        description=&#x27;Use simulation (Gazebo) clock if true&#x27;\\n    )\\n\\n    robot_namespace_arg = DeclareLaunchArgument(\\n        &#x27;robot_ns&#x27;,\\n        default_value=&#x27;&#x27;,\\n        description=&#x27;Top-level namespace for multi-robot isolation&#x27;\\n    )\\n\\n    # 3. Define Node Actions to Launch\\n    speed_limiter_node = Node(\\n        package=&#x27;navpro_basics&#x27;,\\n        executable=&#x27;task_teleop_speed_limiter&#x27;,\\n        name=&#x27;teleop_speed_limiter&#x27;,\\n        namespace=LaunchConfiguration(&#x27;robot_ns&#x27;),\\n        output=&#x27;screen&#x27;,\\n        emulate_tty=True,\\n        parameters=[\\n            LaunchConfiguration(&#x27;config_file&#x27;),\\n            {&#x27;use_sim_time&#x27;: LaunchConfiguration(&#x27;use_sim_time&#x27;)}\\n        ],\\n        # Remappings allow you to reconnect topic names dynamically!\\n        remappings=[\\n            # (&#x27;old_topic_name&#x27;, &#x27;new_topic_name&#x27;)\\n            (&#x27;/input/cmd_vel&#x27;, &#x27;/teleop/cmd_vel&#x27;),\\n        ]\\n    )\\n\\n    # 4. Assemble and return the complete LaunchDescription\\n    return LaunchDescription([\\n        config_file_arg,\\n        use_sim_time_arg,\\n        robot_namespace_arg,\\n        LogInfo(msg=[&#x27;Launching NavPro Teleop Supervisor with params: &#x27;, LaunchConfiguration(&#x27;config_file&#x27;)]),\\n        speed_limiter_node,\\n    ])\\">📋 Copy</button></div><pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nNavPro Learning Hub - Lesson 10\\nLaunch Script: teleop_supervisor.launch.py\\nDemonstrates arguments, YAML loading, namespaces, and topic remappings.\\n&quot;&quot;&quot;\\n\\nimport os\\nfrom ament_index_python.packages import get_package_share_directory\\nfrom launch import LaunchDescription\\nfrom launch.actions import DeclareLaunchArgument, LogInfo\\nfrom launch.substitutions import LaunchConfiguration\\nfrom launch_ros.actions import Node\\n\\n\\ndef generate_launch_description():\\n    &quot;&quot;&quot;Entry point function required by all ROS 2 launch files.&quot;&quot;&quot;\\n\\n    # 1. Locate the package share directory where installed files reside\\n    pkg_share = get_package_share_directory(&#x27;navpro_basics&#x27;)\\n    default_config_path = os.path.join(pkg_share, &#x27;config&#x27;, &#x27;teleop_params.yaml&#x27;)\\n\\n    # 2. Declare Launch Arguments (Configurable from the command line)\\n    config_file_arg = DeclareLaunchArgument(\\n        &#x27;config_file&#x27;,\\n        default_value=default_config_path,\\n        description=&#x27;Full path to YAML configuration file&#x27;\\n    )\\n\\n    use_sim_time_arg = DeclareLaunchArgument(\\n        &#x27;use_sim_time&#x27;,\\n        default_value=&#x27;false&#x27;,\\n        description=&#x27;Use simulation (Gazebo) clock if true&#x27;\\n    )\\n\\n    robot_namespace_arg = DeclareLaunchArgument(\\n        &#x27;robot_ns&#x27;,\\n        default_value=&#x27;&#x27;,\\n        description=&#x27;Top-level namespace for multi-robot isolation&#x27;\\n    )\\n\\n    # 3. Define Node Actions to Launch\\n    speed_limiter_node = Node(\\n        package=&#x27;navpro_basics&#x27;,\\n        executable=&#x27;task_teleop_speed_limiter&#x27;,\\n        name=&#x27;teleop_speed_limiter&#x27;,\\n        namespace=LaunchConfiguration(&#x27;robot_ns&#x27;),\\n        output=&#x27;screen&#x27;,\\n        emulate_tty=True,\\n        parameters=[\\n            LaunchConfiguration(&#x27;config_file&#x27;),\\n            {&#x27;use_sim_time&#x27;: LaunchConfiguration(&#x27;use_sim_time&#x27;)}\\n        ],\\n        # Remappings allow you to reconnect topic names dynamically!\\n        remappings=[\\n            # (&#x27;old_topic_name&#x27;, &#x27;new_topic_name&#x27;)\\n            (&#x27;/input/cmd_vel&#x27;, &#x27;/teleop/cmd_vel&#x27;),\\n        ]\\n    )\\n\\n    # 4. Assemble and return the complete LaunchDescription\\n    return LaunchDescription([\\n        config_file_arg,\\n        use_sim_time_arg,\\n        robot_namespace_arg,\\n        LogInfo(msg=[&#x27;Launching NavPro Teleop Supervisor with params: &#x27;, LaunchConfiguration(&#x27;config_file&#x27;)]),\\n        speed_limiter_node,\\n    ])</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-key-launch-actions--syntax-breakdown\\">4. Key Launch Actions &amp; Syntax Breakdown</h2>\\n<div class=\\"table-wrapper\\"><table>\\n<thead><tr>\\n<th>Launch Component</th>\\n<th>Function</th>\\n<th>Code Example</th>\\n</tr></thead><tbody>\\n<tr>\\n<td><code class=\\"inline-code\\">get_package_share_directory(&#x27;pkg&#x27;)</code></td>\\n<td>Locates the installation path where YAMLs and URDFs were copied</td>\\n<td><code class=\\"inline-code\\">os.path.join(pkg_dir, &#x27;config&#x27;, &#x27;my.yaml&#x27;)</code></td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">DeclareLaunchArgument</code></td>\\n<td>Exposes a CLI parameter with description and default value</td>\\n<td><code class=\\"inline-code\\">DeclareLaunchArgument(&#x27;max_speed&#x27;, default_value=&#x27;1.0&#x27;)</code></td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">LaunchConfiguration</code></td>\\n<td>Evaluates the argument substitution at runtime</td>\\n<td><code class=\\"inline-code\\">parameters=[{&#x27;speed&#x27;: LaunchConfiguration(&#x27;max_speed&#x27;)}]</code></td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">remappings=[(from, to)]</code></td>\\n<td>Dynamically redirects a topic name without changing code</td>\\n<td><code class=\\"inline-code\\">remappings=[(&#x27;/cmd_vel&#x27;, &#x27;/navpro/cmd_vel&#x27;)]</code></td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">namespace=&#x27;amr_1&#x27;</code></td>\\n<td>Prefixes all nodes, topics, and services with a namespace</td>\\n<td><code class=\\"inline-code\\">/amr_1/cmd_vel</code>, <code class=\\"inline-code\\">/amr_1/scan</code></td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">output=&#x27;screen&#x27;</code></td>\\n<td>Forwards stdout/stderr directly to terminal with color coding</td>\\n<td><code class=\\"inline-code\\">output=&#x27;screen&#x27;, emulate_tty=True</code></td>\\n</tr>\\n</tbody></table></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-composition-including-other-launch-files\\">5. Composition: Including Other Launch Files</h2>\\n<p>In advanced systems, top-level launch files include sub-launch files using <code class=\\"inline-code\\">IncludeLaunchDescription</code>:</p>\\n<div class=\\"code-container\\" data-language=\\"python\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">PYTHON</span><button class=\\"copy-code-btn\\" data-code=\\"from launch.actions import IncludeLaunchDescription\\nfrom launch.launch_description_sources import PythonLaunchDescriptionSource\\n\\n# Include robot state publisher from navpro_description\\nrsp_launch = IncludeLaunchDescription(\\n    PythonLaunchDescriptionSource(\\n        os.path.join(get_package_share_directory(&#x27;navpro_description&#x27;), &#x27;launch&#x27;, &#x27;rsp.launch.py&#x27;)\\n    ),\\n    launch_arguments={&#x27;use_sim_time&#x27;: &#x27;true&#x27;}.items()\\n)\\">📋 Copy</button></div><pre><code class=\\"language-python\\">from launch.actions import IncludeLaunchDescription\\nfrom launch.launch_description_sources import PythonLaunchDescriptionSource\\n\\n# Include robot state publisher from navpro_description\\nrsp_launch = IncludeLaunchDescription(\\n    PythonLaunchDescriptionSource(\\n        os.path.join(get_package_share_directory(&#x27;navpro_description&#x27;), &#x27;launch&#x27;, &#x27;rsp.launch.py&#x27;)\\n    ),\\n    launch_arguments={&#x27;use_sim_time&#x27;: &#x27;true&#x27;}.items()\\n)</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-execution--cli-overrides\\">6. Execution &amp; CLI Overrides</h2>\\n<p>Run your launch file:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"ros2 launch navpro_basics teleop_supervisor.launch.py\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">ros2 launch navpro_basics teleop_supervisor.launch.py</code></pre></div>\\n<h3 id=\\"passing-command-line-overrides\\">Passing Command-Line Overrides:</h3>\\n<p>You can override any declared argument on the command line:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# 1. Override use_sim_time\\nros2 launch navpro_basics teleop_supervisor.launch.py use_sim_time:=true\\n\\n# 2. Deploy with a specific robot namespace for multi-robot isolation!\\nros2 launch navpro_basics teleop_supervisor.launch.py robot_ns:=robot_alpha\\n\\n# In a separate terminal, observe the namespace effect:\\nros2 node list\\n# /robot_alpha/teleop_speed_limiter\\n\\nros2 topic list\\n# /robot_alpha/cmd_vel\\n# /robot_alpha/teleop/cmd_vel\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># 1. Override use_sim_time\\nros2 launch navpro_basics teleop_supervisor.launch.py use_sim_time:=true\\n\\n# 2. Deploy with a specific robot namespace for multi-robot isolation!\\nros2 launch navpro_basics teleop_supervisor.launch.py robot_ns:=robot_alpha\\n\\n# In a separate terminal, observe the namespace effect:\\nros2 node list\\n# /robot_alpha/teleop_speed_limiter\\n\\nros2 topic list\\n# /robot_alpha/cmd_vel\\n# /robot_alpha/teleop/cmd_vel</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"7-project-22-multi-node-supervisory-launch-system\\">7. Project 2.2: Multi-Node Supervisory Launch System</h2>\\n<h3 id=\\"project-objective\\">Project Objective:</h3>\\n<p>Build <code class=\\"inline-code\\">navpro_system_bringup.launch.py</code> that launches:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li><code class=\\"inline-code\\">navpro_basics/publisher_explained</code> (remapped to <code class=\\"inline-code\\">/teleop/cmd_vel</code>)</li>\\n<li><code class=\\"inline-code\\">navpro_basics/task_teleop_speed_limiter</code></li>\\n<li><code class=\\"inline-code\\">navpro_basics/subscriber_explained</code> (listening to <code class=\\"inline-code\\">/cmd_vel</code>)</li>\\n<li>An argument <code class=\\"inline-code\\">enable_teleop_publisher</code> (default: <code class=\\"inline-code\\">true</code>). Use <code class=\\"inline-code\\">IfCondition</code> to only launch the teleop publisher if the flag is true!</li>\\n</ol>","quizzes":[{"id":"q_l1_10_1","prompt":"In a ROS 2 Python launch file, what does the 'remappings' parameter on launch_ros.actions.Node allow you to do?","options":["Rename physical USB ports for motor controllers","Redirect topic or service names without modifying the underlying Python source code","Swap the ROS 2 DDS distribution at runtime","Change keyboard shortcuts in RViz2"],"correct":1,"explanation":"Remappings allow routing topics (e.g. from /cmd_vel to /diff_drive_controller/cmd_vel_unstamped) dynamically in launch files, decoupling node code from specific robot topologies."}],"has_quiz":true,"next_id":"lesson_11","prev_id":"lesson_09"},{"id":"lesson_11","num":11,"num_str":"11","title":"Communication Mechanism IV: Action Servers & Clients in Python","slug":"ros2_actions_server_and_client","filename":"11_ros2_actions_server_and_client.md","module":"Advanced Communication Patterns","module_id":2,"duration":"45-60 min","focus":"Goal-Feedback-Result Communication, Preemption & Asynchronous Action Clients","snapshot":[["Actions Pattern","Long-running, preemptible goal execution with real-time progress feedback (e.g., Navigate to Charging Dock)."],["Three Channels","Goal Service (Accept/Reject), Feedback Topic (Continuous % progress), and Result Service (Success/Aborted/Canceled)."]],"html_content":"<h1 id=\\"lesson-11-communication-mechanism-iv-action-servers--clients-in-python\\">Lesson 11: Communication Mechanism IV: Action Servers &amp; Clients in Python</h1>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Focus:</strong> Goal-Feedback-Result Communication, Preemption &amp; Asynchronous Action Clients<br><strong>Course Track:</strong> NavPro Learning Hub - Level 1 (Chapter 17.1)<br><strong>Target Environment:</strong> ROS 2 Jazzy Jalisco</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"1-overview--learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>Services are ideal for instant requests (e.g. &quot;turn on light&quot; or &quot;reset encoder&quot;). However, for long-running robotic tasks that take seconds or minutes to complete (e.g., navigating across a warehouse or executing a 360-degree LiDAR calibration sweep), Services fail because they provide no progress feedback and cannot be canceled midway.</p>\\n<p>ROS 2 <strong>Actions</strong> solve this by implementing the <strong>Goal - Feedback - Result</strong> protocol with native preemption and cancellation support.</p>\\n<p>By the end of this lesson, you will:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Master the 3-part Action lifecycle: Goal submission, Real-time Feedback streaming, and Final Result delivery.</li>\\n<li>Build an object-oriented Python <strong>Action Server</strong> using <code class=\\"inline-code\\">rclpy.action.ActionServer</code>.</li>\\n<li>Handle goal acceptance, goal rejection, feedback broadcasting, and client cancellation requests.</li>\\n<li>Build an asynchronous Python <strong>Action Client</strong> using <code class=\\"inline-code\\">rclpy.action.ActionClient</code>.</li>\\n<li>Interact with, trigger, and cancel active actions via the CLI using <code class=\\"inline-code\\">ros2 action send_goal --feedback</code>.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-action-communication-architecture\\">2. Action Communication Architecture</h2>\\n<p>Under the hood, every ROS 2 Action is implemented as a coordinated set of DDS topics and services:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"                            ACTION LIFECYCLE\\n                            \\n   [Action Client]                                    [Action Server]\\n          |                                                  |\\n          | ----- 1. Send Goal (Service: send_goal) -------&gt; |\\n          | &lt;---- 2. Goal Accepted (GoalResponse.ACCEPT) --- |\\n          |                                                  |\\n          | &lt;==== 3. Periodic Progress (Topic: feedback) === |\\n          | &lt;====    (e.g., Distance remaining: 1.4m)   ==== |\\n          |                                                  |\\n          | ----- 4. (Optional) Cancel Goal ---------------&gt; |\\n          | &lt;----    Cancel Accepted ----------------------- |\\n          |                                                  |\\n          | &lt;---- 5. Final Outcome (Service: get_result) --- |\\n          |          (SUCCEEDED / CANCELED / ABORTED)        |\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">                            ACTION LIFECYCLE\\n                            \\n   [Action Client]                                    [Action Server]\\n          |                                                  |\\n          | ----- 1. Send Goal (Service: send_goal) -------&gt; |\\n          | &lt;---- 2. Goal Accepted (GoalResponse.ACCEPT) --- |\\n          |                                                  |\\n          | &lt;==== 3. Periodic Progress (Topic: feedback) === |\\n          | &lt;====    (e.g., Distance remaining: 1.4m)   ==== |\\n          |                                                  |\\n          | ----- 4. (Optional) Cancel Goal ---------------&gt; |\\n          | &lt;----    Cancel Accepted ----------------------- |\\n          |                                                  |\\n          | &lt;---- 5. Final Outcome (Service: get_result) --- |\\n          |          (SUCCEEDED / CANCELED / ABORTED)        |</code></pre></div>\\n<ul class=\\"lesson-bullet-list\\">\\n<li><strong>Goal:</strong> Initiated by the client (e.g. target pose coordinates).</li>\\n<li><strong>Feedback:</strong> Periodic updates published by the server while executing the goal (e.g. current progress, distance remaining).</li>\\n<li><strong>Result:</strong> Final response sent when the task completes, fails, or is canceled.</li>\\n</ul>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-step-by-step-writing-an-action-server-in-python\\">3. Step-by-Step: Writing an Action Server in Python</h2>\\n<p>Let&#x27;s implement a patrol action server that moves through waypoints, publishes feedback, and handles cancel requests.</p>\\n<p>Create file <code class=\\"inline-code\\">patrol_action_server.py</code>:</p>\\n<div class=\\"code-container\\" data-language=\\"python\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">PYTHON</span><button class=\\"copy-code-btn\\" data-code=\\"#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nNavPro Learning Hub - Lesson 11\\nAction Server: Executes autonomous multi-checkpoint patrol with progress streaming.\\n&quot;&quot;&quot;\\n\\nimport time\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom rclpy.action import ActionServer, CancelResponse, GoalResponse\\nfrom navpro_interfaces.action import Patrol\\n\\n\\nclass PatrolActionServer(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;patrol_action_server&#x27;)\\n\\n        # Create Action Server\\n        self.action_server_ = ActionServer(\\n            self,\\n            Patrol,\\n            &#x27;patrol_robot&#x27;,\\n            execute_callback=self.execute_callback,\\n            goal_callback=self.goal_callback,\\n            cancel_callback=self.cancel_callback\\n        )\\n\\n        self.get_logger().info(&#x27;Patrol Action Server active on action name: &quot;patrol_robot&quot;&#x27;)\\n\\n    def goal_callback(self, goal_request):\\n        &quot;&quot;&quot;Validates incoming goals before accepting.&quot;&quot;&quot;\\n        self.get_logger().info(f&#x27;Received patrol goal request with {len(goal_request.waypoints)} checkpoints.&#x27;)\\n        if len(goal_request.waypoints) == 0:\\n            self.get_logger().warn(&#x27;Rejecting goal: Waypoint list cannot be empty!&#x27;)\\n            return GoalResponse.REJECT\\n        return GoalResponse.ACCEPT\\n\\n    def cancel_callback(self, goal_handle):\\n        &quot;&quot;&quot;Handles client requests to cancel an in-progress patrol.&quot;&quot;&quot;\\n        self.get_logger().warn(&#x27;Received client request to cancel patrol!&#x27;)\\n        return CancelResponse.ACCEPT\\n\\n    def execute_callback(self, goal_handle):\\n        &quot;&quot;&quot;Executes the long-running patrol loop in background thread.&quot;&quot;&quot;\\n        self.get_logger().info(&#x27;Executing patrol mission...&#x27;)\\n        feedback_msg = Patrol.Feedback()\\n        total_waypoints = len(goal_handle.request.waypoints)\\n        battery = 98.0\\n\\n        for i in range(total_waypoints):\\n            # Check if the client requested cancellation!\\n            if goal_handle.is_cancel_requested:\\n                goal_handle.canceled()\\n                self.get_logger().warn(&#x27;Patrol mission canceled by client request.&#x27;)\\n                result = Patrol.Result()\\n                result.success = False\\n                result.completed_waypoints = i\\n                return result\\n\\n            # Simulate traveling to waypoint i\\n            time.sleep(1.5)\\n            battery -= 2.5\\n\\n            # Stream feedback to the client\\n            feedback_msg.current_waypoint_index = i + 1\\n            feedback_msg.distance_to_next_waypoint = round(max(0.0, 5.0 - (i * 1.2)), 2)\\n            feedback_msg.battery_remaining_pct = round(battery, 1)\\n\\n            goal_handle.publish_feedback(feedback_msg)\\n            self.get_logger().info(\\n                f&#x27;Checkpoint [{feedback_msg.current_waypoint_index}/{total_waypoints}] reached. Batt: {battery}%&#x27;\\n            )\\n\\n        # Mark goal as successfully completed\\n        goal_handle.succeed()\\n        result = Patrol.Result()\\n        result.success = True\\n        result.completed_waypoints = total_waypoints\\n        result.total_distance_traveled = 24.8\\n        self.get_logger().info(&#x27;Patrol mission completed successfully!&#x27;)\\n        return result\\n\\n\\ndef main():\\n    rclpy.init()\\n    server = PatrolActionServer()\\n    try:\\n        rclpy.spin(server)\\n    except KeyboardInterrupt:\\n        pass\\n    finally:\\n        server.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\">📋 Copy</button></div><pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nNavPro Learning Hub - Lesson 11\\nAction Server: Executes autonomous multi-checkpoint patrol with progress streaming.\\n&quot;&quot;&quot;\\n\\nimport time\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom rclpy.action import ActionServer, CancelResponse, GoalResponse\\nfrom navpro_interfaces.action import Patrol\\n\\n\\nclass PatrolActionServer(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;patrol_action_server&#x27;)\\n\\n        # Create Action Server\\n        self.action_server_ = ActionServer(\\n            self,\\n            Patrol,\\n            &#x27;patrol_robot&#x27;,\\n            execute_callback=self.execute_callback,\\n            goal_callback=self.goal_callback,\\n            cancel_callback=self.cancel_callback\\n        )\\n\\n        self.get_logger().info(&#x27;Patrol Action Server active on action name: &quot;patrol_robot&quot;&#x27;)\\n\\n    def goal_callback(self, goal_request):\\n        &quot;&quot;&quot;Validates incoming goals before accepting.&quot;&quot;&quot;\\n        self.get_logger().info(f&#x27;Received patrol goal request with {len(goal_request.waypoints)} checkpoints.&#x27;)\\n        if len(goal_request.waypoints) == 0:\\n            self.get_logger().warn(&#x27;Rejecting goal: Waypoint list cannot be empty!&#x27;)\\n            return GoalResponse.REJECT\\n        return GoalResponse.ACCEPT\\n\\n    def cancel_callback(self, goal_handle):\\n        &quot;&quot;&quot;Handles client requests to cancel an in-progress patrol.&quot;&quot;&quot;\\n        self.get_logger().warn(&#x27;Received client request to cancel patrol!&#x27;)\\n        return CancelResponse.ACCEPT\\n\\n    def execute_callback(self, goal_handle):\\n        &quot;&quot;&quot;Executes the long-running patrol loop in background thread.&quot;&quot;&quot;\\n        self.get_logger().info(&#x27;Executing patrol mission...&#x27;)\\n        feedback_msg = Patrol.Feedback()\\n        total_waypoints = len(goal_handle.request.waypoints)\\n        battery = 98.0\\n\\n        for i in range(total_waypoints):\\n            # Check if the client requested cancellation!\\n            if goal_handle.is_cancel_requested:\\n                goal_handle.canceled()\\n                self.get_logger().warn(&#x27;Patrol mission canceled by client request.&#x27;)\\n                result = Patrol.Result()\\n                result.success = False\\n                result.completed_waypoints = i\\n                return result\\n\\n            # Simulate traveling to waypoint i\\n            time.sleep(1.5)\\n            battery -= 2.5\\n\\n            # Stream feedback to the client\\n            feedback_msg.current_waypoint_index = i + 1\\n            feedback_msg.distance_to_next_waypoint = round(max(0.0, 5.0 - (i * 1.2)), 2)\\n            feedback_msg.battery_remaining_pct = round(battery, 1)\\n\\n            goal_handle.publish_feedback(feedback_msg)\\n            self.get_logger().info(\\n                f&#x27;Checkpoint [{feedback_msg.current_waypoint_index}/{total_waypoints}] reached. Batt: {battery}%&#x27;\\n            )\\n\\n        # Mark goal as successfully completed\\n        goal_handle.succeed()\\n        result = Patrol.Result()\\n        result.success = True\\n        result.completed_waypoints = total_waypoints\\n        result.total_distance_traveled = 24.8\\n        self.get_logger().info(&#x27;Patrol mission completed successfully!&#x27;)\\n        return result\\n\\n\\ndef main():\\n    rclpy.init()\\n    server = PatrolActionServer()\\n    try:\\n        rclpy.spin(server)\\n    except KeyboardInterrupt:\\n        pass\\n    finally:\\n        server.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-step-by-step-writing-an-asynchronous-action-client-in-python\\">4. Step-by-Step: Writing an Asynchronous Action Client in Python</h2>\\n<p>Now let&#x27;s build the client that dispatches the patrol goal and monitors real-time feedback:</p>\\n<p>Create file <code class=\\"inline-code\\">patrol_action_client.py</code>:</p>\\n<div class=\\"code-container\\" data-language=\\"python\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">PYTHON</span><button class=\\"copy-code-btn\\" data-code=\\"#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nNavPro Learning Hub - Lesson 11\\nAction Client: Dispatches patrol goal, prints real-time feedback, and awaits result.\\n&quot;&quot;&quot;\\n\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom rclpy.action import ActionClient\\nfrom geometry_msgs.msg import PoseStamped\\nfrom navpro_interfaces.action import Patrol\\n\\n\\nclass PatrolActionClient(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;patrol_action_client&#x27;)\\n        self.client_ = ActionClient(self, Patrol, &#x27;patrol_robot&#x27;)\\n\\n    def send_patrol_goal(self):\\n        self.get_logger().info(&#x27;Waiting for patrol action server to start...&#x27;)\\n        self.client_.wait_for_server()\\n\\n        goal_msg = Patrol.Goal()\\n        goal_msg.loop_count = 1\\n\\n        # Populate 3 dummy waypoints\\n        for i in range(3):\\n            pose = PoseStamped()\\n            pose.pose.position.x = float(i * 2.0)\\n            goal_msg.waypoints.append(pose)\\n\\n        self.get_logger().info(&#x27;Dispatching patrol goal...&#x27;)\\n        # Send goal asynchronously with feedback callback\\n        send_goal_future = self.client_.send_goal_async(\\n            goal_msg,\\n            feedback_callback=self.feedback_callback\\n        )\\n        send_goal_future.add_done_callback(self.goal_response_callback)\\n\\n    def goal_response_callback(self, future):\\n        goal_handle = future.result()\\n        if not goal_handle.accepted:\\n            self.get_logger().error(&#x27;Patrol goal was rejected by the server!&#x27;)\\n            return\\n\\n        self.get_logger().info(&#x27;Patrol goal accepted! Awaiting mission progress...&#x27;)\\n        result_future = goal_handle.get_result_async()\\n        result_future.add_done_callback(self.result_callback)\\n\\n    def feedback_callback(self, feedback_msg):\\n        fb = feedback_msg.feedback\\n        self.get_logger().info(\\n            f&#x27;[FEEDBACK] Checkpoint: {fb.current_waypoint_index} | Dist remaining: {fb.distance_to_next_waypoint}m | Battery: {fb.battery_remaining_pct}%&#x27;\\n        )\\n\\n    def result_callback(self, future):\\n        result = future.result().result\\n        status = future.result().status\\n        self.get_logger().info(f&#x27;[RESULT] Status: {status} | Completed: {result.completed_waypoints} waypoints | Dist: {result.total_distance_traveled}m&#x27;)\\n\\n\\ndef main():\\n    rclpy.init()\\n    client = PatrolActionClient()\\n    client.send_patrol_goal()\\n    try:\\n        rclpy.spin(client)\\n    except KeyboardInterrupt:\\n        pass\\n    finally:\\n        client.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\">📋 Copy</button></div><pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nNavPro Learning Hub - Lesson 11\\nAction Client: Dispatches patrol goal, prints real-time feedback, and awaits result.\\n&quot;&quot;&quot;\\n\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom rclpy.action import ActionClient\\nfrom geometry_msgs.msg import PoseStamped\\nfrom navpro_interfaces.action import Patrol\\n\\n\\nclass PatrolActionClient(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;patrol_action_client&#x27;)\\n        self.client_ = ActionClient(self, Patrol, &#x27;patrol_robot&#x27;)\\n\\n    def send_patrol_goal(self):\\n        self.get_logger().info(&#x27;Waiting for patrol action server to start...&#x27;)\\n        self.client_.wait_for_server()\\n\\n        goal_msg = Patrol.Goal()\\n        goal_msg.loop_count = 1\\n\\n        # Populate 3 dummy waypoints\\n        for i in range(3):\\n            pose = PoseStamped()\\n            pose.pose.position.x = float(i * 2.0)\\n            goal_msg.waypoints.append(pose)\\n\\n        self.get_logger().info(&#x27;Dispatching patrol goal...&#x27;)\\n        # Send goal asynchronously with feedback callback\\n        send_goal_future = self.client_.send_goal_async(\\n            goal_msg,\\n            feedback_callback=self.feedback_callback\\n        )\\n        send_goal_future.add_done_callback(self.goal_response_callback)\\n\\n    def goal_response_callback(self, future):\\n        goal_handle = future.result()\\n        if not goal_handle.accepted:\\n            self.get_logger().error(&#x27;Patrol goal was rejected by the server!&#x27;)\\n            return\\n\\n        self.get_logger().info(&#x27;Patrol goal accepted! Awaiting mission progress...&#x27;)\\n        result_future = goal_handle.get_result_async()\\n        result_future.add_done_callback(self.result_callback)\\n\\n    def feedback_callback(self, feedback_msg):\\n        fb = feedback_msg.feedback\\n        self.get_logger().info(\\n            f&#x27;[FEEDBACK] Checkpoint: {fb.current_waypoint_index} | Dist remaining: {fb.distance_to_next_waypoint}m | Battery: {fb.battery_remaining_pct}%&#x27;\\n        )\\n\\n    def result_callback(self, future):\\n        result = future.result().result\\n        status = future.result().status\\n        self.get_logger().info(f&#x27;[RESULT] Status: {status} | Completed: {result.completed_waypoints} waypoints | Dist: {result.total_distance_traveled}m&#x27;)\\n\\n\\ndef main():\\n    rclpy.init()\\n    client = PatrolActionClient()\\n    client.send_patrol_goal()\\n    try:\\n        rclpy.spin(client)\\n    except KeyboardInterrupt:\\n        pass\\n    finally:\\n        client.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-verification-with-the-ros-2-action-cli\\">5. Verification with the ROS 2 Action CLI</h2>\\n<p>With the server running in Terminal 1, open Terminal 2:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# 1. List active action servers\\nros2 action list\\n\\n# 2. View action type and endpoints\\nros2 action info /patrol_robot\\n\\n# 3. Send goal from command line and watch real-time feedback streaming!\\nros2 action send_goal /patrol_robot navpro_interfaces/action/Patrol &quot;{loop_count: 1, waypoints: [{pose: {position: {x: 1.0}}}, {pose: {position: {x: 2.0}}}]}&quot; --feedback\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># 1. List active action servers\\nros2 action list\\n\\n# 2. View action type and endpoints\\nros2 action info /patrol_robot\\n\\n# 3. Send goal from command line and watch real-time feedback streaming!\\nros2 action send_goal /patrol_robot navpro_interfaces/action/Patrol &quot;{loop_count: 1, waypoints: [{pose: {position: {x: 1.0}}}, {pose: {position: {x: 2.0}}}]}&quot; --feedback</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-hands-on-student-challenge\\">6. Hands-on Student Challenge</h2>\\n<p><strong>Task:</strong></p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>In <code class=\\"inline-code\\">patrol_action_client.py</code>, set up a timer that triggers after 2.0 seconds.</li>\\n<li>In the timer callback, call <code class=\\"inline-code\\">goal_handle.cancel_goal_async()</code>.</li>\\n<li>Verify that the server receives the cancellation request, safely breaks its loop, and returns <code class=\\"inline-code\\">goal_handle.canceled()</code>.</li>\\n</ol>","quizzes":[{"id":"q_l1_11_1","prompt":"What are the three communication phases of a ROS 2 Action?","options":["Subscribe, Filter, Publish","Goal Request/Acceptance, Continuous Feedback Streaming, and Final Result","Ping, Handshake, Disconnect","Compile, Launch, Terminate"],"correct":1,"explanation":"ROS 2 Actions are designed for long-running preemptible tasks. They communicate via: (1) Goal Request & Acceptance, (2) Periodic Feedback, and (3) Final Result."}],"has_quiz":true,"next_id":"lesson_12","prev_id":"lesson_10"},{"id":"lesson_12","num":12,"num_str":"12","title":"Data Recording & Playback with ROS 2 Bags","slug":"ros2_bag_recording_and_playback","filename":"12_ros2_bag_recording_and_playback.md","module":"Advanced Communication Patterns","module_id":2,"duration":"45-60 min","focus":"Robotic Dataset Recording, MCAP Storage Plugin & Python \`rosbag2_py\` Reader","snapshot":[],"html_content":"<h1 id=\\"lesson-12-data-recording--playback-with-ros-2-bags\\">Lesson 12: Data Recording &amp; Playback with ROS 2 Bags</h1>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Focus:</strong> Robotic Dataset Recording, MCAP Storage Plugin &amp; Python <code class=\\"inline-code\\">rosbag2_py</code> Reader<br><strong>Course Track:</strong> NavPro Learning Hub - Level 1 (Chapter 18)<br><strong>Target Environment:</strong> ROS 2 Jazzy Jalisco</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"1-overview--learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>In physical robotics engineering, reproducing a bug that occurred 10 minutes ago in an aisle of a warehouse is impossible without recording the robot&#x27;s sensor data. A <strong>ROS 2 Bag</strong> acts as the robot&#x27;s &quot;flight data recorder,&quot; logging exact binary message frames with microsecond timestamps.</p>\\n<p>By the end of this lesson, you will:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Understand ROS 2 bag storage backends: legacy <strong>SQLite3</strong> vs. modern <strong>MCAP</strong>.</li>\\n<li>Record selective topic subsets (<code class=\\"inline-code\\">/cmd_vel</code>, <code class=\\"inline-code\\">/odom</code>, <code class=\\"inline-code\\">/scan</code>) and split logs by size/duration.</li>\\n<li>Inspect bag metadata and topic statistics using <code class=\\"inline-code\\">ros2 bag info</code>.</li>\\n<li>Replay datasets into the computational graph at varied rates (<code class=\\"inline-code\\">--rate 2.0</code>, <code class=\\"inline-code\\">--loop</code>).</li>\\n<li>Write a Python script using the <code class=\\"inline-code\\">rosbag2_py</code> API to parse and analyze recorded messages offline.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-storage-plugins-sqlite3-vs-mcap\\">2. Storage Plugins: SQLite3 vs. MCAP</h2>\\n<p>In ROS 2 Jazzy, two primary storage plugins exist:</p>\\n<div class=\\"table-wrapper\\"><table>\\n<thead><tr>\\n<th>Feature</th>\\n<th>SQLite3 (<code class=\\"inline-code\\">sqlite3</code>)</th>\\n<th>MCAP (<code class=\\"inline-code\\">mcap</code> - Industry Standard)</th>\\n</tr></thead><tbody>\\n<tr>\\n<td><strong>Default Storage</strong></td>\\n<td>Legacy Default (ROS 2 Humble)</td>\\n<td><strong>Native Default in ROS 2 Jazzy</strong></td>\\n</tr>\\n<tr>\\n<td><strong>Crash Resilience</strong></td>\\n<td>Uncommitted transactions can corrupt file on unexpected power cuts</td>\\n<td>Append-only index ensures data is recoverable after hard power loss</td>\\n</tr>\\n<tr>\\n<td><strong>Write Throughput</strong></td>\\n<td>~150 MB/s (bottleneck for 4K video or 3D LiDAR)</td>\\n<td><strong>400+ MB/s</strong> (zero-copy serialization)</td>\\n</tr>\\n<tr>\\n<td><strong>Visualization</strong></td>\\n<td>Requires conversion</td>\\n<td>Direct drag-and-drop into <strong>Foxglove Studio</strong> and PlotJuggler</td>\\n</tr>\\n</tbody></table></div>\\n<p>Install MCAP storage plugin:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"sudo apt install -y ros-jazzy-rosbag2-storage-mcap\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">sudo apt install -y ros-jazzy-rosbag2-storage-mcap</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-step-by-step-recording-data-via-the-cli\\">3. Step-by-Step: Recording Data via the CLI</h2>\\n<h3 id=\\"31-record-selective-topics\\">3.1 Record Selective Topics</h3>\\n<p>To prevent filling up disk space with unnecessary diagnostic streams, record only essential navigation topics:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# Record velocity, odometry, and laser scans into a timestamped folder\\nros2 bag record -o warehouse_trial_01 /cmd_vel /odom /scan\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># Record velocity, odometry, and laser scans into a timestamped folder\\nros2 bag record -o warehouse_trial_01 /cmd_vel /odom /scan</code></pre></div>\\n<h3 id=\\"32-record-with-mcap-format-and-duration-split\\">3.2 Record with MCAP Format and Duration Split</h3>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# Record with MCAP storage, splitting into new files every 120 seconds\\nros2 bag record -s mcap -d 120 -o patrol_run_mcap /cmd_vel /scan\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># Record with MCAP storage, splitting into new files every 120 seconds\\nros2 bag record -s mcap -d 120 -o patrol_run_mcap /cmd_vel /scan</code></pre></div>\\n<h3 id=\\"33-useful-recording-flags\\">3.3 Useful Recording Flags:</h3>\\n<ul class=\\"lesson-bullet-list\\">\\n<li><code class=\\"inline-code\\">-a</code> or <code class=\\"inline-code\\">--all</code>: Record every topic active on the DDS bus.</li>\\n<li><code class=\\"inline-code\\">-e &#x27;&lt;regex&gt;&#x27;</code>: Record topics matching regular expressions (e.g. <code class=\\"inline-code\\">-e &#x27;/navpro/.*&#x27;</code>).</li>\\n<li><code class=\\"inline-code\\">--max-bag-size &lt;bytes&gt;</code>: Split into a new bag file when current reaches size limit (e.g. <code class=\\"inline-code\\">1073741824</code> for 1GB).</li>\\n</ul>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-inspecting-bag-metadata\\">4. Inspecting Bag Metadata</h2>\\n<p>Inspect what was recorded using <code class=\\"inline-code\\">ros2 bag info</code>:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"ros2 bag info warehouse_trial_01\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">ros2 bag info warehouse_trial_01</code></pre></div>\\n<p><em>Expected Output:</em></p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"Files:             warehouse_trial_01/warehouse_trial_01_0.mcap\\nBag size:          14.2 MiB\\nStorage id:        mcap\\nDuration:          45.123s\\nStart:             Oct 13 2026 10:15:02.102 (1718204102.102)\\nEnd:               Oct 13 2026 10:15:47.225 (1718204147.225)\\nMessages:          2255\\nTopic information: \\n  Topic: /cmd_vel | Type: geometry_msgs/msg/Twist | Count: 450 | Serialization: cdr\\n  Topic: /odom    | Type: nav_msgs/msg/Odometry   | Count: 902 | Serialization: cdr\\n  Topic: /scan    | Type: sensor_msgs/msg/LaserScan | Count: 903 | Serialization: cdr\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">Files:             warehouse_trial_01/warehouse_trial_01_0.mcap\\nBag size:          14.2 MiB\\nStorage id:        mcap\\nDuration:          45.123s\\nStart:             Oct 13 2026 10:15:02.102 (1718204102.102)\\nEnd:               Oct 13 2026 10:15:47.225 (1718204147.225)\\nMessages:          2255\\nTopic information: \\n  Topic: /cmd_vel | Type: geometry_msgs/msg/Twist | Count: 450 | Serialization: cdr\\n  Topic: /odom    | Type: nav_msgs/msg/Odometry   | Count: 902 | Serialization: cdr\\n  Topic: /scan    | Type: sensor_msgs/msg/LaserScan | Count: 903 | Serialization: cdr</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-playback-simulating-the-physical-robot-offline\\">5. Playback: Simulating the Physical Robot Offline</h2>\\n<p>Playing back a bag file re-publishes the recorded messages onto the DDS bus with original timing, allowing you to test localization and navigation algorithms without needing the physical robot turned on!</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# Standard playback\\nros2 bag play warehouse_trial_01\\n\\n# Fast playback at 2x speed\\nros2 bag play warehouse_trial_01 --rate 2.0\\n\\n# Slow motion at 0.5x speed (useful for debugging obstacle avoidance)\\nros2 bag play warehouse_trial_01 --rate 0.5\\n\\n# Continuous loop playback\\nros2 bag play warehouse_trial_01 --loop\\n\\n# Remap topic during playback to avoid collisions with active hardware\\nros2 bag play warehouse_trial_01 --remap /cmd_vel:=/recorded_cmd_vel\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># Standard playback\\nros2 bag play warehouse_trial_01\\n\\n# Fast playback at 2x speed\\nros2 bag play warehouse_trial_01 --rate 2.0\\n\\n# Slow motion at 0.5x speed (useful for debugging obstacle avoidance)\\nros2 bag play warehouse_trial_01 --rate 0.5\\n\\n# Continuous loop playback\\nros2 bag play warehouse_trial_01 --loop\\n\\n# Remap topic during playback to avoid collisions with active hardware\\nros2 bag play warehouse_trial_01 --remap /cmd_vel:=/recorded_cmd_vel</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-offline-python-analysis-using-rosbag2_py\\">6. Offline Python Analysis using <code class=\\"inline-code\\">rosbag2_py</code></h2>\\n<p>You can write Python scripts to parse bags for post-mission telemetry analytics (e.g., maximum speed, total distance traveled):</p>\\n<p>Create file <code class=\\"inline-code\\">analyze_bag.py</code>:</p>\\n<div class=\\"code-container\\" data-language=\\"python\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">PYTHON</span><button class=\\"copy-code-btn\\" data-code=\\"#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nNavPro Learning Hub - Lesson 12\\nOffline Bag Reader: Iterates through recorded messages and computes total distance traveled.\\n&quot;&quot;&quot;\\n\\nimport sys\\nimport math\\nfrom rclpy.serialization import deserialize_message\\nfrom rosidl_runtime_py.utilities import get_message\\nimport rosbag2_py\\n\\n\\ndef analyze_odometry_bag(bag_path: str):\\n    reader = rosbag2_py.SequentialReader()\\n    storage_options = rosbag2_py.StorageOptions(uri=bag_path)\\n    converter_options = rosbag2_py.ConverterOptions(\\n        input_serialization_format=&#x27;cdr&#x27;,\\n        output_serialization_format=&#x27;cdr&#x27;\\n    )\\n    reader.open(storage_options, converter_options)\\n\\n    topic_types = reader.get_all_topics_and_types()\\n    type_map = {topic.name: topic.type for topic in topic_types}\\n\\n    total_distance = 0.0\\n    last_x, last_y = None, None\\n    msg_count = 0\\n\\n    print(f&quot;Reading bag file: {bag_path} ...&quot;)\\n\\n    while reader.has_next():\\n        topic_name, serialized_data, timestamp = reader.read_next()\\n        if topic_name == &#x27;/odom&#x27;:\\n            msg_type = get_message(type_map[topic_name])\\n            msg = deserialize_message(serialized_data, msg_type)\\n\\n            x = msg.pose.pose.position.x\\n            y = msg.pose.pose.position.y\\n\\n            if last_x is not None:\\n                dx = x - last_x\\n                dy = y - last_y\\n                step_dist = math.sqrt(dx*dx + dy*dy)\\n                total_distance += step_dist\\n\\n            last_x, last_y = x, y\\n            msg_count += 1\\n\\n    print(&quot;\\\\n--- Analytics Report ---&quot;)\\n    print(f&quot;Total Odometry Frames: {msg_count}&quot;)\\n    print(f&quot;Total Distance Traveled: {total_distance:.2f} meters&quot;)\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    if len(sys.argv) &lt; 2:\\n        print(&quot;Usage: python3 analyze_bag.py &lt;path_to_bag&gt;&quot;)\\n        sys.exit(1)\\n    analyze_odometry_bag(sys.argv[1])\\">📋 Copy</button></div><pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nNavPro Learning Hub - Lesson 12\\nOffline Bag Reader: Iterates through recorded messages and computes total distance traveled.\\n&quot;&quot;&quot;\\n\\nimport sys\\nimport math\\nfrom rclpy.serialization import deserialize_message\\nfrom rosidl_runtime_py.utilities import get_message\\nimport rosbag2_py\\n\\n\\ndef analyze_odometry_bag(bag_path: str):\\n    reader = rosbag2_py.SequentialReader()\\n    storage_options = rosbag2_py.StorageOptions(uri=bag_path)\\n    converter_options = rosbag2_py.ConverterOptions(\\n        input_serialization_format=&#x27;cdr&#x27;,\\n        output_serialization_format=&#x27;cdr&#x27;\\n    )\\n    reader.open(storage_options, converter_options)\\n\\n    topic_types = reader.get_all_topics_and_types()\\n    type_map = {topic.name: topic.type for topic in topic_types}\\n\\n    total_distance = 0.0\\n    last_x, last_y = None, None\\n    msg_count = 0\\n\\n    print(f&quot;Reading bag file: {bag_path} ...&quot;)\\n\\n    while reader.has_next():\\n        topic_name, serialized_data, timestamp = reader.read_next()\\n        if topic_name == &#x27;/odom&#x27;:\\n            msg_type = get_message(type_map[topic_name])\\n            msg = deserialize_message(serialized_data, msg_type)\\n\\n            x = msg.pose.pose.position.x\\n            y = msg.pose.pose.position.y\\n\\n            if last_x is not None:\\n                dx = x - last_x\\n                dy = y - last_y\\n                step_dist = math.sqrt(dx*dx + dy*dy)\\n                total_distance += step_dist\\n\\n            last_x, last_y = x, y\\n            msg_count += 1\\n\\n    print(&quot;\\\\n--- Analytics Report ---&quot;)\\n    print(f&quot;Total Odometry Frames: {msg_count}&quot;)\\n    print(f&quot;Total Distance Traveled: {total_distance:.2f} meters&quot;)\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    if len(sys.argv) &lt; 2:\\n        print(&quot;Usage: python3 analyze_bag.py &lt;path_to_bag&gt;&quot;)\\n        sys.exit(1)\\n    analyze_odometry_bag(sys.argv[1])</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"7-hands-on-student-challenge\\">7. Hands-on Student Challenge</h2>\\n<p><strong>Task:</strong></p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Start <code class=\\"inline-code\\">publisher_explained</code> from <code class=\\"inline-code\\">navpro_basics</code>.</li>\\n<li>Record 15 seconds of <code class=\\"inline-code\\">/cmd_vel</code> into a bag named <code class=\\"inline-code\\">my_vel_bag</code>.</li>\\n<li>Stop the publisher.</li>\\n<li>Play back <code class=\\"inline-code\\">my_vel_bag</code> while monitoring with <code class=\\"inline-code\\">ros2 topic echo /cmd_vel</code>.</li>\\n<li>Verify that the echoed output matches the original published stream!</li>\\n</ol>","quizzes":[{"id":"q_l1_12_1","prompt":"What is the modern default storage format for rosbag2 in ROS 2 Jazzy, and why is it preferred over sqlite3?","options":["CSV, because it opens directly in Excel","MCAP, because it provides zero-copy streaming, high write throughput, and self-contained schemas without SQLite write-lock overhead","JSON Lines, for web compatibility","Parquet, for cloud analytics"],"correct":1,"explanation":"MCAP is the modern robotics industry recording standard. It offers blazing write performance, schema self-description, and avoids SQLite transaction locking issues during heavy sensor logging."}],"has_quiz":true,"next_id":"lesson_13","prev_id":"lesson_11"},{"id":"lesson_13","num":13,"num_str":"13","title":"Complete ROS 2 Command-Line Interface (CLI) Mastery","slug":"ros2_cli_command_mastery","filename":"13_ros2_cli_command_mastery.md","module":"Advanced Communication Patterns","module_id":2,"duration":"45-60 min","focus":"Full CLI Tooling Reference, Inspection Workflows & Production Troubleshooting","snapshot":[],"html_content":"<h1 id=\\"lesson-13-complete-ros-2-command-line-interface-cli-mastery\\">Lesson 13: Complete ROS 2 Command-Line Interface (CLI) Mastery</h1>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Focus:</strong> Full CLI Tooling Reference, Inspection Workflows &amp; Production Troubleshooting<br><strong>Course Track:</strong> NavPro Learning Hub - Level 1 (Lecture 05)<br><strong>Target Environment:</strong> ROS 2 Jazzy Jalisco</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"1-overview--learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>The ROS 2 Command-Line Interface (<code class=\\"inline-code\\">ros2</code>) is an engineer&#x27;s Swiss Army knife for introspecting, testing, and debugging distributed robotics networks.</p>\\n<p>By the end of this lesson, you will:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Master all 10 core CLI command groups: <code class=\\"inline-code\\">node</code>, <code class=\\"inline-code\\">topic</code>, <code class=\\"inline-code\\">service</code>, <code class=\\"inline-code\\">param</code>, <code class=\\"inline-code\\">action</code>, <code class=\\"inline-code\\">interface</code>, <code class=\\"inline-code\\">bag</code>, <code class=\\"inline-code\\">pkg</code>, <code class=\\"inline-code\\">doctor</code>, and <code class=\\"inline-code\\">daemon</code>.</li>\\n<li>Diagnose and resolve real-world robotics anomalies (dropped messages, QoS mismatches, phantom nodes).</li>\\n<li>Use <code class=\\"inline-code\\">ros2 doctor</code> to audit your network, middleware, and operating system health.</li>\\n<li>Execute complex message injection and debugging directly from the terminal without writing one-off scripts.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-master-cli-reference-matrix\\">2. Master CLI Reference Matrix</h2>\\n<div class=\\"lesson-image-wrapper\\"><img src=\\"assets/images/ros2_cli_ecosystem.svg\\" alt=\\"ROS 2 CLI Command Ecosystem\\" class=\\"lesson-image\\" loading=\\"lazy\\"><span class=\\"image-caption\\">ROS 2 CLI Command Ecosystem</span></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-comprehensive-command-groups\\">3. Comprehensive Command Groups</h2>\\n<h3 id=\\"31-node-introspection-ros2-node\\">3.1 Node Introspection (<code class=\\"inline-code\\">ros2 node</code>)</h3>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# List all active nodes in the current ROS_DOMAIN_ID\\nros2 node list\\n\\n# Inspect all publishers, subscribers, services, and actions associated with a specific node\\nros2 node info /teleop_speed_limiter\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># List all active nodes in the current ROS_DOMAIN_ID\\nros2 node list\\n\\n# Inspect all publishers, subscribers, services, and actions associated with a specific node\\nros2 node info /teleop_speed_limiter</code></pre></div>\\n<h3 id=\\"32-topic-introspection--injection-ros2-topic\\">3.2 Topic Introspection &amp; Injection (<code class=\\"inline-code\\">ros2 topic</code>)</h3>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# List all active topics with their interface message types\\nros2 topic list -t\\n\\n# Inspect topic endpoints, subscriber count, and active QoS profiles\\nros2 topic info /cmd_vel --verbose\\n\\n# Echo live messages flowing through topic (prints formatted JSON/YAML to terminal)\\nros2 topic echo /cmd_vel\\n\\n# Measure exact publishing frequency in Hertz (Hz)\\nros2 topic hz /cmd_vel\\n\\n# Measure network bandwidth utilization (KB/s)\\nros2 topic bw /cmd_vel\\n\\n# Manually publish a single message from the terminal\\nros2 topic pub --once /cmd_vel geometry_msgs/msg/Twist &quot;{linear: {x: 0.2}, angular: {z: 0.0}}&quot;\\n\\n# Continuously publish at 10 Hz\\nros2 topic pub -r 10 /cmd_vel geometry_msgs/msg/Twist &quot;{linear: {x: 0.1}, angular: {z: 0.05}}&quot;\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># List all active topics with their interface message types\\nros2 topic list -t\\n\\n# Inspect topic endpoints, subscriber count, and active QoS profiles\\nros2 topic info /cmd_vel --verbose\\n\\n# Echo live messages flowing through topic (prints formatted JSON/YAML to terminal)\\nros2 topic echo /cmd_vel\\n\\n# Measure exact publishing frequency in Hertz (Hz)\\nros2 topic hz /cmd_vel\\n\\n# Measure network bandwidth utilization (KB/s)\\nros2 topic bw /cmd_vel\\n\\n# Manually publish a single message from the terminal\\nros2 topic pub --once /cmd_vel geometry_msgs/msg/Twist &quot;{linear: {x: 0.2}, angular: {z: 0.0}}&quot;\\n\\n# Continuously publish at 10 Hz\\nros2 topic pub -r 10 /cmd_vel geometry_msgs/msg/Twist &quot;{linear: {x: 0.1}, angular: {z: 0.05}}&quot;</code></pre></div>\\n<h3 id=\\"33-service-introspection--invocation-ros2-service\\">3.3 Service Introspection &amp; Invocation (<code class=\\"inline-code\\">ros2 service</code>)</h3>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# List all active service endpoints\\nros2 service list -t\\n\\n# Identify the .srv interface type used by a service\\nros2 service type /robot/set_autonomous_mode\\n\\n# Call a service with parameters directly from terminal\\nros2 service call /robot/set_autonomous_mode std_srvs/srv/SetBool &quot;{data: true}&quot;\\n\\n# Find all active services using a specific interface\\nros2 service find std_srvs/srv/Trigger\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># List all active service endpoints\\nros2 service list -t\\n\\n# Identify the .srv interface type used by a service\\nros2 service type /robot/set_autonomous_mode\\n\\n# Call a service with parameters directly from terminal\\nros2 service call /robot/set_autonomous_mode std_srvs/srv/SetBool &quot;{data: true}&quot;\\n\\n# Find all active services using a specific interface\\nros2 service find std_srvs/srv/Trigger</code></pre></div>\\n<h3 id=\\"34-dynamic-parameters-ros2-param\\">3.4 Dynamic Parameters (<code class=\\"inline-code\\">ros2 param</code>)</h3>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# List all parameters declared across all active nodes\\nros2 param list\\n\\n# Query current parameter value\\nros2 param get /parameterized_controller max_linear_speed\\n\\n# Dynamically modify a parameter at runtime\\nros2 param set /parameterized_controller max_linear_speed 0.85\\n\\n# Export live parameters of a node to a YAML backup file\\nros2 param dump /parameterized_controller &gt; backup_params.yaml\\n\\n# Load parameters from a YAML file into a running node\\nros2 param load /parameterized_controller backup_params.yaml\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># List all parameters declared across all active nodes\\nros2 param list\\n\\n# Query current parameter value\\nros2 param get /parameterized_controller max_linear_speed\\n\\n# Dynamically modify a parameter at runtime\\nros2 param set /parameterized_controller max_linear_speed 0.85\\n\\n# Export live parameters of a node to a YAML backup file\\nros2 param dump /parameterized_controller &gt; backup_params.yaml\\n\\n# Load parameters from a YAML file into a running node\\nros2 param load /parameterized_controller backup_params.yaml</code></pre></div>\\n<h3 id=\\"35-action-introspection-ros2-action\\">3.5 Action Introspection (<code class=\\"inline-code\\">ros2 action</code>)</h3>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# List all active action servers\\nros2 action list -t\\n\\n# Inspect action server and client count\\nros2 action info /patrol_robot\\n\\n# Send an action goal from terminal and display real-time feedback\\nros2 action send_goal /patrol_robot navpro_interfaces/action/Patrol &quot;{loop_count: 2}&quot; --feedback\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># List all active action servers\\nros2 action list -t\\n\\n# Inspect action server and client count\\nros2 action info /patrol_robot\\n\\n# Send an action goal from terminal and display real-time feedback\\nros2 action send_goal /patrol_robot navpro_interfaces/action/Patrol &quot;{loop_count: 2}&quot; --feedback</code></pre></div>\\n<h3 id=\\"36-interface-definitions-ros2-interface\\">3.6 Interface Definitions (<code class=\\"inline-code\\">ros2 interface</code>)</h3>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# Display the exact fields and comments of any message or service definition\\nros2 interface show geometry_msgs/msg/Twist\\n\\n# Output a template JSON payload for testing\\nros2 interface proto geometry_msgs/msg/Twist\\n\\n# List all interfaces provided by a package\\nros2 interface package navpro_interfaces\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># Display the exact fields and comments of any message or service definition\\nros2 interface show geometry_msgs/msg/Twist\\n\\n# Output a template JSON payload for testing\\nros2 interface proto geometry_msgs/msg/Twist\\n\\n# List all interfaces provided by a package\\nros2 interface package navpro_interfaces</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-advanced-debugging--recovery-tools\\">4. Advanced Debugging &amp; Recovery Tools</h2>\\n<h3 id=\\"41-system-auditing-with-ros2-doctor\\">4.1 System Auditing with <code class=\\"inline-code\\">ros2 doctor</code></h3>\\n<p><code class=\\"inline-code\\">ros2 doctor</code> scans your network interfaces, environment variables, DDS configuration, and computational graph for anomalies:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# Run quick health audit\\nros2 doctor\\n\\n# Generate comprehensive markdown diagnostic report\\nros2 doctor --report\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># Run quick health audit\\nros2 doctor\\n\\n# Generate comprehensive markdown diagnostic report\\nros2 doctor --report</code></pre></div>\\n<p><em>Detects: Unmatched topic publishers with no subscribers, missing environment variables, conflicting DDS settings, and network MTU issues.</em></p>\\n<h3 id=\\"42-resetting-the-ros-2-daemon-ros2-daemon\\">4.2 Resetting the ROS 2 Daemon (<code class=\\"inline-code\\">ros2 daemon</code>)</h3>\\n<p>ROS 2 runs a background caching daemon to accelerate CLI queries. If you kill terminals forcefully, old &quot;ghost&quot; nodes may linger in <code class=\\"inline-code\\">ros2 node list</code>.</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# Check daemon status\\nros2 daemon status\\n\\n# Restart the discovery cache daemon\\nros2 daemon stop\\nros2 daemon start\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># Check daemon status\\nros2 daemon status\\n\\n# Restart the discovery cache daemon\\nros2 daemon stop\\nros2 daemon start</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-real-world-troubleshooting-guide\\">5. Real-World Troubleshooting Guide</h2>\\n<h3 id=\\"issue-1-ros2-topic-echo-displays-nothing-but-node-is-running\\">Issue 1: <code class=\\"inline-code\\">ros2 topic echo</code> displays nothing, but node is running</h3>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Run <code class=\\"inline-code\\">ros2 topic info /topic_name --verbose</code>.</li>\\n<li>Check if Publisher and Subscriber have <strong>QoS Mismatch</strong> (e.g. Publisher is <code class=\\"inline-code\\">BEST_EFFORT</code>, but subscriber requested <code class=\\"inline-code\\">RELIABLE</code>).</li>\\n<li>Check if nodes are on different <code class=\\"inline-code\\">ROS_DOMAIN_ID</code>s: <code class=\\"inline-code\\">echo $ROS_DOMAIN_ID</code>.</li>\\n</ol>\\n<h3 id=\\"issue-2-package-not-found-after-building\\">Issue 2: <code class=\\"inline-code\\">Package not found</code> after building</h3>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Did you run <code class=\\"inline-code\\">source install/setup.bash</code> in the current terminal?</li>\\n<li>Did you create the empty marker file inside <code class=\\"inline-code\\">resource/&lt;package_name&gt;</code>?</li>\\n<li>Check <code class=\\"inline-code\\">setup.py</code> <code class=\\"inline-code\\">data_files</code> to ensure the resource directory was registered.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-hands-on-student-challenge\\">6. Hands-on Student Challenge</h2>\\n<p><strong>Task:</strong></p>\\n<p>Without looking at any source code:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Start <code class=\\"inline-code\\">sim_world.launch.py</code> from <code class=\\"inline-code\\">navpro_gazebo</code>.</li>\\n<li>Use CLI commands to find the exact message type of <code class=\\"inline-code\\">/scan</code>.</li>\\n<li>Measure the publishing rate (Hz) of <code class=\\"inline-code\\">/scan</code>.</li>\\n<li>Publish a <code class=\\"inline-code\\">/cmd_vel</code> message that commands the robot to rotate in place at <code class=\\"inline-code\\">0.5 rad/s</code>.</li>\\n<li>Verify in Gazebo that the robot turns!</li>\\n</ol>","quizzes":[{"id":"q_l1_13_1","prompt":"Which CLI command allows you to inspect message transmission frequency on a topic in real-time?","options":["ros2 topic hz /scan","ros2 topic echo /scan --speed","ros2 topic rate /scan","ros2 doctor --topic /scan"],"correct":0,"explanation":"'ros2 topic hz <topic>' monitors message arrival timestamps and calculates the moving average frequency (Hz), minimum, and maximum delta."}],"has_quiz":true,"next_id":"lesson_14","prev_id":"lesson_12"},{"id":"lesson_14","num":14,"num_str":"14","title":"TF2 Spatial Coordinate Transformations in Python","slug":"tf2_coordinate_transformations_python","filename":"14_tf2_coordinate_transformations_python.md","module":"Kinematics, TF2 & Computer Vision","module_id":3,"duration":"45-60 min","focus":"Coordinate Frames, REP-105 Standards, Euler-to-Quaternion Math & TF Broadcasters/Listeners","snapshot":[],"html_content":"<h1 id=\\"lesson-14-tf2-spatial-coordinate-transformations-in-python\\">Lesson 14: TF2 Spatial Coordinate Transformations in Python</h1>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Focus:</strong> Coordinate Frames, REP-105 Standards, Euler-to-Quaternion Math &amp; TF Broadcasters/Listeners<br><strong>Course Track:</strong> NavPro Learning Hub - Level 1 (Lecture 08 &amp; Day 2)<br><strong>Target Environment:</strong> ROS 2 Jazzy Jalisco</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"1-overview--learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>A robot has many sensors mounted at different locations and orientations: a 2D LiDAR 15cm above the floor, a depth camera angled downward at 15 degrees, and two drive wheels in contact with the ground. When the LiDAR detects an obstacle 2 meters away, the path planner needs to know: <strong>Where is this obstacle relative to the center of the robot chassis, and where is it in the global warehouse map?</strong></p>\\n<p>The <strong>TF2 (Transform 2)</strong> library tracks coordinate frames over time and allows seamless spatial transformations across kinematic chains.</p>\\n<p>By the end of this lesson, you will:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Understand the robotics standard <strong>REP-105</strong> frame hierarchy (<code class=\\"inline-code\\">map -&gt; odom -&gt; base_footprint -&gt; base_link -&gt; laser_frame</code>).</li>\\n<li>Master 3D spatial rotation mathematics: Euler Angles (Roll, Pitch, Yaw) vs. Quaternions ($x, y, z, w$).</li>\\n<li>Write a Python <strong>Static Transform Broadcaster</strong> for fixed physical sensor mounts.</li>\\n<li>Write a Python <strong>Dynamic Transform Broadcaster</strong> to track real-time robot odometry.</li>\\n<li>Write a Python <strong>Transform Listener</strong> using <code class=\\"inline-code\\">Buffer.lookup_transform()</code>.</li>\\n<li>Inspect and debug transform trees using <code class=\\"inline-code\\">view_frames</code>, <code class=\\"inline-code\\">tf2_echo</code>, and RViz2.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-standard-frame-hierarchy-rep-105\\">2. Standard Frame Hierarchy: REP-105</h2>\\n<p>ROS standard <code class=\\"inline-code\\">REP-105</code> defines four primary coordinate frames for all mobile robots:</p>\\n<div class=\\"lesson-image-wrapper\\"><img src=\\"assets/images/tf2_tree_pipeline.svg\\" alt=\\"REP-105 Robot Spatial TF2 Transform Tree\\" class=\\"lesson-image\\" loading=\\"lazy\\"><span class=\\"image-caption\\">REP-105 Robot Spatial TF2 Transform Tree</span></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-spatial-math-euler-angles-vs-quaternions\\">3. Spatial Math: Euler Angles vs. Quaternions</h2>\\n<p>Humans think in <strong>Euler Angles</strong>:</p>\\n<ul class=\\"lesson-bullet-list\\">\\n<li><strong>Roll ($\\\\phi$):</strong> Rotation around X axis (tilting side-to-side).</li>\\n<li><strong>Pitch ($\\\\theta$):</strong> Rotation around Y axis (tilting up and down).</li>\\n<li><strong>Yaw ($\\\\psi$):</strong> Rotation around Z axis (heading/steering direction on the 2D floor).</li>\\n</ul>\\n<h3 id=\\"why-robots-use-quaternions\\">Why Robots Use Quaternions:</h3>\\n<p>Euler angles suffer from <strong>Gimbal Lock</strong> (loss of one degree of freedom when pitch reaches $\\\\pm 90^\\\\circ$). Computers and ROS 2 use <strong>Quaternions</strong>—four-dimensional unit vectors:</p>\\n<p>$$\\\\mathbf{q} = (x, y, z, w)$$</p>\\n<p>For planar mobile robots moving purely on a flat warehouse floor ($Roll = 0, Pitch = 0, Yaw = \\\\theta$):</p>\\n<p>$$x = 0.0, \\\\quad y = 0.0, \\\\quad z = \\\\sin(\\\\theta / 2), \\\\quad w = \\\\cos(\\\\theta / 2)$$</p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-step-by-step-writing-a-static-transform-broadcaster\\">4. Step-by-Step: Writing a Static Transform Broadcaster</h2>\\n<p>Static transforms represent rigid attachments that never move relative to the robot chassis (e.g. the LiDAR sensor bracket).</p>\\n<p>Create file <code class=\\"inline-code\\">static_broadcaster.py</code>:</p>\\n<div class=\\"code-container\\" data-language=\\"python\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">PYTHON</span><button class=\\"copy-code-btn\\" data-code=\\"#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nNavPro Learning Hub - Lesson 14\\nStatic Transform Broadcaster: Publishes fixed LiDAR sensor offset from base_link.\\n&quot;&quot;&quot;\\n\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom geometry_msgs.msg import TransformStamped\\nfrom tf2_ros import StaticTransformBroadcaster\\n\\n\\nclass StaticFramePublisher(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;static_frame_publisher&#x27;)\\n        self.broadcaster_ = StaticTransformBroadcaster(self)\\n\\n        tf_msg = TransformStamped()\\n        tf_msg.header.stamp = self.get_clock().now().to_msg()\\n        tf_msg.header.frame_id = &#x27;base_link&#x27;        # Parent frame\\n        tf_msg.child_frame_id = &#x27;laser_frame&#x27;       # Child frame\\n\\n        # Physical mount offset: 8cm forward (+X), 16cm up (+Z)\\n        tf_msg.transform.translation.x = 0.08\\n        tf_msg.transform.translation.y = 0.0\\n        tf_msg.transform.translation.z = 0.16\\n\\n        # Zero rotation (facing forward)\\n        tf_msg.transform.rotation.x = 0.0\\n        tf_msg.transform.rotation.y = 0.0\\n        tf_msg.transform.rotation.z = 0.0\\n        tf_msg.transform.rotation.w = 1.0\\n\\n        # Broadcast static transform\\n        self.broadcaster_.sendTransform(tf_msg)\\n        self.get_logger().info(&#x27;Broadcasted static transform: base_link -&gt; laser_frame&#x27;)\\n\\n\\ndef main():\\n    rclpy.init()\\n    node = StaticFramePublisher()\\n    try:\\n        rclpy.spin(node)\\n    finally:\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\">📋 Copy</button></div><pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nNavPro Learning Hub - Lesson 14\\nStatic Transform Broadcaster: Publishes fixed LiDAR sensor offset from base_link.\\n&quot;&quot;&quot;\\n\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom geometry_msgs.msg import TransformStamped\\nfrom tf2_ros import StaticTransformBroadcaster\\n\\n\\nclass StaticFramePublisher(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;static_frame_publisher&#x27;)\\n        self.broadcaster_ = StaticTransformBroadcaster(self)\\n\\n        tf_msg = TransformStamped()\\n        tf_msg.header.stamp = self.get_clock().now().to_msg()\\n        tf_msg.header.frame_id = &#x27;base_link&#x27;        # Parent frame\\n        tf_msg.child_frame_id = &#x27;laser_frame&#x27;       # Child frame\\n\\n        # Physical mount offset: 8cm forward (+X), 16cm up (+Z)\\n        tf_msg.transform.translation.x = 0.08\\n        tf_msg.transform.translation.y = 0.0\\n        tf_msg.transform.translation.z = 0.16\\n\\n        # Zero rotation (facing forward)\\n        tf_msg.transform.rotation.x = 0.0\\n        tf_msg.transform.rotation.y = 0.0\\n        tf_msg.transform.rotation.z = 0.0\\n        tf_msg.transform.rotation.w = 1.0\\n\\n        # Broadcast static transform\\n        self.broadcaster_.sendTransform(tf_msg)\\n        self.get_logger().info(&#x27;Broadcasted static transform: base_link -&gt; laser_frame&#x27;)\\n\\n\\ndef main():\\n    rclpy.init()\\n    node = StaticFramePublisher()\\n    try:\\n        rclpy.spin(node)\\n    finally:\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-step-by-step-writing-a-dynamic-transform-broadcaster\\">5. Step-by-Step: Writing a Dynamic Transform Broadcaster</h2>\\n<p>Dynamic transforms update continuously as the robot moves through the world (e.g. <code class=\\"inline-code\\">odom -&gt; base_footprint</code>).</p>\\n<p>Create file <code class=\\"inline-code\\">dynamic_broadcaster.py</code>:</p>\\n<div class=\\"code-container\\" data-language=\\"python\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">PYTHON</span><button class=\\"copy-code-btn\\" data-code=\\"#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nNavPro Learning Hub - Lesson 14\\nDynamic Transform Broadcaster: Integrates forward motion and broadcasts odom -&gt; base_footprint at 20Hz.\\n&quot;&quot;&quot;\\n\\nimport math\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom geometry_msgs.msg import TransformStamped\\nfrom tf2_ros import TransformBroadcaster\\n\\n\\nclass DynamicOdometryBroadcaster(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;dynamic_odometry_broadcaster&#x27;)\\n        self.broadcaster_ = TransformBroadcaster(self)\\n\\n        # Robot planar pose state\\n        self.x = 0.0\\n        self.y = 0.0\\n        self.yaw = 0.0\\n        self.linear_velocity = 0.2    # m/s forward\\n        self.angular_velocity = 0.1   # rad/s turning\\n\\n        self.last_time = self.get_clock().now()\\n        # 20 Hz broadcast loop (0.05s)\\n        self.timer_ = self.create_timer(0.05, self.broadcast_odometry_transform)\\n\\n    def broadcast_odometry_transform(self):\\n        current_time = self.get_clock().now()\\n        dt = (current_time - self.last_time).nanoseconds / 1e9\\n        self.last_time = current_time\\n\\n        # Numerical integration of differential drive motion\\n        self.x += self.linear_velocity * math.cos(self.yaw) * dt\\n        self.y += self.linear_velocity * math.sin(self.yaw) * dt\\n        self.yaw += self.angular_velocity * dt\\n\\n        tf_msg = TransformStamped()\\n        tf_msg.header.stamp = current_time.to_msg()\\n        tf_msg.header.frame_id = &#x27;odom&#x27;\\n        tf_msg.child_frame_id = &#x27;base_footprint&#x27;\\n\\n        tf_msg.transform.translation.x = self.x\\n        tf_msg.transform.translation.y = self.y\\n        tf_msg.transform.translation.z = 0.0\\n\\n        # Planar quaternion from yaw\\n        tf_msg.transform.rotation.x = 0.0\\n        tf_msg.transform.rotation.y = 0.0\\n        tf_msg.transform.rotation.z = math.sin(self.yaw / 2.0)\\n        tf_msg.transform.rotation.w = math.cos(self.yaw / 2.0)\\n\\n        self.broadcaster_.sendTransform(tf_msg)\\n\\n\\ndef main():\\n    rclpy.init()\\n    node = DynamicOdometryBroadcaster()\\n    try:\\n        rclpy.spin(node)\\n    finally:\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\">📋 Copy</button></div><pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nNavPro Learning Hub - Lesson 14\\nDynamic Transform Broadcaster: Integrates forward motion and broadcasts odom -&gt; base_footprint at 20Hz.\\n&quot;&quot;&quot;\\n\\nimport math\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom geometry_msgs.msg import TransformStamped\\nfrom tf2_ros import TransformBroadcaster\\n\\n\\nclass DynamicOdometryBroadcaster(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;dynamic_odometry_broadcaster&#x27;)\\n        self.broadcaster_ = TransformBroadcaster(self)\\n\\n        # Robot planar pose state\\n        self.x = 0.0\\n        self.y = 0.0\\n        self.yaw = 0.0\\n        self.linear_velocity = 0.2    # m/s forward\\n        self.angular_velocity = 0.1   # rad/s turning\\n\\n        self.last_time = self.get_clock().now()\\n        # 20 Hz broadcast loop (0.05s)\\n        self.timer_ = self.create_timer(0.05, self.broadcast_odometry_transform)\\n\\n    def broadcast_odometry_transform(self):\\n        current_time = self.get_clock().now()\\n        dt = (current_time - self.last_time).nanoseconds / 1e9\\n        self.last_time = current_time\\n\\n        # Numerical integration of differential drive motion\\n        self.x += self.linear_velocity * math.cos(self.yaw) * dt\\n        self.y += self.linear_velocity * math.sin(self.yaw) * dt\\n        self.yaw += self.angular_velocity * dt\\n\\n        tf_msg = TransformStamped()\\n        tf_msg.header.stamp = current_time.to_msg()\\n        tf_msg.header.frame_id = &#x27;odom&#x27;\\n        tf_msg.child_frame_id = &#x27;base_footprint&#x27;\\n\\n        tf_msg.transform.translation.x = self.x\\n        tf_msg.transform.translation.y = self.y\\n        tf_msg.transform.translation.z = 0.0\\n\\n        # Planar quaternion from yaw\\n        tf_msg.transform.rotation.x = 0.0\\n        tf_msg.transform.rotation.y = 0.0\\n        tf_msg.transform.rotation.z = math.sin(self.yaw / 2.0)\\n        tf_msg.transform.rotation.w = math.cos(self.yaw / 2.0)\\n\\n        self.broadcaster_.sendTransform(tf_msg)\\n\\n\\ndef main():\\n    rclpy.init()\\n    node = DynamicOdometryBroadcaster()\\n    try:\\n        rclpy.spin(node)\\n    finally:\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-step-by-step-writing-a-transform-listener\\">6. Step-by-Step: Writing a Transform Listener</h2>\\n<p>A Transform Listener queries the transform buffer to compute coordinates across multi-hop frames:</p>\\n<div class=\\"code-container\\" data-language=\\"python\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">PYTHON</span><button class=\\"copy-code-btn\\" data-code=\\"#!/usr/bin/env python3\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom tf2_ros import Buffer, TransformListener\\nfrom tf2_ros import LookupException, ConnectivityException, ExtrapolationException\\n\\n\\nclass TransformQueryNode(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;transform_query_node&#x27;)\\n        self.tf_buffer = Buffer()\\n        self.tf_listener = TransformListener(self.tf_buffer, self)\\n        self.timer = self.create_timer(1.0, self.query_pose)\\n\\n    def query_pose(self):\\n        try:\\n            # Query the position of laser_frame relative to the global odom origin\\n            # Target frame: &#x27;odom&#x27;, Source frame: &#x27;laser_frame&#x27;, Time: Time(0) = latest available\\n            t = self.tf_buffer.lookup_transform(\\n                &#x27;odom&#x27;,\\n                &#x27;laser_frame&#x27;,\\n                rclpy.time.Time()\\n            )\\n            pos = t.transform.translation\\n            self.get_logger().info(f&#x27;LiDAR in Odom frame -&gt; x={pos.x:.2f}, y={pos.y:.2f}, z={pos.z:.2f}&#x27;)\\n        except (LookupException, ConnectivityException, ExtrapolationException) as e:\\n            self.get_logger().warn(f&#x27;Could not transform odom to laser_frame: {e}&#x27;)\\">📋 Copy</button></div><pre><code class=\\"language-python\\">#!/usr/bin/env python3\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom tf2_ros import Buffer, TransformListener\\nfrom tf2_ros import LookupException, ConnectivityException, ExtrapolationException\\n\\n\\nclass TransformQueryNode(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;transform_query_node&#x27;)\\n        self.tf_buffer = Buffer()\\n        self.tf_listener = TransformListener(self.tf_buffer, self)\\n        self.timer = self.create_timer(1.0, self.query_pose)\\n\\n    def query_pose(self):\\n        try:\\n            # Query the position of laser_frame relative to the global odom origin\\n            # Target frame: &#x27;odom&#x27;, Source frame: &#x27;laser_frame&#x27;, Time: Time(0) = latest available\\n            t = self.tf_buffer.lookup_transform(\\n                &#x27;odom&#x27;,\\n                &#x27;laser_frame&#x27;,\\n                rclpy.time.Time()\\n            )\\n            pos = t.transform.translation\\n            self.get_logger().info(f&#x27;LiDAR in Odom frame -&gt; x={pos.x:.2f}, y={pos.y:.2f}, z={pos.z:.2f}&#x27;)\\n        except (LookupException, ConnectivityException, ExtrapolationException) as e:\\n            self.get_logger().warn(f&#x27;Could not transform odom to laser_frame: {e}&#x27;)</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"7-inspection--visual-debugging-tools\\">7. Inspection &amp; Visual Debugging Tools</h2>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# 1. Echo live transform translation and quaternion values in terminal\\nros2 run tf2_ros tf2_echo odom laser_frame\\n\\n# 2. Generate a visual PDF tree diagram of all active frames\\nros2 run tf2_tools view_frames\\n# Generates: frames.pdf\\nevince frames.pdf  # View PDF in Ubuntu\\n\\n# 3. Monitor in RViz2:\\n# In RViz2, add the &quot;TF&quot; display plugin and check &quot;Show Arrows&quot; and &quot;Show Names&quot;\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># 1. Echo live transform translation and quaternion values in terminal\\nros2 run tf2_ros tf2_echo odom laser_frame\\n\\n# 2. Generate a visual PDF tree diagram of all active frames\\nros2 run tf2_tools view_frames\\n# Generates: frames.pdf\\nevince frames.pdf  # View PDF in Ubuntu\\n\\n# 3. Monitor in RViz2:\\n# In RViz2, add the &quot;TF&quot; display plugin and check &quot;Show Arrows&quot; and &quot;Show Names&quot;</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"8-hands-on-student-challenge\\">8. Hands-on Student Challenge</h2>\\n<p><strong>Task:</strong></p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>In <code class=\\"inline-code\\">static_broadcaster.py</code>, add a second static transform: <code class=\\"inline-code\\">base_link</code> -&gt; <code class=\\"inline-code\\">camera_link</code> (offset: $x=0.15, y=0.0, z=0.25$, facing forward).</li>\\n<li>Run both the static broadcaster and the dynamic odometry broadcaster.</li>\\n<li>Use <code class=\\"inline-code\\">ros2 run tf2_ros tf2_echo odom camera_link</code> to verify that the listener automatically resolves the multi-hop transformation: <code class=\\"inline-code\\">odom -&gt; base_footprint -&gt; base_link -&gt; camera_link</code>!</li>\\n</ol>","quizzes":[{"id":"q_l1_14_1","prompt":"According to REP-105 (Mobile Robot Coordinate Frames), which frame represents continuous smooth odometric estimation without discrete jumps?","options":["map","odom","base_link","base_footprint"],"correct":1,"explanation":"The 'odom' frame is continuous and smooth, ideal for short-term control. The 'map' frame represents global SLAM/AMCL localization and may experience discrete jumps during loop closures."}],"has_quiz":true,"next_id":"lesson_15","prev_id":"lesson_13"},{"id":"lesson_15","num":15,"num_str":"15","title":"Distributed ROS 2, Multi-Robot Fleets & DDS Networking","slug":"distributed_ros2_and_dds_networking","filename":"15_distributed_ros2_and_dds_networking.md","module":"Kinematics, TF2 & Computer Vision","module_id":3,"duration":"45-60 min","focus":"DDS Discovery Protocols, \`ROS_DOMAIN_ID\` Isolation, CycloneDDS vs FastDDS & Fleet Architecture","snapshot":[],"html_content":"<h1 id=\\"lesson-15-distributed-ros-2-multi-robot-fleets--dds-networking\\">Lesson 15: Distributed ROS 2, Multi-Robot Fleets &amp; DDS Networking</h1>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Focus:</strong> DDS Discovery Protocols, <code class=\\"inline-code\\">ROS_DOMAIN_ID</code> Isolation, CycloneDDS vs FastDDS &amp; Fleet Architecture<br><strong>Course Track:</strong> NavPro Learning Hub - Level 1 (Lecture 07)<br><strong>Target Environment:</strong> ROS 2 Jazzy Jalisco</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"1-overview--learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>One of the greatest superpowers of ROS 2 is native distributed computing. Two physical computers, a Raspberry Pi on a robot chassis, an edge AI compute box, and a ground control station PC connected to the same local network can communicate seamlessly without running a central server (<code class=\\"inline-code\\">roscore</code>).</p>\\n<p>However, without proper network configuration, <strong>every student in a classroom or every AMR in a warehouse will discover and steer each other&#x27;s robots!</strong></p>\\n<p>By the end of this lesson, you will:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Understand the DDS Simple Participant Discovery Protocol (SPDP) over UDP multicast.</li>\\n<li>Master network segmentation using the <code class=\\"inline-code\\">ROS_DOMAIN_ID</code> environment variable.</li>\\n<li>Understand the mathematical UDP port assignment schema used by DDS vendors.</li>\\n<li>Compare and switch RMW middleware implementations: <strong>eProsima FastDDS</strong> vs. <strong>Eclipse CycloneDDS</strong>.</li>\\n<li>Configure a <strong>Discovery Server</strong> for large fleets operating on restricted enterprise Wi-Fi networks.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-how-dds-discovers-nodes-multicast-protocol\\">2. How DDS Discovers Nodes: Multicast Protocol</h2>\\n<p>When a ROS 2 node boots up:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>It sends periodic <strong>UDP Multicast</strong> announcement packets to standard IP address <code class=\\"inline-code\\">239.255.0.1</code>.</li>\\n<li>Any other ROS 2 node listening on the same subnet receives the packet and extracts the node&#x27;s topics, types, and QoS profiles.</li>\\n<li>The nodes establish direct <strong>peer-to-peer unicast UDP connections</strong> for high-speed message transfer.</li>\\n</ol>\\n<div class=\\"lesson-image-wrapper\\"><img src=\\"assets/images/dds_discovery_domains.svg\\" alt=\\"DDS Multicast Discovery Bus &amp; Domain Isolation\\" class=\\"lesson-image\\" loading=\\"lazy\\"><span class=\\"image-caption\\">DDS Multicast Discovery Bus &amp; Domain Isolation</span></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-network-isolation-with-ros_domain_id\\">3. Network Isolation with <code class=\\"inline-code\\">ROS_DOMAIN_ID</code></h2>\\n<p>To isolate your robot from other robots on the same Wi-Fi network, set a unique integer ID between <code class=\\"inline-code\\">0</code> and <code class=\\"inline-code\\">101</code>:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"export ROS_DOMAIN_ID=42\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">export ROS_DOMAIN_ID=42</code></pre></div>\\n<h3 id=\\"the-dds-udp-port-assignment-formula\\">The DDS UDP Port Assignment Formula:</h3>\\n<p>DDS calculates its operating UDP network ports deterministically from the Domain ID:</p>\\n<p>$$\\\\text{Multicast Port} = 7400 + (250 \\\\times \\\\text{Domain ID})$$</p>\\n<p>$$\\\\text{Unicast Port} = 7410 + (250 \\\\times \\\\text{Domain ID}) + (2 \\\\times \\\\text{Participant ID})$$</p>\\n<p><em>For <code class=\\"inline-code\\">ROS_DOMAIN_ID = 0</code>: Multicast Port = 7400.</em></p>\\n<p><em>For <code class=\\"inline-code\\">ROS_DOMAIN_ID = 42</code>: Multicast Port = $7400 + (250 \\\\times 42) = 17900$.</em></p>\\n<p>Because the operating system routes network traffic by port number, nodes on <code class=\\"inline-code\\">DOMAIN_ID=42</code> can never hear or interfere with nodes on <code class=\\"inline-code\\">DOMAIN_ID=0</code>.</p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-middleware-selection-fastdds-vs-cyclonedds\\">4. Middleware Selection: FastDDS vs. CycloneDDS</h2>\\n<p>ROS 2 communicates via an abstraction layer called <strong>RMW (ROS Middleware)</strong>. You can change the underlying DDS implementation without modifying a single line of your Python code!</p>\\n<div class=\\"table-wrapper\\"><table>\\n<thead><tr>\\n<th>Feature</th>\\n<th>eProsima FastDDS (Default)</th>\\n<th>Eclipse CycloneDDS</th>\\n</tr></thead><tbody>\\n<tr>\\n<td><strong>Default in ROS 2</strong></td>\\n<td>Yes</td>\\n<td>No (requires package install)</td>\\n</tr>\\n<tr>\\n<td><strong>Wi-Fi Loss Resilience</strong></td>\\n<td>Moderate (tuned for high throughput)</td>\\n<td><strong>Superior</strong> (highly robust in noisy/lossy wireless networks)</td>\\n</tr>\\n<tr>\\n<td><strong>Discovery Mechanism</strong></td>\\n<td>Multicast or Discovery Server</td>\\n<td>Multicast or Peered Unicast</td>\\n</tr>\\n<tr>\\n<td><strong>Configuration</strong></td>\\n<td>Complex XML profiles</td>\\n<td>Clean, lightweight XML (<code class=\\"inline-code\\">cyclonedds.xml</code>)</td>\\n</tr>\\n</tbody></table></div>\\n<h3 id=\\"switching-to-cyclonedds\\">Switching to CycloneDDS:</h3>\\n<p>Install the RMW package:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"sudo apt install -y ros-jazzy-rmw-cyclonedds-cpp\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">sudo apt install -y ros-jazzy-rmw-cyclonedds-cpp</code></pre></div>\\n<p>Set the environment variable in your terminal or <code class=\\"inline-code\\">~/.bashrc</code>:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"export RMW_IMPLEMENTATION=rmw_cyclonedds_cpp\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">export RMW_IMPLEMENTATION=rmw_cyclonedds_cpp</code></pre></div>\\n<p>Verify which middleware is currently active:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"echo $RMW_IMPLEMENTATION\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">echo $RMW_IMPLEMENTATION</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-enterprise-fleets-the-fastdds-discovery-server\\">5. Enterprise Fleets: The FastDDS Discovery Server</h2>\\n<p>In enterprise warehouses with 50+ AMRs, UDP multicast can flood and crash corporate Wi-Fi access points. To solve this, ROS 2 supports a <strong>Discovery Server</strong> where nodes connect directly to a designated static IP address using unicast.</p>\\n<div class=\\"lesson-image-wrapper\\"><img src=\\"assets/images/fastdds_discovery_server.svg\\" alt=\\"FastDDS Discovery Server Architecture\\" class=\\"lesson-image\\" loading=\\"lazy\\"><span class=\\"image-caption\\">FastDDS Discovery Server Architecture</span></div>\\n<h3 id=\\"starting-a-discovery-server\\">Starting a Discovery Server:</h3>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"fastdds discovery -i 0 -l 192.168.1.100 -p 11811\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">fastdds discovery -i 0 -l 192.168.1.100 -p 11811</code></pre></div>\\n<h3 id=\\"directing-nodes-to-use-the-discovery-server\\">Directing Nodes to Use the Discovery Server:</h3>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"export ROS_DISCOVERY_SERVER=&quot;192.168.1.100:11811&quot;\\nros2 run navpro_basics publisher_explained\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">export ROS_DISCOVERY_SERVER=&quot;192.168.1.100:11811&quot;\\nros2 run navpro_basics publisher_explained</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-multi-robot-collaboration-via-namespacing\\">6. Multi-Robot Collaboration via Namespacing</h2>\\n<p>When running multiple robots that share a fleet coordinator on the same <code class=\\"inline-code\\">ROS_DOMAIN_ID</code>, wrap each robot in a unique <strong>Namespace</strong>:</p>\\n<h3 id=\\"robot-alpha-launch\\">Robot Alpha Launch:</h3>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"ros2 launch navpro_gazebo sim_world.launch.py robot_ns:=amr_01\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">ros2 launch navpro_gazebo sim_world.launch.py robot_ns:=amr_01</code></pre></div>\\n<p><em>Creates topics:</em> <code class=\\"inline-code\\">/amr_01/cmd_vel</code>, <code class=\\"inline-code\\">/amr_01/odom</code>, <code class=\\"inline-code\\">/amr_01/scan</code>.</p>\\n<h3 id=\\"robot-bravo-launch\\">Robot Bravo Launch:</h3>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"ros2 launch navpro_gazebo sim_world.launch.py robot_ns:=amr_02\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">ros2 launch navpro_gazebo sim_world.launch.py robot_ns:=amr_02</code></pre></div>\\n<p><em>Creates topics:</em> <code class=\\"inline-code\\">/amr_02/cmd_vel</code>, <code class=\\"inline-code\\">/amr_02/odom</code>, <code class=\\"inline-code\\">/amr_02/scan</code>.</p>\\n<p>The central fleet server subscribes to <code class=\\"inline-code\\">/amr_01/odom</code> and <code class=\\"inline-code\\">/amr_02/odom</code> simultaneously without topic collision!</p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"7-hands-on-student-challenge\\">7. Hands-on Student Challenge</h2>\\n<p><strong>Task:</strong></p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Open two terminals.</li>\\n<li>In Terminal 1, set <code class=\\"inline-code\\">export ROS_DOMAIN_ID=10</code> and start <code class=\\"inline-code\\">publisher_explained</code>.</li>\\n<li>In Terminal 2, set <code class=\\"inline-code\\">export ROS_DOMAIN_ID=20</code> and run <code class=\\"inline-code\\">ros2 topic list</code>.</li>\\n<li>Verify that Terminal 2 cannot see <code class=\\"inline-code\\">/cmd_vel</code>!</li>\\n<li>In Terminal 2, change to <code class=\\"inline-code\\">export ROS_DOMAIN_ID=10</code> and verify that <code class=\\"inline-code\\">/cmd_vel</code> appears immediately.</li>\\n</ol>","quizzes":[{"id":"q_l1_15_1","prompt":"Why does ROS 2 DDS discover nodes automatically across an Ethernet switch without any master node running?","options":["Because the Linux kernel auto-forwards all ROS packets","Because DDS Simple Participant Discovery Protocol (SPDP) broadcasts announcements on UDP multicast group 239.255.0.1","Because VS Code acts as the hidden discovery server","Because DNS records are updated dynamically"],"correct":1,"explanation":"DDS implementations use SPDP multicast packets on well-known ports derived from ROS_DOMAIN_ID. Participants automatically announce their presence to all listening peers on the network."}],"has_quiz":true,"next_id":"lesson_16","prev_id":"lesson_14"},{"id":"lesson_16","num":16,"num_str":"16","title":"Project 3.2: Computer Vision & OpenCV Integration with ROS 2","slug":"project_opencv_ros2_vision","filename":"16_project_opencv_ros2_vision.md","module":"Kinematics, TF2 & Computer Vision","module_id":3,"duration":"45-60 min","focus":"Python Computer Vision Pipeline, \`cv_bridge\` Conversion & Vision Service Processing","snapshot":[],"html_content":"<h1 id=\\"lesson-16-project-32-computer-vision--opencv-integration-with-ros-2\\">Lesson 16: Project 3.2: Computer Vision &amp; OpenCV Integration with ROS 2</h1>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Focus:</strong> Python Computer Vision Pipeline, <code class=\\"inline-code\\">cv_bridge</code> Conversion &amp; Vision Service Processing<br><strong>Course Track:</strong> NavPro Learning Hub - Level 1 (Project 3.2 - Python Only)<br><strong>Target Environment:</strong> ROS 2 Jazzy Jalisco</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"1-overview--learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>Visual perception is essential for modern autonomous mobile robots: identifying QR barcodes on warehouse shelving, detecting pallet drop zones, and tracking human workers.</p>\\n<p>ROS 2 streams images using the standard message type <code class=\\"inline-code\\">sensor_msgs/msg/Image</code>. However, computer vision libraries like <strong>OpenCV</strong> manipulate images as standard NumPy multidimensional arrays. The official ROS package <strong><code class=\\"inline-code\\">cv_bridge</code></strong> bridges this gap.</p>\\n<p>By the end of this capstone lesson, you will:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Understand image serialization in ROS 2: encoding types (<code class=\\"inline-code\\">bgr8</code>, <code class=\\"inline-code\\">rgb8</code>, <code class=\\"inline-code\\">mono8</code>).</li>\\n<li>Use <code class=\\"inline-code\\">cv_bridge.CvBridge</code> to convert between <code class=\\"inline-code\\">sensor_msgs/msg/Image</code> and OpenCV NumPy matrices.</li>\\n<li>Build a Python <strong>Camera Streamer Node</strong> generating simulated color test video.</li>\\n<li>Build a Python <strong>Vision Processing Service Node</strong> executing Canny Edge Detection and contour extraction.</li>\\n<li>Inspect live image topics using <code class=\\"inline-code\\">rqt_image_view</code> and RViz2.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-the-cv_bridge-conversion-architecture\\">2. The <code class=\\"inline-code\\">cv_bridge</code> Conversion Architecture</h2>\\n<div class=\\"lesson-image-wrapper\\"><img src=\\"assets/images/opencv_cv_bridge_pipeline.svg\\" alt=\\"OpenCV cv_bridge Conversion Pipeline\\" class=\\"lesson-image\\" loading=\\"lazy\\"><span class=\\"image-caption\\">OpenCV cv_bridge Conversion Pipeline</span></div>\\n<h3 id=\\"install-prerequisites\\">Install Prerequisites:</h3>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"sudo apt install -y ros-jazzy-cv-bridge ros-jazzy-image-transport python3-opencv rqt-image-view\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">sudo apt install -y ros-jazzy-cv-bridge ros-jazzy-image-transport python3-opencv rqt-image-view</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-step-by-step-camera-streamer-node-camera_publisherpy\\">3. Step-by-Step: Camera Streamer Node (<code class=\\"inline-code\\">camera_publisher.py</code>)</h2>\\n<p>This node simulates an onboard mobile robot camera publishing 640x480 video frames at 15 Hz.</p>\\n<p>Create file <code class=\\"inline-code\\">camera_publisher.py</code>:</p>\\n<div class=\\"code-container\\" data-language=\\"python\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">PYTHON</span><button class=\\"copy-code-btn\\" data-code=\\"#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nNavPro Learning Hub - Lesson 16\\nCamera Streamer: Generates simulated moving geometric patterns and publishes sensor_msgs/Image.\\n&quot;&quot;&quot;\\n\\nimport math\\nimport numpy as np\\nimport cv2\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom sensor_msgs.msg import Image\\nfrom cv_bridge import CvBridge\\n\\n\\nclass SimulatedCameraPublisher(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;camera_publisher&#x27;)\\n\\n        # Create Publisher on /camera/image_raw\\n        self.pub_ = self.create_publisher(Image, &#x27;/camera/image_raw&#x27;, 10)\\n        self.bridge_ = CvBridge()\\n\\n        # 15 Hz stream timer\\n        self.timer_ = self.create_timer(1.0 / 15.0, self.stream_frame)\\n        self.tick_ = 0\\n\\n        self.get_logger().info(&#x27;Simulated Camera Publisher active on /camera/image_raw (15 Hz).&#x27;)\\n\\n    def stream_frame(self):\\n        self.tick_ += 1\\n\\n        # 1. Create a 640x480 dark slate canvas (NumPy array)\\n        frame = np.full((480, 640, 3), 32, dtype=np.uint8)\\n\\n        # 2. Draw moving target circle simulating a warehouse pallet target\\n        center_x = int(320 + 180 * math.sin(self.tick_ * 0.08))\\n        center_y = int(240 + 80 * math.cos(self.tick_ * 0.08))\\n\\n        # Outer bounding box\\n        cv2.rectangle(frame, (center_x - 50, center_y - 50), (center_x + 50, center_y + 50), (0, 200, 255), 3)\\n        # Inner target circle\\n        cv2.circle(frame, (center_x, center_y), 25, (0, 255, 120), -1)\\n\\n        # Draw HUD Telemetry text overlay\\n        cv2.putText(frame, f&quot;NAVPRO OPTICAL FEED | FRAME #{self.tick_}&quot;, (20, 40),\\n                    cv2.FONT_HERSHEY_SIMPLEX, 0.7, (220, 220, 220), 2)\\n\\n        # 3. Convert OpenCV NumPy array to ROS 2 Image message\\n        msg = self.bridge_.cv2_to_imgmsg(frame, encoding=&#x27;bgr8&#x27;)\\n        msg.header.stamp = self.get_clock().now().to_msg()\\n        msg.header.frame_id = &#x27;camera_optical_link&#x27;\\n\\n        # 4. Publish message\\n        self.pub_.publish(msg)\\n\\n\\ndef main():\\n    rclpy.init()\\n    node = SimulatedCameraPublisher()\\n    try:\\n        rclpy.spin(node)\\n    except KeyboardInterrupt:\\n        pass\\n    finally:\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\">📋 Copy</button></div><pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nNavPro Learning Hub - Lesson 16\\nCamera Streamer: Generates simulated moving geometric patterns and publishes sensor_msgs/Image.\\n&quot;&quot;&quot;\\n\\nimport math\\nimport numpy as np\\nimport cv2\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom sensor_msgs.msg import Image\\nfrom cv_bridge import CvBridge\\n\\n\\nclass SimulatedCameraPublisher(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;camera_publisher&#x27;)\\n\\n        # Create Publisher on /camera/image_raw\\n        self.pub_ = self.create_publisher(Image, &#x27;/camera/image_raw&#x27;, 10)\\n        self.bridge_ = CvBridge()\\n\\n        # 15 Hz stream timer\\n        self.timer_ = self.create_timer(1.0 / 15.0, self.stream_frame)\\n        self.tick_ = 0\\n\\n        self.get_logger().info(&#x27;Simulated Camera Publisher active on /camera/image_raw (15 Hz).&#x27;)\\n\\n    def stream_frame(self):\\n        self.tick_ += 1\\n\\n        # 1. Create a 640x480 dark slate canvas (NumPy array)\\n        frame = np.full((480, 640, 3), 32, dtype=np.uint8)\\n\\n        # 2. Draw moving target circle simulating a warehouse pallet target\\n        center_x = int(320 + 180 * math.sin(self.tick_ * 0.08))\\n        center_y = int(240 + 80 * math.cos(self.tick_ * 0.08))\\n\\n        # Outer bounding box\\n        cv2.rectangle(frame, (center_x - 50, center_y - 50), (center_x + 50, center_y + 50), (0, 200, 255), 3)\\n        # Inner target circle\\n        cv2.circle(frame, (center_x, center_y), 25, (0, 255, 120), -1)\\n\\n        # Draw HUD Telemetry text overlay\\n        cv2.putText(frame, f&quot;NAVPRO OPTICAL FEED | FRAME #{self.tick_}&quot;, (20, 40),\\n                    cv2.FONT_HERSHEY_SIMPLEX, 0.7, (220, 220, 220), 2)\\n\\n        # 3. Convert OpenCV NumPy array to ROS 2 Image message\\n        msg = self.bridge_.cv2_to_imgmsg(frame, encoding=&#x27;bgr8&#x27;)\\n        msg.header.stamp = self.get_clock().now().to_msg()\\n        msg.header.frame_id = &#x27;camera_optical_link&#x27;\\n\\n        # 4. Publish message\\n        self.pub_.publish(msg)\\n\\n\\ndef main():\\n    rclpy.init()\\n    node = SimulatedCameraPublisher()\\n    try:\\n        rclpy.spin(node)\\n    except KeyboardInterrupt:\\n        pass\\n    finally:\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-step-by-step-vision-processing-node-with-service-vision_service_nodepy\\">4. Step-by-Step: Vision Processing Node with Service (<code class=\\"inline-code\\">vision_service_node.py</code>)</h2>\\n<p>This node subscribes to <code class=\\"inline-code\\">/camera/image_raw</code>, performs Canny edge detection, and exposes a ROS 2 Service <code class=\\"inline-code\\">/vision/capture_target</code> that counts how many edges/contours exist in the current scene!</p>\\n<p>Create file <code class=\\"inline-code\\">vision_service_node.py</code>:</p>\\n<div class=\\"code-container\\" data-language=\\"python\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">PYTHON</span><button class=\\"copy-code-btn\\" data-code=\\"#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nNavPro Learning Hub - Lesson 16\\nVision Service: Performs Canny edge detection and exposes a trigger service to count contours.\\n&quot;&quot;&quot;\\n\\nimport cv2\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom sensor_msgs.msg import Image\\nfrom std_srvs.srv import Trigger\\nfrom cv_bridge import CvBridge, CvBridgeError\\n\\n\\nclass VisionProcessorNode(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;vision_processor_node&#x27;)\\n\\n        self.bridge_ = CvBridge()\\n        self.latest_cv_image = None\\n        self.detected_contour_count = 0\\n\\n        # 1. Subscriber to raw camera feed\\n        self.sub_ = self.create_subscription(\\n            Image,\\n            &#x27;/camera/image_raw&#x27;,\\n            self.image_callback,\\n            10\\n        )\\n\\n        # 2. Publisher for processed edge detection output\\n        self.processed_pub_ = self.create_publisher(Image, &#x27;/camera/image_edges&#x27;, 10)\\n\\n        # 3. Service Server: Returns inspection analytics on demand\\n        self.srv_ = self.create_service(\\n            Trigger,\\n            &#x27;/vision/inspect_target&#x27;,\\n            self.handle_inspect_service\\n        )\\n\\n        self.get_logger().info(&#x27;Vision Processor Node active. Listening on /camera/image_raw.&#x27;)\\n\\n    def image_callback(self, msg: Image):\\n        &quot;&quot;&quot;Processes incoming camera frames in real time.&quot;&quot;&quot;\\n        try:\\n            # Convert ROS 2 Image to OpenCV BGR matrix\\n            cv_image = self.bridge_.imgmsg_to_cv2(msg, desired_encoding=&#x27;bgr8&#x27;)\\n            self.latest_cv_image = cv_image\\n        except CvBridgeError as e:\\n            self.get_logger().error(f&#x27;CvBridge conversion error: {e}&#x27;)\\n            return\\n\\n        # 1. Convert to Grayscale\\n        gray = cv2.cvtColor(cv_image, cv2.COLOR_BGR2GRAY)\\n\\n        # 2. Apply Gaussian Blur to filter sensor noise\\n        blurred = cv2.GaussianBlur(gray, (5, 5), 0)\\n\\n        # 3. Canny Edge Detection (Thresholds 50 to 150)\\n        edges = cv2.Canny(blurred, 50, 150)\\n\\n        # 4. Find Contours\\n        contours, _ = cv2.findContours(edges, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)\\n        self.detected_contour_count = len(contours)\\n\\n        # 5. Convert edge detection back to ROS Image message and publish\\n        out_msg = self.bridge_.cv2_to_imgmsg(edges, encoding=&#x27;mono8&#x27;)\\n        out_msg.header = msg.header\\n        self.processed_pub_.publish(out_msg)\\n\\n    def handle_inspect_service(self, request: Trigger.Request, response: Trigger.Response) -&gt; Trigger.Response:\\n        &quot;&quot;&quot;Service callback returning the current optical inspection outcome.&quot;&quot;&quot;\\n        if self.latest_cv_image is None:\\n            response.success = False\\n            response.message = &quot;No camera frames received yet.&quot;\\n            return response\\n\\n        response.success = True\\n        response.message = f&quot;Optical Inspection Complete: Identified {self.detected_contour_count} distinct objects/edges.&quot;\\n        self.get_logger().info(f&#x27;Inspection Service triggered -&gt; {response.message}&#x27;)\\n        return response\\n\\n\\ndef main():\\n    rclpy.init()\\n    node = VisionProcessorNode()\\n    try:\\n        rclpy.spin(node)\\n    except KeyboardInterrupt:\\n        pass\\n    finally:\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\">📋 Copy</button></div><pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nNavPro Learning Hub - Lesson 16\\nVision Service: Performs Canny edge detection and exposes a trigger service to count contours.\\n&quot;&quot;&quot;\\n\\nimport cv2\\nimport rclpy\\nfrom rclpy.node import Node\\nfrom sensor_msgs.msg import Image\\nfrom std_srvs.srv import Trigger\\nfrom cv_bridge import CvBridge, CvBridgeError\\n\\n\\nclass VisionProcessorNode(Node):\\n\\n    def __init__(self):\\n        super().__init__(&#x27;vision_processor_node&#x27;)\\n\\n        self.bridge_ = CvBridge()\\n        self.latest_cv_image = None\\n        self.detected_contour_count = 0\\n\\n        # 1. Subscriber to raw camera feed\\n        self.sub_ = self.create_subscription(\\n            Image,\\n            &#x27;/camera/image_raw&#x27;,\\n            self.image_callback,\\n            10\\n        )\\n\\n        # 2. Publisher for processed edge detection output\\n        self.processed_pub_ = self.create_publisher(Image, &#x27;/camera/image_edges&#x27;, 10)\\n\\n        # 3. Service Server: Returns inspection analytics on demand\\n        self.srv_ = self.create_service(\\n            Trigger,\\n            &#x27;/vision/inspect_target&#x27;,\\n            self.handle_inspect_service\\n        )\\n\\n        self.get_logger().info(&#x27;Vision Processor Node active. Listening on /camera/image_raw.&#x27;)\\n\\n    def image_callback(self, msg: Image):\\n        &quot;&quot;&quot;Processes incoming camera frames in real time.&quot;&quot;&quot;\\n        try:\\n            # Convert ROS 2 Image to OpenCV BGR matrix\\n            cv_image = self.bridge_.imgmsg_to_cv2(msg, desired_encoding=&#x27;bgr8&#x27;)\\n            self.latest_cv_image = cv_image\\n        except CvBridgeError as e:\\n            self.get_logger().error(f&#x27;CvBridge conversion error: {e}&#x27;)\\n            return\\n\\n        # 1. Convert to Grayscale\\n        gray = cv2.cvtColor(cv_image, cv2.COLOR_BGR2GRAY)\\n\\n        # 2. Apply Gaussian Blur to filter sensor noise\\n        blurred = cv2.GaussianBlur(gray, (5, 5), 0)\\n\\n        # 3. Canny Edge Detection (Thresholds 50 to 150)\\n        edges = cv2.Canny(blurred, 50, 150)\\n\\n        # 4. Find Contours\\n        contours, _ = cv2.findContours(edges, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)\\n        self.detected_contour_count = len(contours)\\n\\n        # 5. Convert edge detection back to ROS Image message and publish\\n        out_msg = self.bridge_.cv2_to_imgmsg(edges, encoding=&#x27;mono8&#x27;)\\n        out_msg.header = msg.header\\n        self.processed_pub_.publish(out_msg)\\n\\n    def handle_inspect_service(self, request: Trigger.Request, response: Trigger.Response) -&gt; Trigger.Response:\\n        &quot;&quot;&quot;Service callback returning the current optical inspection outcome.&quot;&quot;&quot;\\n        if self.latest_cv_image is None:\\n            response.success = False\\n            response.message = &quot;No camera frames received yet.&quot;\\n            return response\\n\\n        response.success = True\\n        response.message = f&quot;Optical Inspection Complete: Identified {self.detected_contour_count} distinct objects/edges.&quot;\\n        self.get_logger().info(f&#x27;Inspection Service triggered -&gt; {response.message}&#x27;)\\n        return response\\n\\n\\ndef main():\\n    rclpy.init()\\n    node = VisionProcessorNode()\\n    try:\\n        rclpy.spin(node)\\n    except KeyboardInterrupt:\\n        pass\\n    finally:\\n        node.destroy_node()\\n        rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-verification--visualizing-in-rqt_image_view\\">5. Verification &amp; Visualizing in <code class=\\"inline-code\\">rqt_image_view</code></h2>\\n<p>In Terminal 1:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"python3 camera_publisher.py\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">python3 camera_publisher.py</code></pre></div>\\n<p>In Terminal 2:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"python3 vision_service_node.py\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">python3 vision_service_node.py</code></pre></div>\\n<p>In Terminal 3, view the raw and processed feeds:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# Launch RQT Image View GUI\\nrqt_image_view\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># Launch RQT Image View GUI\\nrqt_image_view</code></pre></div>\\n<p><em>In the dropdown menu, select <code class=\\"inline-code\\">/camera/image_raw</code> to see the simulated color moving target, and <code class=\\"inline-code\\">/camera/image_edges</code> to view real-time Canny edge extraction!</em></p>\\n<p>In Terminal 4, call the vision inspection service:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"ros2 service call /vision/inspect_target std_srvs/srv/Trigger\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">ros2 service call /vision/inspect_target std_srvs/srv/Trigger</code></pre></div>\\n<p><em>Expected Output:</em></p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"response:\\nstd_srvs.srv.Trigger_Response(\\n  success=True,\\n  message=&#x27;Optical Inspection Complete: Identified 2 distinct objects/edges.&#x27;\\n)\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">response:\\nstd_srvs.srv.Trigger_Response(\\n  success=True,\\n  message=&#x27;Optical Inspection Complete: Identified 2 distinct objects/edges.&#x27;\\n)</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-hands-on-student-challenge\\">6. Hands-on Student Challenge</h2>\\n<p><strong>Task:</strong></p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>In <code class=\\"inline-code\\">vision_service_node.py</code>, add color filtering using <code class=\\"inline-code\\">cv2.inRange()</code> in HSV color space to isolate yellow targets.</li>\\n<li>Calculate the centroid coordinates $(c_x, c_y)$ of the largest contour using OpenCV image moments:</li>\\n</ol>\\n<p>$$c_x = \\\\frac{M_{10}}{M_{00}}, \\\\quad c_y = \\\\frac{M_{01}}{M_{00}}$$</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Include the detected target centroid $(c_x, c_y)$ in the service response message!</li>\\n</ol>","quizzes":[{"id":"q_l1_16_1","prompt":"Which library bridges ROS 2 'sensor_msgs/msg/Image' objects to OpenCV 'cv2.Mat' numpy arrays?","options":["cv_bridge","image_transport","ros2_numpy","torchvision"],"correct":0,"explanation":"cv_bridge provides the CvBridge class with imgmsg_to_cv2() and cv2_to_imgmsg() to convert seamlessly between ROS image messages and NumPy arrays used by OpenCV."}],"has_quiz":true,"next_id":"lesson_17","prev_id":"lesson_15"},{"id":"lesson_17","num":17,"num_str":"17","title":"3D Robot Modeling with URDF & Xacro","slug":"3d_modeling_urdf_xacro","filename":"17_3d_modeling_urdf_xacro.md","module":"3D Simulation & World Modeling","module_id":4,"duration":"45-60 min","focus":"Kinematic Tree Modeling, XML Macros (Xacro), Inertia Tensors & Visual/Collision Geometry","snapshot":[["URDF/Xacro Digital Twin","Defines the physical kinematics (Links) and rotational/prismatic axes (Joints) of the robot."],["TF2 Coordinate Tree","Maintains spatial transformations between coordinate frames (map -> odom -> base_link -> laser_frame)."]],"html_content":"<h1 id=\\"lesson-17-3d-robot-modeling-with-urdf--xacro\\">Lesson 17: 3D Robot Modeling with URDF &amp; Xacro</h1>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Focus:</strong> Kinematic Tree Modeling, XML Macros (Xacro), Inertia Tensors &amp; Visual/Collision Geometry<br><strong>Course Track:</strong> NavPro Learning Hub - Level 1<br><strong>Target Environment:</strong> ROS 2 Jazzy Jalisco</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"1-overview--learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>Before a robot can navigate, plan paths, or simulate physics in Gazebo, ROS 2 must understand its physical structure: chassis dimensions, wheel locations, center of mass, sensor mount positions, and joint limits.</p>\\n<p>This kinematic and physical representation is defined using <strong>URDF (Unified Robot Description Format)</strong> and <strong>Xacro (XML Macros)</strong>.</p>\\n<p>By the end of this lesson, you will:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Understand the hierarchy of Links and Joints in a differential drive robot.</li>\\n<li>Differentiate between Visual, Collision, and Inertial geometry tags.</li>\\n<li>Calculate physical 3D Inertia Tensors ($I_{xx}, I_{yy}, I_{zz}$) for boxes, cylinders, and spheres.</li>\\n<li>Use Xacro macros (<code class=\\"inline-code\\">&lt;xacro:macro&gt;</code>) and properties (<code class=\\"inline-code\\">&lt;xacro:property&gt;</code>) to eliminate code duplication.</li>\\n<li>Convert Xacro files to clean URDF strings at launch time using the <code class=\\"inline-code\\">xacro</code> command substitution.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-urdf-anatomy-links-vs-joints\\">2. URDF Anatomy: Links vs. Joints</h2>\\n<p>A robot model is represented as a directed acyclic tree of <strong>Links</strong> connected by <strong>Joints</strong>:</p>\\n<div class=\\"lesson-image-wrapper\\"><img src=\\"assets/images/urdf_kinematic_tree.svg\\" alt=\\"URDF Kinematic Tree and Joint Hierarchy\\" class=\\"lesson-image\\" loading=\\"lazy\\"><span class=\\"image-caption\\">URDF Kinematic Tree and Joint Hierarchy</span></div>\\n<ul class=\\"lesson-bullet-list\\">\\n<li><strong>Links:</strong> The physical rigid bodies of the robot (chassis, wheels, lidar).</li>\\n<li><strong>Joints:</strong> The kinematic relationships between parent and child links:</li>\\n<li><code class=\\"inline-code\\">fixed</code>: No motion allowed (e.g., lidar mounted to chassis).</li>\\n<li><code class=\\"inline-code\\">continuous</code>: Continuous 360-degree rotation (e.g., differential drive wheels).</li>\\n<li><code class=\\"inline-code\\">revolute</code>: Limited angular rotation with lower/upper limits (e.g., robotic arm joints).</li>\\n<li><code class=\\"inline-code\\">prismatic</code>: Linear sliding motion along an axis (e.g., forklift mast).</li>\\n</ul>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-link-definition-visual-collision-and-inertial\\">3. Link Definition: Visual, Collision, and Inertial</h2>\\n<p>Every physical link must contain three sub-elements:</p>\\n<div class=\\"code-container\\" data-language=\\"xml\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">XML</span><button class=\\"copy-code-btn\\" data-code=\\"&lt;link name=&quot;base_link&quot;&gt;\\n  &lt;!-- 1. Visual: What the operator sees in RViz (mesh or basic shape) --&gt;\\n  &lt;visual&gt;\\n    &lt;origin xyz=&quot;0 0 0.07&quot; rpy=&quot;0 0 0&quot; /&gt;\\n    &lt;geometry&gt;\\n      &lt;box size=&quot;0.40 0.30 0.14&quot; /&gt;\\n    &lt;/geometry&gt;\\n    &lt;material name=&quot;cyan&quot;&gt;&lt;color rgba=&quot;0.0 0.75 0.9 1.0&quot; /&gt;&lt;/material&gt;\\n  &lt;/visual&gt;\\n\\n  &lt;!-- 2. Collision: Simplified geometry used by ODE physics engine for contact checks --&gt;\\n  &lt;collision&gt;\\n    &lt;origin xyz=&quot;0 0 0.07&quot; rpy=&quot;0 0 0&quot; /&gt;\\n    &lt;geometry&gt;\\n      &lt;box size=&quot;0.40 0.30 0.14&quot; /&gt;\\n    &lt;/geometry&gt;\\n  &lt;/collision&gt;\\n\\n  &lt;!-- 3. Inertial: Mass and moment of inertia for realistic dynamics in Gazebo --&gt;\\n  &lt;inertial&gt;\\n    &lt;origin xyz=&quot;0 0 0.07&quot; rpy=&quot;0 0 0&quot; /&gt;\\n    &lt;mass value=&quot;8.0&quot; /&gt;\\n    &lt;inertia ixx=&quot;0.073&quot; ixy=&quot;0&quot; ixz=&quot;0&quot; iyy=&quot;0.120&quot; iyz=&quot;0&quot; izz=&quot;0.167&quot; /&gt;\\n  &lt;/inertial&gt;\\n&lt;/link&gt;\\">📋 Copy</button></div><pre><code class=\\"language-xml\\">&lt;link name=&quot;base_link&quot;&gt;\\n  &lt;!-- 1. Visual: What the operator sees in RViz (mesh or basic shape) --&gt;\\n  &lt;visual&gt;\\n    &lt;origin xyz=&quot;0 0 0.07&quot; rpy=&quot;0 0 0&quot; /&gt;\\n    &lt;geometry&gt;\\n      &lt;box size=&quot;0.40 0.30 0.14&quot; /&gt;\\n    &lt;/geometry&gt;\\n    &lt;material name=&quot;cyan&quot;&gt;&lt;color rgba=&quot;0.0 0.75 0.9 1.0&quot; /&gt;&lt;/material&gt;\\n  &lt;/visual&gt;\\n\\n  &lt;!-- 2. Collision: Simplified geometry used by ODE physics engine for contact checks --&gt;\\n  &lt;collision&gt;\\n    &lt;origin xyz=&quot;0 0 0.07&quot; rpy=&quot;0 0 0&quot; /&gt;\\n    &lt;geometry&gt;\\n      &lt;box size=&quot;0.40 0.30 0.14&quot; /&gt;\\n    &lt;/geometry&gt;\\n  &lt;/collision&gt;\\n\\n  &lt;!-- 3. Inertial: Mass and moment of inertia for realistic dynamics in Gazebo --&gt;\\n  &lt;inertial&gt;\\n    &lt;origin xyz=&quot;0 0 0.07&quot; rpy=&quot;0 0 0&quot; /&gt;\\n    &lt;mass value=&quot;8.0&quot; /&gt;\\n    &lt;inertia ixx=&quot;0.073&quot; ixy=&quot;0&quot; ixz=&quot;0&quot; iyy=&quot;0.120&quot; iyz=&quot;0&quot; izz=&quot;0.167&quot; /&gt;\\n  &lt;/inertial&gt;\\n&lt;/link&gt;</code></pre></div>\\n<div class=\\"alert-callout alert-important\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Keep Collision Geometry Simple:</strong> Never use high-poly visual CAD meshes for <code class=\\"inline-code\\">&lt;collision&gt;</code>. Use primitive shapes (<code class=\\"inline-code\\">box</code>, <code class=\\"inline-code\\">cylinder</code>, <code class=\\"inline-code\\">sphere</code>) to keep Gazebo physics calculations running at 1000 Hz real-time factor!</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-inertia-tensor-mathematics\\">4. Inertia Tensor Mathematics</h2>\\n<p>Gazebo physics simulators require the 3x3 Moment of Inertia Matrix:</p>\\n<p>$$\\\\mathbf{I} = \\\\begin{bmatrix} I_{xx} &amp; I_{xy} &amp; I_{xz} \\\\\\\\ I_{yx} &amp; I_{yy} &amp; I_{yz} \\\\\\\\ I_{zx} &amp; I_{zy} &amp; I_{zz} \\\\end{bmatrix}$$</p>\\n<p>For symmetrical bodies, cross products ($I_{xy}, I_{xz}, I_{yz}$) are zero:</p>\\n<ul class=\\"lesson-bullet-list\\">\\n<li><strong>Solid Box (mass $m$, width $w$, height $h$, depth $d$):</strong></li>\\n</ul>\\n<p>$$I_{xx} = \\\\frac{m}{12}(h^2 + d^2), \\\\quad I_{yy} = \\\\frac{m}{12}(w^2 + d^2), \\\\quad I_{zz} = \\\\frac{m}{12}(w^2 + h^2)$$</p>\\n<ul class=\\"lesson-bullet-list\\">\\n<li><strong>Solid Cylinder (mass $m$, radius $r$, length $h$ along Z):</strong></li>\\n</ul>\\n<p>$$I_{xx} = I_{yy} = \\\\frac{m}{12}(3r^2 + h^2), \\\\quad I_{zz} = \\\\frac{m}{2}r^2$$</p>\\n<ul class=\\"lesson-bullet-list\\">\\n<li><strong>Solid Sphere (mass $m$, radius $r$):</strong></li>\\n</ul>\\n<p>$$I_{xx} = I_{yy} = I_{zz} = \\\\frac{2}{5}m r^2$$</p>\\n<p>In Xacro, we encapsulate these formulas into reusable macros:</p>\\n<div class=\\"code-container\\" data-language=\\"xml\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">XML</span><button class=\\"copy-code-btn\\" data-code=\\"&lt;xacro:macro name=&quot;cylinder_inertia&quot; params=&quot;m r h&quot;&gt;\\n  &lt;inertial&gt;\\n    &lt;mass value=&quot;\${m}&quot; /&gt;\\n    &lt;inertia ixx=&quot;\${(m/12)*(3*r*r + h*h)}&quot; ixy=&quot;0&quot; ixz=&quot;0&quot;\\n             iyy=&quot;\${(m/12)*(3*r*r + h*h)}&quot; iyz=&quot;0&quot;\\n             izz=&quot;\${(m/2)*(r*r)}&quot; /&gt;\\n  &lt;/inertial&gt;\\n&lt;/xacro:macro&gt;\\">📋 Copy</button></div><pre><code class=\\"language-xml\\">&lt;xacro:macro name=&quot;cylinder_inertia&quot; params=&quot;m r h&quot;&gt;\\n  &lt;inertial&gt;\\n    &lt;mass value=&quot;\${m}&quot; /&gt;\\n    &lt;inertia ixx=&quot;\${(m/12)*(3*r*r + h*h)}&quot; ixy=&quot;0&quot; ixz=&quot;0&quot;\\n             iyy=&quot;\${(m/12)*(3*r*r + h*h)}&quot; iyz=&quot;0&quot;\\n             izz=&quot;\${(m/2)*(r*r)}&quot; /&gt;\\n  &lt;/inertial&gt;\\n&lt;/xacro:macro&gt;</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-converting-xacro-at-runtime-in-launch-files\\">5. Converting Xacro at Runtime in Launch Files</h2>\\n<p>Instead of generating static <code class=\\"inline-code\\">.urdf</code> files on disk, ROS 2 processes Xacro dynamically inside <code class=\\"inline-code\\">rsp.launch.py</code>:</p>\\n<div class=\\"code-container\\" data-language=\\"python\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">PYTHON</span><button class=\\"copy-code-btn\\" data-code=\\"from launch.substitutions import Command\\nfrom launch_ros.parameter_descriptions import ParameterValue\\n\\nrobot_description_content = ParameterValue(\\n    Command([&#x27;xacro &#x27;, xacro_file_path]),\\n    value_type=str\\n)\\n\\nrobot_state_publisher_node = Node(\\n    package=&#x27;robot_state_publisher&#x27;,\\n    executable=&#x27;robot_state_publisher&#x27;,\\n    parameters=[{&#x27;robot_description&#x27;: robot_description_content}]\\n)\\">📋 Copy</button></div><pre><code class=\\"language-python\\">from launch.substitutions import Command\\nfrom launch_ros.parameter_descriptions import ParameterValue\\n\\nrobot_description_content = ParameterValue(\\n    Command([&#x27;xacro &#x27;, xacro_file_path]),\\n    value_type=str\\n)\\n\\nrobot_state_publisher_node = Node(\\n    package=&#x27;robot_state_publisher&#x27;,\\n    executable=&#x27;robot_state_publisher&#x27;,\\n    parameters=[{&#x27;robot_description&#x27;: robot_description_content}]\\n)</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-hands-on-student-challenge\\">6. Hands-on Student Challenge</h2>\\n<p><strong>Task:</strong></p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Open <a href=\\"file:///home/chaitu/Projects/navpro_learning_hub/level1/ros2_ws/src/navpro_description/urdf/navpro_robot.urdf.xacro\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\"><code class=\\"inline-code\\">navpro_robot.urdf.xacro</code></a>.</li>\\n<li>Inspect the wheel joint definitions: verify that the axis of rotation for continuous joints is set to <code class=\\"inline-code\\">&lt;axis xyz=&quot;0 1 0&quot;/&gt;</code> (rotating around the Y-axis).</li>\\n<li>Test processing the Xacro file directly from terminal:</li>\\n</ol>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"   xacro $(ros2 pkg prefix --share navpro_description)/urdf/navpro_robot.urdf.xacro &gt; /tmp/test_robot.urdf\\n   check_urdf /tmp/test_robot.urdf\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">   xacro $(ros2 pkg prefix --share navpro_description)/urdf/navpro_robot.urdf.xacro &gt; /tmp/test_robot.urdf\\n   check_urdf /tmp/test_robot.urdf</code></pre></div>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Verify that <code class=\\"inline-code\\">check_urdf</code> outputs: <code class=\\"inline-code\\">robot name is: navpro_mini</code> with 0 syntax errors!</li>\\n</ol>","quizzes":[{"id":"q_l1_17_1","prompt":"What is the primary advantage of Xacro over raw URDF XML files?","options":["Xacro can execute arbitrary Python scripts inside Gazebo","Xacro introduces modular XML macros, reusable property variables, and mathematical expressions to eliminate copy-paste boilerplate","Xacro converts 3D meshes to STL automatically","Xacro runs 10x faster in RViz2"],"correct":1,"explanation":"Xacro (XML Macros) provides programmatic capabilities like <xacro:macro>, property variables (\${wheel_radius}), and math expressions, allowing clean modular robot descriptions."}],"has_quiz":true,"next_id":"lesson_18","prev_id":"lesson_16"},{"id":"lesson_18","num":18,"num_str":"18","title":"RViz2 Visualization & Kinematic TF Inspection","slug":"rviz2_visualization_tf_inspection","filename":"18_rviz2_visualization_tf_inspection.md","module":"3D Simulation & World Modeling","module_id":4,"duration":"45-60 min","focus":"3D Visualization Plugins, Fixed Frames, Display Configurations & Kinematic Sliders","snapshot":[],"html_content":"<h1 id=\\"lesson-18-rviz2-visualization--kinematic-tf-inspection\\">Lesson 18: RViz2 Visualization &amp; Kinematic TF Inspection</h1>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Focus:</strong> 3D Visualization Plugins, Fixed Frames, Display Configurations &amp; Kinematic Sliders<br><strong>Course Track:</strong> NavPro Learning Hub - Level 1<br><strong>Target Environment:</strong> ROS 2 Jazzy Jalisco</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"1-overview--learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p><strong>RViz2 (ROS 2 3D Visualizer)</strong> is the primary window into the mind of your robot. Unlike a physics simulator (which simulates friction, gravity, and collisions in a simulated world), RViz2 visualizes <strong>what the robot&#x27;s onboard algorithms believe is happening</strong> (sensor clouds, transform trees, planned paths, costmap obstacles).</p>\\n<p>By the end of this lesson, you will:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Understand the difference between physics simulation (Gazebo) and sensor visualization (RViz2).</li>\\n<li>Configure core visualization displays: Grid, RobotModel, TF, LaserScan, and Odometry.</li>\\n<li>Master the rule of <strong>RGB = XYZ</strong> coordinate axes.</li>\\n<li>Understand the <strong>Fixed Frame</strong> setting and resolve the common &quot;No transform from [X] to [Y]&quot; error.</li>\\n<li>Save, version-control, and launch custom <code class=\\"inline-code\\">.rviz</code> configuration presets.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-rviz2-vs-gazebo-the-essential-distinction\\">2. RViz2 vs. Gazebo: The Essential Distinction</h2>\\n<div class=\\"table-wrapper\\"><table>\\n<thead><tr>\\n<th>Gazebo Simulator</th>\\n<th>RViz2 Visualizer</th>\\n</tr></thead><tbody>\\n<tr>\\n<td>Simulates the physical universe</td>\\n<td>Visualizes the robot&#x27;s internal software state</td>\\n</tr>\\n<tr>\\n<td>Models motor torque, friction, and slip</td>\\n<td>Shows sensor telemetry (LiDAR points, images)</td>\\n</tr>\\n<tr>\\n<td>Simulates gravity and rigid-body collisions</td>\\n<td>Displays costmaps, planned paths, and TF frames</td>\\n</tr>\\n<tr>\\n<td>Answers: <em>&quot;What is the ground-truth physical state?&quot;</em></td>\\n<td>Answers: <em>&quot;What does the robot software stack perceive?&quot;</em></td>\\n</tr>\\n</tbody></table></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-the-rgb--xyz-rule\\">3. The RGB = XYZ Rule</h2>\\n<p>In all ROS 2 visual tools (RViz2, Gazebo, Blender), coordinate frame axes follow the universal color standard:</p>\\n<p>$$\\\\mathbf{R} = \\\\mathbf{X} \\\\quad (\\\\text{Red: Forward / Longitudinal})$$</p>\\n<p>$$\\\\mathbf{G} = \\\\mathbf{Y} \\\\quad (\\\\text{Green: Left / Lateral})$$</p>\\n<p>$$\\\\mathbf{B} = \\\\mathbf{Z} \\\\quad (\\\\text{Blue: Up / Vertical})$$</p>\\n<div class=\\"lesson-image-wrapper\\"><img src=\\"assets/images/rviz_coordinate_axes.svg\\" alt=\\"ROS 2 RGB=XYZ Coordinate Axes\\" class=\\"lesson-image\\" loading=\\"lazy\\"><span class=\\"image-caption\\">ROS 2 RGB=XYZ Coordinate Axes</span></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-key-rviz2-displays--plugins\\">4. Key RViz2 Displays &amp; Plugins</h2>\\n<div class=\\"table-wrapper\\"><table>\\n<thead><tr>\\n<th>Display Plugin</th>\\n<th>Topic / Source</th>\\n<th>Purpose</th>\\n</tr></thead><tbody>\\n<tr>\\n<td><strong>Grid</strong></td>\\n<td>N/A</td>\\n<td>Ground plane reference grid (1m x 1m cells).</td>\\n</tr>\\n<tr>\\n<td><strong>RobotModel</strong></td>\\n<td><code class=\\"inline-code\\">/robot_description</code></td>\\n<td>Renders the 3D visual geometry from URDF with joint angles.</td>\\n</tr>\\n<tr>\\n<td><strong>TF</strong></td>\\n<td><code class=\\"inline-code\\">/tf</code>, <code class=\\"inline-code\\">/tf_static</code></td>\\n<td>Displays 3D axes and frame names for all coordinate links.</td>\\n</tr>\\n<tr>\\n<td><strong>LaserScan</strong></td>\\n<td><code class=\\"inline-code\\">/scan</code></td>\\n<td>Renders 2D LiDAR range points as color-coded dots.</td>\\n</tr>\\n<tr>\\n<td><strong>Odometry</strong></td>\\n<td><code class=\\"inline-code\\">/odom</code></td>\\n<td>Displays robot linear velocity vectors and trajectory paths.</td>\\n</tr>\\n<tr>\\n<td><strong>Map</strong></td>\\n<td><code class=\\"inline-code\\">/map</code></td>\\n<td>Renders 2D SLAM occupancy grid (White=Free, Black=Wall, Gray=Unknown).</td>\\n</tr>\\n<tr>\\n<td><strong>Path</strong></td>\\n<td><code class=\\"inline-code\\">/plan</code></td>\\n<td>Renders Nav2 global planned trajectories as colored ribbons.</td>\\n</tr>\\n</tbody></table></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-the-critical-fixed-frame-rule\\">5. The Critical &quot;Fixed Frame&quot; Rule</h2>\\n<p>At the top of the RViz2 Displays panel is the <strong>Global Options -&gt; Fixed Frame</strong> property:</p>\\n<ul class=\\"lesson-bullet-list\\">\\n<li>When inspecting a static robot model on a test bench: Set Fixed Frame to <strong><code class=\\"inline-code\\">base_footprint</code></strong>.</li>\\n<li>When visualizing wheel odometry: Set Fixed Frame to <strong><code class=\\"inline-code\\">odom</code></strong>.</li>\\n<li>When navigating inside a warehouse map: Set Fixed Frame to <strong><code class=\\"inline-code\\">map</code></strong>.</li>\\n</ul>\\n<div class=\\"alert-callout alert-warning\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>The #1 RViz2 Error: &quot;No transform from [laser_frame] to [map]&quot;</strong><br>If your Fixed Frame is set to <code class=\\"inline-code\\">map</code>, but neither SLAM nor AMCL is currently running, RViz2 has no way to calculate the transform between <code class=\\"inline-code\\">map</code> and <code class=\\"inline-code\\">odom</code>. All displays will turn RED and report an error.<br><strong>Solution:</strong> Change the Fixed Frame back to <code class=\\"inline-code\\">odom</code> or <code class=\\"inline-code\\">base_footprint</code>!</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-launching-rviz2-with-preset-configurations\\">6. Launching RViz2 with Preset Configurations</h2>\\n<p>Launch the pre-configured model viewer in <code class=\\"inline-code\\">navpro_description</code>:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"ros2 launch navpro_description display.launch.py\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">ros2 launch navpro_description display.launch.py</code></pre></div>\\n<p>This launch file automatically:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Runs <code class=\\"inline-code\\">rsp.launch.py</code> to parse <code class=\\"inline-code\\">navpro_robot.urdf.xacro</code>.</li>\\n<li>Starts <code class=\\"inline-code\\">joint_state_publisher_gui</code> with interactive sliders to turn the wheels.</li>\\n<li>Opens RViz2 pre-loaded with <code class=\\"inline-code\\">rviz/robot_model.rviz</code>.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"7-hands-on-student-challenge\\">7. Hands-on Student Challenge</h2>\\n<p><strong>Task:</strong></p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Run <code class=\\"inline-code\\">ros2 launch navpro_description display.launch.py</code>.</li>\\n<li>In the <code class=\\"inline-code\\">Joint State Publisher GUI</code> window, move the sliders for <code class=\\"inline-code\\">left_wheel_joint</code> and <code class=\\"inline-code\\">right_wheel_joint</code>.</li>\\n<li>Verify in RViz2 that the wheels rotate in real time.</li>\\n<li>Add the <code class=\\"inline-code\\">TF</code> display plugin in the left panel. Check &quot;Show Names&quot; to see <code class=\\"inline-code\\">base_footprint</code>, <code class=\\"inline-code\\">base_link</code>, <code class=\\"inline-code\\">laser_frame</code>, and <code class=\\"inline-code\\">imu_link</code>.</li>\\n</ol>","quizzes":[{"id":"q_l1_18_1","prompt":"What is the universal color convention for coordinate frame axes (X, Y, Z) in RViz2?","options":["Red = X, Green = Y, Blue = Z (RGB = XYZ)","Red = Z, Green = X, Blue = Y","Blue = X, Green = Y, Red = Z","Yellow = X, Cyan = Y, Magenta = Z"],"correct":0,"explanation":"RViz2 strictly follows the RGB = XYZ standard: Red is the X-axis (Forward), Green is the Y-axis (Left), and Blue is the Z-axis (Up)."}],"has_quiz":true,"next_id":"lesson_19","prev_id":"lesson_17"},{"id":"lesson_19","num":19,"num_str":"19","title":"Gazebo Physics Simulation & Sensor Plugins","slug":"gazebo_physics_and_sensor_plugins","filename":"19_gazebo_physics_and_sensor_plugins.md","module":"3D Simulation & World Modeling","module_id":4,"duration":"45-60 min","focus":"Physics Engine Simulation, Differential Drive Plugins, 2D LiDAR Ray Sensors & IMU","snapshot":[],"html_content":"<h1 id=\\"lesson-19-gazebo-physics-simulation--sensor-plugins\\">Lesson 19: Gazebo Physics Simulation &amp; Sensor Plugins</h1>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Focus:</strong> Physics Engine Simulation, Differential Drive Plugins, 2D LiDAR Ray Sensors &amp; IMU<br><strong>Course Track:</strong> NavPro Learning Hub - Level 1<br><strong>Target Environment:</strong> ROS 2 Jazzy Jalisco</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"1-overview--learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>Testing navigation code on physical hardware carries real risks: collision damage, battery discharge, and hardware downtime. Physics simulation in <strong>Gazebo</strong> allows robotics developers to test autonomous algorithms in safe, repeatable, photorealistic environments.</p>\\n<p>By the end of this lesson, you will:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Understand Gazebo architecture: the backend physics server (<code class=\\"inline-code\\">gzserver</code>) vs. frontend visual renderer (<code class=\\"inline-code\\">gzclient</code>).</li>\\n<li>Configure the <strong>Gazebo Differential Drive Plugin</strong> (<code class=\\"inline-code\\">libgazebo_ros_diff_drive.so</code>) to translate <code class=\\"inline-code\\">/cmd_vel</code> into simulated motor torques and wheel odometry.</li>\\n<li>Configure the <strong>Gazebo 2D LiDAR Ray Sensor Plugin</strong> (<code class=\\"inline-code\\">libgazebo_ros_ray_sensor.so</code>) with realistic Gaussian noise.</li>\\n<li>Configure the <strong>Gazebo IMU Plugin</strong> (<code class=\\"inline-code\\">libgazebo_ros_imu_sensor.so</code>) for orientation and acceleration data.</li>\\n<li>Spawn the robot into the simulation world using the <code class=\\"inline-code\\">spawn_entity.py</code> service.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-gazebo-architecture\\">2. Gazebo Architecture</h2>\\n<div class=\\"lesson-image-wrapper\\"><img src=\\"assets/images/gazebo_sim_architecture.svg\\" alt=\\"Gazebo Simulation Pipeline Architecture\\" class=\\"lesson-image\\" loading=\\"lazy\\"><span class=\\"image-caption\\">Gazebo Simulation Pipeline Architecture</span></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-the-differential-drive-controller-plugin\\">3. The Differential Drive Controller Plugin</h2>\\n<p>Open <a href=\\"file:///home/chaitu/Projects/navpro_learning_hub/level1/ros2_ws/src/navpro_description/urdf/gazebo_plugins.xacro\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\"><code class=\\"inline-code\\">urdf/gazebo_plugins.xacro</code></a>:</p>\\n<div class=\\"code-container\\" data-language=\\"xml\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">XML</span><button class=\\"copy-code-btn\\" data-code=\\"&lt;gazebo&gt;\\n  &lt;plugin name=&quot;navpro_diff_drive&quot; filename=&quot;libgazebo_ros_diff_drive.so&quot;&gt;\\n    &lt;!-- Remappings to connect with standard ROS 2 topics --&gt;\\n    &lt;ros&gt;\\n      &lt;namespace&gt;/&lt;/namespace&gt;\\n      &lt;remapping&gt;cmd_vel:=cmd_vel&lt;/remapping&gt;\\n      &lt;remapping&gt;odom:=odom&lt;/remapping&gt;\\n    &lt;/ros&gt;\\n\\n    &lt;!-- Physical Wheel Joints from URDF --&gt;\\n    &lt;left_joint&gt;left_wheel_joint&lt;/left_joint&gt;\\n    &lt;right_joint&gt;right_wheel_joint&lt;/right_joint&gt;\\n\\n    &lt;!-- Kinematics Constants --&gt;\\n    &lt;wheel_separation&gt;0.32&lt;/wheel_separation&gt;\\n    &lt;wheel_diameter&gt;0.12&lt;/wheel_diameter&gt;\\n\\n    &lt;!-- Motor Torque Limits --&gt;\\n    &lt;max_wheel_torque&gt;20.0&lt;/max_wheel_torque&gt;\\n    &lt;max_wheel_acceleration&gt;1.5&lt;/max_wheel_acceleration&gt;\\n\\n    &lt;!-- Output Topics &amp; TF Broadcast --&gt;\\n    &lt;publish_odom&gt;true&lt;/publish_odom&gt;\\n    &lt;publish_odom_tf&gt;true&lt;/publish_odom_tf&gt;\\n    &lt;publish_wheel_tf&gt;true&lt;/publish_wheel_tf&gt;\\n\\n    &lt;odometry_frame&gt;odom&lt;/odometry_frame&gt;\\n    &lt;robot_base_frame&gt;base_footprint&lt;/robot_base_frame&gt;\\n    &lt;update_rate&gt;50.0&lt;/update_rate&gt;\\n  &lt;/plugin&gt;\\n&lt;/gazebo&gt;\\">📋 Copy</button></div><pre><code class=\\"language-xml\\">&lt;gazebo&gt;\\n  &lt;plugin name=&quot;navpro_diff_drive&quot; filename=&quot;libgazebo_ros_diff_drive.so&quot;&gt;\\n    &lt;!-- Remappings to connect with standard ROS 2 topics --&gt;\\n    &lt;ros&gt;\\n      &lt;namespace&gt;/&lt;/namespace&gt;\\n      &lt;remapping&gt;cmd_vel:=cmd_vel&lt;/remapping&gt;\\n      &lt;remapping&gt;odom:=odom&lt;/remapping&gt;\\n    &lt;/ros&gt;\\n\\n    &lt;!-- Physical Wheel Joints from URDF --&gt;\\n    &lt;left_joint&gt;left_wheel_joint&lt;/left_joint&gt;\\n    &lt;right_joint&gt;right_wheel_joint&lt;/right_joint&gt;\\n\\n    &lt;!-- Kinematics Constants --&gt;\\n    &lt;wheel_separation&gt;0.32&lt;/wheel_separation&gt;\\n    &lt;wheel_diameter&gt;0.12&lt;/wheel_diameter&gt;\\n\\n    &lt;!-- Motor Torque Limits --&gt;\\n    &lt;max_wheel_torque&gt;20.0&lt;/max_wheel_torque&gt;\\n    &lt;max_wheel_acceleration&gt;1.5&lt;/max_wheel_acceleration&gt;\\n\\n    &lt;!-- Output Topics &amp; TF Broadcast --&gt;\\n    &lt;publish_odom&gt;true&lt;/publish_odom&gt;\\n    &lt;publish_odom_tf&gt;true&lt;/publish_odom_tf&gt;\\n    &lt;publish_wheel_tf&gt;true&lt;/publish_wheel_tf&gt;\\n\\n    &lt;odometry_frame&gt;odom&lt;/odometry_frame&gt;\\n    &lt;robot_base_frame&gt;base_footprint&lt;/robot_base_frame&gt;\\n    &lt;update_rate&gt;50.0&lt;/update_rate&gt;\\n  &lt;/plugin&gt;\\n&lt;/gazebo&gt;</code></pre></div>\\n<h3 id=\\"key-parameters\\">Key Parameters:</h3>\\n<ul class=\\"lesson-bullet-list\\">\\n<li><code class=\\"inline-code\\">&lt;wheel_separation&gt;</code>: Distance between left and right wheel contact patches (0.32m). If this value is incorrect in the plugin, turning commands will produce inaccurate angular velocities.</li>\\n<li><code class=\\"inline-code\\">&lt;wheel_diameter&gt;</code>: Diameter of the drive wheels (0.12m). Drives linear speed calculation.</li>\\n<li><code class=\\"inline-code\\">&lt;publish_odom_tf&gt;</code>: When set to <code class=\\"inline-code\\">true</code>, the plugin broadcasts the dynamic <code class=\\"inline-code\\">odom -&gt; base_footprint</code> transform automatically.</li>\\n</ul>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-the-2d-lidar-ray-sensor-plugin\\">4. The 2D LiDAR Ray Sensor Plugin</h2>\\n<p>Open <a href=\\"file:///home/chaitu/Projects/navpro_learning_hub/level1/ros2_ws/src/navpro_description/urdf/lidar.xacro\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\"><code class=\\"inline-code\\">urdf/lidar.xacro</code></a>:</p>\\n<div class=\\"code-container\\" data-language=\\"xml\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">XML</span><button class=\\"copy-code-btn\\" data-code=\\"&lt;gazebo reference=&quot;laser_frame&quot;&gt;\\n  &lt;sensor name=&quot;laser_sensor&quot; type=&quot;ray&quot;&gt;\\n    &lt;pose&gt;0 0 0 0 0 0&lt;/pose&gt;\\n    &lt;visualize&gt;false&lt;/visualize&gt;\\n    &lt;update_rate&gt;10.0&lt;/update_rate&gt;\\n    &lt;ray&gt;\\n      &lt;scan&gt;\\n        &lt;horizontal&gt;\\n          &lt;samples&gt;360&lt;/samples&gt;\\n          &lt;resolution&gt;1&lt;/resolution&gt;\\n          &lt;min_angle&gt;-3.14159265&lt;/min_angle&gt;\\n          &lt;max_angle&gt;3.14159265&lt;/max_angle&gt;\\n        &lt;/horizontal&gt;\\n      &lt;/scan&gt;\\n      &lt;range&gt;\\n        &lt;min&gt;0.15&lt;/min&gt;\\n        &lt;max&gt;12.0&lt;/max&gt;\\n        &lt;resolution&gt;0.01&lt;/resolution&gt;\\n      &lt;/range&gt;\\n      &lt;noise&gt;\\n        &lt;type&gt;gaussian&lt;/type&gt;\\n        &lt;mean&gt;0.0&lt;/mean&gt;\\n        &lt;stddev&gt;0.01&lt;/stddev&gt; &lt;!-- 1cm simulated measurement noise --&gt;\\n      &lt;/noise&gt;\\n    &lt;/ray&gt;\\n    &lt;plugin name=&quot;navpro_laser_controller&quot; filename=&quot;libgazebo_ros_ray_sensor.so&quot;&gt;\\n      &lt;ros&gt;\\n        &lt;argument&gt;~/out:=scan&lt;/argument&gt;\\n      &lt;/ros&gt;\\n      &lt;output_type&gt;sensor_msgs/LaserScan&lt;/output_type&gt;\\n      &lt;frame_name&gt;laser_frame&lt;/frame_name&gt;\\n    &lt;/plugin&gt;\\n  &lt;/sensor&gt;\\n&lt;/gazebo&gt;\\">📋 Copy</button></div><pre><code class=\\"language-xml\\">&lt;gazebo reference=&quot;laser_frame&quot;&gt;\\n  &lt;sensor name=&quot;laser_sensor&quot; type=&quot;ray&quot;&gt;\\n    &lt;pose&gt;0 0 0 0 0 0&lt;/pose&gt;\\n    &lt;visualize&gt;false&lt;/visualize&gt;\\n    &lt;update_rate&gt;10.0&lt;/update_rate&gt;\\n    &lt;ray&gt;\\n      &lt;scan&gt;\\n        &lt;horizontal&gt;\\n          &lt;samples&gt;360&lt;/samples&gt;\\n          &lt;resolution&gt;1&lt;/resolution&gt;\\n          &lt;min_angle&gt;-3.14159265&lt;/min_angle&gt;\\n          &lt;max_angle&gt;3.14159265&lt;/max_angle&gt;\\n        &lt;/horizontal&gt;\\n      &lt;/scan&gt;\\n      &lt;range&gt;\\n        &lt;min&gt;0.15&lt;/min&gt;\\n        &lt;max&gt;12.0&lt;/max&gt;\\n        &lt;resolution&gt;0.01&lt;/resolution&gt;\\n      &lt;/range&gt;\\n      &lt;noise&gt;\\n        &lt;type&gt;gaussian&lt;/type&gt;\\n        &lt;mean&gt;0.0&lt;/mean&gt;\\n        &lt;stddev&gt;0.01&lt;/stddev&gt; &lt;!-- 1cm simulated measurement noise --&gt;\\n      &lt;/noise&gt;\\n    &lt;/ray&gt;\\n    &lt;plugin name=&quot;navpro_laser_controller&quot; filename=&quot;libgazebo_ros_ray_sensor.so&quot;&gt;\\n      &lt;ros&gt;\\n        &lt;argument&gt;~/out:=scan&lt;/argument&gt;\\n      &lt;/ros&gt;\\n      &lt;output_type&gt;sensor_msgs/LaserScan&lt;/output_type&gt;\\n      &lt;frame_name&gt;laser_frame&lt;/frame_name&gt;\\n    &lt;/plugin&gt;\\n  &lt;/sensor&gt;\\n&lt;/gazebo&gt;</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-spawning-the-robot-into-gazebo\\">5. Spawning the Robot into Gazebo</h2>\\n<p>In <a href=\\"file:///home/chaitu/Projects/navpro_learning_hub/level1/ros2_ws/src/navpro_gazebo/launch/sim_world.launch.py\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\"><code class=\\"inline-code\\">launch/sim_world.launch.py</code></a>, the <code class=\\"inline-code\\">spawn_entity.py</code> script queries the <code class=\\"inline-code\\">/robot_description</code> topic and injects the model into the running physics world:</p>\\n<div class=\\"code-container\\" data-language=\\"python\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">PYTHON</span><button class=\\"copy-code-btn\\" data-code=\\"spawn_robot = Node(\\n    package=&#x27;gazebo_ros&#x27;,\\n    executable=&#x27;spawn_entity.py&#x27;,\\n    name=&#x27;spawn_navpro_robot&#x27;,\\n    output=&#x27;screen&#x27;,\\n    arguments=[\\n        &#x27;-topic&#x27;, &#x27;robot_description&#x27;,\\n        &#x27;-entity&#x27;, &#x27;navpro_mini&#x27;,\\n        &#x27;-x&#x27;, &#x27;0.0&#x27;,\\n        &#x27;-y&#x27;, &#x27;0.0&#x27;,\\n        &#x27;-z&#x27;, &#x27;0.05&#x27;\\n    ]\\n)\\">📋 Copy</button></div><pre><code class=\\"language-python\\">spawn_robot = Node(\\n    package=&#x27;gazebo_ros&#x27;,\\n    executable=&#x27;spawn_entity.py&#x27;,\\n    name=&#x27;spawn_navpro_robot&#x27;,\\n    output=&#x27;screen&#x27;,\\n    arguments=[\\n        &#x27;-topic&#x27;, &#x27;robot_description&#x27;,\\n        &#x27;-entity&#x27;, &#x27;navpro_mini&#x27;,\\n        &#x27;-x&#x27;, &#x27;0.0&#x27;,\\n        &#x27;-y&#x27;, &#x27;0.0&#x27;,\\n        &#x27;-z&#x27;, &#x27;0.05&#x27;\\n    ]\\n)</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-execution--verification\\">6. Execution &amp; Verification</h2>\\n<p>Launch the complete simulation:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"ros2 launch navpro_gazebo sim_world.launch.py\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">ros2 launch navpro_gazebo sim_world.launch.py</code></pre></div>\\n<p>In a second terminal, verify that sensor streams are active:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# 1. Check LiDAR scanning at 10 Hz\\nros2 topic hz /scan\\n\\n# 2. Check wheel odometry streaming at 50 Hz\\nros2 topic hz /odom\\n\\n# 3. Check IMU acceleration streaming at 50 Hz\\nros2 topic hz /imu/data\\n\\n# 4. Drive the robot forward in simulation!\\nros2 topic pub --once /cmd_vel geometry_msgs/msg/Twist &quot;{linear: {x: 0.3}, angular: {z: 0.0}}&quot;\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># 1. Check LiDAR scanning at 10 Hz\\nros2 topic hz /scan\\n\\n# 2. Check wheel odometry streaming at 50 Hz\\nros2 topic hz /odom\\n\\n# 3. Check IMU acceleration streaming at 50 Hz\\nros2 topic hz /imu/data\\n\\n# 4. Drive the robot forward in simulation!\\nros2 topic pub --once /cmd_vel geometry_msgs/msg/Twist &quot;{linear: {x: 0.3}, angular: {z: 0.0}}&quot;</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"7-hands-on-student-challenge\\">7. Hands-on Student Challenge</h2>\\n<p><strong>Task:</strong></p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Start teleoperation control:</li>\\n</ol>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"   ros2 run teleop_twist_keyboard teleop_twist_keyboard\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">   ros2 run teleop_twist_keyboard teleop_twist_keyboard</code></pre></div>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Drive the robot around the warehouse obstacles in Gazebo.</li>\\n<li>Open a second terminal and echo <code class=\\"inline-code\\">/scan</code>. Observe how range values decrease as you approach warehouse storage racks!</li>\\n</ol>","quizzes":[{"id":"q_l1_19_1","prompt":"Which Gazebo Harmonic sensor type is used to simulate a 2D planar LiDAR sensor (such as RPLidar or Hokuyo)?","options":["depth_camera","gpu_lidar (or gpu_ray)","imu","magnetometer"],"correct":1,"explanation":"gpu_lidar (formerly gpu_ray) uses GPU hardware acceleration to simulate laser rangefinder beams and publishes raw range data bridged to sensor_msgs/LaserScan."}],"has_quiz":true,"next_id":"lesson_20","prev_id":"lesson_18"},{"id":"lesson_20","num":20,"num_str":"20","title":"Building Custom Simulation Worlds in Gazebo","slug":"building_simulation_worlds","filename":"20_building_simulation_worlds.md","module":"3D Simulation & World Modeling","module_id":4,"duration":"45-60 min","focus":"SDF World Architecture, Physics Solver Tuning, Warehouse Modeling & Environment Assets","snapshot":[],"html_content":"<h1 id=\\"lesson-20-building-custom-simulation-worlds-in-gazebo\\">Lesson 20: Building Custom Simulation Worlds in Gazebo</h1>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Focus:</strong> SDF World Architecture, Physics Solver Tuning, Warehouse Modeling &amp; Environment Assets<br><strong>Course Track:</strong> NavPro Learning Hub - Level 1<br><strong>Target Environment:</strong> ROS 2 Jazzy Jalisco</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"1-overview--learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>Empty simulation worlds (an infinite flat plane with no features) are useless for testing navigation algorithms: LiDAR lasers find no objects to bounce off, and SLAM cannot extract geometric scan-matching features.</p>\\n<p>In this lesson, you will learn how to design, build, and configure rich 3D simulation environments using the <strong>SDF (Simulation Description Format)</strong> format.</p>\\n<p>By the end of this lesson, you will:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Understand the structural anatomy of an SDF <code class=\\"inline-code\\">.world</code> file.</li>\\n<li>Tune the ODE physics solver (<code class=\\"inline-code\\">max_step_size</code>, <code class=\\"inline-code\\">real_time_update_rate</code>, <code class=\\"inline-code\\">contact_surface_layer</code>) for stability.</li>\\n<li>Construct physical warehouse enclosures: outer perimeter walls, storage aisles, and charging docks.</li>\\n<li>Set default GUI user camera viewport coordinates to eliminate manual mouse panning at launch.</li>\\n<li>Load custom simulation environments dynamically using launch arguments.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-anatomy-of-an-sdf-world-file\\">2. Anatomy of an SDF World File</h2>\\n<p>A <code class=\\"inline-code\\">.world</code> file contains physics parameters, environmental lighting, and static models:</p>\\n<div class=\\"code-container\\" data-language=\\"xml\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">XML</span><button class=\\"copy-code-btn\\" data-code=\\"&lt;?xml version=&quot;1.0&quot; ?&gt;\\n&lt;sdf version=&quot;1.6&quot;&gt;\\n  &lt;world name=&quot;warehouse_obstacle_world&quot;&gt;\\n\\n    &lt;!-- 1. Physics Engine Configuration --&gt;\\n    &lt;physics name=&quot;default_physics&quot; default=&quot;0&quot; type=&quot;ode&quot;&gt;\\n      &lt;max_step_size&gt;0.001&lt;/max_step_size&gt;\\n      &lt;real_time_factor&gt;1.0&lt;/real_time_factor&gt;\\n      &lt;real_time_update_rate&gt;1000.0&lt;/real_time_update_rate&gt;\\n    &lt;/physics&gt;\\n\\n    &lt;!-- 2. Environmental Lighting &amp; Floor --&gt;\\n    &lt;include&gt;&lt;uri&gt;model://sun&lt;/uri&gt;&lt;/include&gt;\\n    &lt;include&gt;&lt;uri&gt;model://ground_plane&lt;/uri&gt;&lt;/include&gt;\\n\\n    &lt;!-- 3. Static Physical Structures (Walls &amp; Racks) --&gt;\\n    &lt;model name=&quot;warehouse_wall_north&quot;&gt;\\n      &lt;static&gt;true&lt;/static&gt;\\n      &lt;!-- Model definitions ... --&gt;\\n    &lt;/model&gt;\\n\\n    &lt;!-- 4. Default GUI Camera Angle --&gt;\\n    &lt;gui fullscreen=&#x27;0&#x27;&gt;\\n      &lt;camera name=&#x27;user_camera&#x27;&gt;\\n        &lt;pose&gt;0.0 -7.5 7.0 0 0.8 1.57&lt;/pose&gt;\\n        &lt;view_controller&gt;orbit&lt;/view_controller&gt;\\n      &lt;/camera&gt;\\n    &lt;/gui&gt;\\n\\n  &lt;/world&gt;\\n&lt;/sdf&gt;\\">📋 Copy</button></div><pre><code class=\\"language-xml\\">&lt;?xml version=&quot;1.0&quot; ?&gt;\\n&lt;sdf version=&quot;1.6&quot;&gt;\\n  &lt;world name=&quot;warehouse_obstacle_world&quot;&gt;\\n\\n    &lt;!-- 1. Physics Engine Configuration --&gt;\\n    &lt;physics name=&quot;default_physics&quot; default=&quot;0&quot; type=&quot;ode&quot;&gt;\\n      &lt;max_step_size&gt;0.001&lt;/max_step_size&gt;\\n      &lt;real_time_factor&gt;1.0&lt;/real_time_factor&gt;\\n      &lt;real_time_update_rate&gt;1000.0&lt;/real_time_update_rate&gt;\\n    &lt;/physics&gt;\\n\\n    &lt;!-- 2. Environmental Lighting &amp; Floor --&gt;\\n    &lt;include&gt;&lt;uri&gt;model://sun&lt;/uri&gt;&lt;/include&gt;\\n    &lt;include&gt;&lt;uri&gt;model://ground_plane&lt;/uri&gt;&lt;/include&gt;\\n\\n    &lt;!-- 3. Static Physical Structures (Walls &amp; Racks) --&gt;\\n    &lt;model name=&quot;warehouse_wall_north&quot;&gt;\\n      &lt;static&gt;true&lt;/static&gt;\\n      &lt;!-- Model definitions ... --&gt;\\n    &lt;/model&gt;\\n\\n    &lt;!-- 4. Default GUI Camera Angle --&gt;\\n    &lt;gui fullscreen=&#x27;0&#x27;&gt;\\n      &lt;camera name=&#x27;user_camera&#x27;&gt;\\n        &lt;pose&gt;0.0 -7.5 7.0 0 0.8 1.57&lt;/pose&gt;\\n        &lt;view_controller&gt;orbit&lt;/view_controller&gt;\\n      &lt;/camera&gt;\\n    &lt;/gui&gt;\\n\\n  &lt;/world&gt;\\n&lt;/sdf&gt;</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-physics-solver-tuning-for-robotics\\">3. Physics Solver Tuning for Robotics</h2>\\n<div class=\\"table-wrapper\\"><table>\\n<thead><tr>\\n<th>Parameter</th>\\n<th>Recommended Value</th>\\n<th>Purpose &amp; Impact</th>\\n</tr></thead><tbody>\\n<tr>\\n<td><code class=\\"inline-code\\">&lt;type&gt;</code></td>\\n<td><code class=\\"inline-code\\">ode</code></td>\\n<td>Open Dynamics Engine. Industry standard for rigid body mobile robot simulation.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">&lt;max_step_size&gt;</code></td>\\n<td><code class=\\"inline-code\\">0.001</code> (1 millisecond)</td>\\n<td>Integration time step. Smaller values increase simulation accuracy but require more CPU.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">&lt;real_time_update_rate&gt;</code></td>\\n<td><code class=\\"inline-code\\">1000.0</code></td>\\n<td>Number of solver steps per wall-clock second. With step size 0.001, this yields 100% real-time speed.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">&lt;sor&gt;</code></td>\\n<td><code class=\\"inline-code\\">1.3</code></td>\\n<td>Successive Over-Relaxation parameter (1.0 to 1.4) to stabilize joint contact forces.</td>\\n</tr>\\n</tbody></table></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-constructing-warehouse-elements\\">4. Constructing Warehouse Elements</h2>\\n<p>Open <a href=\\"file:///home/chaitu/Projects/navpro_learning_hub/level1/ros2_ws/src/navpro_gazebo/worlds/warehouse_obstacle_world.world\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\"><code class=\\"inline-code\\">worlds/warehouse_obstacle_world.world</code></a>:</p>\\n<h3 id=\\"41-boundary-walls-10m-x-10m-warehouse\\">4.1 Boundary Walls (10m x 10m Warehouse)</h3>\\n<p>Setting <code class=\\"inline-code\\">&lt;static&gt;true&lt;/static&gt;</code> tells the physics engine that the object is fixed to the world frame and cannot be moved by robot collisions:</p>\\n<div class=\\"code-container\\" data-language=\\"xml\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">XML</span><button class=\\"copy-code-btn\\" data-code=\\"&lt;model name=&quot;wall_north&quot;&gt;\\n  &lt;static&gt;true&lt;/static&gt;\\n  &lt;pose&gt;0 5.0 1.0 0 0 0&lt;/pose&gt;\\n  &lt;link name=&quot;link&quot;&gt;\\n    &lt;collision name=&quot;collision&quot;&gt;\\n      &lt;geometry&gt;&lt;box&gt;&lt;size&gt;10.2 0.2 2.0&lt;/size&gt;&lt;/box&gt;&lt;/geometry&gt;\\n    &lt;/collision&gt;\\n    &lt;visual name=&quot;visual&quot;&gt;\\n      &lt;geometry&gt;&lt;box&gt;&lt;size&gt;10.2 0.2 2.0&lt;/size&gt;&lt;/box&gt;&lt;/geometry&gt;\\n      &lt;material&gt;&lt;ambient&gt;0.7 0.7 0.7 1&lt;/ambient&gt;&lt;diffuse&gt;0.8 0.8 0.8 1&lt;/diffuse&gt;&lt;/material&gt;\\n    &lt;/visual&gt;\\n  &lt;/link&gt;\\n&lt;/model&gt;\\">📋 Copy</button></div><pre><code class=\\"language-xml\\">&lt;model name=&quot;wall_north&quot;&gt;\\n  &lt;static&gt;true&lt;/static&gt;\\n  &lt;pose&gt;0 5.0 1.0 0 0 0&lt;/pose&gt;\\n  &lt;link name=&quot;link&quot;&gt;\\n    &lt;collision name=&quot;collision&quot;&gt;\\n      &lt;geometry&gt;&lt;box&gt;&lt;size&gt;10.2 0.2 2.0&lt;/size&gt;&lt;/box&gt;&lt;/geometry&gt;\\n    &lt;/collision&gt;\\n    &lt;visual name=&quot;visual&quot;&gt;\\n      &lt;geometry&gt;&lt;box&gt;&lt;size&gt;10.2 0.2 2.0&lt;/size&gt;&lt;/box&gt;&lt;/geometry&gt;\\n      &lt;material&gt;&lt;ambient&gt;0.7 0.7 0.7 1&lt;/ambient&gt;&lt;diffuse&gt;0.8 0.8 0.8 1&lt;/diffuse&gt;&lt;/material&gt;\\n    &lt;/visual&gt;\\n  &lt;/link&gt;\\n&lt;/model&gt;</code></pre></div>\\n<h3 id=\\"42-storage-racks--pallet-aisles\\">4.2 Storage Racks &amp; Pallet Aisles</h3>\\n<div class=\\"code-container\\" data-language=\\"xml\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">XML</span><button class=\\"copy-code-btn\\" data-code=\\"&lt;model name=&quot;storage_rack_a&quot;&gt;\\n  &lt;static&gt;true&lt;/static&gt;\\n  &lt;pose&gt;-2.5 1.8 0.75 0 0 0&lt;/pose&gt;\\n  &lt;link name=&quot;link&quot;&gt;\\n    &lt;collision name=&quot;collision&quot;&gt;\\n      &lt;geometry&gt;&lt;box&gt;&lt;size&gt;3.0 0.8 1.5&lt;/size&gt;&lt;/box&gt;&lt;/geometry&gt;\\n    &lt;/collision&gt;\\n    &lt;visual name=&quot;visual&quot;&gt;\\n      &lt;geometry&gt;&lt;box&gt;&lt;size&gt;3.0 0.8 1.5&lt;/size&gt;&lt;/box&gt;&lt;/geometry&gt;\\n      &lt;material&gt;&lt;ambient&gt;0.2 0.4 0.8 1&lt;/ambient&gt;&lt;diffuse&gt;0.2 0.5 0.9 1&lt;/diffuse&gt;&lt;/material&gt;\\n    &lt;/visual&gt;\\n  &lt;/link&gt;\\n&lt;/model&gt;\\">📋 Copy</button></div><pre><code class=\\"language-xml\\">&lt;model name=&quot;storage_rack_a&quot;&gt;\\n  &lt;static&gt;true&lt;/static&gt;\\n  &lt;pose&gt;-2.5 1.8 0.75 0 0 0&lt;/pose&gt;\\n  &lt;link name=&quot;link&quot;&gt;\\n    &lt;collision name=&quot;collision&quot;&gt;\\n      &lt;geometry&gt;&lt;box&gt;&lt;size&gt;3.0 0.8 1.5&lt;/size&gt;&lt;/box&gt;&lt;/geometry&gt;\\n    &lt;/collision&gt;\\n    &lt;visual name=&quot;visual&quot;&gt;\\n      &lt;geometry&gt;&lt;box&gt;&lt;size&gt;3.0 0.8 1.5&lt;/size&gt;&lt;/box&gt;&lt;/geometry&gt;\\n      &lt;material&gt;&lt;ambient&gt;0.2 0.4 0.8 1&lt;/ambient&gt;&lt;diffuse&gt;0.2 0.5 0.9 1&lt;/diffuse&gt;&lt;/material&gt;\\n    &lt;/visual&gt;\\n  &lt;/link&gt;\\n&lt;/model&gt;</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-viewport-camera-positioning\\">5. Viewport Camera Positioning</h2>\\n<p>You can preset the initial perspective of the Gazebo 3D camera so you don&#x27;t have to reposition it every time:</p>\\n<div class=\\"code-container\\" data-language=\\"xml\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">XML</span><button class=\\"copy-code-btn\\" data-code=\\"&lt;gui fullscreen=&#x27;0&#x27;&gt;\\n  &lt;camera name=&#x27;user_camera&#x27;&gt;\\n    &lt;!-- &lt;pose&gt; X Y Z Roll Pitch Yaw &lt;/pose&gt; --&gt;\\n    &lt;pose&gt;0.0 -7.5 7.0 0 0.8 1.57&lt;/pose&gt;\\n    &lt;view_controller&gt;orbit&lt;/view_controller&gt;\\n  &lt;/camera&gt;\\n&lt;/gui&gt;\\">📋 Copy</button></div><pre><code class=\\"language-xml\\">&lt;gui fullscreen=&#x27;0&#x27;&gt;\\n  &lt;camera name=&#x27;user_camera&#x27;&gt;\\n    &lt;!-- &lt;pose&gt; X Y Z Roll Pitch Yaw &lt;/pose&gt; --&gt;\\n    &lt;pose&gt;0.0 -7.5 7.0 0 0.8 1.57&lt;/pose&gt;\\n    &lt;view_controller&gt;orbit&lt;/view_controller&gt;\\n  &lt;/camera&gt;\\n&lt;/gui&gt;</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-hands-on-student-challenge\\">6. Hands-on Student Challenge</h2>\\n<p><strong>Task:</strong></p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Open <a href=\\"file:///home/chaitu/Projects/navpro_learning_hub/level1/ros2_ws/src/navpro_gazebo/worlds/warehouse_obstacle_world.world\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\"><code class=\\"inline-code\\">warehouse_obstacle_world.world</code></a>.</li>\\n<li>Add a new cylindrical obstacle named <code class=\\"inline-code\\">inspection_target_pillar</code> at coordinates $(x = -2.0, y = 0.0, z = 0.5)$ with radius <code class=\\"inline-code\\">0.2m</code> and height <code class=\\"inline-code\\">1.0m</code>.</li>\\n<li>Set its material color to Red (<code class=\\"inline-code\\">&lt;diffuse&gt;1.0 0.1 0.1 1&lt;/diffuse&gt;</code>).</li>\\n<li>Re-launch <code class=\\"inline-code\\">ros2 launch navpro_gazebo sim_world.launch.py</code> and verify your new pillar appears in the simulation!</li>\\n</ol>","quizzes":[{"id":"q_l1_20_1","prompt":"What XML format is used to define Gazebo worlds, lighting, gravity, and static warehouse obstacles?","options":["URDF","SDF (Simulation Description Format)","YAML","JSON"],"correct":1,"explanation":"SDF (Simulation Description Format) describes entire simulation environments including physics engines, terrain heights, sun models, friction, and multiple robot models."}],"has_quiz":true,"next_id":"lesson_21","prev_id":"lesson_19"},{"id":"lesson_21","num":21,"num_str":"21","title":"2D LiDAR SLAM Mapping with SLAM Toolbox","slug":"2d_slam_mapping_slam_toolbox","filename":"21_2d_slam_mapping_slam_toolbox.md","module":"Autonomous Navigation with Nav2","module_id":5,"duration":"45-60 min","focus":"2D Occupancy Grid Mapping, Pose Graph Optimization, Loop Closure & Map Serialization","snapshot":[["2D Cartography & SLAM","Simultaneously computes robot pose while mapping an unknown environment using LiDAR scan matching."],["Loop Closure","Recognizes previously visited locations to cancel out accumulated odometry drift using non-linear pose-graph optimization."]],"html_content":"<h1 id=\\"lesson-21-2d-lidar-slam-mapping-with-slam-toolbox\\">Lesson 21: 2D LiDAR SLAM Mapping with SLAM Toolbox</h1>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Focus:</strong> 2D Occupancy Grid Mapping, Pose Graph Optimization, Loop Closure &amp; Map Serialization<br><strong>Course Track:</strong> NavPro Learning Hub - Level 1<br><strong>Target Environment:</strong> ROS 2 Jazzy Jalisco</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"1-overview--learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>Before an autonomous mobile robot can plan collision-free paths, it requires a topological model of its operating space. <strong>SLAM (Simultaneous Localization and Mapping)</strong> solves the &quot;chicken-or-egg&quot; problem: the robot must construct a map while simultaneously using that partial map to estimate its own position.</p>\\n<p>In ROS 2, <strong>SLAM Toolbox</strong> is the industry-standard mapping engine, replacing legacy ROS 1 Gmapping and Cartographer.</p>\\n<p>By the end of this lesson, you will:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Understand the core principles of Graph-Based LiDAR SLAM: scan matching, pose graphs, and loop closures.</li>\\n<li>Configure <code class=\\"inline-code\\">slam_toolbox.yaml</code> for online asynchronous mapping.</li>\\n<li>Drive the simulated NavPro robot to map a 10m x 10m warehouse environment.</li>\\n<li>Trigger a <strong>Loop Closure</strong> to mathematically eliminate accumulated odometry drift.</li>\\n<li>Export and serialize the generated map into <code class=\\"inline-code\\">.yaml</code> and <code class=\\"inline-code\\">.pgm</code> assets using <code class=\\"inline-code\\">nav2_map_server</code>.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-graph-slam-architecture\\">2. Graph SLAM Architecture</h2>\\n<div class=\\"lesson-image-wrapper\\"><img src=\\"assets/images/graph_slam_pipeline.svg\\" alt=\\"Graph SLAM Architecture &amp; Loop Closure\\" class=\\"lesson-image\\" loading=\\"lazy\\"><span class=\\"image-caption\\">Graph SLAM Architecture &amp; Loop Closure</span></div>\\n<ul class=\\"lesson-bullet-list\\">\\n<li><strong>Front-End (Scan Matcher):</strong> Correlates incoming LiDAR beams with previous scans to compute local incremental movements.</li>\\n<li><strong>Back-End (Graph Optimizer):</strong> Builds a network of historical robot poses. When the robot re-enters a previously visited location (<strong>Loop Closure</strong>), a Ceres non-linear solver distributes error across the graph to snap the map straight.</li>\\n</ul>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-deep-dive-configslam_toolboxyaml\\">3. Deep Dive: <code class=\\"inline-code\\">config/slam_toolbox.yaml</code></h2>\\n<p>Open <a href=\\"file:///home/chaitu/Projects/navpro_learning_hub/level1/ros2_ws/src/navpro_navigation/config/slam_toolbox.yaml\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\"><code class=\\"inline-code\\">config/slam_toolbox.yaml</code></a>:</p>\\n<div class=\\"code-container\\" data-language=\\"yaml\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">YAML</span><button class=\\"copy-code-btn\\" data-code=\\"slam_toolbox:\\n  ros__parameters:\\n    # Solver Parameters\\n    solver_plugin: solver_plugins::CeresSolver\\n    ceres_linear_solver: SPARSE_NORMAL_CHOLESKY\\n    \\n    # Coordinate Frames\\n    odom_frame: odom\\n    map_frame: map\\n    base_frame: base_footprint\\n    scan_topic: /scan\\n    mode: mapping\\n\\n    # Map Resolution &amp; Range\\n    resolution: 0.05                  # 5 centimeters per pixel\\n    max_laser_range: 12.0             # Discard LiDAR reflections beyond 12m\\n    minimum_time_interval: 0.2        # Don&#x27;t add nodes faster than 5 Hz\\n    minimum_travel_distance: 0.2      # Add new pose graph node every 20cm\\n    minimum_travel_heading: 0.2       # Add new pose graph node every ~11 degrees\\n\\n    # Loop Closure Tuning\\n    do_loop_closing: true             # Enable automatic loop closure\\n    loop_search_maximum_distance: 3.0 # Search within 3.0m radius for known features\\n    loop_match_minimum_chain_size: 10\\">📋 Copy</button></div><pre><code class=\\"language-yaml\\">slam_toolbox:\\n  ros__parameters:\\n    # Solver Parameters\\n    solver_plugin: solver_plugins::CeresSolver\\n    ceres_linear_solver: SPARSE_NORMAL_CHOLESKY\\n    \\n    # Coordinate Frames\\n    odom_frame: odom\\n    map_frame: map\\n    base_frame: base_footprint\\n    scan_topic: /scan\\n    mode: mapping\\n\\n    # Map Resolution &amp; Range\\n    resolution: 0.05                  # 5 centimeters per pixel\\n    max_laser_range: 12.0             # Discard LiDAR reflections beyond 12m\\n    minimum_time_interval: 0.2        # Don&#x27;t add nodes faster than 5 Hz\\n    minimum_travel_distance: 0.2      # Add new pose graph node every 20cm\\n    minimum_travel_heading: 0.2       # Add new pose graph node every ~11 degrees\\n\\n    # Loop Closure Tuning\\n    do_loop_closing: true             # Enable automatic loop closure\\n    loop_search_maximum_distance: 3.0 # Search within 3.0m radius for known features\\n    loop_match_minimum_chain_size: 10</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-step-by-step-mapping-workflow\\">4. Step-by-Step Mapping Workflow</h2>\\n<h3 id=\\"step-41-launch-simulation\\">Step 4.1: Launch Simulation</h3>\\n<p>Terminal 1:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"ros2 launch navpro_gazebo sim_world.launch.py\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">ros2 launch navpro_gazebo sim_world.launch.py</code></pre></div>\\n<h3 id=\\"step-42-launch-slam-toolbox\\">Step 4.2: Launch SLAM Toolbox</h3>\\n<p>Terminal 2:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"ros2 launch navpro_navigation slam.launch.py\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">ros2 launch navpro_navigation slam.launch.py</code></pre></div>\\n<p><em>RViz2 will open, showing the initial 2D occupancy grid growing in real time.</em></p>\\n<h3 id=\\"step-43-drive-the-robot\\">Step 4.3: Drive the Robot</h3>\\n<p>Terminal 3:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"ros2 run teleop_twist_keyboard teleop_twist_keyboard\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">ros2 run teleop_twist_keyboard teleop_twist_keyboard</code></pre></div>\\n<p><em>Drive the robot slowly (0.2 m/s) through all warehouse aisles. Ensure you complete full loops back to the starting point to trigger loop closures!</em></p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-saving-the-map\\">5. Saving the Map</h2>\\n<p>Once all warehouse walls and obstacles are sharply defined, serialize the map:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"mkdir -p ~/ros2_ws/src/navpro_navigation/maps\\ncd ~/ros2_ws/src/navpro_navigation/maps\\n\\n# Save map as warehouse_map.yaml and warehouse_map.pgm\\nros2 run nav2_map_server map_saver_cli -f warehouse_map\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">mkdir -p ~/ros2_ws/src/navpro_navigation/maps\\ncd ~/ros2_ws/src/navpro_navigation/maps\\n\\n# Save map as warehouse_map.yaml and warehouse_map.pgm\\nros2 run nav2_map_server map_saver_cli -f warehouse_map</code></pre></div>\\n<h3 id=\\"51-understanding-the-map-output-files\\">5.1 Understanding the Map Output Files:</h3>\\n<ol class=\\"lesson-ordered-list\\">\\n<li><strong><code class=\\"inline-code\\">warehouse_map.pgm</code>:</strong> A Portable Graymap image where each pixel represents a cell:</li>\\n</ol>\\n<ul class=\\"lesson-bullet-list\\">\\n<li>Pixel value <code class=\\"inline-code\\">254</code> (White): Free navigable space.</li>\\n<li>Pixel value <code class=\\"inline-code\\">0</code> (Black): Occupied obstacle (wall, rack).</li>\\n<li>Pixel value <code class=\\"inline-code\\">205</code> (Gray): Unknown unexplored space.</li>\\n</ul>\\n<ol class=\\"lesson-ordered-list\\">\\n<li><strong><code class=\\"inline-code\\">warehouse_map.yaml</code>:</strong></li>\\n</ol>\\n<div class=\\"code-container\\" data-language=\\"yaml\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">YAML</span><button class=\\"copy-code-btn\\" data-code=\\"   image: warehouse_map.pgm\\n   resolution: 0.050000        # 0.05 meters (5cm) per pixel\\n   origin: [-5.0, -5.0, 0.0]   # Lower-left corner coordinates (x, y, yaw) in world frame\\n   negate: 0\\n   occupied_thresh: 0.65\\n   free_thresh: 0.196\\">📋 Copy</button></div><pre><code class=\\"language-yaml\\">   image: warehouse_map.pgm\\n   resolution: 0.050000        # 0.05 meters (5cm) per pixel\\n   origin: [-5.0, -5.0, 0.0]   # Lower-left corner coordinates (x, y, yaw) in world frame\\n   negate: 0\\n   occupied_thresh: 0.65\\n   free_thresh: 0.196</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-hands-on-student-challenge\\">6. Hands-on Student Challenge</h2>\\n<p><strong>Task:</strong></p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Open the saved <code class=\\"inline-code\\">warehouse_map.pgm</code> in an image viewer.</li>\\n<li>Verify that straight walls in Gazebo appear as crisp, non-blurred straight lines in the map.</li>\\n<li>If walls appear doubled or curved, review Section 3: reduce <code class=\\"inline-code\\">resolution</code> or drive the robot more smoothly to allow the scan matcher to converge!</li>\\n</ol>","quizzes":[{"id":"q_l1_21_1","prompt":"What algorithm architecture does 'SLAM Toolbox' use to solve 2D mapping and loop closure?","options":["Particle filtering (Gmapping)","Pose-graph optimization with scan-matching and Ceres solver","Extended Kalman Filter (EKF)","Deep reinforcement learning"],"correct":1,"explanation":"SLAM Toolbox uses graph-based SLAM. It creates pose graphs with scan-matching constraints and executes non-linear graph optimization using the Ceres solver to resolve loop closures."}],"has_quiz":true,"next_id":"lesson_22","prev_id":"lesson_20"},{"id":"lesson_22","num":22,"num_str":"22","title":"Nav2 Stack Architecture & Costmap 2D Configuration","slug":"nav2_architecture_and_costmaps","filename":"22_nav2_architecture_and_costmaps.md","module":"Autonomous Navigation with Nav2","module_id":5,"duration":"45-60 min","focus":"Navigation2 Server Architecture, Costmap 2D Layers, Inflation Math & Safety Buffers","snapshot":[["Nav2 Costmap Layers","Layered 2D occupancy grids combining Static Map, Obstacle Raytracing, and Inflation Safety Gradients."],["Cost Decay Gradient","Exponentially penalizes trajectories close to physical obstacles to keep the robot safely centered in corridors."]],"html_content":"<h1 id=\\"lesson-22-nav2-stack-architecture--costmap-2d-configuration\\">Lesson 22: Nav2 Stack Architecture &amp; Costmap 2D Configuration</h1>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Focus:</strong> Navigation2 Server Architecture, Costmap 2D Layers, Inflation Math &amp; Safety Buffers<br><strong>Course Track:</strong> NavPro Learning Hub - Level 1<br><strong>Target Environment:</strong> ROS 2 Jazzy Jalisco</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"1-overview--learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>Now that we have a static map and filtered odometry, we introduce <strong>Nav2 (Navigation 2)</strong>—the production-grade autonomous path planning and execution system for mobile robots.</p>\\n<p>Nav2 does not rely on a monolithic node; it employs a modular, server-based architecture orchestrated by <strong>Behavior Trees</strong>.</p>\\n<p>By the end of this lesson, you will:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Understand the core Nav2 architecture: Planner Server, Controller Server, BT Navigator, and Behavior Server.</li>\\n<li>Master <strong>Costmap 2D</strong>: how robots model navigable and non-navigable space.</li>\\n<li>Configure the three standard Costmap layers: <strong>Static Layer</strong>, <strong>Obstacle Layer</strong>, and <strong>Inflation Layer</strong>.</li>\\n<li>Understand the mathematical formula governing obstacle inflation and safety zones.</li>\\n<li>Define robot footprints to prevent clipping corners in narrow warehouse aisles.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-the-nav2-server-architecture\\">2. The Nav2 Server Architecture</h2>\\n<div class=\\"lesson-image-wrapper\\"><img src=\\"assets/images/nav2_server_architecture.svg\\" alt=\\"Nav2 Server Architecture\\" class=\\"lesson-image\\" loading=\\"lazy\\"><span class=\\"image-caption\\">Nav2 Server Architecture</span></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-costmap-2d-layered-representation\\">3. Costmap 2D: Layered Representation</h2>\\n<p>A Costmap represents space as an occupancy grid where each cell is assigned a cost between <code class=\\"inline-code\\">0</code> (Completely Free) and <code class=\\"inline-code\\">254</code> (Lethal Obstacle):</p>\\n<div class=\\"lesson-image-wrapper\\"><img src=\\"assets/images/costmap_inflation_layers.svg\\" alt=\\"Nav2 Costmap 2D Inflation Layers\\" class=\\"lesson-image\\" loading=\\"lazy\\"><span class=\\"image-caption\\">Nav2 Costmap 2D Inflation Layers</span></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-inflation-layer-mathematics-the-safety-buffer\\">4. Inflation Layer Mathematics: The Safety Buffer</h2>\\n<p>The <strong>Inflation Layer</strong> prevents robots from skimming too close to walls. It assigns costs according to distance from the nearest lethal obstacle:</p>\\n<p>$$\\\\text{cost} = \\\\exp\\\\left(-\\\\text{cost\\\\_scaling\\\\_factor} \\\\times (\\\\text{distance} - \\\\text{robot\\\\_radius})\\\\right) \\\\times 253$$</p>\\n<ul class=\\"lesson-bullet-list\\">\\n<li><code class=\\"inline-code\\">robot_radius</code>: Radius of the circular robot footprint (e.g. <code class=\\"inline-code\\">0.25m</code>).</li>\\n<li><code class=\\"inline-code\\">inflation_radius</code>: Outer boundary of the safety zone (e.g. <code class=\\"inline-code\\">0.55m</code>). Outside this distance, cost is <code class=\\"inline-code\\">0</code>.</li>\\n<li><code class=\\"inline-code\\">cost_scaling_factor</code>: Exponential decay rate (e.g. <code class=\\"inline-code\\">3.0</code>). Higher values drop the cost faster, encouraging paths closer to obstacles. Lower values force the robot to stay strictly centered in aisles.</li>\\n</ul>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-global-vs-local-costmap-configuration\\">5. Global vs. Local Costmap Configuration</h2>\\n<p>Open <a href=\\"file:///home/chaitu/Projects/navpro_learning_hub/level1/ros2_ws/src/navpro_navigation/config/nav2_params.yaml\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\"><code class=\\"inline-code\\">config/nav2_params.yaml</code></a>:</p>\\n<h3 id=\\"51-global-costmap\\">5.1 Global Costmap:</h3>\\n<p>Used by the Global Planner to compute complete long-range paths across the whole building:</p>\\n<div class=\\"code-container\\" data-language=\\"yaml\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">YAML</span><button class=\\"copy-code-btn\\" data-code=\\"global_costmap:\\n  global_costmap:\\n    ros__parameters:\\n      global_frame: map\\n      robot_base_frame: base_footprint\\n      robot_radius: 0.25\\n      resolution: 0.05\\n      track_unknown_space: true\\n      plugins: [&quot;static_layer&quot;, &quot;obstacle_layer&quot;, &quot;inflation_layer&quot;]\\">📋 Copy</button></div><pre><code class=\\"language-yaml\\">global_costmap:\\n  global_costmap:\\n    ros__parameters:\\n      global_frame: map\\n      robot_base_frame: base_footprint\\n      robot_radius: 0.25\\n      resolution: 0.05\\n      track_unknown_space: true\\n      plugins: [&quot;static_layer&quot;, &quot;obstacle_layer&quot;, &quot;inflation_layer&quot;]</code></pre></div>\\n<h3 id=\\"52-local-costmap\\">5.2 Local Costmap:</h3>\\n<p>A small, high-frequency <strong>rolling window</strong> (e.g. 3m x 3m centered on the robot) used by the local controller to dodge walking humans and moving forklifts:</p>\\n<div class=\\"code-container\\" data-language=\\"yaml\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">YAML</span><button class=\\"copy-code-btn\\" data-code=\\"local_costmap:\\n  local_costmap:\\n    ros__parameters:\\n      global_frame: odom\\n      robot_base_frame: base_footprint\\n      rolling_window: true    # Moves with the robot!\\n      width: 3\\n      height: 3\\n      resolution: 0.05\\n      plugins: [&quot;obstacle_layer&quot;, &quot;inflation_layer&quot;]\\">📋 Copy</button></div><pre><code class=\\"language-yaml\\">local_costmap:\\n  local_costmap:\\n    ros__parameters:\\n      global_frame: odom\\n      robot_base_frame: base_footprint\\n      rolling_window: true    # Moves with the robot!\\n      width: 3\\n      height: 3\\n      resolution: 0.05\\n      plugins: [&quot;obstacle_layer&quot;, &quot;inflation_layer&quot;]</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-hands-on-student-challenge\\">6. Hands-on Student Challenge</h2>\\n<p><strong>Task:</strong></p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Open <a href=\\"file:///home/chaitu/Projects/navpro_learning_hub/level1/ros2_ws/src/navpro_navigation/config/nav2_params.yaml\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\"><code class=\\"inline-code\\">nav2_params.yaml</code></a>.</li>\\n<li>Locate <code class=\\"inline-code\\">local_costmap -&gt; inflation_layer -&gt; cost_scaling_factor</code>.</li>\\n<li>Change <code class=\\"inline-code\\">cost_scaling_factor</code> from <code class=\\"inline-code\\">3.0</code> to <code class=\\"inline-code\\">5.0</code>.</li>\\n<li>Observe in RViz2 how the cost gradient bands around obstacles become narrower, allowing the AMR to pass through tighter doorways!</li>\\n</ol>","quizzes":[{"id":"q_l1_22_1","prompt":"In Nav2 Costmap 2D, what is the role of the Inflation Layer?","options":["It compresses the map image size for network bandwidth","It expands obstacle boundaries by the robot's inscribed radius and applies exponential decay costs to prevent the robot from brushing against walls","It dynamically updates the battery level","It recalculates motor wheel PID gains"],"correct":1,"explanation":"The Inflation Layer propagates lethal obstacle costs outward by robot radius + inflation radius, penalizing paths too close to physical obstacles and preventing side collisions."}],"has_quiz":true,"next_id":"lesson_23","prev_id":"lesson_21"},{"id":"lesson_23","num":23,"num_str":"23","title":"Nav2 Path Planners & Local Controller Tuning","slug":"nav2_planners_controllers_tuning","filename":"23_nav2_planners_controllers_tuning.md","module":"Autonomous Navigation with Nav2","module_id":5,"duration":"45-60 min","focus":"Global Planners (Smac/NavFn), DWB Trajectory Rollouts, Critic Scoring & Pure Pursuit","snapshot":[],"html_content":"<h1 id=\\"lesson-23-nav2-path-planners--local-controller-tuning\\">Lesson 23: Nav2 Path Planners &amp; Local Controller Tuning</h1>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Focus:</strong> Global Planners (Smac/NavFn), DWB Trajectory Rollouts, Critic Scoring &amp; Pure Pursuit<br><strong>Course Track:</strong> NavPro Learning Hub - Level 1<br><strong>Target Environment:</strong> ROS 2 Jazzy Jalisco</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"1-overview--learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>Autonomous navigation is a two-tier problem:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li><strong>Global Planning:</strong> &quot;How do I get from Warehouse Dock A to Packaging Shelf 4 across the whole building?&quot; (Computed once at 1 Hz).</li>\\n<li><strong>Local Control:</strong> &quot;How do I turn my wheels right now at 20 Hz to follow that line while dodging a pallet jack that just entered my path?&quot;</li>\\n</ol>\\n<p>By the end of this lesson, you will:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Understand the difference between Global Path Planning (NavFn / Smac) and Local Trajectory Control (DWB / Regulated Pure Pursuit).</li>\\n<li>Master the <strong>DWB Local Planner Critic Scoring Algorithm</strong>.</li>\\n<li>Tune DWB critics (<code class=\\"inline-code\\">PathAlign</code>, <code class=\\"inline-code\\">GoalDist</code>, <code class=\\"inline-code\\">BaseObstacle</code>, <code class=\\"inline-code\\">RotateToGoal</code>) to control robot aggression and smoothness.</li>\\n<li>Set position (<code class=\\"inline-code\\">xy_goal_tolerance</code>) and orientation (<code class=\\"inline-code\\">yaw_goal_tolerance</code>) convergence thresholds.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-planners-vs-controllers-the-two-tier-paradigm\\">2. Planners vs. Controllers: The Two-Tier Paradigm</h2>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"                   GLOBAL PLANNER (Navfn / Smac)\\n                   Runs at 1-2 Hz. Computes static line\\n                   of waypoints from Start to Goal.\\n                               |\\n                               | Global Path: /plan\\n                               v\\n                  LOCAL CONTROLLER (DWB / RPP)\\n                  Runs at 20 Hz. Generates candidate\\n                  velocity arcs, avoids obstacles, outputs:\\n                               |\\n                               | Motor Commands: /cmd_vel\\n                               v\\n                     DIFFERENTIAL DRIVE ROBOT\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">                   GLOBAL PLANNER (Navfn / Smac)\\n                   Runs at 1-2 Hz. Computes static line\\n                   of waypoints from Start to Goal.\\n                               |\\n                               | Global Path: /plan\\n                               v\\n                  LOCAL CONTROLLER (DWB / RPP)\\n                  Runs at 20 Hz. Generates candidate\\n                  velocity arcs, avoids obstacles, outputs:\\n                               |\\n                               | Motor Commands: /cmd_vel\\n                               v\\n                     DIFFERENTIAL DRIVE ROBOT</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-dwb-local-planner-trajectory-rollout--critic-scoring\\">3. DWB Local Planner: Trajectory Rollout &amp; Critic Scoring</h2>\\n<p>The <strong>DWB Local Planner</strong> evaluates dozens of potential velocity trajectories $(v_x, \\\\omega_z)$ projected forward in time (<code class=\\"inline-code\\">sim_time = 1.7s</code>):</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"                               DWB TRAJECTORY SCORING\\n                               \\n                                          Arc 1 (Too close to wall -&gt; PENALTY)\\n                                       .-&#x27;\\n                         Robot       .&#x27;   Arc 2 (Follows path smoothly -&gt; BEST SCORE)\\n                         [===] =====+\\n                                     \`.   Arc 3 (Drifts away from path -&gt; PENALTY)\\n                                       \`-.\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">                               DWB TRAJECTORY SCORING\\n                               \\n                                          Arc 1 (Too close to wall -&gt; PENALTY)\\n                                       .-&#x27;\\n                         Robot       .&#x27;   Arc 2 (Follows path smoothly -&gt; BEST SCORE)\\n                         [===] =====+\\n                                     \`.   Arc 3 (Drifts away from path -&gt; PENALTY)\\n                                       \`-.</code></pre></div>\\n<p>Every trajectory arc is scored against an ensemble of mathematical <strong>Critics</strong>:</p>\\n<p>$$\\\\text{Total Score} = \\\\sum_{i} \\\\left( \\\\text{weight}_i \\\\times \\\\text{critic\\\\_cost}_i \\\\right)$$</p>\\n<p>The trajectory with the lowest overall penalty cost is selected and published to <code class=\\"inline-code\\">/cmd_vel</code>!</p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-key-dwb-critics--tuning-matrix\\">4. Key DWB Critics &amp; Tuning Matrix</h2>\\n<p>Open <a href=\\"file:///home/chaitu/Projects/navpro_learning_hub/level1/ros2_ws/src/navpro_navigation/config/nav2_params.yaml\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\"><code class=\\"inline-code\\">config/nav2_params.yaml</code></a>:</p>\\n<div class=\\"code-container\\" data-language=\\"yaml\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">YAML</span><button class=\\"copy-code-btn\\" data-code=\\"controller_server:\\n  ros__parameters:\\n    FollowPath:\\n      plugin: &quot;dwb_core::DWBLocalPlanner&quot;\\n      max_vel_x: 0.5\\n      max_vel_theta: 1.0\\n      sim_time: 1.7\\n      vx_samples: 20\\n      vtheta_samples: 20\\n      critics: [&quot;RotateToGoal&quot;, &quot;BaseObstacle&quot;, &quot;PathAlign&quot;, &quot;GoalDist&quot;]\\n\\n      BaseObstacle.scale: 0.02\\n      PathAlign.scale: 32.0\\n      GoalDist.scale: 24.0\\n      RotateToGoal.scale: 32.0\\">📋 Copy</button></div><pre><code class=\\"language-yaml\\">controller_server:\\n  ros__parameters:\\n    FollowPath:\\n      plugin: &quot;dwb_core::DWBLocalPlanner&quot;\\n      max_vel_x: 0.5\\n      max_vel_theta: 1.0\\n      sim_time: 1.7\\n      vx_samples: 20\\n      vtheta_samples: 20\\n      critics: [&quot;RotateToGoal&quot;, &quot;BaseObstacle&quot;, &quot;PathAlign&quot;, &quot;GoalDist&quot;]\\n\\n      BaseObstacle.scale: 0.02\\n      PathAlign.scale: 32.0\\n      GoalDist.scale: 24.0\\n      RotateToGoal.scale: 32.0</code></pre></div>\\n<div class=\\"table-wrapper\\"><table>\\n<thead><tr>\\n<th>Critic Name</th>\\n<th>What it Rewards / Penalizes</th>\\n<th>If Weight is Too High</th>\\n<th>If Weight is Too Low</th>\\n</tr></thead><tbody>\\n<tr>\\n<td><strong><code class=\\"inline-code\\">BaseObstacle</code></strong></td>\\n<td>Heavy penalty if trajectory intersects costmap obstacles</td>\\n<td>Robot is overly timid, freezes near doorways</td>\\n<td>Robot clips corners and collides with racks</td>\\n</tr>\\n<tr>\\n<td><strong><code class=\\"inline-code\\">PathAlign</code></strong></td>\\n<td>Rewards pointing the robot chassis along the global path vector</td>\\n<td>Robot strictly adheres to path, struggles to steer around dynamic obstacles</td>\\n<td>Robot cuts corners recklessly</td>\\n</tr>\\n<tr>\\n<td><strong><code class=\\"inline-code\\">GoalDist</code></strong></td>\\n<td>Pulls the robot toward the final goal point</td>\\n<td>Robot ignores global path and tries to drive directly through obstacles</td>\\n<td>Robot crawls sluggishly near the goal</td>\\n</tr>\\n<tr>\\n<td><strong><code class=\\"inline-code\\">RotateToGoal</code></strong></td>\\n<td>Rewards rotating in place to match the final heading</td>\\n<td>Robot slows down prematurely to rotate</td>\\n<td>Robot reaches coordinate but stops facing the wrong direction</td>\\n</tr>\\n</tbody></table></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-regulated-pure-pursuit-rpp\\">5. Regulated Pure Pursuit (RPP)</h2>\\n<p>For industrial AMR and AGV applications where robots must strictly follow designated one-way warehouse lanes without cutting corners, Nav2 offers the <strong>Regulated Pure Pursuit Controller</strong>:</p>\\n<div class=\\"code-container\\" data-language=\\"yaml\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">YAML</span><button class=\\"copy-code-btn\\" data-code=\\"FollowPath:\\n  plugin: &quot;nav2_regulated_pure_pursuit_controller::RegulatedPurePursuitController&quot;\\n  desired_linear_vel: 0.5\\n  lookahead_dist: 0.6\\n  min_lookahead_dist: 0.3\\n  max_lookahead_dist: 0.9\\n  use_regulated_linear_velocity_scaling: true\\">📋 Copy</button></div><pre><code class=\\"language-yaml\\">FollowPath:\\n  plugin: &quot;nav2_regulated_pure_pursuit_controller::RegulatedPurePursuitController&quot;\\n  desired_linear_vel: 0.5\\n  lookahead_dist: 0.6\\n  min_lookahead_dist: 0.3\\n  max_lookahead_dist: 0.9\\n  use_regulated_linear_velocity_scaling: true</code></pre></div>\\n<ul class=\\"lesson-bullet-list\\">\\n<li>Automatically scales speed down as path curvature increases (slows down smoothly for tight 90-degree turns).</li>\\n</ul>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-hands-on-student-challenge\\">6. Hands-on Student Challenge</h2>\\n<p><strong>Task:</strong></p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>In <code class=\\"inline-code\\">nav2_params.yaml</code>, modify <code class=\\"inline-code\\">general_goal_checker</code>:</li>\\n</ol>\\n<ul class=\\"lesson-bullet-list\\">\\n<li>Set <code class=\\"inline-code\\">xy_goal_tolerance: 0.10</code> (10cm precision).</li>\\n<li>Set <code class=\\"inline-code\\">yaw_goal_tolerance: 0.15</code> (~8.5 degrees precision).</li>\\n</ul>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Launch navigation:</li>\\n</ol>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"   ros2 launch navpro_navigation navigation.launch.py\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">   ros2 launch navpro_navigation navigation.launch.py</code></pre></div>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Use the RViz2 <strong>2D Goal Pose</strong> tool to command a goal. Observe how precisely the robot stops at the target pose!</li>\\n</ol>","quizzes":[{"id":"q_l1_23_1","prompt":"Which Nav2 component is responsible for high-frequency (e.g. 20Hz) obstacle avoidance and outputting /cmd_vel motor commands?","options":["Global Planner (e.g. NavFn or SmacPlanner)","Local Controller (e.g. DWB or Regulated Pure Pursuit)","Costmap 2D Static Layer","Lifecycle Manager"],"correct":1,"explanation":"The Controller (Local Planner) runs at high frequency (20Hz), tracking the global path while dynamically dodging local obstacles and publishing velocity commands to /cmd_vel."}],"has_quiz":true,"next_id":"lesson_24","prev_id":"lesson_22"},{"id":"lesson_24","num":24,"num_str":"24","title":"Behavior Trees, Recovery Behaviors & Lifecycle Management","slug":"nav2_behavior_trees_and_recoveries","filename":"24_nav2_behavior_trees_and_recoveries.md","module":"Autonomous Navigation with Nav2","module_id":5,"duration":"45-60 min","focus":"BT Navigator Engine, Recovery Plugins (Spin, BackUp, Wait) & Lifecycle State Machines","snapshot":[["Behavior Trees (BT)","Hierarchical tree execution enabling reactive autonomous decision-making and recovery behaviors."],["Control Nodes","Fallbacks (Selector = OR logic for recoveries), Sequences (AND logic for navigation steps), and Action/Condition leaves."]],"html_content":"<h1 id=\\"lesson-24-behavior-trees-recovery-behaviors--lifecycle-management\\">Lesson 24: Behavior Trees, Recovery Behaviors &amp; Lifecycle Management</h1>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Focus:</strong> BT Navigator Engine, Recovery Plugins (Spin, BackUp, Wait) &amp; Lifecycle State Machines<br><strong>Course Track:</strong> NavPro Learning Hub - Level 1<br><strong>Target Environment:</strong> ROS 2 Jazzy Jalisco</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"1-overview--learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>What happens when an autonomous robot gets stuck? A pallet jack is parked in its path, a worker stands in the doorway, or localization loses confidence?</p>\\n<p>In legacy robotics, state machines became unmaintainable &quot;spaghetti state diagrams.&quot; In Nav2, decision-making is governed by <strong>Behavior Trees (BT)</strong> and managed by <strong>Lifecycle Nodes</strong>.</p>\\n<p>By the end of this lesson, you will:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Understand why Behavior Trees replaced Finite State Machines in modern autonomous systems.</li>\\n<li>Master the core BT node primitives: Action, Condition, Sequence, and Fallback.</li>\\n<li>Configure the <strong>Recovery Behavior Server</strong> (Spin, BackUp, Wait, and Costmap Clearing).</li>\\n<li>Master ROS 2 <strong>Lifecycle Management</strong> (<code class=\\"inline-code\\">Unconfigured -&gt; Inactive -&gt; Active</code>).</li>\\n<li>Visualize and audit behavior trees in real time.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-why-behavior-trees-over-state-machines\\">2. Why Behavior Trees Over State Machines?</h2>\\n<div class=\\"table-wrapper\\"><table>\\n<thead><tr>\\n<th>Finite State Machine (FSM)</th>\\n<th>Behavior Tree (BT)</th>\\n</tr></thead><tbody>\\n<tr>\\n<td>$N^2$ possible transition arrows</td>\\n<td>Highly modular sub-trees</td>\\n</tr>\\n<tr>\\n<td>High risk of unhandled edge cases</td>\\n<td>Composable and readable</td>\\n</tr>\\n<tr>\\n<td>Difficult to add new behaviors</td>\\n<td>Reactive tick-based execution</td>\\n</tr>\\n</tbody></table></div>\\n<p>A Behavior Tree executes by sending periodic <strong>Ticks</strong> from the root downward. Each node returns one of three statuses:</p>\\n<ul class=\\"lesson-bullet-list\\">\\n<li><code class=\\"inline-code\\">SUCCESS</code>: The action completed successfully.</li>\\n<li><code class=\\"inline-code\\">FAILURE</code>: The action failed (e.g. planner found no path).</li>\\n<li><code class=\\"inline-code\\">RUNNING</code>: The action is currently in progress (e.g. robot is moving).</li>\\n</ul>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-the-recovery-sub-tree-pipeline\\">3. The Recovery Sub-Tree Pipeline</h2>\\n<p>When the robot encounters an obstacle that blocks its planned path:</p>\\n<div class=\\"lesson-image-wrapper\\"><img src=\\"assets/images/nav2_bt_pipeline.svg\\" alt=\\"Nav2 Behavior Tree Recovery Pipeline\\" class=\\"lesson-image\\" loading=\\"lazy\\"><span class=\\"image-caption\\">Nav2 Behavior Tree Recovery Pipeline</span></div>\\n<ol class=\\"lesson-ordered-list\\">\\n<li><strong>Clear Entire Costmap:</strong> Strips out transient sensor noise or dynamic obstacles that may have already moved.</li>\\n<li><strong>BackUp Recovery:</strong> Reverses 30cm to create maneuvering clearance.</li>\\n<li><strong>Spin Recovery:</strong> Rotates 360 degrees to scan the perimeter and find open exits.</li>\\n<li><strong>Wait Recovery:</strong> Pauses for 2-5 seconds allowing walking humans to clear the lane.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-the-ros-2-lifecycle-state-machine\\">4. The ROS 2 Lifecycle State Machine</h2>\\n<p>Every major node in Nav2 (Planner, Controller, Recoveries, Costmaps) is a <strong>Managed Lifecycle Node</strong>:</p>\\n<div class=\\"lesson-image-wrapper\\"><img src=\\"assets/images/lifecycle_state_machine.svg\\" alt=\\"ROS 2 Managed Lifecycle Node\\" class=\\"lesson-image\\" loading=\\"lazy\\"><span class=\\"image-caption\\">ROS 2 Managed Lifecycle Node</span></div>\\n<h3 id=\\"why-lifecycle-nodes-are-crucial\\">Why Lifecycle Nodes are Crucial:</h3>\\n<p>In ROS 1, nodes started operating immediately on launch. If a path planner launched before the map server was finished loading, the robot would crash.</p>\\n<p>In ROS 2, the <strong><code class=\\"inline-code\\">lifecycle_manager</code></strong> guarantees that all nodes are configured, memory is allocated, and topics are connected before any node enters the <code class=\\"inline-code\\">Active</code> state!</p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-inspecting-lifecycle-states-with-the-cli\\">5. Inspecting Lifecycle States with the CLI</h2>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# 1. List all managed lifecycle nodes\\nros2 lifecycle nodes\\n\\n# 2. Query the lifecycle state of the controller server\\nros2 lifecycle get /controller_server\\n# Output: active [3]\\n\\n# 3. Manually transition a node state for diagnostics\\nros2 lifecycle set /controller_server deactivate\\nros2 lifecycle set /controller_server activate\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># 1. List all managed lifecycle nodes\\nros2 lifecycle nodes\\n\\n# 2. Query the lifecycle state of the controller server\\nros2 lifecycle get /controller_server\\n# Output: active [3]\\n\\n# 3. Manually transition a node state for diagnostics\\nros2 lifecycle set /controller_server deactivate\\nros2 lifecycle set /controller_server activate</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-hands-on-student-challenge\\">6. Hands-on Student Challenge</h2>\\n<p><strong>Task:</strong></p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Start Nav2 navigation: <code class=\\"inline-code\\">ros2 launch navpro_navigation navigation.launch.py</code>.</li>\\n<li>Send a navigation goal into a dead-end corridor in the warehouse.</li>\\n<li>In Gazebo, place a static box directly in front of the robot while it is driving.</li>\\n<li>Watch the robot stop, trigger the Recovery Pipeline: observe it backup 0.3m, spin, recompute a global detour around the obstacle, and proceed!</li>\\n</ol>","quizzes":[{"id":"q_l1_24_1","prompt":"What are the core control node types in a Nav2 Behavior Tree XML definition?","options":["Sequence, Fallback (Selector), and Parallel","If, Else, While","Pub, Sub, Service","Try, Catch, Finally"],"correct":0,"explanation":"Behavior Trees use Control Nodes (Sequence, Fallback/Selector, Parallel) to evaluate Action and Condition leaf nodes, enabling deterministic navigation failure recovery."}],"has_quiz":true,"next_id":"lesson_25","prev_id":"lesson_23"},{"id":"lesson_25","num":25,"num_str":"25","title":"Autonomous Navigation Scripting with Nav2 Simple Commander","slug":"autonomous_patrol_nav2_simple_commander","filename":"25_autonomous_patrol_nav2_simple_commander.md","module":"Autonomous Navigation with Nav2","module_id":5,"duration":"45-60 min","focus":"Python Mission Scripting, \`BasicNavigator\` API, Multi-Waypoint Patrols & Timeout Guards","snapshot":[],"html_content":"<h1 id=\\"lesson-25-autonomous-navigation-scripting-with-nav2-simple-commander\\">Lesson 25: Autonomous Navigation Scripting with Nav2 Simple Commander</h1>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Focus:</strong> Python Mission Scripting, <code class=\\"inline-code\\">BasicNavigator</code> API, Multi-Waypoint Patrols &amp; Timeout Guards<br><strong>Course Track:</strong> NavPro Learning Hub - Level 1 (Day 3 Capstone)<br><strong>Target Environment:</strong> ROS 2 Jazzy Jalisco</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"1-overview--learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>Up to this point, you commanded goals manually by clicking buttons in RViz2. In commercial warehouse robotics, an AMR receives autonomous mission assignments from an ERP or warehouse execution system (WES): <strong>&quot;Pick up pallet at Station Alpha -&gt; Deliver to Packing Bay Bravo -&gt; Return to Charger.&quot;</strong></p>\\n<p>The <strong>Nav2 Simple Commander API (<code class=\\"inline-code\\">BasicNavigator</code>)</strong> is the official Python programmatic SDK for orchestrating autonomous navigation tasks.</p>\\n<p>By the end of this lesson, you will:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Initialize the navigation stack programmatically using <code class=\\"inline-code\\">BasicNavigator.waitUntilNav2Active()</code>.</li>\\n<li>Seed initial localization estimates using <code class=\\"inline-code\\">setInitialPose()</code>.</li>\\n<li>Dispatch asynchronous navigation goals with <code class=\\"inline-code\\">goToPose()</code> and multi-point missions with <code class=\\"inline-code\\">followWaypoints()</code>.</li>\\n<li>Monitor non-blocking real-time feedback (distance remaining, estimated time of arrival).</li>\\n<li>Implement safety watchdog timeout loops and goal cancellation.</li>\\n<li>Build and execute an autonomous multi-waypoint inspection patrol loop.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-the-simple-commander-python-api-architecture\\">2. The Simple Commander Python API Architecture</h2>\\n<div class=\\"lesson-image-wrapper\\"><img src=\\"assets/images/nav2_simple_commander.svg\\" alt=\\"Nav2 Simple Commander Architecture\\" class=\\"lesson-image\\" loading=\\"lazy\\"><span class=\\"image-caption\\">Nav2 Simple Commander Architecture</span></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-core-basicnavigator-methods\\">3. Core <code class=\\"inline-code\\">BasicNavigator</code> Methods</h2>\\n<div class=\\"table-wrapper\\"><table>\\n<thead><tr>\\n<th>Method</th>\\n<th>Return Type</th>\\n<th>Description</th>\\n</tr></thead><tbody>\\n<tr>\\n<td><code class=\\"inline-code\\">setInitialPose(pose)</code></td>\\n<td><code class=\\"inline-code\\">None</code></td>\\n<td>Publishes 2D pose to <code class=\\"inline-code\\">/initialpose</code> for AMCL particle filter convergence.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">waitUntilNav2Active()</code></td>\\n<td><code class=\\"inline-code\\">None</code></td>\\n<td>Blocks script until all Nav2 lifecycle nodes report <code class=\\"inline-code\\">Active</code> state.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">goToPose(goal_pose)</code></td>\\n<td><code class=\\"inline-code\\">None</code></td>\\n<td>Asynchronously dispatches a navigation goal (non-blocking).</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">followWaypoints(poses)</code></td>\\n<td><code class=\\"inline-code\\">None</code></td>\\n<td>Dispatches a sequential list of waypoints.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">isTaskComplete()</code></td>\\n<td><code class=\\"inline-code\\">bool</code></td>\\n<td>Returns <code class=\\"inline-code\\">True</code> when navigation has terminated (succeeded, canceled, or failed).</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">getFeedback()</code></td>\\n<td><code class=\\"inline-code\\">NavigationFeedback</code></td>\\n<td>Returns real-time metrics: <code class=\\"inline-code\\">distance_remaining</code>, <code class=\\"inline-code\\">navigation_time</code>.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">cancelTask()</code></td>\\n<td><code class=\\"inline-code\\">None</code></td>\\n<td>Immediately aborts the in-progress navigation goal.</td>\\n</tr>\\n<tr>\\n<td><code class=\\"inline-code\\">getResult()</code></td>\\n<td><code class=\\"inline-code\\">TaskResult</code></td>\\n<td>Returns final outcome enum (<code class=\\"inline-code\\">SUCCEEDED</code>, <code class=\\"inline-code\\">CANCELED</code>, <code class=\\"inline-code\\">FAILED</code>).</td>\\n</tr>\\n</tbody></table></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-complete-autonomous-patrol-script-walkthrough\\">4. Complete Autonomous Patrol Script Walkthrough</h2>\\n<p>Open <a href=\\"file:///home/chaitu/Projects/navpro_learning_hub/level1/ros2_ws/src/navpro_navigation/navpro_navigation/solution_multi_waypoint_patrol.py\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\"><code class=\\"inline-code\\">ros2_ws/src/navpro_navigation/navpro_navigation/solution_multi_waypoint_patrol.py</code></a>:</p>\\n<div class=\\"code-container\\" data-language=\\"python\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">PYTHON</span><button class=\\"copy-code-btn\\" data-code=\\"#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nAutonomous Multi-Waypoint Warehouse Patrol Script\\nUses Nav2 Simple Commander API with non-blocking feedback and timeout guards.\\n&quot;&quot;&quot;\\n\\nimport time\\nimport math\\nimport rclpy\\nfrom geometry_msgs.msg import PoseStamped\\nfrom nav2_simple_commander.robot_navigator import BasicNavigator, TaskResult\\n\\n\\ndef create_pose(navigator, x, y, yaw):\\n    &quot;&quot;&quot;Helper creating a PoseStamped in map frame.&quot;&quot;&quot;\\n    pose = PoseStamped()\\n    pose.header.frame_id = &#x27;map&#x27;\\n    pose.header.stamp = navigator.get_clock().now().to_msg()\\n    pose.pose.position.x = float(x)\\n    pose.pose.position.y = float(y)\\n    pose.pose.orientation.z = math.sin(yaw / 2.0)\\n    pose.pose.orientation.w = math.cos(yaw / 2.0)\\n    return pose\\n\\n\\ndef main():\\n    rclpy.init()\\n    navigator = BasicNavigator()\\n\\n    # 1. Wait until Nav2 lifecycle nodes are Active\\n    navigator.get_logger().info(&#x27;Waiting for Nav2 to activate...&#x27;)\\n    navigator.waitUntilNav2Active()\\n\\n    # 2. Define patrol checkpoints: (Name, X, Y, Yaw)\\n    checkpoints = [\\n        (&quot;Station Alpha&quot;, 1.5, 0.5, 0.0),\\n        (&quot;Storage Bay Bravo&quot;, 2.0, 2.0, 1.57),\\n        (&quot;Inspection Point Charlie&quot;, 0.5, 1.8, 3.14),\\n    ]\\n\\n    # 3. Execute sequential patrol loop\\n    for name, x, y, yaw in checkpoints:\\n        goal = create_pose(navigator, x, y, yaw)\\n        navigator.get_logger().info(f&#x27;Navigating to {name} ({x}, {y})...&#x27;)\\n        navigator.goToPose(goal)\\n\\n        start_time = time.time()\\n        while not navigator.isTaskComplete():\\n            fb = navigator.getFeedback()\\n            if fb:\\n                navigator.get_logger().info(\\n                    f&#x27;[{name}] Remaining distance: {fb.distance_remaining:.2f}m&#x27;,\\n                    throttle_duration_sec=2.0\\n                )\\n\\n            # Safety Watchdog Timeout: cancel if travel exceeds 45 seconds!\\n            if time.time() - start_time &gt; 45.0:\\n                navigator.get_logger().warn(f&#x27;Timeout at {name}! Canceling...&#x27;)\\n                navigator.cancelTask()\\n                break\\n\\n            time.sleep(1.0)\\n\\n        # Process outcome\\n        if navigator.getResult() == TaskResult.SUCCEEDED:\\n            navigator.get_logger().info(f&#x27;Reached {name}! Dwell inspection pause (2s)...&#x27;)\\n            time.sleep(2.0)\\n        else:\\n            navigator.get_logger().error(f&#x27;Failed to reach {name}! Aborting mission.&#x27;)\\n            break\\n\\n    # 4. Return to home dock\\n    navigator.get_logger().info(&#x27;Patrol complete! Returning to dock...&#x27;)\\n    dock = create_pose(navigator, 0.0, 0.0, 0.0)\\n    navigator.goToPose(dock)\\n    while not navigator.isTaskComplete():\\n        time.sleep(1.0)\\n\\n    navigator.get_logger().info(&#x27;Safely docked.&#x27;)\\n    rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()\\">📋 Copy</button></div><pre><code class=\\"language-python\\">#!/usr/bin/env python3\\n&quot;&quot;&quot;\\nAutonomous Multi-Waypoint Warehouse Patrol Script\\nUses Nav2 Simple Commander API with non-blocking feedback and timeout guards.\\n&quot;&quot;&quot;\\n\\nimport time\\nimport math\\nimport rclpy\\nfrom geometry_msgs.msg import PoseStamped\\nfrom nav2_simple_commander.robot_navigator import BasicNavigator, TaskResult\\n\\n\\ndef create_pose(navigator, x, y, yaw):\\n    &quot;&quot;&quot;Helper creating a PoseStamped in map frame.&quot;&quot;&quot;\\n    pose = PoseStamped()\\n    pose.header.frame_id = &#x27;map&#x27;\\n    pose.header.stamp = navigator.get_clock().now().to_msg()\\n    pose.pose.position.x = float(x)\\n    pose.pose.position.y = float(y)\\n    pose.pose.orientation.z = math.sin(yaw / 2.0)\\n    pose.pose.orientation.w = math.cos(yaw / 2.0)\\n    return pose\\n\\n\\ndef main():\\n    rclpy.init()\\n    navigator = BasicNavigator()\\n\\n    # 1. Wait until Nav2 lifecycle nodes are Active\\n    navigator.get_logger().info(&#x27;Waiting for Nav2 to activate...&#x27;)\\n    navigator.waitUntilNav2Active()\\n\\n    # 2. Define patrol checkpoints: (Name, X, Y, Yaw)\\n    checkpoints = [\\n        (&quot;Station Alpha&quot;, 1.5, 0.5, 0.0),\\n        (&quot;Storage Bay Bravo&quot;, 2.0, 2.0, 1.57),\\n        (&quot;Inspection Point Charlie&quot;, 0.5, 1.8, 3.14),\\n    ]\\n\\n    # 3. Execute sequential patrol loop\\n    for name, x, y, yaw in checkpoints:\\n        goal = create_pose(navigator, x, y, yaw)\\n        navigator.get_logger().info(f&#x27;Navigating to {name} ({x}, {y})...&#x27;)\\n        navigator.goToPose(goal)\\n\\n        start_time = time.time()\\n        while not navigator.isTaskComplete():\\n            fb = navigator.getFeedback()\\n            if fb:\\n                navigator.get_logger().info(\\n                    f&#x27;[{name}] Remaining distance: {fb.distance_remaining:.2f}m&#x27;,\\n                    throttle_duration_sec=2.0\\n                )\\n\\n            # Safety Watchdog Timeout: cancel if travel exceeds 45 seconds!\\n            if time.time() - start_time &gt; 45.0:\\n                navigator.get_logger().warn(f&#x27;Timeout at {name}! Canceling...&#x27;)\\n                navigator.cancelTask()\\n                break\\n\\n            time.sleep(1.0)\\n\\n        # Process outcome\\n        if navigator.getResult() == TaskResult.SUCCEEDED:\\n            navigator.get_logger().info(f&#x27;Reached {name}! Dwell inspection pause (2s)...&#x27;)\\n            time.sleep(2.0)\\n        else:\\n            navigator.get_logger().error(f&#x27;Failed to reach {name}! Aborting mission.&#x27;)\\n            break\\n\\n    # 4. Return to home dock\\n    navigator.get_logger().info(&#x27;Patrol complete! Returning to dock...&#x27;)\\n    dock = create_pose(navigator, 0.0, 0.0, 0.0)\\n    navigator.goToPose(dock)\\n    while not navigator.isTaskComplete():\\n        time.sleep(1.0)\\n\\n    navigator.get_logger().info(&#x27;Safely docked.&#x27;)\\n    rclpy.shutdown()\\n\\n\\nif __name__ == &#x27;__main__&#x27;:\\n    main()</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-execution--verification\\">5. Execution &amp; Verification</h2>\\n<p>With simulation and navigation active:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"ros2 run navpro_navigation task_multi_waypoint_patrol\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">ros2 run navpro_navigation task_multi_waypoint_patrol</code></pre></div>\\n<p>Watch the robot sequentially drive through every warehouse aisle, halt for inspection scans, and automatically return to the home docking station!</p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-student-task--reference-solution\\">6. Student Task &amp; Reference Solution</h2>\\n<ul class=\\"lesson-bullet-list\\">\\n<li><strong>Your Assignment File:</strong> <a href=\\"file:///home/chaitu/Projects/navpro_learning_hub/level1/ros2_ws/src/navpro_navigation/navpro_navigation/task_multi_waypoint_patrol.py\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\"><code class=\\"inline-code\\">task_multi_waypoint_patrol.py</code></a></li>\\n<li><strong>Instructor Reference Answer:</strong> <a href=\\"file:///home/chaitu/Projects/navpro_learning_hub/level1/ros2_ws/src/navpro_navigation/navpro_navigation/solution_multi_waypoint_patrol.py\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\"><code class=\\"inline-code\\">solution_multi_waypoint_patrol.py</code></a></li>\\n</ul>","quizzes":[{"id":"q_l1_25_1","prompt":"Which high-level Python class from 'nav2_simple_commander' provides intuitive navigation APIs such as 'goToPose()' and 'followWaypoints()'?","options":["BasicNavigator","Nav2Client","SimpleGoalRunner","AmrCommander"],"correct":0,"explanation":"nav2_simple_commander.robot_navigator.BasicNavigator wraps the complex action client and lifecycle boilerplate into clean Python methods like goToPose() and followWaypoints()."}],"has_quiz":true,"next_id":"lesson_26","prev_id":"lesson_24"},{"id":"lesson_26","num":26,"num_str":"26","title":"Physical Robot Hardware Deployment (Sim-to-Real)","slug":"physical_robot_hardware_deployment","filename":"26_physical_robot_hardware_deployment.md","module":"Autonomous Navigation with Nav2","module_id":5,"duration":"45-60 min","focus":"Embedded Hardware Bringup, Micro-ROS/Serial Drivers, AMCL Relocalization & Physical AMR Deployment","snapshot":[],"html_content":"<h1 id=\\"lesson-26-physical-robot-hardware-deployment-sim-to-real\\">Lesson 26: Physical Robot Hardware Deployment (Sim-to-Real)</h1>\\n<div class=\\"alert-callout alert-note\\"><div class=\\"alert-icon\\"></div><div class=\\"alert-body\\"><strong>Focus:</strong> Embedded Hardware Bringup, Micro-ROS/Serial Drivers, AMCL Relocalization &amp; Physical AMR Deployment<br><strong>Course Track:</strong> NavPro Learning Hub - Level 1 (Physical Hardware Capstone)<br><strong>Target Environment:</strong> Physical NavPro Mini AMR Hardware</div></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"1-overview--learning-objectives\\">1. Overview &amp; Learning Objectives</h2>\\n<p>Simulation is the testing ground; physical hardware is the real world. In the physical realm, you face real motor back-EMF, wheel slippage on dusty floors, Wi-Fi latency, battery depletion, and sensor reflections.</p>\\n<p>Because ROS 2 isolates hardware drivers behind standardized interfaces (<code class=\\"inline-code\\">/cmd_vel</code>, <code class=\\"inline-code\\">/odom</code>, <code class=\\"inline-code\\">/scan</code>, <code class=\\"inline-code\\">/imu/data</code>), <strong>the exact same navigation script you wrote for Gazebo in Lesson 25 runs on the physical robot with ZERO code changes!</strong></p>\\n<p>By the end of this capstone lesson, you will:</p>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Understand the Sim-to-Real architectural mapping from Gazebo plugins to physical hardware drivers.</li>\\n<li>Establish a wireless DDS connection between your workstation PC and the onboard robot SBC (Single Board Computer).</li>\\n<li>Bring up the physical 2D LiDAR sensor driver on <code class=\\"inline-code\\">/dev/ttyUSB0</code>.</li>\\n<li>Establish Micro-ROS / Serial communication with the ESP32 motor controller.</li>\\n<li>Perform <strong>AMCL Global Relocalization</strong> using the 2D Pose Estimate tool in RViz2.</li>\\n<li>Execute an autonomous multi-waypoint patrol mission on the physical NavPro robot.</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"2-sim-to-real-architecture-mapping\\">2. Sim-to-Real Architecture Mapping</h2>\\n<p>Notice how the software interfaces remain 100% identical:</p>\\n<div class=\\"lesson-image-wrapper\\"><img src=\\"assets/images/sim_to_real_pipeline.svg\\" alt=\\"Sim-to-Real Hardware Deployment Architecture\\" class=\\"lesson-image\\" loading=\\"lazy\\"><span class=\\"image-caption\\">Sim-to-Real Hardware Deployment Architecture</span></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"3-step-by-step-hardware-bringup-procedure\\">3. Step-by-Step: Hardware Bringup Procedure</h2>\\n<h3 id=\\"step-31-network-setup--ssh-connection\\">Step 3.1: Network Setup &amp; SSH Connection</h3>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Power on the NavPro robot.</li>\\n<li>Ensure both your workstation laptop and the robot are connected to the same dedicated 5GHz Wi-Fi router.</li>\\n<li>Identify the robot IP address (e.g. <code class=\\"inline-code\\">192.168.1.50</code>).</li>\\n<li>SSH into the robot&#x27;s onboard compute:</li>\\n</ol>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"   ssh navpro@192.168.1.50\\n   # Password: navpro\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">   ssh navpro@192.168.1.50\\n   # Password: navpro</code></pre></div>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Ensure both your laptop and the robot share the exact same <code class=\\"inline-code\\">ROS_DOMAIN_ID</code>:</li>\\n</ol>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"   export ROS_DOMAIN_ID=1\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">   export ROS_DOMAIN_ID=1</code></pre></div>\\n<hr class=\\"divider\\">\\n<h3 id=\\"step-32-launch-physical-hardware-drivers-onboard-robot\\">Step 3.2: Launch Physical Hardware Drivers (Onboard Robot)</h3>\\n<p>On the robot SBC, launch the hardware layer:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# 1. Bring up LiDAR Driver (RPLiDAR on /dev/ttyUSB0)\\nros2 launch rplidar_ros rplidar_a1_launch.py\\n\\n# 2. In a second terminal, start Micro-ROS Agent connecting to ESP32 motor board:\\nros2 run micro_ros_agent micro_ros_agent serial --dev /dev/ttyUSB1 -b 115200\\n\\n# 3. Start Robot State Publisher:\\nros2 launch navpro_description rsp.launch.py\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># 1. Bring up LiDAR Driver (RPLiDAR on /dev/ttyUSB0)\\nros2 launch rplidar_ros rplidar_a1_launch.py\\n\\n# 2. In a second terminal, start Micro-ROS Agent connecting to ESP32 motor board:\\nros2 run micro_ros_agent micro_ros_agent serial --dev /dev/ttyUSB1 -b 115200\\n\\n# 3. Start Robot State Publisher:\\nros2 launch navpro_description rsp.launch.py</code></pre></div>\\n<hr class=\\"divider\\">\\n<h3 id=\\"step-33-verify-real-hardware-streams-from-your-laptop\\">Step 3.3: Verify Real Hardware Streams (From Your Laptop)</h3>\\n<p>On your laptop (without SSH), verify that the topics are visible across the wireless network:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"# 1. Verify LiDAR points are streaming\\nros2 topic hz /scan\\n# Average rate: 10.02 Hz\\n\\n# 2. Verify physical wheel odometry\\nros2 topic echo /odom --once\\n\\n# 3. Perform a low-speed teleop safety test (0.1 m/s)\\nros2 topic pub --once /cmd_vel geometry_msgs/msg/Twist &quot;{linear: {x: 0.1}, angular: {z: 0.0}}&quot;\\">📋 Copy</button></div><pre><code class=\\"language-bash\\"># 1. Verify LiDAR points are streaming\\nros2 topic hz /scan\\n# Average rate: 10.02 Hz\\n\\n# 2. Verify physical wheel odometry\\nros2 topic echo /odom --once\\n\\n# 3. Perform a low-speed teleop safety test (0.1 m/s)\\nros2 topic pub --once /cmd_vel geometry_msgs/msg/Twist &quot;{linear: {x: 0.1}, angular: {z: 0.0}}&quot;</code></pre></div>\\n<hr class=\\"divider\\">\\n<h2 id=\\"4-amcl-relocalization-on-the-physical-floor\\">4. AMCL Relocalization on the Physical Floor</h2>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>On your laptop, launch the navigation stack with the facility map:</li>\\n</ol>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"   ros2 launch navpro_navigation navigation.launch.py map:=/path/to/warehouse_map.yaml\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">   ros2 launch navpro_navigation navigation.launch.py map:=/path/to/warehouse_map.yaml</code></pre></div>\\n<ol class=\\"lesson-ordered-list\\">\\n<li>Open RViz2 on your laptop.</li>\\n<li>Click the <strong>2D Pose Estimate</strong> button in the top toolbar.</li>\\n<li>Click and drag on the map at the robot&#x27;s approximate physical location on the floor.</li>\\n<li>In RViz2, observe the green Particle Cloud (<code class=\\"inline-code\\">/particlecloud</code>).</li>\\n<li>Drive the robot forward and turn slightly using teleop: as LiDAR beams hit the real walls, the particle cloud will snap together tightly, indicating high localization confidence!</li>\\n</ol>\\n<hr class=\\"divider\\">\\n<h2 id=\\"5-executing-autonomous-missions-on-real-hardware\\">5. Executing Autonomous Missions on Real Hardware</h2>\\n<p>With the physical robot localized, run your autonomous patrol script from Lesson 25:</p>\\n<div class=\\"code-container\\" data-language=\\"bash\\"><div class=\\"code-header\\"><span class=\\"code-lang-tag\\">BASH</span><button class=\\"copy-code-btn\\" data-code=\\"ros2 run navpro_navigation task_multi_waypoint_patrol\\">📋 Copy</button></div><pre><code class=\\"language-bash\\">ros2 run navpro_navigation task_multi_waypoint_patrol</code></pre></div>\\n<p>Watch the physical NavPro robot navigate around real warehouse racks, dodge unexpected obstacles, and autonomously return to the charging station!</p>\\n<hr class=\\"divider\\">\\n<h2 id=\\"6-graduation--course-completion\\">6. Graduation &amp; Course Completion</h2>\\n<p>Congratulations! You have completed the <strong>NavPro Level 1 Course</strong>: from raw DDS communications and OOP Python nodes to kinematics, 3D modeling, Gazebo physics simulation, sensor fusion, 2D SLAM, Nav2 path planning, and physical hardware deployment.</p>\\n<p>You are now ready to progress to <strong>Level 2: Enterprise Robotics Architect &amp; AI Agent Integration</strong>!</p>","quizzes":[{"id":"q_l1_26_1","prompt":"During Sim-to-Real hardware bringup, why must AMCL be provided with an accurate initial pose (/initialpose) before autonomous navigation?","options":["Because physical motors refuse to draw current without a map","Because AMCL particles need a Gaussian hypothesis around the robot's physical starting location to match incoming LiDAR scans against the pre-built map","Because the USB serial port requires an initial pose handshake","Because Gazebo will crash if AMCL is not initialized"],"correct":1,"explanation":"AMCL is a Monte Carlo localization filter. Without an initial pose guess, particles are dispersed uniformly across the entire facility, preventing rapid localization convergence."}],"has_quiz":true,"next_id":null,"prev_id":"lesson_25"}]`),o={total_lessons:26,modules:e,lessons:n};export{o as l};
